pub const OpenOptions = struct {
    pub const PhysicalRootMode = enum {
        /// The DB path names a directory-backed physical root. DB owns its
        /// publication lease and persists the projection incarnation there.
        filesystem_managed,
        /// The DB path is only a logical namespace. An external backend owns
        /// physical publication, locking, and durability for that namespace.
        external_backend,
    };

    pub const OpenMode = enum {
        writer,
        writer_no_replay,
        query_readonly,
        status_only,

        pub fn allowsReplay(self: @This()) bool {
            return self == .writer;
        }

        pub fn allowsIndexWorkers(self: @This()) bool {
            return self == .writer or self == .writer_no_replay;
        }

        pub fn allowsOptionalRuntimes(self: @This()) bool {
            return self == .writer or self == .writer_no_replay;
        }
    };

    pub const GraphMetricIdleMaintenanceMode = enum {
        legacy,
        planned,
        auto,
        degree_canary,
    };

    /// External owners drive historical index work outside their capture fence.
    defer_index_backfill_on_open: bool = false,
    table_storage: ?table_storage_mod.Settings = null,
    open_mode: OpenOptions.OpenMode = .writer,
    /// An authenticated restore decoder needs rows and schema layouts, never
    /// source projections. Do not open intentionally omitted index artifacts.
    primary_only_readonly: bool = false,
    initial_owner_range: ?range_state_mod.InitialOwnerRange = null,
    initial_child_bootstrap: ?relational_initial_child_publication.Bootstrap = null,
    map_size: usize = 256 * 1024 * 1024,
    no_sync: bool = false,
    primary_backend: PrimaryBackend = .{ .lsm = db_config.primary_lsm_options_default },
    primary_runtime_store: ?*backend_erased_mod.Store = null,
    storage: ?lsm_backend_mod.Storage = null,
    lsm_cache: ?*lsm_backend_mod.Cache = null,
    hbc_cache: ?*hbc_mod.Cache = null,
    lsm_root_generation: u64 = 0,
    staged_generation: ?*const generation_lifecycle.StagedGeneration = null,
    /// Exclusive offline tooling may inspect a fenced source root. The caller
    /// must close it before publication; ordinary open cannot bypass the fence.
    exclusive_generation: ?*const generation_lifecycle.ExclusiveTransition = null,
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
    /// Optional storage-backend capacity probe. BackendRuntime configurators
    /// may install this while composing a DB open; it is resource policy input,
    /// not executor ownership.
    capacity_source: ?types.RepairCapacitySource = null,
    change_journal_backend: ?change_journal_mod.StorageBackend = null,
    change_journal_storage: ?lsm_backend_mod.Storage = null,
    index_backends: db_config.IndexBackendOptions = .{},
    index_base_path: ?[]const u8 = null,
    index_open_parallelism: ?usize = null,
    /// Authoritative local-provisioning schema to persist after the primary
    /// store is open but before any configured index is opened or backfilled.
    /// The caller retains ownership for the duration of `open`. This closes a
    /// schema-migration ordering hole where an interrupted target-generation
    /// backfill could resume with the previously persisted (or schema-less)
    /// mapper before the provisioner got a chance to call `setSchema`.
    schema_before_index_load: ?SchemaBeforeIndexLoad = null,
    /// An ordinary catalog-authoritative owner must retry when its pinned
    /// schema predates the durable root. Historical Raft apply may retain the
    /// newer schema while replaying an older entry's mutation.
    reject_stale_schema_before_index_load: bool = false,
    identity_namespace: ?doc_identity.Namespace = null,
    /// Immutable authenticated deployment ownership, not selected by a source
    /// request. Decoders/library opens may leave this unset.
    online_source_authority: ?source_authority_mod.Kind = null,
    prefer_existing_identity_namespace: bool = false,
    executor: derived_executor_mod.Config = .{},
    backend_runtime: ?*background_runtime_mod.BackendRuntime = null,
    /// Borrowed realtime clock for durable repair retry scheduling. Defaults to
    /// the backend runtime clock; the caller must keep an override alive until close.
    index_repair_clock: ?platform_clock.Clock = null,
    /// Private proof installed only by a validated `NativeRestoreOpenPlan`.
    /// A path-bound proof prevents a copied option set from silently skipping
    /// configuration for a different DB namespace.
    _backend_configuration_resolution: ?BackendConfigurationResolution = null,
    secret_store: ?*common_secrets.FileStore = null,
    remote_content: ?*const scraping.RemoteContentConfig = null,
    start_index_workers: bool = true,
    /// Externally leased owners drive maintenance themselves.
    start_independent_maintenance: bool = true,
    start_optional_runtimes: bool = true,
    start_optional_runtime_workers: bool = true,
    /// Managed caches install distributed callbacks before activating replay.
    start_resolver_workers: bool = true,
    external_derived_checkpoints: bool = true,
    /// Optional durable namespace for replica-local index repair state.
    /// Externally owned roots use this to keep crash-resume intent and replay
    /// pins inside the same atomic storage generation as their indexes.
    index_repair_checkpoint_storage: ?lsm_backend_mod.Storage = null,
    physical_root_mode: PhysicalRootMode = .filesystem_managed,
    /// Durable identity supplied by an externally owned physical backend.
    /// Filesystem-managed roots persist their own checkpoint; container
    /// backends such as Lite must bind the DB to the container generation and
    /// logical namespace that actually owns its bytes.
    external_root_incarnation: u128 = 0,
    /// Optional enrichment providers. `DB.open` takes ownership of every
    /// non-null provider when called, including when the open subsequently
    /// fails. A successfully opened DB releases them from `close`.
    enrichment: ?enrichment_runtime_mod.Config = null,
    ttl_cleanup: ttl_runtime_mod.Config = .{},
    coordinated_ttl: ?coordinated_ttl.Port = null,
    transaction_recovery: transaction_runtime_mod.Config = .{},
    text_merge: text_merge_runtime_mod.Config = .{},
    sparse_compaction: sparse_compaction_runtime_mod.Config = .{},
    /// Automatically consume configured metrics and durable refresh/rebuild
    /// requests on active writable owners. Existing background-worker gates
    /// also apply. The worker and its lease start lazily when metrics exist.
    graph_metric_maintenance: graph_metric_runtime_mod.Config = .{},
    graph_metric_idle_maintenance: GraphMetricIdleMaintenanceMode = .auto,
    graph_metric_idle_planned_options: index_manager_mod.IndexManager.GraphMetricPlannedMaintenanceOptions = .{},
    graph_metric_idle_auto_options: index_manager_mod.IndexManager.GraphMetricPlannedAutoIdleOptions = .{},
    graph_metric_idle_degree_canary_options: index_manager_mod.IndexManager.GraphMetricDegreeCanaryOptions = .{},
    /// Optional cross-shard candidate source for entity resolution blocking,
    /// injected by the serving layer (see `api/distributed_candidate_source.zig`).
    /// Null means local-only blocking against the worker's own store. Must
    /// outlive the DB.
    resolution_candidate_source: ?resolution_runtime_mod.CandidateSource = null,
    artifact_publication_dispatcher: ?ArtifactPublicationDispatcher = null,
    /// Optional cross-shard entity sink for the promoter, injected by the serving
    /// layer (see `api/distributed_entity_sink.zig`). Must outlive the DB.
    entity_sink: ?promotion_runtime_mod.EntitySink = null,
    /// Optional ownership guard for promotion. Raft apply-side DBs set this so
    /// only the source shard leader emits entity writes; standalone DBs leave it
    /// null and are treated as local owners.
    promotion_owner: ?promotion_runtime_mod.PromotionOwner = null,
    /// What the promoter does when no sink is currently available. The safe
    /// default holds replay so a later sink injection or routing repair can retry.
    entity_sink_missing_policy: promotion_runtime_mod.MissingSinkPolicy = .wait,
    /// Optional name embedder for resolution: backfills a mention's name
    /// embedding (for cosine/ann blocking) when a resolver declares a
    /// `name_embedding` model and the extraction artifact carries no vector.
    /// Caller-owned; must outlive the DB. Null disables backfill.
    resolution_embedder: ?embedder_mod.DenseEmbedder = null,
    /// Optional publication of committed derived/change-journal effects.
    /// The adapter declares local commit requirements and owns remote policy.
    replication_async_effect_mirror: ?ReplicationAsyncEffectMirror = null,
    /// Optional publication of committed user batch mutations, using versioned
    /// batch_mutation envelopes for replay. Completion is an adapter callback.
    replication_async_batch_mirror: ?ReplicationAsyncBatchMirror = null,
    /// Optional publication of committed metadata/catalog changes, using the
    /// stable metadata_mutation envelope.
    replication_async_metadata_mirror: ?ReplicationAsyncMetadataMirror = null,
    /// Borrowed write admission. Replicated apply explicitly bypasses this
    /// client guard; the adapter also decides whether mutating background work
    /// may start, independently of the DB's requested runtime defaults.
    replication_write_gate: ?ReplicationWriteGate = null,
    /// Bounded stall guard for the foreground `runUntilIdle` drain (Lite's
    /// synchronous ingest drain, in particular): if a managed derived index
    /// cannot advance its replay target for this long, `runUntilIdle` fails
    /// with `error.RunUntilIdleNoProgress` naming the stuck index and its
    /// indexed/expected counters instead of spinning indefinitely. 0 disables
    /// the guard. Never applied to background/steady-state replay or to any
    /// other drain entry point -- see `ReplayDrainOptions.no_progress_timeout_ns`.
    run_until_idle_no_progress_timeout_ms: u64 = default_run_until_idle_no_progress_timeout_ns / std.time.ns_per_ms,
};

pub const DenseNativeMigrationPolicySource = db_config.DenseNativeMigrationPolicySource;

/// Immutable backend decision shared by every phase of one native restore.
/// The runtime configurator is evaluated once against the final logical DB
/// identity; candidate opens receive an explicit path-bound proof and never
/// invoke it again.
pub const NativeRestoreOpenPlan = struct {
    _options: OpenOptions,
    _target_path_fingerprint: u64,

    fn resolvedOptionsForPath(self: @This(), path: []const u8) OpenOptions {
        var opts = self._options;
        opts._backend_configuration_resolution = .{
            .path_fingerprint = backendConfigurationPathFingerprint(path),
        };
        return opts;
    }

    pub fn optionsForTarget(self: @This(), target_path: []const u8) !OpenOptions {
        if (backendConfigurationPathFingerprint(target_path) != self._target_path_fingerprint)
            return error.NativeRestoreTargetPathMismatch;
        var opts = self.resolvedOptionsForPath(target_path);
        // A configurator is not allowed to retain or manufacture lifecycle
        // authority. Target opens always acquire the published-generation read
        // lease for themselves.
        opts.staged_generation = null;
        return opts;
    }

    /// Reuses the target's path-independent backend policy only for the
    /// lifecycle-owned candidate attached to that exact target. Callers cannot
    /// mint configuration proofs for unrelated paths.
    pub fn optionsForStagedGeneration(
        self: @This(),
        staged_generation: *const generation_lifecycle.StagedGeneration,
    ) !OpenOptions {
        const live_path = staged_generation.livePath();
        if (backendConfigurationPathFingerprint(live_path) != self._target_path_fingerprint)
            return error.NativeRestoreTargetPathMismatch;
        try staged_generation.validateLivePath(live_path);
        var opts = self.resolvedOptionsForPath(staged_generation.path());
        // Keep the lifecycle capability attached until DB.open. Validation at
        // option construction alone is racy: the stage may be closed or
        // superseded before the candidate is actually opened.
        opts.staged_generation = staged_generation;
        return opts;
    }

    pub fn physicalRootMode(self: @This()) OpenOptions.PhysicalRootMode {
        return self._options.physical_root_mode;
    }
};

