fn clearPortableImportTargetBounded(alloc: Allocator, store: *docstore_mod.DocStore) !void {
    const marker = store.getPortableImportRollback(alloc, portable_import_in_progress_key) catch |err| switch (err) {
        error.NotFound => return,
        else => return err,
    };
    defer alloc.free(marker);
    const encoded_baseline = try missingAsNull(store.getPortableImportRollback(alloc, portable_import_identity_baseline_key));
    defer if (encoded_baseline) |encoded| alloc.free(encoded);
    const baseline = if (encoded_baseline) |encoded|
        try backup_codec.decodeKeyValueBatch(alloc, encoded)
    else
        try alloc.alloc(backup_codec.KeyValueEntry, 0);
    defer {
        for (baseline) |entry| {
            alloc.free(entry.key);
            alloc.free(entry.value);
        }
        alloc.free(baseline);
    }
    if (baseline.len > portable_import_identity_baseline_max_entries) return error.InvalidPortableImportMarker;
    var baseline_bytes: usize = 0;
    for (baseline) |entry| {
        if (entry.key.len == 0 or entry.key[0] != internal_keys.identity_namespace) return error.InvalidPortableImportMarker;
        baseline_bytes +|= entry.key.len +| entry.value.len;
        if (baseline_bytes > portable_import_identity_baseline_max_bytes) return error.InvalidPortableImportMarker;
    }

    while (true) {
        const Collect = struct {
            alloc: Allocator,
            keys: std.ArrayListUnmanaged([]u8) = .empty,
            bytes: usize = 0,

            pub fn deinit(self: *@This()) void {
                for (self.keys.items) |key| self.alloc.free(key);
                self.keys.deinit(self.alloc);
            }

            fn visit(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const self: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                // Keep the recovery authority durable until every partial
                // generation key has been removed.
                if (std.mem.eql(u8, key, portable_import_in_progress_key) or
                    std.mem.eql(u8, key, portable_import_identity_baseline_key) or
                    !portable_backup.isPortableStoreKey(key)) return .@"continue";
                if (self.keys.items.len != 0 and
                    (self.keys.items.len >= portable_import_publish_batch_entries or
                        self.bytes +| key.len > portable_import_publish_batch_bytes)) return .stop;
                const owned = try self.alloc.dupe(u8, key);
                errdefer self.alloc.free(owned);
                try self.keys.append(self.alloc, owned);
                self.bytes += owned.len;
                return .@"continue";
            }
        };
        var page = Collect{ .alloc = alloc };
        defer page.deinit();
        try store.scanPortableImportRollbackWithContext("", "", .{}, &page, Collect.visit);
        if (page.keys.items.len == 0) {
            const restores: []const docstore_mod.KVPair = @ptrCast(baseline);
            try store.putBatch(restores, &.{ portable_import_in_progress_key, portable_import_identity_baseline_key });
            return;
        }
        const deletes: []const []const u8 = @ptrCast(page.keys.items);
        try store.putBatch(&.{}, deletes);
    }
}

fn encodePortableImportIdentityBaseline(alloc: Allocator, store: *docstore_mod.DocStore) ![]u8 {
    const Collect = struct {
        alloc: Allocator,
        entries: std.ArrayListUnmanaged(backup_codec.KeyValueEntry) = .empty,
        bytes: usize = 0,

        pub fn deinit(self: *@This()) void {
            for (self.entries.items) |entry| {
                self.alloc.free(entry.key);
                self.alloc.free(entry.value);
            }
            self.entries.deinit(self.alloc);
        }

        fn visit(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const self: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            if (self.entries.items.len >= portable_import_identity_baseline_max_entries or
                self.bytes +| key.len +| value.len > portable_import_identity_baseline_max_bytes)
            {
                return error.LiteImportTargetNotEmpty;
            }
            const owned_key = try self.alloc.dupe(u8, key);
            errdefer self.alloc.free(owned_key);
            const owned_value = try self.alloc.dupe(u8, value);
            errdefer self.alloc.free(owned_value);
            try self.entries.append(self.alloc, .{ .key = owned_key, .value = owned_value });
            self.bytes +|= key.len +| value.len;
            return .@"continue";
        }
    };
    var baseline = Collect{ .alloc = alloc };
    defer baseline.deinit();
    const lower = [_]u8{internal_keys.identity_namespace};
    const upper = [_]u8{internal_keys.identity_namespace + 1};
    try store.scanPortableImportRollbackWithContext(&lower, &upper, .{}, &baseline, Collect.visit);
    return try backup_codec.encodeKeyValueBatch(alloc, baseline.entries.items);
}

fn recoverIncompletePortableImport(alloc: Allocator, store: *docstore_mod.DocStore, read_only: bool) !void {
    const marker = store.get(alloc, portable_import_in_progress_key) catch |err| switch (err) {
        error.NotFound => return,
        else => return err,
    };
    defer alloc.free(marker);
    if (std.mem.eql(u8, marker, portable_import_marker_committed)) {
        // The generation and committed marker crossed the same forced durable
        // boundary. Marker removal is only housekeeping: a crash before that
        // cleanup must preserve the acknowledged generation.
        if (!read_only) {
            try store.putBatch(&.{}, &.{ portable_import_in_progress_key, portable_import_identity_baseline_key });
            store.sync(true) catch |err| {
                std.log.warn("portable import committed-marker cleanup deferred class={s}", .{@errorName(err)});
            };
        }
        return;
    }
    if (!std.mem.eql(u8, marker, portable_import_marker_publishing) and
        !std.mem.eql(u8, marker, portable_import_stage_lease_magic))
    {
        return error.InvalidPortableImportMarker;
    }
    if (read_only) return error.IncompletePortableImport;
    std.log.warn("recovering incomplete portable import by restoring pristine target", .{});
    try clearPortableImportTargetBounded(alloc, store);
    try store.sync(true);
}

pub fn threadedIo() if (builtin.os.tag == .freestanding) void else std.Io.Threaded {
    if (builtin.os.tag == .freestanding) return;
    return std.Io.Threaded.init(std.heap.page_allocator, .{});
}

/// Generic directory-store imports are decoded into a bounded, durable scratch
/// LSM before they touch the live store. Lite restores use a disposable native
/// generation instead, so their publication never creates an archive-sized
/// pending transaction.
pub const PortableImportStage = struct {
    alloc: Allocator,
    path: []u8,
    lease_file: std.Io.File,
    backend: lsm_backend_mod.BackendHandle,
    runtime_store: backend_erased_mod.Store,
    store: docstore_mod.DocStore,

    pub fn init(
        alloc: Allocator,
        target_path: []const u8,
        data: []const u8,
        opts: portable_backup.ImportOptions,
    ) !PortableImportStage {
        if (comptime builtin.os.tag == .freestanding) return error.UnsupportedOperation;

        const location = try createUniquePortableImportStageBase(alloc, target_path);
        const path = location.path;
        var lease_file = location.lease_file;
        errdefer {
            var io_impl = threadedIo();
            defer io_impl.deinit();
            lease_file.close(io_impl.io());
            const deleted = blk: {
                std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch break :blk false;
                break :blk true;
            };
            if (deleted) deletePortableImportStageLease(alloc, io_impl.io(), path) catch {};
            alloc.free(path);
        }
        var stage_options = db_config.primary_lsm_options_default;
        // The scratch generation is disposable and never recovered after a
        // process crash, so a WAL would only duplicate I/O and disk usage. A
        // tighter flush bound keeps the final mutable tail modest as well.
        stage_options.wal_enabled = false;
        stage_options.flush_threshold_bytes = 16 * 1024 * 1024;
        var backend = try lsm_backend_mod.BackendHandle.open(alloc, path, stage_options);
        errdefer backend.close();
        var runtime_store = try backend.ptr().runtimeStore(alloc, .{ .name = "portable-restore-stage" });
        errdefer runtime_store.deinit();
        var store = try docstore_mod.DocStore.openRuntime(alloc, &runtime_store);
        errdefer store.close();

        var staging_import_opts = opts;
        staging_import_opts.unpublished_staging = true;
        try portable_backup.importPortableWithOptions(alloc, &store, data, staging_import_opts);
        // Finish pending manifest/storage work before validation. Size-based
        // flushes keep the resident staging footprint bounded for large
        // archives; the final mutable tail is capped by the threshold above.
        try store.sync(true);
        return .{
            .alloc = alloc,
            .path = path,
            .lease_file = lease_file,
            .backend = backend,
            .runtime_store = runtime_store,
            .store = store,
        };
    }

    pub fn deinit(self: *PortableImportStage) void {
        self.store.close();
        self.runtime_store.deinit();
        self.backend.close();
        if (comptime builtin.os.tag != .freestanding) {
            var io_impl = threadedIo();
            defer io_impl.deinit();
            self.lease_file.close(io_impl.io());
            var scratch_deleted = true;
            std.Io.Dir.cwd().deleteTree(io_impl.io(), self.path) catch |err| {
                scratch_deleted = false;
                std.log.warn("portable restore scratch cleanup failed path={s} class={s}", .{ self.path, @errorName(err) });
            };
            if (scratch_deleted) {
                deletePortableImportStageLease(self.alloc, io_impl.io(), self.path) catch |err| {
                    std.log.warn("portable restore scratch lease cleanup failed path={s} class={s}", .{ self.path, @errorName(err) });
                };
            }
        }
        self.alloc.free(self.path);
        self.* = undefined;
    }

    pub fn reassignIdentityNamespace(self: *PortableImportStage, alloc: Allocator, namespace: doc_identity.Namespace) !void {
        try doc_identity.reassignNamespaceAlloc(alloc, &self.store, namespace);
    }

    pub fn publish(self: *PortableImportStage, target: *docstore_mod.DocStore) !void {
        // The target is fenced and pristine. A durable marker makes the
        // bounded sequence of commits one recoverable publication unit: open
        // rolls back publishing markers and preserves committed markers.
        const identity_baseline = try encodePortableImportIdentityBaseline(self.alloc, target);
        defer self.alloc.free(identity_baseline);
        target.putBatch(&.{
            .{ .key = portable_import_identity_baseline_key, .value = identity_baseline },
            .{ .key = portable_import_in_progress_key, .value = portable_import_marker_publishing },
        }, &.{}) catch |publish_err| {
            return self.rollbackOrFence(target, publish_err);
        };
        // The rollback authority must reach durable storage before any target
        // batch can be flushed or published independently.
        target.sync(true) catch |publish_err| return self.rollbackOrFence(target, publish_err);

        self.publishMarkedGeneration(target) catch |publish_err| {
            return self.rollbackOrFence(target, publish_err);
        };
    }

    fn rollbackOrFence(
        self: *PortableImportStage,
        target: *docstore_mod.DocStore,
        publish_err: anyerror,
    ) anyerror!void {
        const rollback_result: anyerror!void = if (builtin.is_test and test_fail_portable_import_rollback) blk: {
            test_fail_portable_import_rollback = false;
            break :blk error.InjectedPortableImportRollbackFailure;
        } else clearPortableImportTargetBounded(self.alloc, target);
        rollback_result catch |rollback_err| {
            target.requirePortableImportRecovery();
            std.log.err(
                "portable import failed and rollback requires reopen path={s} publish_class={s} rollback_class={s}",
                .{ self.path, @errorName(publish_err), @errorName(rollback_err) },
            );
            return error.PortableImportRecoveryRequired;
        };
        target.sync(true) catch |rollback_sync_err| {
            target.requirePortableImportRecovery();
            std.log.err(
                "portable import rollback completed in memory but durability requires reopen path={s} publish_class={s} rollback_class={s}",
                .{ self.path, @errorName(publish_err), @errorName(rollback_sync_err) },
            );
            return error.PortableImportRecoveryRequired;
        };
        return publish_err;
    }

    fn publishMarkedGeneration(self: *PortableImportStage, target: *docstore_mod.DocStore) !void {
        try artifact_footprint_mod.invalidate(target);
        try target.beginBulkIngestSession();
        var bulk_active = true;
        defer if (bulk_active) target.abortBulkIngestSession();
        const Publish = struct {
            alloc: Allocator,
            target: *docstore_mod.DocStore,
            writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty,
            bytes: usize = 0,

            fn clear(state: *@This()) void {
                for (state.writes.items) |kv| {
                    state.alloc.free(kv.key);
                    state.alloc.free(kv.value);
                }
                state.writes.clearRetainingCapacity();
                state.bytes = 0;
            }

            pub fn deinit(state: *@This()) void {
                state.clear();
                state.writes.deinit(state.alloc);
            }

            fn flush(state: *@This()) !void {
                if (state.writes.items.len == 0) return;
                try state.target.putBatchWithReplayWithOptions(null, state.writes.items, &.{}, null, .{ .mode = .bulk_ingest });
                state.clear();
                if (builtin.is_test and test_fail_portable_import_publish_after_batch) {
                    test_fail_portable_import_publish_after_batch = false;
                    return error.InjectedPortableImportPublishFailure;
                }
            }

            fn copy(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (std.mem.eql(u8, key, portable_import_in_progress_key)) return error.InvalidBackupRequest;
                // The staging store generated its own local footprint while
                // importing. Never overwrite destination epochs/cursors with
                // those facts; destination mutation hooks observe the bytes.
                if (artifact_footprint_mod.isKey(key)) return .@"continue";
                const entry_bytes = key.len +| value.len;
                if (state.writes.items.len != 0 and
                    (state.writes.items.len >= portable_import_publish_batch_entries or
                        state.bytes +| entry_bytes > portable_import_publish_batch_bytes)) try state.flush();
                const owned_key = try state.alloc.dupe(u8, key);
                errdefer state.alloc.free(owned_key);
                const owned_value = try state.alloc.dupe(u8, value);
                errdefer state.alloc.free(owned_value);
                try state.writes.append(state.alloc, .{ .key = owned_key, .value = owned_value });
                state.bytes +|= entry_bytes;
                return .@"continue";
            }
        };
        var state = Publish{ .alloc = self.alloc, .target = target };
        defer state.deinit();
        try self.store.scanWithContext("", "", .{}, &state, Publish.copy);
        try state.flush();
        try target.finishBulkIngestSessionWithOptions(.{ .compact = false });
        bulk_active = false;
        // Preserve rollback authority until the generation and its committed
        // marker cross the forced durability boundary together. If that sync
        // fails, rollback can still restore routing and identity metadata from
        // the live journal; deleting it in the marker write would make the
        // failure path irrecoverable.
        try target.put(portable_import_in_progress_key, portable_import_marker_committed);
        if (builtin.is_test and test_fail_portable_import_committed_sync) {
            test_fail_portable_import_committed_sync = false;
            return error.InjectedPortableImportCommittedSyncFailure;
        }
        try target.sync(true);
        target.putBatch(&.{}, &.{
            portable_import_in_progress_key,
            portable_import_identity_baseline_key,
        }) catch |err| {
            std.log.warn("portable import committed-journal cleanup deferred class={s}", .{@errorName(err)});
            return;
        };
        target.sync(true) catch |err| {
            std.log.warn("portable import committed-journal sync deferred class={s}", .{@errorName(err)});
        };
    }
};

pub fn loadOrCreateDurableRootIdentity(
    alloc: Allocator,
    backend_runtime: ?*background_runtime_mod.BackendRuntime,
    path: []const u8,
) !root_identity.State {
    if (comptime builtin.os.tag == .freestanding) return error.UnsupportedPlatform;
    if (backend_runtime) |runtime| {
        const io = runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        return try root_identity.loadOrCreate(alloc, io, path);
    }
    // Legacy callers may omit a runtime entirely. Keep their fallback at this
    // operation boundary; a supplied runtime must carry its own filesystem
    // authority so storage work never creates a hidden executor.
    var io_impl = threadedIo();
    defer io_impl.deinit();
    return try root_identity.loadOrCreate(alloc, io_impl.io(), path);
}

pub const monotonicTimeNs = execution_resources.monotonicTimeNs;

pub const elapsedSince = execution_resources.elapsedSince;

pub fn restoreIntentMarkerPathAlloc(alloc: Allocator, path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}/.restore-intent", .{path});
}

pub fn restoreStateMarkerPathAlloc(alloc: Allocator, path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}/.restore-state", .{path});
}

pub fn restoreImportMarkerPathAlloc(alloc: Allocator, path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}/.restore-importing", .{path});
}

pub fn deleteFileIfExists(io: Io, path: []const u8) !void {
    std.Io.Dir.cwd().deleteFile(io, path) catch |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    };
}

pub const RestoreState = struct {
    backup_id: []u8,
    location: []u8,
    artifact_sha256: []u8,
    native_manifest_size_bytes: u64,
    native_manifest_sha256: []u8,
    snapshot_path: []u8,
    group_id: u64,
    phase: []u8,
    primary_restored: bool,
    runtime_repair_complete: bool,
    graph_ownership_cursor: []u8,
    last_error: []u8,

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.backup_id);
        alloc.free(self.location);
        alloc.free(self.artifact_sha256);
        alloc.free(self.native_manifest_sha256);
        alloc.free(self.snapshot_path);
        alloc.free(self.phase);
        alloc.free(self.graph_ownership_cursor);
        alloc.free(self.last_error);
        self.* = undefined;
    }
};

pub const RestoreIdentity = struct {
    backup_id: []const u8,
    location: []const u8,
    artifact_sha256: []const u8,
    native_manifest_size_bytes: u64 = 0,
    native_manifest_sha256: []const u8 = "",
    snapshot_path: []const u8,
    group_id: u64,
};

const restore_marker_format_version: u32 = 1;
const max_restore_marker_bytes: usize = 64 * 1024;

const RestoreStateDisk = struct {
    format_version: u32 = restore_marker_format_version,
    backup_id: []const u8,
    location: []const u8,
    artifact_sha256: []const u8,
    native_manifest_size_bytes: u64 = 0,
    native_manifest_sha256: []const u8 = "",
    snapshot_path: []const u8,
    group_id: u64,
    phase: []const u8,
    primary_restored: bool,
    runtime_repair_complete: bool,
    graph_ownership_cursor: []const u8 = "",
    last_error: []const u8,
};

pub const RestoreImportDisk = struct {
    format_version: u32 = restore_marker_format_version,
    snapshot_root: []const u8,
    backup_id: []const u8,
    location: []const u8,
    artifact_sha256: []const u8,
    native_manifest_size_bytes: u64 = 0,
    native_manifest_sha256: []const u8 = "",
    snapshot_path: []const u8,
    group_id: u64,
};

pub fn restoreStateAlloc(
    alloc: Allocator,
    backup_id: []const u8,
    location: []const u8,
    artifact_sha256: []const u8,
    native_manifest_size_bytes: u64,
    native_manifest_sha256: []const u8,
    snapshot_path: []const u8,
    group_id: u64,
    phase: []const u8,
    primary_restored: bool,
    runtime_repair_complete: bool,
    graph_ownership_cursor: []const u8,
    last_error: []const u8,
) !RestoreState {
    const backup_id_owned = try alloc.dupe(u8, backup_id);
    errdefer alloc.free(backup_id_owned);
    const location_owned = try alloc.dupe(u8, location);
    errdefer alloc.free(location_owned);
    const artifact_sha256_owned = try alloc.dupe(u8, artifact_sha256);
    errdefer alloc.free(artifact_sha256_owned);
    const native_manifest_sha256_owned = try alloc.dupe(u8, native_manifest_sha256);
    errdefer alloc.free(native_manifest_sha256_owned);
    const snapshot_path_owned = try alloc.dupe(u8, snapshot_path);
    errdefer alloc.free(snapshot_path_owned);
    const phase_owned = try alloc.dupe(u8, phase);
    errdefer alloc.free(phase_owned);
    const graph_ownership_cursor_owned = try alloc.dupe(u8, graph_ownership_cursor);
    errdefer alloc.free(graph_ownership_cursor_owned);
    const last_error_owned = try alloc.dupe(u8, last_error);
    errdefer alloc.free(last_error_owned);

    return .{
        .backup_id = backup_id_owned,
        .location = location_owned,
        .artifact_sha256 = artifact_sha256_owned,
        .native_manifest_size_bytes = native_manifest_size_bytes,
        .native_manifest_sha256 = native_manifest_sha256_owned,
        .snapshot_path = snapshot_path_owned,
        .group_id = group_id,
        .phase = phase_owned,
        .primary_restored = primary_restored,
        .runtime_repair_complete = runtime_repair_complete,
        .graph_ownership_cursor = graph_ownership_cursor_owned,
        .last_error = last_error_owned,
    };
}

const RestoreImportState = struct {
    snapshot_root: []u8,
    identity: RestoreState,

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.snapshot_root);
        self.identity.deinit(alloc);
        self.* = undefined;
    }
};

fn validRestoreArtifactSha256(value: []const u8) bool {
    if (value.len != std.crypto.hash.sha2.Sha256.digest_length * 2) return false;
    for (value) |c| {
        if (!std.ascii.isDigit(c) and !(c >= 'a' and c <= 'f')) return false;
    }
    return true;
}

fn validRestoreCursorHex(value: []const u8) bool {
    if (value.len % 2 != 0) return false;
    for (value) |c| {
        if (!std.ascii.isDigit(c) and !(c >= 'a' and c <= 'f')) return false;
    }
    return true;
}

pub fn validRestoreIdentity(identity: RestoreIdentity) bool {
    return identity.backup_id.len > 0 and
        identity.location.len > 0 and
        validRestoreArtifactSha256(identity.artifact_sha256) and
        ((identity.native_manifest_size_bytes == 0 and identity.native_manifest_sha256.len == 0) or
            (identity.native_manifest_size_bytes > 0 and validRestoreArtifactSha256(identity.native_manifest_sha256))) and
        identity.snapshot_path.len > 0 and
        identity.group_id != 0;
}

pub fn writeRestoreMarkerAtomicWithIo(
    alloc: Allocator,
    io: Io,
    root: []const u8,
    path: []const u8,
    raw: []const u8,
) !void {
    if (raw.len > max_restore_marker_bytes) return error.RestoreMarkerTooLarge;
    var entropy: [8]u8 = undefined;
    try platform.entropy.fill(io, &entropy);
    const nonce = std.fmt.bytesToHex(entropy, .lower);
    const tmp_path = try std.fmt.allocPrint(alloc, "{s}.tmp-{s}", .{ path, &nonce });
    defer alloc.free(tmp_path);
    errdefer if (std.fs.path.isAbsolute(tmp_path))
        std.Io.Dir.deleteFileAbsolute(io, tmp_path) catch {}
    else
        std.Io.Dir.cwd().deleteFile(io, tmp_path) catch {};

    {
        var file = try fs_paths.createFilePortable(io, tmp_path, .{ .truncate = true });
        defer file.close(io);
        var writer_buffer: [4096]u8 = undefined;
        var writer = file.writer(io, &writer_buffer);
        try writer.interface.writeAll(raw);
        try writer.end();
        try file.sync(io);
    }
    if (std.fs.path.isAbsolute(path))
        try std.Io.Dir.renameAbsolute(tmp_path, path, io)
    else
        try std.Io.Dir.rename(std.Io.Dir.cwd(), tmp_path, std.Io.Dir.cwd(), path, io);
    try fs_paths.syncDirPortable(io, root);
}

pub fn readRestoreStateForPathAlloc(alloc: Allocator, path: []const u8) !?RestoreState {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    return try readRestoreStateForPathAllocWithIo(alloc, io_impl.io(), path);
}

pub fn readRestoreStateForPathAllocWithIo(alloc: Allocator, io: Io, path: []const u8) !?RestoreState {
    const state_path = try restoreStateMarkerPathAlloc(alloc, path);
    defer alloc.free(state_path);

    const raw = std.Io.Dir.cwd().readFileAlloc(io, state_path, alloc, .limited(max_restore_marker_bytes)) catch |err| switch (err) {
        error.FileNotFound => return null,
        else => return err,
    };
    defer alloc.free(raw);
    var parsed = std.json.parseFromSlice(RestoreStateDisk, alloc, raw, .{ .allocate = .alloc_always }) catch
        return error.InvalidRestoreState;
    defer parsed.deinit();
    const disk = parsed.value;
    if (disk.format_version != restore_marker_format_version or
        disk.backup_id.len == 0 or
        disk.location.len == 0 or
        !validRestoreArtifactSha256(disk.artifact_sha256) or
        ((disk.native_manifest_size_bytes == 0) != (disk.native_manifest_sha256.len == 0)) or
        (disk.native_manifest_sha256.len > 0 and !validRestoreArtifactSha256(disk.native_manifest_sha256)) or
        disk.snapshot_path.len == 0 or
        disk.group_id == 0 or
        disk.phase.len == 0 or
        !validRestoreCursorHex(disk.graph_ownership_cursor))
    {
        return error.InvalidRestoreState;
    }
    return try restoreStateAlloc(
        alloc,
        disk.backup_id,
        disk.location,
        disk.artifact_sha256,
        disk.native_manifest_size_bytes,
        disk.native_manifest_sha256,
        disk.snapshot_path,
        disk.group_id,
        disk.phase,
        disk.primary_restored,
        disk.runtime_repair_complete,
        disk.graph_ownership_cursor,
        disk.last_error,
    );
}

pub fn writeRestoreStateForPath(alloc: Allocator, path: []const u8, state: RestoreState) !void {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    return try writeRestoreStateForPathWithIo(alloc, io_impl.io(), path, state);
}

pub fn writeRestoreStateForPathWithIo(alloc: Allocator, io: Io, path: []const u8, state: RestoreState) !void {
    if (!validRestoreIdentity(.{
        .backup_id = state.backup_id,
        .location = state.location,
        .artifact_sha256 = state.artifact_sha256,
        .native_manifest_size_bytes = state.native_manifest_size_bytes,
        .native_manifest_sha256 = state.native_manifest_sha256,
        .snapshot_path = state.snapshot_path,
        .group_id = state.group_id,
    }) or state.phase.len == 0) return error.InvalidRestoreState;
    try fs_paths.createDirPathPortable(io, path);
    const state_path = try restoreStateMarkerPathAlloc(alloc, path);
    defer alloc.free(state_path);
    const raw = try std.json.Stringify.valueAlloc(alloc, RestoreStateDisk{
        .backup_id = state.backup_id,
        .location = state.location,
        .artifact_sha256 = state.artifact_sha256,
        .native_manifest_size_bytes = state.native_manifest_size_bytes,
        .native_manifest_sha256 = state.native_manifest_sha256,
        .snapshot_path = state.snapshot_path,
        .group_id = state.group_id,
        .phase = state.phase,
        .primary_restored = state.primary_restored,
        .runtime_repair_complete = state.runtime_repair_complete,
        .graph_ownership_cursor = state.graph_ownership_cursor,
        .last_error = state.last_error,
    }, .{});
    defer alloc.free(raw);
    try writeRestoreMarkerAtomicWithIo(alloc, io, path, state_path, raw);
}

fn readRestoreImportStateAlloc(alloc: Allocator, path: []const u8) !?RestoreImportState {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    return try readRestoreImportStateAllocWithIo(alloc, io_impl.io(), path);
}

pub fn readRestoreImportStateAllocWithIo(alloc: Allocator, io: Io, path: []const u8) !?RestoreImportState {
    const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
    defer alloc.free(import_marker_path);

    const raw = std.Io.Dir.cwd().readFileAlloc(io, import_marker_path, alloc, .limited(max_restore_marker_bytes)) catch |err| switch (err) {
        error.FileNotFound => return null,
        else => return err,
    };
    defer alloc.free(raw);
    var parsed = std.json.parseFromSlice(RestoreImportDisk, alloc, raw, .{ .allocate = .alloc_always }) catch
        return error.InvalidRestoreImportMarker;
    defer parsed.deinit();
    const disk = parsed.value;
    if (disk.format_version != restore_marker_format_version or
        disk.snapshot_root.len == 0 or
        disk.backup_id.len == 0 or
        disk.location.len == 0 or
        !validRestoreArtifactSha256(disk.artifact_sha256) or
        ((disk.native_manifest_size_bytes == 0) != (disk.native_manifest_sha256.len == 0)) or
        (disk.native_manifest_sha256.len > 0 and !validRestoreArtifactSha256(disk.native_manifest_sha256)) or
        disk.snapshot_path.len == 0 or
        disk.group_id == 0)
    {
        return error.InvalidRestoreImportMarker;
    }
    const snapshot_root = try alloc.dupe(u8, disk.snapshot_root);
    errdefer alloc.free(snapshot_root);
    const identity = try restoreStateAlloc(
        alloc,
        disk.backup_id,
        disk.location,
        disk.artifact_sha256,
        disk.native_manifest_size_bytes,
        disk.native_manifest_sha256,
        disk.snapshot_path,
        disk.group_id,
        "runtime_repair",
        true,
        false,
        "",
        "",
    );
    return .{
        .snapshot_root = snapshot_root,
        .identity = identity,
    };
}

fn spinOrYield() void {
    if (builtin.os.tag == .freestanding) {
        std.atomic.spinLoopHint();
    } else {
        platform.time.yieldNow();
    }
}

const atomicMaxU64 = execution_resources.atomicMaxU64;

fn setDenseCatchUpProgress(ctx: *AsyncContext, progress: ReplayProgress) void {
    ctx.stats.dense_catch_up.active.store(if (progress.active) 1 else 0, .monotonic);
    ctx.stats.dense_catch_up.phase.store(@backingInt(if (progress.active) types.DenseCatchUpStats.Phase.replay else types.DenseCatchUpStats.Phase.idle), .monotonic);
    ctx.stats.dense_catch_up.current_sequence.store(progress.sequence, .monotonic);
    ctx.stats.dense_catch_up.current_target_sequence.store(progress.target_sequence, .monotonic);
    ctx.stats.dense_catch_up.current_scanned_entries.store(progress.scanned_entries, .monotonic);
    ctx.stats.dense_catch_up.current_applied_entries.store(progress.applied_entries, .monotonic);
    ctx.stats.dense_catch_up.replay_scan_batches.store(progress.replay_scan_batches, .monotonic);
    ctx.stats.dense_catch_up.replay_hint_filter_skips.store(progress.replay_hint_filter_skips, .monotonic);
    _ = ctx.stats.dense_catch_up.progress_updates.fetchAdd(1, .monotonic);
}

fn setDenseCatchUpPhase(ctx: *AsyncContext, phase: types.DenseCatchUpStats.Phase) void {
    ctx.stats.dense_catch_up.phase.store(@backingInt(phase), .monotonic);
    _ = ctx.stats.dense_catch_up.progress_updates.fetchAdd(1, .monotonic);
}

fn noteDenseBulkFinishProgress(ctx_ptr: *anyopaque, progress: backend_types.BulkIngestFinishOptions.Progress) void {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    const phase: types.DenseCatchUpStats.Phase = switch (progress.phase) {
        .begin => .bulk_finish,
        .split => .bulk_split,
        .publish => .bulk_publish,
        .complete => .bulk_finish,
    };
    ctx.stats.dense_catch_up.phase.store(@backingInt(phase), .monotonic);
    ctx.stats.dense_catch_up.bulk_finish_current_window.store(progress.publish_window, .monotonic);
    ctx.stats.dense_catch_up.bulk_finish_current_window_split_steps.store(progress.split_steps, .monotonic);
    ctx.stats.dense_catch_up.bulk_finish_deferred_leaf_splits.store(progress.deferred_leaf_splits, .monotonic);
    ctx.stats.dense_catch_up.bulk_finish_current_window_ns.store(progress.elapsed_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.bulk_finish_max_window_ns, progress.elapsed_ns);
    if (progress.phase == .publish) {
        _ = ctx.stats.dense_catch_up.bulk_finish_windows.fetchAdd(1, .monotonic);
        _ = ctx.stats.dense_catch_up.bulk_finish_split_steps.fetchAdd(progress.split_steps, .monotonic);
        if (progress.elapsed_ns > std.time.ns_per_s) {
            std.log.info(
                "dense catch-up bulk finish publish window window={} split_steps={} deferred_leaf_splits={} elapsed_ms={}",
                .{ progress.publish_window, progress.split_steps, progress.deferred_leaf_splits, progress.elapsed_ns / std.time.ns_per_ms },
            );
        }
    }
    _ = ctx.stats.dense_catch_up.progress_updates.fetchAdd(1, .monotonic);
}

pub const lockAtomicWithBackoff = local_mutation.lockAtomicWithBackoff;

pub fn ensureSnapshotActive(cancellation: types.CancellationToken) !void {
    if (cancellation.isCancelled()) return error.Canceled;
}

pub fn lockAtomicWithCancellation(mutex: *std.atomic.Mutex, cancellation: types.CancellationToken) !void {
    var attempts: usize = 0;
    while (!mutex.tryLock()) : (attempts += 1) {
        try ensureSnapshotActive(cancellation);
        if (builtin.os.tag == .freestanding or builtin.single_threaded or attempts < 64) {
            std.atomic.spinLoopHint();
        } else if (attempts < 128) {
            platform.time.yieldNow();
        } else {
            const backoff_step = @min(attempts - 128, 5);
            sleepNs(@min(@as(u64, 50_000) << @intCast(backoff_step), @as(u64, 1_000_000)));
        }
    }
    errdefer mutex.unlock();
    try ensureSnapshotActive(cancellation);
}

pub fn splitBootstrapMarkersEqual(a: range_state_mod.SplitBootstrapMarker, b: range_state_mod.SplitBootstrapMarker) bool {
    return a.transition_id == b.transition_id and
        a.attempt_epoch == b.attempt_epoch and
        a.source_group_id == b.source_group_id and
        a.destination_group_id == b.destination_group_id and
        a.bootstrap_complete == b.bootstrap_complete;
}

pub const lockAtomicWithBackoffProfiled = local_mutation.lockAtomicWithBackoffProfiled;

fn lockApplyWithBackoffProfiled(rw_lock: *WriterPreferringRwLock, stats: *MutexContentionStats) ProfiledApplyLock {
    if (!asyncIndexProfileEnabled()) {
        rw_lock.lockExclusive();
        return .{
            .rw_lock = rw_lock,
            .stats = stats,
            .hold_start_ns = 0,
            .profiled = false,
        };
    }
    _ = stats.lock_calls.fetchAdd(1, .monotonic);
    if (rw_lock.tryLockExclusive()) {
        return .{
            .rw_lock = rw_lock,
            .stats = stats,
            .hold_start_ns = monotonicTimeNs(),
            .profiled = true,
        };
    }

    _ = stats.contended_calls.fetchAdd(1, .monotonic);
    const current_waiters = stats.current_waiters.fetchAdd(1, .monotonic) + 1;
    atomicMaxU64(&stats.max_waiters, current_waiters);
    defer _ = stats.current_waiters.fetchSub(1, .monotonic);

    const wait_start_ns = monotonicTimeNs();
    var attempts: usize = 0;
    var spin_loops: u64 = 0;
    var yield_loops: u64 = 0;
    var sleep_loops: u64 = 0;
    while (!rw_lock.tryLockExclusive()) : (attempts += 1) {
        if (builtin.os.tag == .freestanding or builtin.single_threaded) {
            std.atomic.spinLoopHint();
            spin_loops += 1;
            continue;
        }
        if (attempts < 64) {
            std.atomic.spinLoopHint();
            spin_loops += 1;
            continue;
        }
        if (attempts < 128) {
            platform.time.yieldNow();
            yield_loops += 1;
            continue;
        }
        const backoff_step = @min(attempts - 128, 5);
        const sleep_ns = @min(@as(u64, 50_000) << @intCast(backoff_step), @as(u64, 1_000_000));
        sleepNs(sleep_ns);
        sleep_loops += 1;
    }

    const wait_ns = elapsedSince(wait_start_ns);
    _ = stats.spin_loops.fetchAdd(spin_loops, .monotonic);
    _ = stats.yield_loops.fetchAdd(yield_loops, .monotonic);
    _ = stats.sleep_loops.fetchAdd(sleep_loops, .monotonic);
    _ = stats.wait_ns.fetchAdd(wait_ns, .monotonic);
    atomicMaxU64(&stats.max_wait_ns, wait_ns);
    return .{
        .rw_lock = rw_lock,
        .stats = stats,
        .hold_start_ns = monotonicTimeNs(),
        .profiled = true,
    };
}

