    /// Low-level value-returning open. A returned value may move before its
    /// owner installs it, so this function cannot safely launch workers that
    /// retain `self`. Long-lived public owners should use `openOwned`; internal
    /// containers must call `startQuarantineRetryWorkerIfNeeded` only after
    /// installing the value at its final address.
    pub fn open(alloc: Allocator, path: []const u8, requested_opts: OpenOptions) !DB {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ alloc, path, requested_opts });
        return blk: {
            var opts = requested_opts;
            if (opts.initial_child_bootstrap) |bootstrap| {
                try bootstrap.validate();
                if (opts.identity_namespace == null or !opts.identity_namespace.?.eql(bootstrap.namespace) or
                    opts.schema_before_index_load != null) return error.InvalidInitialChildPublication;
            }
            // Provider interfaces are move-only. Keep them in the mutable
            // options until a runtime has adopted them so partial opens have
            // exactly one cleanup owner.
            errdefer if (opts.enrichment) |*cfg| deinitOwnedEnrichmentConfig(alloc, cfg);
            if (opts._backend_configuration_resolution) |resolution| {
                if (resolution.path_fingerprint != backendConfigurationPathFingerprint(path))
                    return error.BackendConfigurationPathMismatch;
            } else {
                if (opts.backend_runtime) |runtime| {
                    if (runtime.db_open_configurator) |configurator| {
                        try configurator.configure(path, &opts);
                    }
                }
            }
            const runtime_alloc = backgroundRuntimeAllocator(alloc);
            var owned_backend_runtime: ?background_runtime_mod.BackendRuntimeHandle = null;
            errdefer if (owned_backend_runtime) |*handle| handle.deinit();
            const backend_runtime = opts.backend_runtime orelse blk_runtime: {
                if (opts.executor.backend == .manual and
                    opts.physical_root_mode == .filesystem_managed)
                {
                    owned_backend_runtime = try background_runtime_mod.BackendRuntimeHandle.initManualWithOwnedFilesystemIo(runtime_alloc);
                } else {
                    owned_backend_runtime = try background_runtime_mod.BackendRuntimeHandle.init(runtime_alloc, .{
                        .backend = opts.executor.backend,
                    });
                }
                break :blk_runtime owned_backend_runtime.?.runtime;
            };
            var generation_read_lease = if (opts.staged_generation) |staged_generation| staged_blk: {
                try staged_generation.validatePath(path);
                break :staged_blk null;
            } else if (opts.exclusive_generation) |transition| exclusive_blk: {
                try transition.validate(path);
                break :exclusive_blk null;
            } else if (opts.physical_root_mode == .external_backend)
                null
            else
                try generation_lifecycle.acquirePublishedGenerationReadWithRuntime(alloc, path, backend_runtime);
            errdefer if (generation_read_lease) |*lease| lease.deinit();
            if (opts.physical_root_mode == .filesystem_managed and opts.exclusive_generation == null) {
                if (comptime builtin.os.tag == .freestanding) {
                    return error.UnsupportedPlatform;
                } else {
                    const fence = try std.fs.path.join(alloc, &.{ path, vector_migration.contract.offline_fence_file });
                    defer alloc.free(fence);
                    const io = backend_runtime.filesystemIo() orelse return error.MissingBackendRuntimeIo;
                    if (std.Io.Dir.cwd().access(io, fence, .{})) |_| {
                        return error.VectorMigrationOfflineAdmission;
                    } else |err| if (err != error.FileNotFound) return err;
                }
            }

            const open_started_ns = monotonicTimeNs();
            const replication_write_gate = if (opts.replication_write_gate) |gate| gate.pinned() else null;
            var profile = OpenProfile{};
            var owned_resource_manager: ?*resource_manager_mod.ResourceManager = null;
            const bind_cache_resource_manager = opts.resource_manager != null;
            if (opts.resource_manager == null) {
                const manager = try alloc.create(resource_manager_mod.ResourceManager);
                manager.* = resource_manager_mod.ResourceManager.init(standaloneResourceManagerOptions(alloc));
                owned_resource_manager = manager;
                opts.resource_manager = manager;
            }
            errdefer if (owned_resource_manager) |manager| {
                manager.deinit(alloc);
                alloc.destroy(manager);
            };
            var owned_async_context: ?*AsyncContext = null;
            var owned_executor: ?*derived_executor_mod.Executor = null;
            errdefer {
                if (owned_executor) |ptr| runtime_alloc.destroy(ptr);
                if (owned_async_context) |ptr| runtime_alloc.destroy(ptr);
            }
            if (opts.index_repair_checkpoint_storage == null)
                opts.index_repair_checkpoint_storage = backend_runtime.storage();
            var effective_executor = opts.executor;
            if ((backend_runtime.io() == null or backend_runtime.usesBorrowedIo()) and effective_executor.backend == .io_threaded) {
                effective_executor.backend = .manual;
            }
            const backend_owner_id = try backend_runtime.allocOwnerId();
            var backend_owner_transferred = false;
            errdefer if (!backend_owner_transferred)
                backend_runtime.durable_jobs.closeOwner(backend_owner_id);
            const repair_cleanup_owner_id = try backend_runtime.allocOwnerId();
            var repair_cleanup_owner_transferred = false;
            errdefer if (!repair_cleanup_owner_transferred)
                backend_runtime.durable_jobs.closeOwner(repair_cleanup_owner_id);
            var publication_recovery = try publication_recovery_owner.Owner.init(backend_runtime);
            var publication_recovery_transferred = false;
            errdefer if (!publication_recovery_transferred)
                publication_recovery.deinit();
            var primary_lsm_background_executor: lsm_backend_mod.BackgroundExecutor = undefined;
            var effective_primary_backend = opts.primary_backend;
            var effective_index_backends = opts.index_backends;
            if (openModeRequiresReadOnlyBackends(opts.open_mode)) {
                applyReadOnlyToPrimaryBackend(&effective_primary_backend);
                applyReadOnlyToIndexBackends(&effective_index_backends);
            }
            switch (effective_primary_backend) {
                .lsm => |*lsm_opts| {
                    lsm_opts.cache = opts.lsm_cache orelse lsm_opts.cache;
                    lsm_opts.root_generation = opts.lsm_root_generation;
                    installLsmReadRuntime(lsm_opts, backend_runtime);
                    primary_lsm_background_executor = makeLsmBackgroundExecutor(backend_runtime, backend_owner_id);
                    lsm_opts.background_executor = &primary_lsm_background_executor;
                },
                .lsm_memory => |*lsm_opts| {
                    lsm_opts.cache = opts.lsm_cache orelse lsm_opts.cache;
                    lsm_opts.root_generation = opts.lsm_root_generation;
                    installLsmReadRuntime(lsm_opts, backend_runtime);
                    primary_lsm_background_executor = makeLsmBackgroundExecutor(backend_runtime, backend_owner_id);
                    lsm_opts.background_executor = &primary_lsm_background_executor;
                },
                .mem => {},
            }
            installIndexLsmReadRuntime(&effective_index_backends, backend_runtime);
            const core_opts: db_config.CoreOpenOptions = .{
                .map_size = opts.map_size,
                .no_sync = opts.no_sync,
                .read_only = openModeRequiresReadOnlyBackends(opts.open_mode),
                .primary_backend = effective_primary_backend,
                .primary_runtime_store = opts.primary_runtime_store,
                .storage = opts.storage,
                .lsm_cache = opts.lsm_cache,
                .hbc_cache = opts.hbc_cache,
                .lsm_root_generation = opts.lsm_root_generation,
                .resource_manager = opts.resource_manager,
                .bind_cache_resource_manager = bind_cache_resource_manager,
                .index_backends = effective_index_backends,
            };
            const resolved_config = db_config.ResolvedOpenConfig.init(
                effective_primary_backend,
                opts.storage,
                opts.lsm_cache,
                opts.hbc_cache,
                opts.lsm_root_generation,
                opts.resource_manager,
                bind_cache_resource_manager,
                effective_index_backends,
            );
            const core_owner = try alloc.create(db_core.DBCore);
            var core_owner_initialized = false;
            var core_owner_transferred = false;
            errdefer if (!core_owner_transferred) {
                if (core_owner_initialized) core_owner.deinit();
                alloc.destroy(core_owner);
            };
            const open_primary_started_ns = monotonicTimeNs();
            var opened_primary = try openPrimaryStore(alloc, path, core_opts);
            var opened_primary_owned = true;
            errdefer if (opened_primary_owned) {
                var failed_primary = opened_primary;
                failed_primary.store.close();
                failed_primary.owner.close(alloc);
            };
            // Portable publication uses bounded commits guarded by an
            // in-store completion marker. Recover before schema/catalog
            // construction so no runtime can observe a partial generation.
            try recoverIncompletePortableImport(
                alloc,
                &opened_primary.store,
                openModeRequiresReadOnlyBackends(opts.open_mode),
            );
            // Identity images written before the live directory existed
            // (released v0.2.x servers) store a namespace without its ALD1
            // marker. A writable owner builds the directory once, before range
            // initialization or core open read the namespace; read-only opens
            // keep failing closed.
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                const upgrade_control = if (opts.initial_owner_range) |*initial| initial.cancellationToken() else types.CancellationToken.none;
                try doc_identity.upgradeImportedLiveDirectoryAlloc(alloc, &opened_primary.store, upgrade_control);
            }
            if (opts.initial_owner_range) |initial| try range_state_mod.initializeOwnerRange(alloc, &opened_primary.store, initial);
            profile.primary_store_ns = elapsedSince(open_primary_started_ns);
            const core_resources_started_ns = monotonicTimeNs();
            // openCoreResourcesFromPrimaryStore assumes ownership on entry,
            // including all of its error paths.
            opened_primary_owned = false;
            var core = try db_core.openCoreResourcesFromPrimaryStore(
                alloc,
                path,
                opts.index_base_path orelse path,
                opts.map_size,
                opts.no_sync,
                resolved_config.primary_backend_kind,
                resolved_config.primary_lsm_storage,
                opts.change_journal_backend,
                opts.change_journal_storage,
                resolved_config.index_backends,
                opened_primary,
                opts.identity_namespace,
                false,
                if (opts.prefer_existing_identity_namespace) .use_existing else .reject,
                opts.external_derived_checkpoints,
                opts.index_repair_checkpoint_storage,
                opts.lsm_root_generation,
                openModeRequiresReadOnlyBackends(opts.open_mode),
            );
            var core_owned = true;
            errdefer if (core_owned) core.deinit(alloc);
            profile.core_resources_ns = elapsedSince(core_resources_started_ns);
            const async_context = try runtime_alloc.create(AsyncContext);
            owned_async_context = async_context;
            const executor = try runtime_alloc.create(derived_executor_mod.Executor);
            owned_executor = executor;
            var stored_primary_backend = effective_primary_backend;
            switch (stored_primary_backend) {
                .lsm => |*lsm_opts| lsm_opts.background_executor = null,
                .lsm_memory => |*lsm_opts| lsm_opts.background_executor = null,
                .mem => {},
            }
            const background_work_allowed = replicationWriteGateAllowsBackgroundWork(replication_write_gate);
            const start_index_workers = opts.open_mode.allowsIndexWorkers() and opts.start_index_workers and background_work_allowed;

            core_owner.* = try db_core.DBCore.fromOpened(
                alloc,
                backend_runtime.io() orelse backend_runtime.filesystemIo() orelse std.Options.debug_io,
                core,
            );
            core_owned = false;
            core_owner_initialized = true;
            // Reject a stale catalog-authoritative descriptor as soon as the
            // durable schema is known, before binding source authority or
            // starting any owner-side maintenance. Historical Raft apply is
            // allowed to replay against the newer on-disk schema instead.
            if (opts.reject_stale_schema_before_index_load) {
                if (opts.schema_before_index_load) |prepared_schema| {
                    if (core_owner.schema) |durable_schema| {
                        if (durable_schema.version > prepared_schema.runtime_schema.version)
                            return error.SchemaVersionRegression;
                    }
                }
            }
            core_owner.identity_visibility.summary = try doc_identity.visibilitySummaryFromStore(core_owner.store);
            // Freestanding builds have no file-backed secret store. Keep the
            // native FileStore implementation out of the WASM module graph.
            const policy_secret: ?[]u8 = if (comptime builtin.os.tag == .freestanding) null else if (opts.secret_store) |store|
                try optionalRowPolicyAuthority(alloc, store, "antfly.trusted_principal.secret")
            else
                null;
            var policy_authority_owned = true;
            errdefer if (policy_authority_owned) if (policy_secret) |value| {
                @memset(value, 0);
                alloc.free(value);
            };
            const policy_issuer: ?[]u8 = if (comptime builtin.os.tag == .freestanding) null else if (opts.secret_store) |store|
                try optionalRowPolicyAuthority(alloc, store, "antfly.trusted_principal.issuer")
            else
                null;
            errdefer if (policy_authority_owned) if (policy_issuer) |value| alloc.free(value);
            const local_execution = try runtime_alloc.create(LocalExecutionState);
            local_execution.* = .{
                .artifact_publication_dispatcher = opts.artifact_publication_dispatcher,
                .row_policy_gate = row_policy_gate_mod.Gate.init(core_owner.table_catalog),
                .row_policy_authority_secret = if (policy_secret != null and policy_issuer != null) policy_secret else null,
                .row_policy_authority_issuer = if (policy_secret != null and policy_issuer != null) policy_issuer else null,
                .initial_child_hidden = .init(opts.initial_child_bootstrap != null),
                .initial_child_bootstrap = opts.initial_child_bootstrap,
                .replication_async_effect_mirror = opts.replication_async_effect_mirror,
                .replication_async_batch_mirror = opts.replication_async_batch_mirror,
                .replication_async_metadata_mirror = opts.replication_async_metadata_mirror,
                .replication_write_gate = replication_write_gate,
                .optional_runtime_workers_enabled = false,
            };
            var db = DB{
                .local_execution = local_execution,
                .owned_row_policy_authority_secret = policy_secret,
                .owned_row_policy_authority_issuer = policy_issuer,
                .alloc = alloc,
                .runtime_alloc = runtime_alloc,
                .generation_read_lease = generation_read_lease,
                .open_mode = opts.open_mode,
                .primary_backend = stored_primary_backend,
                .primary_lsm_storage = resolved_config.primary_lsm_storage,
                .physical_root_mode = opts.physical_root_mode,
                .index_backends = resolved_config.index_backends,
                .core = core_owner,
                .async_context = async_context,
                .backend_runtime = backend_runtime,
                .backend_owner_id = backend_owner_id,
                .status_owner_epoch = publication_mod.allocateOwnerEpoch(),
                .repair_cleanup_owner_id = repair_cleanup_owner_id,
                .publication_recovery = publication_recovery,
                .owned_backend_runtime = owned_backend_runtime,
                .owned_resource_manager = owned_resource_manager,
                .index_repair_clock = opts.index_repair_clock,
                .capacity_source = opts.capacity_source orelse opts.resource_manager.?.capacitySource(),
                .executor = executor,
                .start_index_workers = start_index_workers,
                .start_independent_maintenance = opts.start_independent_maintenance,
                .run_until_idle_no_progress_timeout_ns = @as(u64, opts.run_until_idle_no_progress_timeout_ms) *| std.time.ns_per_ms,
                .graph_metric_idle_maintenance = opts.graph_metric_idle_maintenance,
                .graph_metric_idle_planned_options = opts.graph_metric_idle_planned_options,
                .graph_metric_idle_auto_options = opts.graph_metric_idle_auto_options,
                .graph_metric_idle_degree_canary_options = opts.graph_metric_idle_degree_canary_options,
                .resolver_workers_enabled = opts.start_resolver_workers,
                .secret_store = opts.secret_store,
                .remote_content = opts.remote_content,
                .enrichment_append_context = null,
                .enrichment_runtime = null,
                .resolution_candidate_source = opts.resolution_candidate_source,
                .resolution_embedder = opts.resolution_embedder,
                .entity_sink = opts.entity_sink,
                .promotion_owner = opts.promotion_owner,
                .entity_sink_missing_policy = opts.entity_sink_missing_policy,
                .ttl_cleanup_context = null,
                .ttl_runtime = null,
                .transaction_recovery_identity_context = null,
                .transaction_recovery_local_context = null,
                .transaction_runtime = null,
                .text_merge_runtime = null,
                .sparse_compaction_runtime = null,
                .graph_metric_runtime = null,
                .shadow = null,
            };
            core_owner_transferred = true;
            backend_owner_transferred = true;
            repair_cleanup_owner_transferred = true;
            publication_recovery_transferred = true;
            var executor_ready = false;
            owned_async_context = null;
            owned_backend_runtime = null;
            owned_resource_manager = null;
            owned_executor = null;
            generation_read_lease = null;
            policy_authority_owned = false;
            errdefer db.deinitWrapperState(executor_ready);
            if (db.core.table_catalog.row_policy_phase == .active) {
                const schema = db.core.schema orelse return error.RowPolicyCatalogChanged;
                db.local_execution.row_policy_bundle = (try row_policy_bundle_mod.load(alloc, db.core.store, db.core.identity_namespace.table_id, schema)) orelse
                    return error.RowPolicyAuthenticationRequired;
                if (!db.local_execution.row_policy_bundle.?.matchesCatalog(db.core.table_catalog)) return error.RowPolicyCatalogChanged;
            }
            db.core.index_manager.setIo(db.backend_runtime.io());
            db.core.apply_mutex.io = db.backend_runtime.io();
            db.core.snapshot_admission.lock.io = db.backend_runtime.io();
            db.core.snapshot_replay_admission.lock.io = db.backend_runtime.io();
            db.core.index_manager.setPrimaryLsmBackend(db.core.primary_store_owner.lsmBackend());
            db.core.setIndexOpenParallelism(opts.index_open_parallelism);
            const init_async_started_ns = monotonicTimeNs();
            try db.initAsyncInfrastructure(effective_executor, opts.resource_manager);
            profile.init_async_infrastructure_ns = elapsedSince(init_async_started_ns);
            executor_ready = true;
            if (opts.online_source_authority) |authority| {
                const source_authority = source_authority_mod;
                const namespace = online_source_contract.namespaceBytes(db.core.identity_namespace);
                if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                    var authority_txn = try db.core.store.beginWriteTxn();
                    errdefer authority_txn.abort();
                    try source_authority.bind(&authority_txn, authority, namespace);
                    try authority_txn.commit();
                } else {
                    var authority_txn = try db.core.store.beginReadTxn();
                    defer authority_txn.abort();
                    if (try source_authority.load(&authority_txn) != null) _ = try source_authority.require(&authority_txn, authority, namespace);
                }
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                if (comptime builtin.os.tag != .freestanding) {
                    try db.resumePreparedSourcePin();
                    try source_pin.reconcileReleased(&db);
                }
            } else {
                db.source_pin_cleanup.epoch.store(0, .release);
            }
            const table_storage_started_ns = monotonicTimeNs();
            try db.initializeTableStorage(opts.table_storage);
            profile.table_storage_ns = elapsedSince(table_storage_started_ns);
            if (!openModeRequiresReadOnlyBackends(opts.open_mode) and
                opts.physical_root_mode == .filesystem_managed)
            {
                const identity = try loadOrCreateDurableRootIdentity(alloc, db.backend_runtime, path);
                db.root_incarnation = identity.incarnation;
            } else if (opts.physical_root_mode == .external_backend) {
                db.root_incarnation = opts.external_root_incarnation;
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // Persisted primary completion prefixes cannot attest external
                // index files after process restart. Revoke before opening any
                // index runtime; fresh physical validation/publication must
                // establish this receiver's projection evidence again.
                try apply_state.invalidateProjectionCompletion(alloc, db.core.store);
            }
            db.core.index_manager.artifact_projection_root = db.root_incarnation;
            if (opts.schema_before_index_load) |prepared_schema| {
                // This option is used by the metadata-authoritative local
                // provisioner. Persist directly through the core before index
                // open; no index runtime exists yet and the metadata record is
                // already the durable authority for this replica projection.
                // Raft catch-up can reopen an older entry's pinned descriptor
                // after this physical DB has durably installed a newer schema.
                // Keep that newer epoch; the older entry's native applied
                // marker decides whether it still needs its data mutation.
                if (db.core.schema != null and db.core.schema.?.version > prepared_schema.runtime_schema.version) {
                    if (opts.reject_stale_schema_before_index_load) return error.SchemaVersionRegression;
                    std.log.debug("owner open retains newer durable schema path={s} durable_version={d} descriptor_version={d}", .{
                        path, db.core.schema.?.version, prepared_schema.runtime_schema.version,
                    });
                } else if (try childGenerationSourcePinsSchema(db.core, prepared_schema.runtime_schema.version)) {
                    // Parent ACKs precede the metadata child descriptor cut.
                    // A cold owner may reopen in that interval, but the
                    // descriptor cannot install an FK generation. Keep the
                    // durable old schema until exact Raft install does so.
                } else if (prepared_schema.public_schema_json) |public_json| {
                    const versioned_public_key = try public_table_schema.versionedSchemaKeyAlloc(alloc, prepared_schema.runtime_schema.version);
                    defer alloc.free(versioned_public_key);
                    _ = try db.core.commitSchemaMetadata(prepared_schema.runtime_schema, &.{
                        .{ .key = public_schema_json_key, .value = public_json },
                        .{ .key = versioned_public_key, .value = public_json },
                    }, &.{}, null);
                } else {
                    _ = try db.core.commitSchemaMetadata(prepared_schema.runtime_schema, &.{}, &.{public_schema_json_key}, null);
                }
                try db.core.refreshSchemaIndexes();
                try db.refreshRelationalRuntimeMode();
            }
            if (try db.restoreStagingStatus(alloc)) |value| {
                var staging_status = value;
                defer staging_status.deinit();
                db.local_execution.restore_staging_required.store(staging_status.value.phase != .published, .release);
            }
            {
                var hidden_read = try db.core.store.beginReadTxn();
                defer hidden_read.abort();
                if (try relational_initial_child_publication.load(&hidden_read)) |hidden| {
                    if (opts.initial_child_bootstrap) |bootstrap| if (!bootstrap.matches(hidden)) return error.InitialChildPublicationChanged;
                    db.local_execution.initial_child_hidden.store(hidden.phase != .released, .release);
                }
                // A cold old owner must not start graph workers or admit graph
                // reads between reopening its index catalog and a resumed
                // coordinator observing the durable cutover fence.
                const graph_retirement = try graph_retirement_seal.status(&hidden_read);
                if (graph_retirement.intent != null)
                    db.core.index_manager.setGraphRetirementAdmissionAssumeCatalogLock(false);
            }
            const optional_runtimes_initialized = opts.open_mode.allowsOptionalRuntimes() and opts.start_optional_runtimes and background_work_allowed;
            const optional_runtime_workers_enabled = optional_runtimes_initialized and opts.start_optional_runtime_workers;
            db.local_execution.optional_runtime_workers_enabled = optional_runtime_workers_enabled;
            if (optional_runtimes_initialized) {
                const init_optional_started_ns = monotonicTimeNs();
                try db.initOptionalRuntimes(&opts);
                profile.init_optional_runtimes_ns = elapsedSince(init_optional_started_ns);
            } else if (opts.enrichment) |*cfg| {
                // Read-only/status and standby opens never construct an
                // enrichment runtime, but the open contract still owns the
                // moved providers.
                deinitOwnedEnrichmentConfig(alloc, cfg);
                opts.enrichment = null;
            }

            try db.attachAlgebraicHllMaintenanceLane();

            const admission_prefix = try internal_keys.managedIndexAdmissionRootPrefixAlloc(alloc);
            defer alloc.free(admission_prefix);
            const managed_admissions = try db.core.store.scanPrefix(alloc, admission_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, managed_admissions);
            try db.core.index_manager.replaceManagedAdmissionSnapshot(managed_admissions);
            if (managed_admissions.len != 0 and !openModeRequiresReadOnlyBackends(opts.open_mode)) {
                db.requestManagedAdmissionMaterialization();
            }

            if (opts.primary_only_readonly and opts.open_mode != .query_readonly) return error.UnsupportedOperation;
            if (opts.open_mode == .query_readonly) {
                const pending_merge = try missingAsNull(db.core.store.get(alloc, graph_merge_import_recovery_key));
                if (pending_merge) |record| {
                    alloc.free(record);
                    return error.GraphMaintenanceInProgress;
                }
            }
            if (opts.open_mode == .status_only or opts.primary_only_readonly) {
                try db.core.loadIndexCatalogOnly();
            } else if (opts.open_mode == .query_readonly) {
                const load_indexes_started_ns = monotonicTimeNs();
                try db.core.loadIndexesNoBackfill();
                profile.load_indexes_ns = elapsedSince(load_indexes_started_ns);
            } else {
                const load_indexes_started_ns = monotonicTimeNs();
                if (opts.defer_index_backfill_on_open) try db.core.loadIndexesDeferredBackfill() else try db.core.loadIndexes();
                profile.load_indexes_ns = elapsedSince(load_indexes_started_ns);
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                for (db.core.index_manager.graph_indexes.items) |entry| if (entry.ttl_duration_ns != 0) {
                    try db.core.index_manager.aggregateAuthoritativeReaderVersion(db.core.store, resolver_catalog_mod.graph_expiration_namespace_reader_version);
                    break;
                };
                try finishGraphMergeImport(&db, null);
            }
            // Validate the physical snapshot while the opened generation is
            // still untouched by replay and background workers. Status can
            // then retain this proof as live writes advance past the durable
            // checkpoint's cardinality.
            if (opts.open_mode != .status_only) db.validateOpenedDenseServingCertificates();
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // Catalog admission and its outbox are one primary-store
                // commit. Materialize any crash-surviving outbox before replay
                // or workers can observe the newly loaded generation.
                try db.drainManagedIndexAdmissions(alloc);
                var repair_state: ?index_repair_state.State = db.loadOrCreateCurrentIndexRepairState(alloc) catch |err| switch (err) {
                    error.DurableIndexRepairStateUnavailable => null,
                    error.InvalidIndexRepairState => invalid_state_blk: {
                        // Preserve primary availability, but fail every derived
                        // index closed and retain the complete replay journal.
                        // Without a trustworthy intent/pin checkpoint no
                        // projection may prove serviceability or authorize
                        // truncation.
                        db.async_context.index_repair_state_corrupt.store(true, .release);
                        db.async_context.index_repair_replay_pinned.store(true, .release);
                        break :invalid_state_blk null;
                    },
                    else => return err,
                };
                if (repair_state) |*state| {
                    state.deinit(alloc);
                    repair_state = null;
                    try db.removeOrphanedIndexRepairIntents(alloc);
                    repair_state = db.loadIndexRepairState(alloc) catch |err| switch (err) {
                        error.FileNotFound => null,
                        else => return err,
                    };
                }
                if (repair_state) |*state| {
                    for (state.entries.items) |entry| {
                        if (entry.intent.phase != .terminal and entry.intent.automation == .enabled) {
                            db.async_context.visibility_observer.replay_pending = true;
                            break;
                        }
                    }
                    db.async_context.index_repair_replay_pinned.store(state.minimumRetainAfterSequence() != null, .release);
                    state.deinit(alloc);
                }
            }
            // The primary-store marker is the admission authority. Install its
            // gate in every mode before consulting the materialized checkpoint so
            // a crash between those two writes cannot expose an empty index.
            try db.core.index_manager.markManagedAdmissionsUnavailable();
            try db.refreshIndexRepairAvailabilityGate(alloc);
            if (opts.open_mode != .status_only) {
                db.hydrateAlgebraicObservationStatusBestEffort();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // A pending intent may still need both its candidate and the
                // previously active generation for rollback. Orphan cleanup
                // is safe only after durable repair debt is absent; malformed
                // state also fails closed and retains every possible anchor.
                const has_durable_repair_debt = db.hasPendingIndexRepairIntents(alloc) catch true;
                if (!has_durable_repair_debt) db.scheduleInactiveRepairShadowCleanup();
            }
            if (opts.open_mode != .status_only) {
                try db.rebaseManagedIndexAppliedSequencesIfNeeded();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                _ = try db.rebuildArtifactRepairSummaryIfMissing(alloc);
                _ = try db.rebuildArtifactRepairKindIndexIfMissing(alloc);
                try db.persistIndexLoadFailuresFromManager(alloc);
            }
            db.recordStartupOpenStats(profile);
            const split_retire_cursor = try missingAsNull(db.core.store.get(alloc, graph_split_retire_cursor_key));
            if (split_retire_cursor) |cursor| {
                alloc.free(cursor);
                if (openModeRequiresReadOnlyBackends(opts.open_mode)) {
                    if (opts.open_mode == .query_readonly) return error.GraphMaintenanceInProgress;
                } else {
                    // Precommit retirement can be interrupted with graph
                    // pages already withdrawn. Restore them from still-owned
                    // primary artifacts before this reopened DB serves reads.
                    try recoverInterruptedGraphSplitRetirement(&db);
                }
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                const graph_due_rebuild = try missingAsNull(db.core.store.get(alloc, graph_edge_ttl_due_rebuild_marker));
                if (graph_due_rebuild) |marker| {
                    alloc.free(marker);
                    try rebuildGraphTtlDueIndexInRange(alloc, db.core.store, db.core.index_manager, db.core.index_manager.byte_range);
                    try db.core.store.delete(graph_edge_ttl_due_rebuild_marker);
                }
            }
            if (opts.open_mode.allowsReplay()) {
                const replay_started_ns = monotonicTimeNs();
                replayPendingDerivedBatches(&db, null, null, .{}) catch |err| switch (err) {
                    error.ArtifactRepairRequired => {},
                    else => return err,
                };
                profile.replay_pending_derived_ns = elapsedSince(replay_started_ns);
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // A crash after the primary split commit can leave a durable
                // source fence active. Finish its replayable prune pages before
                // this owner serves reads of retained document-owned edges.
                while (try db.core.index_manager.runGraphOwnershipCleanupStep()) {}
            } else if (opts.open_mode == .query_readonly and db.core.index_manager.graphOwnershipCleanupPending()) {
                // A read-only backend cannot finish a pending source fence.
                // Serving it would hide retained-owner edges until a writable
                // recovery completed, so refuse this snapshot explicitly.
                return error.GraphMaintenanceInProgress;
            }
            if (optional_runtime_workers_enabled) {
                try db.resumeGeneratedReplayFromJournalIfNeeded();
            }
            if (db.start_index_workers) {
                const start_workers_started_ns = monotonicTimeNs();
                try startAsyncWorkers(&db);
                if (opts.open_mode.allowsReplay()) {
                    db.resumeAsyncReplayFromJournalIfNeeded();
                }
                profile.start_index_workers_ns = elapsedSince(start_workers_started_ns);
            }
            if (optional_runtime_workers_enabled) {
                const start_optional_started_ns = monotonicTimeNs();
                try db.startOptionalRuntimes();
                profile.start_optional_runtimes_ns = elapsedSince(start_optional_started_ns);
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // A durable outbox is a write-ordering obligation, not a read
                // availability dependency. Stable resident owners schedule
                // recovery after this movable DB value reaches its final
                // address; the first mutation retains a synchronous crash-order
                // barrier in case scheduling has not completed yet.
                if (db.core.table_catalog.index_state != .none and
                    db.core.table_catalog.index_state != .ready)
                    db.reconcilePublishedSchemaIndexes(db.core.table_catalog.active_schema_version);
                // Cleanup jobs can call back into repair/coverage state. Submit
                // them only after startup replay and optional runtimes have
                // completed initialization, so open remains single-threaded.
                db.scheduleGeneratedArtifactCleanup();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) _ = try db.drainStandaloneGraphEndpointCleanup();
            profile.total_ns = monotonicTimeNs() - open_started_ns;
            if (openProfileEnabled()) {
                logOpenProfile(path, opts.open_mode, db.start_index_workers, profile);
            }
            break :blk db;
        };
    }

    pub const resolveNativeRestoreOpenPlan = db_restore.resolveNativeRestoreOpenPlan;

    pub const nativeRestoreStoragePublicationCompatible = db_restore.nativeRestoreStoragePublicationCompatible;

    pub const nativeRestorePrimaryStoragePublicationCompatible = db_restore.nativeRestorePrimaryStoragePublicationCompatible;

    fn initializeTableStorage(self: *DB, requested: ?table_storage_mod.Settings) !void {
        var migration_job = try vector_migration.load(self.alloc, self.core.store);
        defer if (migration_job) |*job| job.deinit();
        const raw = try missingAsNull(self.core.store.get(self.alloc, &internal_keys.table_storage_settings_key));
        defer if (raw) |value| self.alloc.free(value);
        if (raw) |value| {
            var parsed = try std.json.parseFromSlice(table_storage_mod.Settings, self.alloc, value, .{});
            defer parsed.deinit();
            if (requested) |settings| {
                if (settings.dense_embeddings != parsed.value.dense_embeddings) {
                    // Only this table's durable ownership publication can
                    // bridge a catalog update interrupted after DB commit.
                    const job = if (migration_job) |job| job.value else return error.ImmutableTableStorageSettings;
                    try self.validateVectorMigrationIdentity(job);
                    if (!job.published() or settings.dense_embeddings != .primary_lsm or
                        parsed.value.dense_embeddings != .vector_store) return error.ImmutableTableStorageSettings;
                }
            }
            self.local_execution.table_storage = parsed.value;
            if (self.local_execution.table_storage.dense_embeddings == .vector_store) {
                const source_open_started = monotonicTimeNs();
                try self.openSourceVectors(false);
                const source_open_ns = elapsedSince(source_open_started);
                const source_recovery_started = monotonicTimeNs();
                // Source/primary WAL recovery establishes durable authority.
                // Reclamation is not a prerequisite for reading committed
                // payloads: retain failed preparations and old versions until
                // the stable DB maintenance owner completes a bounded mark.
                if (!openModeRequiresReadOnlyBackends(self.open_mode))
                    try self.refreshSourceVectorOwnershipScopes();
                const source_recovery_ns = elapsedSince(source_recovery_started);
                const source_generation_started = monotonicTimeNs();
                try self.core.index_manager.refreshSourcePayloadGeneration();
                if (openProfileEnabled()) std.log.info("db_source_open_profile path={s} open_ns={} recovery_ns={} generation_ns={}", .{ self.core.path, source_open_ns, source_recovery_ns, elapsedSince(source_generation_started) });
            }
        } else if (requested) |settings| {
            if (openModeRequiresReadOnlyBackends(self.open_mode)) {
                if (settings.dense_embeddings != .primary_lsm) return error.MissingTableStorageSettings;
            } else try self.configureTableStorage(settings);
        }
        if (migration_job) |job| {
            try self.validateVectorMigrationIdentity(job.value);
            if (job.value.published() != (self.local_execution.table_storage.dense_embeddings == .vector_store))
                return error.InvalidVectorMigrationState;
            if (job.value.phase == .cancelled) {
                if (self.local_execution.table_storage.dense_embeddings != .primary_lsm) return error.InvalidVectorMigrationState;
                // No primary reference was ever published by a cancelled job.
                // At open there are no local sessions/workers to race teardown;
                // other process read mappings retain their own file leases.
                if (!openModeRequiresReadOnlyBackends(self.open_mode)) {
                    const root = try std.fs.path.join(self.alloc, &.{ self.core.path, "source-vectors" });
                    defer self.alloc.free(root);
                    if (self.primary_lsm_storage) |storage| {
                        storage.deleteTree(root) catch |err| {
                            std.log.warn("cancelled source candidate cleanup deferred err={s}", .{@errorName(err)});
                        };
                    } else if (comptime builtin.os.tag != .freestanding) {
                        const io = self.backend_runtime.filesystemIo() orelse return error.MissingBackendRuntimeIo;
                        std.Io.Dir.cwd().deleteTree(io, root) catch |err| {
                            std.log.warn("cancelled source candidate cleanup deferred err={s}", .{@errorName(err)});
                        };
                    } else return error.UnsupportedPlatform;
                }
            } else if (job.value.active()) {
                try self.openSourceVectors(false);
                self.installVectorMigrationRuntime(job.value);
            }
        }
    }

    pub fn validateVectorMigrationIdentity(self: *DB, job: vector_migration.contract.Job) !void {
        const identity = try std.json.Stringify.valueAlloc(self.alloc, self.core.identity_namespace, .{});
        defer self.alloc.free(identity);
        if (!std.mem.eql(u8, identity, job.table_identity)) return error.VectorMigrationIdentityMismatch;
    }

    fn vectorMigrationConfigurationHash(self: *DB) !u64 {
        const indexes = try self.core.listIndexes(self.alloc);
        defer types.freeIndexConfigs(self.alloc, indexes);
        const enrichments = try self.core.listEnrichments(self.alloc);
        defer types.freeEnrichmentConfigs(self.alloc, enrichments);
        const encoded = try std.json.Stringify.valueAlloc(self.alloc, .{
            .schema = self.core.schema,
            .indexes = indexes,
            .enrichments = enrichments,
        }, .{});
        defer self.alloc.free(encoded);
        return std.hash.Wyhash.hash(0, encoded);
    }

    fn installVectorMigrationRuntime(self: *DB, job: vector_migration.contract.Job) void {
        self.local_execution.vector_migration_active.store(job.active(), .release);
        const source = self.local_execution.source_vectors.load(.acquire) orelse return;
        source.setMigrationRetention(job.active());
        source.migration_disk_reserve.store(if (job.active()) job.budget.disk_reserve_bytes else 0, .release);
        source.migration_temporary_limit.store(if (job.active()) job.budget.temporary_bytes else 0, .release);
        self.core.store.configurePayloadPolicy(
            if (job.phase == .cancelling or job.phase == .cancelled) null else source.interface(),
            job.captures(),
            if (job.active()) job.budget.temporary_bytes else null,
        );
    }

    pub fn authorizeOfflineVectorMigrationCandidate(self: *DB, stage: *const generation_lifecycle.StagedGeneration) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, stage });
        try stage.validatePath(self.core.path);
        self.local_execution.vector_migration_offline_candidate = true;
    }

    pub fn vectorMigrationCommand(self: *DB, alloc: Allocator, command: vector_migration.contract.Command) ![]u8 {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc, command });
        try command.request.validate();
        if (command.action != .start and command.action != .cancel) {
            const raw = try self.vectorMigrationStatus(alloc) orelse return error.VectorMigrationNotFound;
            defer alloc.free(raw);
            var prior = try std.json.parseFromSlice(vector_migration.contract.Job, alloc, raw, .{});
            defer prior.deinit();
            if (command.action == .status) {
                if (!std.mem.eql(u8, prior.value.job_id, command.request.job_id)) return error.VectorMigrationNotFound;
                return try alloc.dupe(u8, raw);
            }
            if (!std.mem.eql(u8, prior.value.job_id, command.request.job_id) or
                prior.value.mode != command.request.mode or !std.meta.eql(prior.value.budget, command.request.budget))
                return error.VectorMigrationIdempotencyConflict;
        }
        switch (command.action) {
            .start => try self.startVectorMigration(command.request),
            .step => try self.advanceVectorMigration(command.request.job_id),
            .publish => try self.publishVectorMigration(command.request.job_id),
            .cancel => try self.cancelVectorMigrationImpl(command.request.job_id, command.request),
            .status => {},
        }
        const result = try self.vectorMigrationStatus(alloc) orelse return error.VectorMigrationNotFound;
        errdefer alloc.free(result);
        var parsed = try std.json.parseFromSlice(vector_migration.contract.Job, alloc, result, .{});
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.job_id, command.request.job_id)) return error.VectorMigrationIdempotencyConflict;
        return result;
    }

    pub fn vectorMigrationStatus(self: *DB, alloc: Allocator) !?[]u8 {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        var job = (try vector_migration.load(alloc, self.core.store)) orelse return null;
        defer job.deinit();
        if (self.core.store.get(alloc, vector_migration.contract.accounting_key)) |bytes| {
            defer alloc.free(bytes);
            if (bytes.len != 8) return error.InvalidVectorMigrationState;
            job.value.charged_temporary_bytes = std.mem.readInt(u64, bytes[0..8], .little);
        } else |err| if (err != error.NotFound) return err;
        return try std.json.Stringify.valueAlloc(alloc, job.value, .{});
    }

    pub fn startVectorMigration(self: *DB, request: vector_migration.contract.Request) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, request });
        try request.validate();
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (request.mode == .offline and !self.local_execution.vector_migration_offline_candidate) return error.VectorStoreRequiresOfflineCommand;
        var structural = self.beginIndexStructuralMutation("source ownership migration", "*");
        defer structural.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var ownership_epoch: u64 = 1;
        if (try vector_migration.load(self.alloc, self.core.store)) |existing| {
            var job = existing;
            defer job.deinit();
            try self.validateVectorMigrationIdentity(job.value);
            if (std.mem.eql(u8, job.value.job_id, request.job_id)) {
                if (job.value.mode != request.mode or !std.meta.eql(job.value.budget, request.budget))
                    return error.VectorMigrationIdempotencyConflict;
                return;
            }
            if (job.value.phase != .cancelled) return error.VectorMigrationAlreadyExists;
            ownership_epoch = try std.math.add(u64, job.value.ownership_epoch, 1);
        }
        if (self.local_execution.table_storage.dense_embeddings != .primary_lsm) return error.VectorMigrationAlreadyPublished;
        if (self.core.splitState() != null) return error.VectorStoreLifecycleUnsupported;
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            // Configuration will be frozen for the migration's lifetime.
            // Do not strand an already-admitted catalog transition behind
            // that freeze; let its durable owner finish before capturing it.
            try self.requireArtifactReconcileUnfenced(&read, null);
        }
        for (self.core.index_manager.dense_indexes.items) |entry| {
            if (!entry.native_physical_v2 and !try self.core.index_manager.denseNativePhysicalMigrationRequired(entry.config.name))
                return error.VectorStoreLifecycleUnsupported;
        }
        const identity = try std.json.Stringify.valueAlloc(self.alloc, self.core.identity_namespace, .{});
        defer self.alloc.free(identity);
        const configuration_hash = try self.vectorMigrationConfigurationHash();
        const disk = try platform.filesystem.capacity(self.core.path);
        if (disk.available_bytes < request.budget.disk_reserve_bytes +| request.budget.batch_bytes * 8)
            return error.VectorMigrationDiskReserve;
        // The source manifest is durable before the primary job admits any
        // capture. A crash before the job commit leaves only orphan data.
        try self.openSourceVectors(true);
        try self.local_execution.source_vectors.load(.acquire).?.beginMigrationRetention();
        errdefer self.requireVectorMigrationRecovery();
        const raw_epoch = try missingAsNull(self.core.store.get(self.alloc, artifact_payload_mod.reference_epoch_key));
        defer if (raw_epoch) |value| self.alloc.free(value);
        const epoch: u64 = if (raw_epoch) |value| blk: {
            if (value.len != 8) return error.InvalidVectorReferenceEpoch;
            break :blk std.mem.readInt(u64, value[0..8], .little);
        } else 0;
        const job: vector_migration.contract.Job = .{
            .job_id = request.job_id,
            .mode = request.mode,
            .budget = request.budget,
            .table_identity = identity,
            .configuration_hash = configuration_hash,
            .ownership_epoch = ownership_epoch,
            .snapshot_fence = epoch,
            .replay_cursor = epoch,
        };
        var txn = try self.core.store.runtime_store.beginWrite();
        var committed = false;
        defer if (!committed) txn.abort();
        try vector_migration.save(self.alloc, &txn, job);
        try txn.put(vector_migration.contract.accounting_key, &(@as([8]u8, @splat(0))));
        try txn.commit();
        committed = true;
        try self.core.store.runtime_store.sync(true);
        self.installVectorMigrationRuntime(job);
    }

    pub fn advanceVectorMigration(self: *DB, job_id: []const u8) anyerror!void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, job_id });
        var zig017_return_error: ?anyerror = null;
        // Staging pins index/catalog lifetime but never holds table apply over
        // corpus-sized ANN work. Completion is checked again under apply.
        const status = (self.vectorMigrationStatus(self.alloc) catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        }) orelse return zig017_failure: {
            zig017_return_error = error.VectorMigrationNotFound;
            break :zig017_failure error.VectorMigrationNotFound;
        };
        defer self.alloc.free(status);
        var observed = (std.json.parseFromSlice(vector_migration.contract.Job, self.alloc, status, .{}) catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        });
        defer observed.deinit();
        if (!std.mem.eql(u8, observed.value.job_id, job_id)) return zig017_failure: {
            zig017_return_error = error.VectorMigrationIdempotencyConflict;
            break :zig017_failure error.VectorMigrationIdempotencyConflict;
        };
        // Reopening can restore a post-publication receipt before optional
        // serving projections are ready. Resume their bounded publication in
        // every destructive phase, not just the first serving transition.
        if (observed.value.phase == .serving or observed.value.phase == .cleanup or observed.value.phase == .reclaiming) {
            const legacy = blk: {
                var lease = self.tryAcquireIndexCatalogReadLease() orelse return;
                defer lease.release();
                if (self.core.index_manager.dense_indexes.items.len != 0 and
                    self.core.index_manager.source_payload_store == null) return;
                for (self.core.index_manager.dense_indexes.items) |entry| {
                    if ((self.core.index_manager.denseNativePhysicalMigrationRequired(entry.config.name) catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    }))
                        break :blk (self.alloc.dupe(u8, entry.config.name) catch |zig017_err| {
                            zig017_return_error = zig017_err;
                            return zig017_err;
                        });
                }
                break :blk null;
            };
            if (legacy) |name| {
                defer self.alloc.free(name);
                var repair = (self.repairArtifactIssuesWithRequest(self.alloc, .{ .target = .index, .index_name = name, .limit = 1 }) catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                defer repair.deinit(self.alloc);
            }
            _ = (self.publishVectorBlockBasesOnlineReported(.{ .require_quiescence = false, .require_storage_encoding = true }) catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
        }
        if (observed.value.phase == .reclaiming and observed.value.primary_reclamation_requested) {
            // Offline operators have no maintenance worker. Online execution
            // uses the same bounded scheduler without holding the table apply
            // lock over streaming compaction I/O.
            _ = (self.core.primary_store_owner.lsm.handle.backend.runValueReclamationStep() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
        }
        (self.lockApplyForPortableRuntime() catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        });
        defer self.core.unlockApply();
        var job = ((vector_migration.load(self.alloc, self.core.store) catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        })) orelse return zig017_failure: {
            zig017_return_error = error.VectorMigrationNotFound;
            break :zig017_failure error.VectorMigrationNotFound;
        };
        defer job.deinit();
        if (!std.mem.eql(u8, job.value.job_id, job_id)) return zig017_failure: {
            zig017_return_error = error.VectorMigrationIdempotencyConflict;
            break :zig017_failure error.VectorMigrationIdempotencyConflict;
        };
        (self.validateVectorMigrationIdentity(job.value) catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        });
        if (job.value.configuration_hash != (self.vectorMigrationConfigurationHash() catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        })) return zig017_failure: {
            zig017_return_error = error.VectorMigrationConfigurationChanged;
            break :zig017_failure error.VectorMigrationConfigurationChanged;
        };
        if (!job.value.active() or job.value.phase == .ready) return;
        errdefer if (zig017_return_error) |err| switch (@as(anyerror, err)) {
            error.VectorMigrationTemporaryBudgetExceeded, error.VectorMigrationDiskReserve, error.VectorMigrationRowExceedsBudget => {},
            else => self.requireVectorMigrationRecovery(),
        };
        // The durable phase alone is not a proof about this owner lifetime.
        // Preserve source data and the active receipt until all loaded ANN
        // indexes can serve from the converted storage after recovery.
        if ((job.value.phase == .cleanup or job.value.phase == .reclaiming) and
            !self.core.index_manager.sourceMigrationServingComplete()) return;
        if (job.value.phase == .reclaiming) {
            const backend = self.core.primary_store_owner.lsm.handle.backend;
            if (!job.value.primary_reclamation_requested) {
                // One final flush includes all replacements and candidate
                // deletes before requesting the old overlap closures. Persist
                // the manifest request before its primary receipt. A crash
                // between them safely repeats the request after reopening.
                (self.core.store.runtime_store.sync(true) catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                (backend.requestValueReclamation() catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                (vector_migration.boundary(.reclamation_request) catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                job.value.primary_reclamation_requested = true;
            } else {
                if ((backend.hasValueReclamationRequests() catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                })) return;
                // Fence the manifest that discharged the last request before
                // reporting completion. Pinned readers may retain old files.
                (backend.persistManifest() catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                job.value.phase = .complete;
            }
            var txn = (self.core.store.runtime_store.beginWrite() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            var committed = false;
            defer if (!committed) txn.abort();
            (vector_migration.save(self.alloc, &txn, job.value) catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            (txn.commit() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            committed = true;
            (self.core.store.runtime_store.syncReplayState() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            (vector_migration.boundary(.reclamation_receipt) catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
        } else if (job.value.phase == .serving) {
            if (!self.core.index_manager.sourceMigrationServingComplete()) return;
            job.value.phase = .cleanup;
            var txn = (self.core.store.runtime_store.beginWrite() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            var committed = false;
            defer if (!committed) txn.abort();
            (vector_migration.save(self.alloc, &txn, job.value) catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            (txn.commit() catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
            committed = true;
            (self.core.store.runtime_store.sync(true) catch |zig017_err| {
                zig017_return_error = zig017_err;
                return zig017_err;
            });
        } else vector_migration.advance(self.alloc, self.core.store, self.local_execution.source_vectors.load(.acquire).?.interface(), job.value) catch |err| {
            switch (err) {
                error.VectorMigrationTemporaryBudgetExceeded, error.VectorMigrationDiskReserve, error.VectorMigrationRowExceedsBudget => {
                    // Known pre-preparation admission failure: preserve progress
                    // and expose the reason without requiring a DB restart.
                    job.value.last_error = @errorName(err);
                    var txn = (self.core.store.runtime_store.beginWrite() catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    });
                    var committed = false;
                    defer if (!committed) txn.abort();
                    (vector_migration.save(self.alloc, &txn, job.value) catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    });
                    (txn.commit() catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    });
                    committed = true;
                    (self.core.store.runtime_store.sync(true) catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    });
                },
                else => {},
            }
            zig017_return_error = err;
            return err;
        };
        var next = ((vector_migration.load(self.alloc, self.core.store) catch |zig017_err| {
            zig017_return_error = zig017_err;
            return zig017_err;
        })).?;
        defer next.deinit();
        self.installVectorMigrationRuntime(next.value);
    }

    pub fn publishVectorMigration(self: *DB, job_id: []const u8) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, job_id });
        var structural = self.beginIndexStructuralMutation("source ownership publication", "*");
        defer structural.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var job = (try vector_migration.load(self.alloc, self.core.store)) orelse return error.VectorMigrationNotFound;
        defer job.deinit();
        if (!std.mem.eql(u8, job.value.job_id, job_id)) return error.VectorMigrationIdempotencyConflict;
        try self.validateVectorMigrationIdentity(job.value);
        if (job.value.configuration_hash != try self.vectorMigrationConfigurationHash()) return error.VectorMigrationConfigurationChanged;
        if (job.value.published()) return;
        if (job.value.phase != .ready) return error.VectorMigrationNotReady;
        errdefer self.requireVectorMigrationRecovery();
        try vector_migration.publish(self.alloc, self.core.store, job.value);
        self.local_execution.table_storage = .{ .dense_embeddings = .vector_store };
        self.core.store.configurePayloadPolicy(self.local_execution.source_vectors.load(.acquire).?.interface(), false, job.value.budget.temporary_bytes);
        self.core.index_manager.table_owns_embedding_artifacts = true;
        self.core.index_manager.source_payload_store = self.local_execution.source_vectors.load(.acquire);
        try self.refreshSourceVectorOwnershipScopes();
        try self.core.index_manager.refreshSourcePayloadGeneration();
    }

    pub fn cancelVectorMigration(self: *DB, job_id: []const u8) !void {
        return self.cancelVectorMigrationImpl(job_id, null);
    }

    fn cancelVectorMigrationImpl(self: *DB, job_id: []const u8, admitted: ?vector_migration.contract.Request) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var prior = try vector_migration.load(self.alloc, self.core.store);
        defer if (prior) |*value| value.deinit();
        // A catalog admission can outlive a rejected/ambiguous DB start. Under
        // the same apply lock as startup, save a terminal receipt before the
        // caller releases the catalog fence. No source payload was committed
        // without a DB job, so there is no candidate cleanup to drive here.
        if (prior == null or (prior.?.value.phase == .cancelled and !std.mem.eql(u8, prior.?.value.job_id, job_id))) {
            const request = admitted orelse return error.VectorMigrationNotFound;
            if (self.local_execution.table_storage.dense_embeddings != .primary_lsm) return error.VectorMigrationAlreadyPublished;
            if (prior) |value| try self.validateVectorMigrationIdentity(value.value);
            const identity = try std.json.Stringify.valueAlloc(self.alloc, self.core.identity_namespace, .{});
            defer self.alloc.free(identity);
            const receipt: vector_migration.contract.Job = .{
                .job_id = request.job_id,
                .mode = request.mode,
                .budget = request.budget,
                .phase = .cancelled,
                .table_identity = identity,
                .configuration_hash = try self.vectorMigrationConfigurationHash(),
                .ownership_epoch = if (prior) |value| try std.math.add(u64, value.value.ownership_epoch, 1) else 1,
                .snapshot_fence = 0,
                .replay_cursor = 0,
            };
            var txn = try self.core.store.runtime_store.beginWrite();
            var committed = false;
            defer if (!committed) txn.abort();
            errdefer self.requireVectorMigrationRecovery();
            try vector_migration.save(self.alloc, &txn, receipt);
            try txn.put(vector_migration.contract.accounting_key, &(@as([8]u8, @splat(0))));
            try txn.commit();
            committed = true;
            try self.core.store.runtime_store.sync(true);
            self.installVectorMigrationRuntime(receipt);
            return;
        }
        const job = &prior.?;
        if (!std.mem.eql(u8, job.value.job_id, job_id)) return error.VectorMigrationIdempotencyConflict;
        if (admitted) |request| {
            if (job.value.mode != request.mode or !std.meta.eql(job.value.budget, request.budget))
                return error.VectorMigrationIdempotencyConflict;
        }
        try self.validateVectorMigrationIdentity(job.value);
        if (job.value.published()) return error.VectorMigrationAlreadyPublished;
        if (job.value.phase == .cancelled or job.value.phase == .cancelling) return;
        job.value.phase = .cancelling;
        job.value.cursor = "";
        var txn = try self.core.store.runtime_store.beginWrite();
        var committed = false;
        defer if (!committed) txn.abort();
        errdefer self.requireVectorMigrationRecovery();
        try vector_migration.save(self.alloc, &txn, job.value);
        try txn.commit();
        committed = true;
        try self.core.store.runtime_store.sync(true);
        self.installVectorMigrationRuntime(job.value);
    }

    pub const requireVectorMigrationRecovery = db_repair.requireVectorMigrationRecovery;

    pub fn enforceVectorMigrationConfigurationGate(self: *const DB) !void {
        if (self.local_execution.vector_migration_active.load(.acquire)) return error.VectorMigrationActive;
    }

    fn openSourceVectors(self: *DB, create: bool) !void {
        if (self.local_execution.source_vectors.load(.acquire) != null) return;
        const external_read = self.open_mode == .query_readonly and
            self.physical_root_mode == .external_backend and !create;
        if (self.primary_backend != .lsm or (!external_read and self.physical_root_mode != .filesystem_managed) or
            self.local_execution.replication_write_gate != null or self.local_execution.replication_async_batch_mirror != null or self.local_execution.replication_async_effect_mirror != null)
            return error.VectorStoreRequiresLocalSingleShardTable;
        var native: ?*lsm_backend_mod.NativeStorage = null;
        errdefer if (native) |owned| {
            owned.deinit();
            self.alloc.destroy(owned);
        };
        const storage = if (external_read)
            self.primary_lsm_storage orelse return error.VectorStoreRequiresLocalSingleShardTable
        else owned: {
            const value = try self.alloc.create(lsm_backend_mod.NativeStorage);
            value.* = lsm_backend_mod.NativeStorage.init(self.alloc, .threaded) catch |err| {
                self.alloc.destroy(value);
                return err;
            };
            native = value;
            break :owned value.storage();
        };
        const root = try std.fs.path.join(self.alloc, &.{ self.core.path, "source-vectors" });
        defer self.alloc.free(root);
        if (!create) {
            const current = try std.fs.path.join(self.alloc, &.{ root, "CURRENT" });
            defer self.alloc.free(current);
            _ = storage.fileSize(current) catch |err| switch (err) {
                error.FileNotFound => return error.MissingVectorPayloadStore,
                else => return err,
            };
        }
        const source = try self.alloc.create(vector_payload_store_mod.Store);
        errdefer self.alloc.destroy(source);
        var source_policy = vector_payload_store_mod.Store.OpenPolicy.fromEnvironment();
        source_policy.inventory_read_only = self.open_mode != .query_readonly;
        source.* = try vector_payload_store_mod.Store.openManagedWithPolicy(self.alloc, self.core.index_manager.resource_manager, storage, root, openModeRequiresReadOnlyBackends(self.open_mode), source_policy);
        errdefer source.deinit();
        if (!external_read) source.enableBackgroundCollection();
        source.ann_reference_root = try std.fs.path.join(source.alloc, &.{ self.core.index_manager.base_path, "vector-blocks" });
        self.source_vector_storage = native;
        self.local_execution.source_vectors.store(source, .release);
        if (self.local_execution.table_storage.dense_embeddings == .vector_store) {
            self.core.store.configurePayloadPolicy(source.interface(), false, null);
            self.core.index_manager.table_owns_embedding_artifacts = true;
            self.core.index_manager.source_payload_store = source;
        }
    }

    /// Creation/provisioning-only configuration. Existing persisted authority
    /// cannot be changed, and populated roots require an explicit migration.
    pub fn configureTableStorage(self: *DB, settings: table_storage_mod.Settings) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, settings });
        if (settings.engine != .local) return error.ObjectStorageRequiresHostedTable;
        lockApply(self);
        defer self.core.unlockApply();
        const raw = try missingAsNull(self.core.store.get(self.alloc, &internal_keys.table_storage_settings_key));
        defer if (raw) |value| self.alloc.free(value);
        if (raw) |value| {
            var parsed = try std.json.parseFromSlice(table_storage_mod.Settings, self.alloc, value, .{});
            defer parsed.deinit();
            if (parsed.value.dense_embeddings != settings.dense_embeddings) return error.ImmutableTableStorageSettings;
            return;
        }
        if (settings.dense_embeddings == .vector_store) {
            var txn = try self.core.store.beginReadTxn();
            defer txn.abort();
            var cursor = try txn.openCursor();
            defer cursor.close();
            if (try cursor.seekAtOrAfter(&.{internal_keys.user_namespace})) |entry| {
                if (internal_keys.isInternalUserKey(entry.key)) return error.VectorStoreRequiresEmptyTable;
            }
            try self.openSourceVectors(true);
        }
        const encoded = try std.json.Stringify.valueAlloc(self.alloc, settings, .{});
        defer self.alloc.free(encoded);
        // A failed primary append/sync may have persisted the marker. Fence
        // source writes until reopen resolves that outcome; never continue
        // creating references under an unconfirmed table mode.
        errdefer if (self.local_execution.source_vectors.load(.acquire)) |source| {
            source.poison();
        };
        try self.core.store.put(&internal_keys.table_storage_settings_key, encoded);
        try self.core.store.sync(true);
        self.local_execution.table_storage = settings;
        if (settings.dense_embeddings == .vector_store) {
            const source = self.local_execution.source_vectors.load(.acquire).?;
            self.core.store.configurePayloadPolicy(source.interface(), false, null);
            self.core.index_manager.table_owns_embedding_artifacts = true;
            self.core.index_manager.source_payload_store = source;
        }
    }

    /// Null means source storage is disabled. Contention is retryable, never
    /// evidence that a configured source store or its accounting is absent.
    pub fn sourceVectorStats(self: *DB) error{StorageBusy}!?vector_payload_store_mod.Stats {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self}) catch |err| switch (err) {
            error.StorageBusy => error.StorageBusy,
            else => @panic("incompatible storage owner"),
        };
        const source = self.local_execution.source_vectors.load(.acquire) orelse return null;
        return source.tryStatsSnapshot() orelse error.StorageBusy;
    }

    pub fn refreshSourceVectorOwnershipScopes(self: *DB) !void {
        const source = self.local_execution.source_vectors.load(.acquire) orelse return;
        const configs = try self.core.listIndexes(self.alloc);
        defer types.freeIndexConfigs(self.alloc, configs);
        const scopes = try self.core.index_manager.sourcePayloadScopeHashesAlloc(configs);
        defer self.core.index_manager.alloc.free(scopes);
        try source.setAnnScopes(scopes);
    }

    /// Advance source-payload collection without waiting for retained readers.
    /// Returns true on completion, false if source storage is disabled or work
    /// is deferred/incomplete, and an error on failure. Immediate completion
    /// requires quiescent readers and sufficient per-call work/memory budgets;
    /// disabling index workers alone does not drain startup cleanup readers.
    pub fn collectSourceVectorGarbage(self: *DB) !bool {
        const source = self.local_execution.source_vectors.load(.acquire) orelse return false;
        try source.advanceMarkingSnapshot();
        lockApply(self);
        defer self.core.unlockApply();
        try self.refreshSourceVectorOwnershipScopes();
        const collected = try source.collectDeferredMark(&self.core.store.runtime_store);
        if (collected) try self.core.index_manager.refreshSourcePayloadGeneration();
        return collected;
    }

    pub const closeImmutableSnapshot = db_restore.closeImmutableSnapshot;

    pub fn close(self: *DB) void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self}) catch unreachable;
        if (self.closed) return;
        self.closed = true;
        self.restore_decoder_cache.deinit(self.backend_runtime.filesystemIo() orelse std.Options.debug_io);
        self.rewrite_program_cache.deinit(self.backend_runtime.io() orelse std.Options.debug_io);
        self.rewrite_tail_cache.deinit(self.backend_runtime.io() orelse std.Options.debug_io);
        self.deinitWrapperState(true);
    }

    /// Opens a DB in stable allocator-owned storage. Callers that retain the DB
    /// should prefer this form whenever background workers are enabled: worker
    /// callbacks may retain the DB address until `closeOwned` joins them.
    pub fn openOwned(alloc: Allocator, path: []const u8, opts: OpenOptions) !*DB {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ alloc, path, opts });
        const owned = try alloc.create(DB);
        errdefer alloc.destroy(owned);
        owned.* = try open(alloc, path, opts);
        errdefer owned.close();
        owned.startResidentBackgroundWorkersIfNeeded();
        return owned;
    }

    /// Mark a DB installed at its final address before scheduling any callback
    /// that borrows it. Resident caches and owned handles share this entry
    /// point so newly added maintenance cannot accidentally retain a movable
    /// stack value.
    pub fn startResidentBackgroundWorkersIfNeeded(self: *DB) void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self}) catch unreachable;
        self.stable_address = true;
        // TTL callbacks retain only stable context, never this movable wrapper.
        // The resident probe observes their atomic outbox notification.
        if (self.local_execution.replication_async_effect_mirror != null) self.publication_recovery.watch(self.publicationOutboxRecoveryPort());
        self.scheduleDurableReplicationOutboxRecovery();
        self.startArtifactRepairMetadataWorkerIfNeeded();
        self.startQuarantineRetryWorkerIfNeeded();
        self.startGraphEndpointCleanupWorker();
        self.group_source_owner.start(.{ .ptr = self, .runtime = self.backend_runtime, .run = runLocalGroupSourceSlice });
    }

    pub fn closeOwned(self: *DB) void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self}) catch unreachable;
        const owner_alloc = self.alloc;
        self.close();
        owner_alloc.destroy(self);
    }

    pub fn isClosed(self: *const DB) bool {
        return self.closed;
    }

    /// Named diagnostic for `error.RunUntilIdleNoProgress` (see
    /// `checkTargetAdvanceNoProgress`): exactly which managed index could not
    /// advance its derived replay target, and its last observed indexed vs.
    /// durable-expected counters when the bounded stall fired.
    pub const NoProgressDiagnostic = execution_resources.NoProgressDiagnostic;

    fn setLastRunUntilIdleNoProgressDiagnostic(
        self: *DB,
        index_name: []const u8,
        indexed: u64,
        expected: u64,
        stuck_ns: u64,
    ) !void {
        const owned_name = try self.alloc.dupe(u8, index_name);
        if (self.last_run_until_idle_no_progress) |*previous| previous.deinit(self.alloc);
        self.last_run_until_idle_no_progress = .{
            .index_name = owned_name,
            .indexed = indexed,
            .expected = expected,
            .stuck_ns = stuck_ns,
        };
    }

    /// Read-only view of the most recent no-progress diagnostic, if any.
    /// Valid until the next `runUntilIdle` call or `DB.close`.
