    pub var test_enrichment_restart_failures_remaining: std.atomic.Value(u32) = .init(0);
    pub var test_enrichment_reconfigure_after_detached_hook: ?*const fn (*DB) anyerror!void = null;

    pub const startEnrichmentRuntimeForLifecycle = db_enrichment.startEnrichmentRuntimeForLifecycle;

    pub const scheduleEnrichmentRestartContext = db_enrichment.scheduleEnrichmentRestartContext;
    pub const enrichmentRestartWanted = db_enrichment.enrichmentRestartWanted;
    pub const attemptEnrichmentRestart = db_enrichment.attemptEnrichmentRestart;
    const MaintenanceRuntimeKind = enum { text_merge, sparse_compaction };
    fn restartWanted(_: *anyopaque) bool {
        return true;
    }
    fn attemptTextMergeRestart(ptr: *anyopaque) !bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return if (ctx.text_merge_runtime) |runtime| try runtime.ensureRunning() else true;
    }
    fn attemptSparseCompactionRestart(ptr: *anyopaque) !bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return if (ctx.sparse_compaction_runtime) |runtime| try runtime.ensureRunning() else true;
    }
    fn scheduleMaintenanceRestartContext(ctx: *AsyncContext, lane: background_runtime_mod.DurableJobLane, owner_id: u64, kind: MaintenanceRuntimeKind) void {
        const owner = switch (kind) {
            .text_merge => &ctx.text_merge_restart_owner,
            .sparse_compaction => &ctx.sparse_compaction_restart_owner,
        };
        owner.schedule(.{ .ptr = ctx, .lane = lane, .owner_id = owner_id, .io = ctx.io, .closing = &ctx.background_closing, .wanted = restartWanted, .attempt = switch (kind) {
            .text_merge => attemptTextMergeRestart,
            .sparse_compaction => attemptSparseCompactionRestart,
        }, .name = @tagName(kind) });
    }

    pub const quiesceEnrichmentForStructuralMutation = db_enrichment.quiesceEnrichmentForStructuralMutation;

    pub fn quiesceTextMergeForStructuralMutation(self: *DB) bool {
        const runtime = self.text_merge_runtime orelse return false;
        return runtime.pause();
    }

    pub fn quiesceSparseCompactionForStructuralMutation(self: *DB) bool {
        const runtime = self.sparse_compaction_runtime orelse return false;
        return runtime.pause();
    }

    fn restartTextMergeAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.text_merge_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            // Index catalog durability is already decided at this point.
            // Queries and foreground indexing remain available; surface the
            // maintenance degradation without misreporting the mutation.
            std.log.warn("failed to restart text merge runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .text_merge,
            );
        };
    }

    fn restartSparseCompactionAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.sparse_compaction_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            std.log.warn("failed to restart sparse compaction runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .sparse_compaction,
            );
        };
    }

    pub const IndexStructuralMutationGuard = struct {
        db: *DB,
        snapshot_mutation: snapshot_admission_mod.SnapshotAdmission.MutationLease,
        operation: []const u8,
        index_name: []const u8,
        restart_text_merge: bool,
        restart_sparse_compaction: bool,
        catalog_barrier_held: bool = false,
        active: bool = true,

        pub fn acquireCatalogBarrierUntil(self: *@This(), deadline_ns: u64) bool {
            std.debug.assert(self.active and !self.catalog_barrier_held);
            if (!self.db.beginIndexCatalogBarrierUntil(deadline_ns)) return false;
            self.catalog_barrier_held = true;
            return true;
        }

        pub fn acquireCatalogBarrierWithCancellation(self: *@This(), io: std.Io, cancellation: types.CancellationToken) !void {
            std.debug.assert(self.active and !self.catalog_barrier_held);
            const admission = &self.db.core.index_manager.published_dense_admission;
            const previous = admission.fetchOr(published_dense_catalog_closed, .acq_rel);
            if (previous & published_dense_catalog_closed != 0) return error.IndexRebuilding;
            // A canceled acquisition has not changed catalog pointers. Reopen
            // admission while retaining every reader pin; the successful
            // mutation release still requires a completely drained barrier.
            errdefer {
                const aborted = admission.fetchAnd(published_dense_reader_mask, .release);
                std.debug.assert(aborted & published_dense_catalog_closed != 0);
            }
            while (admission.load(.acquire) & published_dense_reader_mask != 0) {
                try cancellation.check();
                try io.sleep(.fromMilliseconds(1), .awake);
            }
            try cancellation.check();
            self.catalog_barrier_held = true;
        }

        fn releaseCatalogBarrier(self: *@This()) void {
            if (!self.catalog_barrier_held) return;
            self.db.endIndexCatalogBarrier();
            self.catalog_barrier_held = false;
        }

        pub fn release(self: *@This()) void {
            if (!self.active) return;
            // The catalog is stable once the caller releases apply exclusive;
            // let lock-free dense searches resume before runtime startup work.
            self.releaseCatalogBarrier();
            // Restart while serialization is still held: another structural
            // mutation must not stop a runtime between this restart and the
            // corresponding unlock.
            if (self.restart_sparse_compaction) {
                self.db.restartSparseCompactionAfterStructuralMutation(self.operation, self.index_name);
            }
            if (self.restart_text_merge) {
                self.db.restartTextMergeAfterStructuralMutation(self.operation, self.index_name);
            }
            self.db.local_execution.index_structural_mutation_mutex.unlock();
            self.snapshot_mutation.release();
            self.active = false;
        }

        pub fn deinit(self: *@This()) void {
            self.release();
        }
    };

    /// Lightweight serialization for repair-control commits which bind to the
    /// current catalog incarnation but do not publish or retire runtime index
    /// pointers. Full structural mutations take the same mutex and additionally
    /// drain background pointer borrowers; discovery needs only the shared
    /// incarnation boundary and therefore does not stop merge/compaction work.
    const IndexCatalogIncarnationGuard = struct {
        db: *DB,
        active: bool = true,

        pub fn release(self: *@This()) void {
            if (!self.active) return;
            self.db.local_execution.index_structural_mutation_mutex.unlock();
            self.active = false;
        }

        pub fn deinit(self: *@This()) void {
            self.release();
        }
    };

    pub fn beginIndexCatalogIncarnationGuard(self: *DB) IndexCatalogIncarnationGuard {
        lockAtomicWithBackoff(&self.local_execution.index_structural_mutation_mutex);
        return .{ .db = self };
    }

    pub const QuarantineIndexPublicationFence = struct {
        db: *DB,
        structural_guard: ?IndexStructuralMutationGuard = null,
        apply_locked: bool = false,

        pub fn iface(self: *@This()) index_manager_mod.IndexManager.CatalogPublicationFence {
            return .{
                .ptr = self,
                .lock_fn = lockOpaque,
                .unlock_fn = unlockOpaque,
            };
        }

        fn lockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.structural_guard == null and !self.apply_locked);
            self.structural_guard = self.db.beginIndexStructuralMutation("quarantined index publication", "*");
            if (builtin.is_test) test_quarantine_publication_fence_entered.store(true, .release);
            lockApply(self.db);
            self.apply_locked = true;
        }

        fn unlockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.apply_locked and self.structural_guard != null);
            self.db.core.unlockApply();
            self.apply_locked = false;
            self.structural_guard.?.release();
            self.structural_guard = null;
        }
    };

    /// Serializes every live index-catalog publication and drains background
    /// tasks that borrow inline index generations. Callers must acquire this
    /// before the DB apply lock; active tasks retire under that lock while the
    /// guard waits for their workers to stop.
    pub fn beginIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        var guard = self.beginDrainedIndexStructuralMutation(operation, index_name);
        if (!guard.acquireCatalogBarrierUntil(std.math.maxInt(u64))) unreachable;
        return guard;
    }

    fn beginDrainedIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        return self.beginDrainedIndexStructuralMutationWithLease(operation, index_name, self.core.snapshot_admission.acquireMutation());
    }

    // Consumes the caller's admission. Native capture lends an explicit scoped
    // lease; ordinary structural operations acquire their own shared lease.
    pub fn beginDrainedIndexStructuralMutationWithLease(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
        snapshot_mutation: snapshot_admission_mod.SnapshotAdmission.MutationLease,
    ) IndexStructuralMutationGuard {
        std.debug.assert(snapshot_mutation.active and snapshot_mutation.admission == self.core.snapshot_admission);
        lockAtomicWithBackoff(&self.local_execution.index_structural_mutation_mutex);
        return .{
            .db = self,
            .snapshot_mutation = snapshot_mutation,
            .operation = operation,
            .index_name = index_name,
            .restart_text_merge = self.quiesceTextMergeForStructuralMutation(),
            .restart_sparse_compaction = self.quiesceSparseCompactionForStructuralMutation(),
        };
    }

    pub const scheduleGeneratedArtifactCleanup = db_artifact.scheduleGeneratedArtifactCleanup;

    /// Try to advance one bounded page of retired-index artifact records.
    /// Terminal filesystem finalization owns a separate lease, so callers never
    /// wait behind checkpoint or directory deletion performed by another job.
    pub const GeneratedArtifactCleanupAdvanceResult = cleanup_job_owner.Advance;

    pub const advanceGeneratedArtifactCleanupPage = db_artifact.advanceGeneratedArtifactCleanupPage;

    pub const advanceGeneratedArtifactCleanupContext = db_artifact.advanceGeneratedArtifactCleanupContext;

    pub fn finalizeClaimedRetiredIndexCleanup(
        ctx: *AsyncContext,
        cleanup_locked: *bool,
        index_name: []const u8,
        cleanup_key: []const u8,
    ) !GeneratedArtifactCleanupAdvanceResult {
        if (!ctx.index_artifact_finalization_mutex.tryLock()) return .busy;
        defer ctx.index_artifact_finalization_mutex.unlock();

        // Repair issues describe one concrete consumer generation. A
        // same-name replacement has different artifact identities and cannot
        // resolve diagnoses left by the retired generation. Keep the durable
        // cleanup tombstone authoritative until every issue and its terminal
        // failure history have drained in bounded, crash-idempotent pages.
        if (try drainRetiredIndexArtifactRepairIssuesPageContext(ctx, index_name)) return .progressed;

        // The durable tombstone remains visible while finalization runs, so
        // namespace admission stays fenced. Release page arbitration before
        // checkpoint and filesystem I/O; other indexes can continue draining.
        ctx.index_artifact_cleanup_mutex.unlock();
        cleanup_locked.* = false;
        if (builtin.is_test and test_block_generated_artifact_finalization.load(.acquire)) {
            test_generated_artifact_finalization_entered.store(true, .release);
            while (!test_release_generated_artifact_finalization.load(.acquire)) {
                std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
            }
        }
        try finalizeRetiredIndexCleanupContext(ctx, index_name, cleanup_key);
        return .progressed;
    }

