    pub fn sync(self: *DB, full: bool) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, full });
        if (full) if (self.local_execution.source_vectors.load(.acquire)) |source| try source.advanceMarkingSnapshot();
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.syncStore(full);
        if (self.local_execution.source_vectors.load(.acquire)) |source| {
            try source.checkpoint();
            if (full) {
                try self.refreshSourceVectorOwnershipScopes();
                if (try source.collectDeferredMark(&self.core.store.runtime_store)) try self.core.index_manager.refreshSourcePayloadGeneration();
            }
        }
    }

    pub fn syncIndexes(self: *DB, force: bool) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, force });
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.index_manager.syncAll(force);
    }

    pub const PreparedMergeArtifacts = local_mutation.PreparedMergeArtifacts;

    pub const prepareMergeArtifactEffects = local_mutation.prepareMergeArtifactEffects;

