    pub fn encodeManagedIndexAdmissionMarker(
        marker: ManagedIndexAdmissionMarker,
    ) [managed_index_admission_encoded_len]u8 {
        var out: [managed_index_admission_encoded_len]u8 = undefined;
        std.mem.writeInt(u64, out[0..8], managed_index_admission_magic, .little);
        std.mem.writeInt(u64, out[8..16], marker.config_hash, .little);
        std.mem.writeInt(u64, out[16..24], marker.source_doc_count, .little);
        std.mem.writeInt(u64, out[24..32], marker.identity_generation, .little);
        std.mem.writeInt(u64, out[32..40], marker.replay_target_sequence, .little);
        std.mem.writeInt(u64, out[40..48], @backingInt(marker.disposition), .little);
        return out;
    }

    pub fn decodeManagedIndexAdmissionMarker(raw: []const u8) !ManagedIndexAdmissionMarker {
        if (raw.len != managed_index_admission_encoded_len) return error.InvalidManagedIndexAdmission;
        if (std.mem.readInt(u64, raw[0..8], .little) != managed_index_admission_magic)
            return error.InvalidManagedIndexAdmission;
        const disposition = std.enums.fromInt(
            IndexAdmissionDisposition,
            std.mem.readInt(u64, raw[40..48], .little),
        ) orelse return error.InvalidManagedIndexAdmission;
        return .{
            .config_hash = std.mem.readInt(u64, raw[8..16], .little),
            .source_doc_count = std.mem.readInt(u64, raw[16..24], .little),
            .identity_generation = std.mem.readInt(u64, raw[24..32], .little),
            .replay_target_sequence = std.mem.readInt(u64, raw[32..40], .little),
            .disposition = disposition,
        };
    }

    fn managedAdmissionVisibilitySummary(self: *DB) !doc_identity.VisibilitySummary {
        // Admission is a rare structural mutation and must be based on the
        // primary store that commits the catalog marker. The runtime cache is
        // published only after hot-standby mirrors complete, so a mirror failure can
        // legitimately leave it behind the durable primary state.
        if (try doc_identity.visibilitySummaryFromStore(self.core.store)) |summary| return summary;
        const empty = (try doc_identity.loadAllNewTrustedStateForNamespace(
            self.core.store,
            self.core.identity_namespace,
        )) orelse return error.InvalidDocIdentity;
        return empty.visibility_summary;
    }

    pub fn externalCoverageHasStoredArtifacts(self: *DB, cfg: types.IndexConfig) !bool {
        if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) return false;
        const dense_names = if (cfg.kind == .dense_vector)
            try index_manager_mod.denseConfigArtifactNamesAlloc(self.alloc, cfg)
        else
            null;
        defer if (dense_names) |names| {
            for (names) |name| self.alloc.free(name);
            self.alloc.free(names);
        };
        const artifact_names: []const []const u8 = if (dense_names) |names| names else &.{cfg.name};
        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const ScanState = struct {
            artifact_names: []const []const u8,
            found: bool = false,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                for (state.artifact_names) |artifact_name| {
                    const matches = (internal_keys.isEmbeddingArtifactKey(key) and
                        internal_keys.matchesEmbeddingArtifactName(key, artifact_name)) or
                        (internal_keys.isDerivedEmbeddingArtifactKey(key) and
                            internal_keys.matchesDerivedEmbeddingArtifactName(key, artifact_name));
                    if (matches) {
                        state.found = true;
                        return .stop;
                    }
                }
                return .@"continue";
            }
        };
        var state = ScanState{ .artifact_names = artifact_names };
        try self.core.store.scanWithContext(lower, "", .{}, &state, ScanState.scanEntry);
        return state.found;
    }

    pub const requireOnlineArtifactCatalogMutableLocked = db_artifact.requireOnlineArtifactCatalogMutableLocked;

    pub const requireArtifactReconcileUnfenced = db_artifact.requireArtifactReconcileUnfenced;

    pub const requireOnlineArtifactCatalogMutableWithContextLocked = db_artifact.requireOnlineArtifactCatalogMutableWithContextLocked;

    pub const installIndexWhileEnrichmentQuiesced = db_enrichment.installIndexWhileEnrichmentQuiesced;

    pub const requireGraphCatalogMutableForTransactions = db_graph.requireGraphCatalogMutableForTransactions;

    pub fn installIndexForReconciliation(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode, context: ?artifact_reconcile_intent.Context, replaces: ?[]const u8, prepared: ?*PreparedGraphReplacement) !InstalledIndex {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            try self.requireArtifactReconcileUnfenced(&read, context);
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&read, context);
        }
        if (cfg.kind == .graph or self.core.index_manager.graphIndex(cfg.name) != null)
            try self.requireGraphCatalogMutableForTransactions();
        if (admission_mode == .managed and !indexKindSupportsManagedGenerationRepair(cfg.kind))
            return error.UnsupportedOperation;
        try self.removeOrphanedIndexRepairIntentForFreshAdmission(self.alloc, cfg.name);
        const old_repair = if (replaces) |old| try self.prepareIndexRepairForDeletion(self.alloc, old) else null;
        defer if (old_repair != null) self.endIndexRepairLease(replaces.?);
        const summary = try self.managedAdmissionVisibilitySummary();
        const externally_populated = try index_manager_mod.configUsesExternalCoverage(self.alloc, cfg);
        const external_artifacts_exist = externally_populated and
            try self.externalCoverageHasStoredArtifacts(cfg);
        const disposition: IndexAdmissionDisposition = if (admission_mode == .managed and
            summary.live_ordinals != 0 and
            (!externally_populated or external_artifacts_exist))
            .managed_rebuild
        else
            .activation_fence;
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, cfg.name);
        defer self.alloc.free(admission_key);
        const admission_value = encodeManagedIndexAdmissionMarker(.{
            .config_hash = types.indexConfigHash(cfg),
            .source_doc_count = summary.live_ordinals,
            .identity_generation = @max(summary.max_created_generation, summary.max_deleted_generation),
            .replay_target_sequence = self.core.nextDerivedSequence(),
            .disposition = disposition,
        });
        const admission_write: index_manager_mod.IndexManager.AtomicCatalogMutation = .{ .put = .{
            .key = admission_key,
            .value = &admission_value,
        } };
        var catalog_committed = false;
        // Allocate the service gate before committing admission. Once the
        // catalog and marker become durable, allocation failure must not
        // create an ungated window in the current process.
        try self.core.index_manager.markUnscopedRepairUnavailable(cfg.name);
        errdefer if (!catalog_committed) {
            self.core.index_manager.clearUnscopedRepairUnavailable(cfg.name);
        };

        // Managed empty-source and proven-empty external admissions bypass
        // ordinary synchronous backfill. Source identity proves the former;
        // a streaming artifact-key probe proves the latter. Both start clean
        // at the current replay head.
        // Stage replay must land before the shadow can claim a complete
        // source cut. This is a metadata-only readiness check under resolver
        // activity admission; never drain a corpus while holding activation.
        for (self.core.index_manager.resolvers.items) |resolver| {
            if (!std.mem.eql(u8, resolver.replacement_index, cfg.name)) continue;
            const resolution_stats = self.resolutionStageStats();
            if (resolution_stats.catch_up_required or resolution_stats.blocked) return error.Busy;
            var probe = try self.core.store.beginProbeTxn();
            defer probe.abort();
            for ([_][]const u8{ resolver_catalog_mod.reresolve_resume_key, resolver_catalog_mod.reresolve_repair_resume_key }) |key| {
                _ = probe.get(key) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
                return error.Busy;
            }
            break;
        }
        if (prepared) |candidate| try candidate.finish(self, cfg);
        var applied = if (replaces) |old| try self.core.replaceGraphIndex(old, cfg, admission_write, if (prepared) |candidate| &candidate.entry else null) else switch (admission_mode) {
            .ordinary => try self.core.addIndex(cfg, admission_write),
            .managed => try self.core.addManagedIndex(cfg, admission_write),
        };
        catalog_committed = true;
        if (old_repair) |id| self.removeIndexRepairIntentAndPin(self.alloc, id) catch |err| {
            std.log.warn("index replacement committed with stale repair intent name={s} err={s}", .{ replaces.?, @errorName(err) });
        };
        var post_commit_error: ?anyerror = if (builtin.is_test and test_fail_index_activation_after_catalog_commit)
            error.TestPostCommitIndexActivation
        else
            null;
        if (admission_mode == .managed and disposition == .activation_fence) {
            applied = self.core.nextDerivedSequence();
        }
        if (post_commit_error == null) {
            self.core.saveAppliedSequence(cfg.name, applied) catch |err| {
                post_commit_error = err;
            };
        }
        if (post_commit_error == null) {
            self.initializeDenseArtifactTargetCounterForAdmission(cfg, disposition) catch |err| {
                post_commit_error = err;
            };
        }
        if (post_commit_error == null and
            disposition == .managed_rebuild and
            cfg.kind == .dense_vector)
        {
            // The empty canonical generation is a valid progressive build
            // target, but it is not a completed projection of this non-empty
            // source. Arm the native stable-tip lifecycle before enrichment
            // can publish its first replay window. Leaving this checkpoint
            // clean at sequence zero strands exact-vector publication: native
            // postings can advance while no owner is permitted to publish the
            // matching vector generation or its status compatibility mirror.
            if (self.core.loadProjectionCheckpoint(self.alloc, cfg.name)) |current| {
                self.core.saveProjectionCheckpoint(cfg.name, .{
                    .applied_sequence = current.applied_sequence,
                    .status = .rebuilding,
                    .generation = current.generation,
                    .config_hash = types.indexConfigHash(cfg),
                    .published_count = current.published_count,
                }) catch |err| {
                    post_commit_error = err;
                };
            } else |err| post_commit_error = err;
        }
        if (post_commit_error == null) {
            saveIndexStatusSnapshots(self.alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{.{
                .index_name = cfg.name,
                .sequence = applied,
            }}) catch |err| {
                post_commit_error = err;
            };
        }
        if (cfg.kind == .algebraic) {
            self.hydrateAlgebraicObservationStatusForIndexBestEffort(cfg.name);
        }
        var needs_enrichment_replay = false;
        if (post_commit_error == null) {
            needs_enrichment_replay = self.core.indexRequiresEnrichmentReplay(cfg.name) catch |err| blk: {
                post_commit_error = err;
                break :blk false;
            };
        }
        return .{
            .applied = applied,
            // Prepared graph replacements replayed their producers in bounded
            // pages before construction. Do not rescan the corpus at cutover.
            .needs_enrichment_replay = needs_enrichment_replay and prepared == null,
            .managed_admission_pending = disposition == .managed_rebuild,
            .post_commit_error = post_commit_error,
        };
    }

    pub const restartEnrichmentAfterStructuralMutation = db_enrichment.restartEnrichmentAfterStructuralMutation;

    fn finalizeCompletedIndexAdmission(self: *DB, index_name: []const u8) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, index_name);
        defer self.alloc.free(key);
        try self.finalizeCompletedIndexAdmissionLocked(index_name, key);
    }

    /// Requires the DB apply lock.
    fn finalizeCompletedIndexAdmissionLocked(self: *DB, index_name: []const u8, key: []const u8) !void {
        if (self.core.denseIndex(index_name)) |entry| {
            const raw = try missingAsNull(self.core.store.get(self.alloc, key));
            defer if (raw) |value| self.alloc.free(value);
            if (raw) |value| {
                const marker = try decodeManagedIndexAdmissionMarker(value);
                if (marker.disposition == .activation_fence and marker.source_doc_count == 0 and
                    marker.config_hash == types.indexConfigHash(entry.config) and
                    entry.index.servingActiveCountForCheckpoint() == @as(?u64, 0))
                {
                    var checkpoint = try self.core.loadProjectionCheckpoint(self.alloc, index_name);
                    if (checkpoint.status == .clean and checkpoint.config_hash == marker.config_hash) {
                        checkpoint.published_count = 0;
                        try self.core.saveProjectionCheckpoint(index_name, checkpoint);
                    }
                }
            }
        }
        self.core.store.delete(key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        self.core.index_manager.clearManagedAdmissionSnapshotForIndex(index_name);
        self.core.index_manager.clearUnscopedRepairUnavailable(index_name);
        // The managed-admission marker is the durable control record for an
        // initial materialization, not corruption debt. Preserve that class
        // on the clear edge just as the repair-intent path does. Leaving the
        // default `.repair` here makes the serving layer interpret successful
        // activation as a new corruption boundary and re-fence the exact
        // incarnation it has just acknowledged.
        notifyQueryVisibilityEvent(self.async_context, .{
            .change = .index_repair_cleared,
            .repair = .{
                .index_name = index_name,
                .work_class = .initial_build,
                .previous_admission = .blocked,
                .admission = .serviceable,
            },
        });
    }

    pub const recoverCommittedIndexAdmission = db_repair.recoverCommittedIndexAdmission;

    fn completeInstalledIndexAdmission(
        self: *DB,
        cfg: types.IndexConfig,
        installed: InstalledIndex,
        restart_enrichment: bool,
    ) !?u128 {
        var worker_applied = installed.applied;
        if (installed.needs_enrichment_replay) {
            if (!installed.managed_admission_pending) {
                // Ordinary admission can seed its serving generation directly
                // from retained artifacts before the worker begins replay.
                const rebuilt = switch (cfg.kind) {
                    .dense_vector => try rebuildDenseIndexForTargetCoverageContext(self.async_context, cfg.name, 2048),
                    .sparse_vector => try rebuildSparseIndexFromStoredEmbeddingArtifactsContext(self.async_context, cfg.name, 2048),
                    else => 0,
                };
                const generation_baseline = self.core.nextDerivedSequence();
                if (rebuilt > 0 or generation_baseline > worker_applied) {
                    worker_applied = generation_baseline;
                    try self.core.saveAppliedSequence(cfg.name, worker_applied);
                    try saveIndexStatusSnapshots(self.alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{.{
                        .index_name = cfg.name,
                        .sequence = worker_applied,
                    }});
                }
            }
            if (self.enrichment_runtime != null and !installed.managed_admission_pending) {
                // Ordinary embedded admission retains its synchronous
                // readiness contract. Managed admission persists a repair
                // intent below; that owner pages source-document replay after
                // the write-capability barrier is released, so DDL remains
                // O(groups) rather than O(corpus).
                const refs = try self.replayGeneratedEnrichmentsFromStoredDocs(self.alloc);
                if (refs == 0) {
                    const target_sequence = self.core.nextDerivedSequence();
                    try self.core.saveAppliedSequence(cfg.name, target_sequence);
                    try self.markEnrichmentAppliedIfNoPendingThrough(target_sequence);
                }
            }
        }

        const repair_id = if (installed.managed_admission_pending) repair_blk: {
            // Project the admission marker into a durable repair intent before
            // releasing structural ownership. For generated indexes the same
            // intent owns resumable source replay and advances its producer
            // fence page by page before shadow construction can begin.
            self.requestManagedAdmissionMaterialization();
            // Drain the complete outbox, not only this index. A prior admission
            // may have committed before a transient checkpoint failure.
            try self.drainManagedIndexAdmissionsUnderStructuralGuard(self.alloc);
            break :repair_blk try self.indexRepairIdForIndex(self.alloc, cfg.name);
        } else null;

        // A managed admission with the durable repair scheduler enabled is
        // completed by its shadow generation. Starting the canonical worker
        // here makes it finalize HBC once per producer window while competing
        // with artifact production, even though that generation will be
        // discarded. Install the worker at the shadow activation fence above.
        const defer_worker_to_managed_repair = installed.managed_admission_pending and
            self.local_execution.optional_runtime_workers_enabled and
            try types.indexPublicationPolicy(self.alloc, cfg) == .atomic;
        if (self.start_index_workers and !defer_worker_to_managed_repair) {
            try self.executor.addWorker(cfg.name, .{ .name = cfg.name, .kind = cfg.kind }, worker_applied);
        }
        if (restart_enrichment) try self.restartEnrichmentAfterStructuralMutation("index creation", cfg.name);
        if (self.start_index_workers and !defer_worker_to_managed_repair) {
            const current_target = self.core.nextDerivedSequence();
            if (current_target > worker_applied) self.executor.notifyIndexes(current_target, &.{cfg.name});
        }
        if (!installed.managed_admission_pending) try self.finalizeCompletedIndexAdmission(cfg.name);
        return repair_id;
    }

    fn addIndexWithAdmission(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode) !?u128 {
        return self.addIndexForReconciliation(cfg, admission_mode, null, null, null);
    }

    pub fn addIndexForReconciliation(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode, context: ?artifact_reconcile_intent.Context, replaces: ?[]const u8, prepared: ?*PreparedGraphReplacement) !?u128 {
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyUnsupported;
        var row_policy_lease = self.local_execution.row_policy_gate.enterRaw() catch return error.RowPolicyUnsupported;
        defer row_policy_lease.release();
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (context == null) try self.enforceReplicationWriteGate();
        var structural_guard = self.beginIndexStructuralMutation("index creation", cfg.name);
        defer structural_guard.deinit();
        {
            lockApplyShared(self);
            defer self.core.unlockApplyShared();
            var probe = try self.core.store.beginReadTxn();
            defer probe.abort();
            try self.requireArtifactReconcileUnfenced(&probe, context);
        }
        try self.enforceVectorMigrationConfigurationGate();
        // Generated artifact namespaces can be shared across differently named
        // indexes. Cleanup is durable and owner-driven; never turn index
        // admission into an unbounded corpus scan. Metadata reconciliation can
        // retry after the conflicting generation's tombstone is retired.
        try self.rejectConflictingRetiredIndexCleanupForAdmission(cfg);
        const restart_enrichment = self.quiesceEnrichmentForStructuralMutation();
        var enrichment_restarted = false;
        errdefer if (restart_enrichment and !enrichment_restarted) {
            self.restartEnrichmentAfterStructuralMutation("failed index creation", cfg.name) catch |restart_err| {
                std.log.err("failed to restore enrichment runtime after index creation error index={s} err={s}", .{ cfg.name, @errorName(restart_err) });
            };
        };
        const paused_old = if (replaces) |old| try self.executor.pauseWorker(old) else false;
        var replacement_committed = false;
        defer if (paused_old) {
            if (replacement_committed) self.executor.removeWorker(replaces.?) else self.executor.resumeWorker(replaces.?);
        };
        const installed = install: {
            var activity: ?ResolverCatalogActivity = if (replaces != null) try self.acquireResolverCatalogActivity(true) else null;
            defer if (activity) |*lease| lease.deinit();
            break :install try self.installIndexForReconciliation(cfg, admission_mode, context, replaces, prepared);
        };
        replacement_committed = true;
        if (replaces != null) {
            self.scheduleGeneratedArtifactCleanup();
            if (self.resolution_runtime) |runtime| runtime.notifyBackfill();
        }
        if (installed.post_commit_error) |activation_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("pending index activation", cfg.name) catch {};
            enrichment_restarted = true;
            return try self.recoverCommittedIndexAdmission(cfg, activation_err);
        }

        const repair_id = self.completeInstalledIndexAdmission(cfg, installed, restart_enrichment) catch |activation_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("pending index activation", cfg.name) catch {};
            enrichment_restarted = true;
            return try self.recoverCommittedIndexAdmission(cfg, activation_err);
        };
        enrichment_restarted = true;
        return repair_id;
    }

    pub const graphReplacementCutoverBudgetNs = db_graph.graphReplacementCutoverBudgetNs;

    pub const PreparedGraphReplacement = struct {
        manager: *index_manager_mod.IndexManager,
        sequence: u64,
        deadline_ns: ?u64 = null,
        tail_source_cursor: usize = 0,
        activation_attempts: u32 = 0,
        entry: ?index_manager_mod.IndexManager.DetachedIndex = null,

        fn finish(candidate: *@This(), db: *DB, cfg: types.IndexConfig) !void {
            // New writes are briefly fenced here; construction and earlier
            // catch-up rounds ran through the ordinary maintenance owner.
            const target = db.core.nextDerivedSequence();

            // Escalation has a finite cooperative budget too. Persisted tail
            // ordinals retain completed work when either budget expires. A
            // slow storage operation may overrun a quantum, but no loop may
            // hold write admission until an arbitrarily large tail is empty.
            const deadline = @min(db.graphReplacementWorkNow() +| graphReplacementCutoverBudgetNs(candidate.activation_attempts), candidate.deadline_ns orelse std.math.maxInt(u64));
            // Freeze writes only for a bounded progress window. Even a tail
            // larger than 1024 can advance its durable checkpoint; it never
            // throws completed work away waiting for an initially small gap.
            while (candidate.sequence < target and db.graphReplacementWorkNow() < deadline) {
                // Coalesce windows of at most 32 unique sources. Larger
                // windows use per-entry batches and can revisit hot documents;
                // an interrupted entry resumes at its durable source ordinal.
                var next = candidate.sequence;
                if (candidate.tail_source_cursor == 0)
                    next = try db.catchUpGraphReplacement(candidate.manager, cfg.name, candidate.sequence, target, 1024, deadline);
                if (next == candidate.sequence and db.graphReplacementWorkNow() < deadline)
                    next = try db.catchUpGraphReplacementTail(candidate.manager, cfg.name, candidate.sequence, target, &candidate.tail_source_cursor, deadline);
                if (next == candidate.sequence) break;
                candidate.sequence = next;
            }
            try candidate.manager.checkpointLsmWalForManagedIndex(.{ .name = cfg.name, .kind = .graph });
            try candidate.manager.syncIndexByName(cfg.name, true);
            if (candidate.sequence < target) {
                const jobs = try db.graphReplacementStatusAlloc(db.alloc);
                defer jobs.deinit();
                for (jobs.value) |saved| if (std.mem.eql(u8, saved.name, cfg.name)) {
                    var job = saved;
                    if (candidate.sequence > saved.applied_sequence or candidate.tail_source_cursor > saved.tail_source_cursor) {
                        job.retry_count = 0;
                        job.retry_after_ns = 0;
                        job.last_error = null;
                    }
                    job.applied_sequence = candidate.sequence;
                    job.tail_source_cursor = candidate.tail_source_cursor;
                    job.activation_attempts +|= 1;
                    try db.core.index_manager.saveGraphReplacementBuild(db.core.store, job);
                    break;
                };
                return error.Busy;
            }
            candidate.entry = try candidate.manager.detachReplacementIndex(cfg.name);
        }
    };

    pub const replaceGraphIndex = db_graph.replaceGraphIndex;

    pub const hasPendingGraphReplacements = db_graph.hasPendingGraphReplacements;

    pub const graphReplacementStatusAlloc = db_graph.graphReplacementStatusAlloc;

    pub const graphReplacementProducerNamesAlloc = db_graph.graphReplacementProducerNamesAlloc;

    pub fn catchUpGraphReplacement(self: *DB, private: *index_manager_mod.IndexManager, name: []const u8, from: u64, target: u64, limit: usize, deadline: ?u64) !u64 {
        if (target <= from) return from;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const Collect = struct {
            database: *DB,
            alloc: Allocator,
            target: u64,
            deadline: ?u64,
            applied: u64,
            documents: std.StringHashMapUnmanaged(void) = .empty,
            artifacts: std.StringHashMapUnmanaged(void) = .empty,

            fn add(state: *@This(), set: *std.StringHashMapUnmanaged(void), keys: []const []const u8) !void {
                for (keys) |key| {
                    const entry = try set.getOrPut(state.alloc, key);
                    if (!entry.found_existing) entry.key_ptr.* = try state.alloc.dupe(u8, key);
                }
            }

            fn record(state: *@This(), sequence: u64, payload: []const u8) anyerror!void {
                if (sequence > state.target) return error.StopReplayChunk;
                if (state.deadline) |end| if (state.database.graphReplacementWorkNow() >= end) return error.StopReplayChunk;
                var decoded = try change_journal_mod.decodeRecord(state.alloc, payload);
                defer decoded.deinit();
                try state.add(&state.documents, decoded.record.changed_doc_keys);
                try state.add(&state.documents, decoded.record.deleted_doc_keys);
                try state.add(&state.documents, decoded.record.overwritten_doc_keys);
                try state.add(&state.artifacts, decoded.record.changed_artifact_keys);
                state.applied = sequence;
            }
        };
        const collect_now = self.graphReplacementWorkNow();
        const collection_deadline = if (deadline) |end| collect_now +| (end -| collect_now) / 4 else null;
        var collected = Collect{ .database = self, .alloc = a, .target = target, .deadline = collection_deadline, .applied = from };
        _ = self.core.store.forEachReplayLaneFrom(internal_keys.replay_all_kind, from +| 1, limit, &collected, Collect.record) catch |err| switch (err) {
            error.StopReplayChunk => {},
            else => return err,
        };
        // A bounded cutover must not repeatedly rebuild a prefix of a large
        // window without acknowledging it. Leave such windows to the ordinal
        // cursor path before spending the work budget. Activation, including
        // escalation, always has a finite deadline; more than 32 unique sources
        // therefore use resumable per-entry batches rather than one coalesced
        // pass. Unfenced construction may coalesce larger windows.
        if (deadline != null and collected.documents.count() + collected.artifacts.count() > 32) return from;
        // A hot source can occur hundreds of times in a replay window. Build
        // its current projection once, then acknowledge the whole window only
        // after every collected source is durable. Interrupted rounds are safe
        // to repeat without advancing their journal watermark.
        var ctx = self.graphReplacementContext(private);
        defer ctx.deinit(self.alloc);
        var source_read = try self.core.store.beginReadTxn();
        defer source_read.abort();
        var documents: std.ArrayList([]const u8) = .empty;
        var document_keys = collected.documents.keyIterator();
        while (document_keys.next()) |key| try documents.append(a, key.*);
        var offset: usize = 0;
        while (offset < documents.items.len) {
            if (deadline) |end| if (self.graphReplacementWorkNow() >= end) return from;
            const end = @min(offset + 32, documents.items.len);
            try rebuildGraphReplacementDocumentsWithRead(&ctx, name, documents.items[offset..end], &source_read);
            offset = end;
        }
        var keys: std.ArrayList([]const u8) = .empty;
        var artifacts = collected.artifacts.keyIterator();
        while (artifacts.next()) |key| {
            const owner_key = try internal_keys.decodeDocumentComponentAlloc(a, key.*);
            if (owner_key != null and collected.documents.contains(owner_key.?)) continue;
            try keys.append(a, key.*);
        }
        if (keys.items.len != 0) {
            if (deadline) |end| if (self.graphReplacementWorkNow() >= end) return from;
            const changed = try materializeGraphSourceArtifactsForIndex(a, ctx.store, private, keys.items, name, .{ .require_resolution_contract = true });
            try applyDerivedBatchToIndexContextProfiled(&ctx, .{ .changed_artifact_keys = changed }, .{ .name = name, .kind = .graph }, null, false, null);
        }
        return collected.applied;
    }

    /// The final write pause can yield within one large journal batch. The
    /// cursor indexes immutable source keys in its next retained entry, and is
    /// published only after the corresponding shadow projection checkpoint.
    fn catchUpGraphReplacementTail(self: *DB, private: *index_manager_mod.IndexManager, name: []const u8, from: u64, target: u64, source_cursor: *usize, deadline: u64) !u64 {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const First = struct {
            alloc: Allocator,
            target: u64,
            sequence: u64 = 0,
            payload: ?[]const u8 = null,
            fn record(state: *@This(), sequence: u64, payload: []const u8) anyerror!void {
                if (sequence > state.target) return error.StopReplayChunk;
                state.sequence = sequence;
                state.payload = try state.alloc.dupe(u8, payload);
            }
        };
        var first = First{ .alloc = a, .target = target };
        _ = self.core.store.forEachReplayLaneFrom(internal_keys.replay_all_kind, from +| 1, 1, &first, First.record) catch |err| switch (err) {
            error.StopReplayChunk => {},
            else => return err,
        };
        const payload = first.payload orelse return from;
        var decoded = try change_journal_mod.decodeRecord(a, payload);
        defer decoded.deinit();
        var documents: std.StringArrayHashMapUnmanaged(void) = .empty;
        for ([_][]const []const u8{ decoded.record.changed_doc_keys, decoded.record.deleted_doc_keys, decoded.record.overwritten_doc_keys }) |keys| {
            for (keys) |key| try documents.put(a, key, {});
        }
        var artifacts: std.StringArrayHashMapUnmanaged(void) = .empty;
        for (decoded.record.changed_artifact_keys) |key| {
            const owner_key = try internal_keys.decodeDocumentComponentAlloc(a, key);
            if (owner_key != null and documents.contains(owner_key.?)) continue;
            try artifacts.put(a, key, {});
        }
        const total = documents.count() + artifacts.count();
        if (source_cursor.* > total) return error.InvalidReplacementReplayCursor;
        var ctx = self.graphReplacementContext(private);
        defer ctx.deinit(self.alloc);
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        while (source_cursor.* < total) {
            if (self.graphReplacementWorkNow() >= deadline) return from;
            const ordinal = source_cursor.*;
            if (ordinal < documents.count()) {
                const end = @min(ordinal + 32, documents.count());
                try rebuildGraphReplacementDocumentsWithRead(&ctx, name, documents.keys()[ordinal..end], &read);
                source_cursor.* = end;
            } else {
                const start = ordinal - documents.count();
                const end = @min(start + 32, artifacts.count());
                const changed = try materializeGraphSourceArtifactsForIndex(a, ctx.store, private, artifacts.keys()[start..end], name, .{ .require_resolution_contract = true });
                try applyDerivedBatchToIndexContextProfiled(&ctx, .{ .changed_artifact_keys = changed }, .{ .name = name, .kind = .graph }, null, false, null);
                source_cursor.* = documents.count() + end;
            }
            if (builtin.is_test) if (test_graph_replacement_tail_batch) |hook| hook(self, source_cursor.*);
        }
        source_cursor.* = 0;
        return first.sequence;
    }

    pub const graphReplacementContext = db_graph.graphReplacementContext;

    pub const advanceGraphReplacement = db_graph.advanceGraphReplacement;

    pub fn replacementRetryable(err: anyerror) bool {
        return switch (err) {
            error.OutOfMemory,
            error.SystemResources,
            error.NoSpaceLeft,
            error.DiskQuota,
            error.ConnectionRefused,
            error.ConnectionResetByPeer,
            error.ConnectionTimedOut,
            error.Timeout,
            error.NetworkUnreachable,
            error.TemporaryNameServerFailure,
            error.SendFailed,
            error.RecvFailed,
            error.RemoteCapabilityDiscoveryTransient,
            error.ConcurrencyUnavailable,
            error.QueueFull,
            error.EmbedTransientFailure,
            error.EmbedRateLimited,
            error.InferenceInvocationMemoryUnavailable,
            => true,
            else => false,
        };
    }

    pub const replacement_total_retry_limit: u32 = 64;
    pub const replacement_max_backoff_ns: u64 = 3200 * std.time.ns_per_ms;

    pub const graphReplacementWorkNow = db_graph.graphReplacementWorkNow;

    pub fn replacementRetryNow(self: *DB) u64 {
        if (builtin.is_test) if (test_graph_replacement_retry_now_ns) |now| return now;
        return @intCast(@max(0, std.Io.Timestamp.now(self.core.index_manager.checkpointIo(), .real).toNanoseconds()));
    }

