    pub fn stats(self: *DB, alloc: Allocator) !types.DBStats {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        // Operational stats must stay bounded and avoid maintenance/scan work.
        // See STATUS.md for the status-plane contract.
        if (!self.core.tryLockApplyShared()) {
            return .{
                .indexes_available = false,
                .async_indexing = self.snapshotAsyncIndexingStats(),
                .doc_set_planning = self.snapshotDocSetPlanningStats(),
                .visibility = self.snapshotVisibilityStats(),
                .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
                .resolution = self.resolutionStageStats(),
                .promotion = self.promotionStageStats(),
                .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
                .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            };
        }
        var result = self.statsLocked(alloc) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        self.overlayRuntimeStatusRuntimeBestEffort(&result);
        return result;
    }

    pub fn runtimeStatusStatsConsistent(self: *DB, alloc: Allocator) !types.DBStats {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        lockApplyShared(self);
        var result = self.statsLocked(alloc) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        self.overlayRuntimeStatusRuntimeBestEffort(&result);
        return result;
    }

    pub fn runtimeStatusStatsConsistentIfAvailable(self: *DB, alloc: Allocator) !?types.DBStats {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        if (self.open_mode == .status_only) {
