        self.local_execution.doc_set_planning_stats.recordResolvedSet(set, missing_ordinal_coverage);
    }

    pub fn recordUnsupportedDocSetFilterShape(self: *DB) void {
        self.local_execution.doc_set_planning_stats.recordUnsupportedFilterShape();
    }

    pub fn currentIdentityReadGenerationForRequest(self: *DB, requested: ?u64) !u64 {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, requested });
        const current_generation = try self.currentIdentityReadGeneration();
        if (requested) |generation| {
            if (generation != current_generation) {
                self.local_execution.doc_set_planning_stats.recordStaleIdentityGenerationRejection();
                return error.IdentityReadGenerationChanged;
            }
            return generation;
        }
        return current_generation;
    }

    fn currentIdentityReadGeneration(self: *DB) !u64 {
        var current_generation = self.core.nextDerivedSequence();
        if (self.core.identity_visibility.summary) |summary| {
            return @max(current_generation, doc_identity.latestGenerationFromSummary(summary));
        }
        if (try doc_identity.latestGenerationFromSummaryFast(self.core.store)) |identity_generation| {
            return @max(current_generation, identity_generation);
        }
        const identity_stats = try doc_identity.fullStatsFromStore(self.core.store);
        current_generation = @max(current_generation, identity_stats.max_created_generation);
        current_generation = @max(current_generation, identity_stats.max_deleted_generation);
        return current_generation;
    }

    pub const snapshotDocSetPlanningStats = db_restore.snapshotDocSetPlanningStats;

    pub const snapshotVisibilityStats = db_restore.snapshotVisibilityStats;

    const DocIdentityCoverage = struct {
        scanned_primary_docs: u64 = 0,
        primary_docs_missing_ordinals: u64 = 0,
        primary_docs_missing_identity_state: u64 = 0,
        primary_docs_with_tombstone_ordinals: u64 = 0,
    };

    fn finalizeDocIdentityRebuildRequired(identity_stats: *types.DocIdentityStats) void {
        identity_stats.rebuild_required = identity_stats.rebuild_required or
            identity_stats.ordinal_capacity_exhausted or
            identity_stats.primary_docs_missing_ordinals != 0 or
            identity_stats.primary_docs_missing_identity_state != 0 or
            identity_stats.primary_docs_with_tombstone_ordinals != 0;
    }

    fn diagnosticDocIdentityStats(self: *DB, byte_range: types.ByteRange) !types.DocIdentityStats {
        var identity_stats = dbDocIdentityStats(try doc_identity.fullStatsFromStore(self.core.store), self.core.identity_namespace);
        const coverage = try self.scanPrimaryDocIdentityCoverage(byte_range);
        identity_stats.scanned_primary_docs = coverage.scanned_primary_docs;
        identity_stats.primary_docs_missing_ordinals = coverage.primary_docs_missing_ordinals;
        identity_stats.primary_docs_missing_identity_state = coverage.primary_docs_missing_identity_state;
        identity_stats.primary_docs_with_tombstone_ordinals = coverage.primary_docs_with_tombstone_ordinals;
        finalizeDocIdentityRebuildRequired(&identity_stats);
        return identity_stats;
    }

    fn statsLocked(self: *DB, alloc: Allocator) !types.DBStats {
        // Serialize owner captures, not HTTP reads. A stamp orders the whole
        // coherent capture; concurrent captures cannot assign a newer revision
        // to an older payload. Individual index snapshots retain their own
        // publication locks and replay prefixes are sampled before their facts.
        lockAtomic(&self.status_publication_mutex);
        defer self.status_publication_mutex.unlock();
        self.status_publication_revision += 1;
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        const async_indexing = self.snapshotAsyncIndexingStats();
        var raw_identity_stats = try doc_identity.fastStatsFromStore(self.core.store);
        // Coalesced primary writes update this summary immediately after the
        // store accepts the batch, while a probe transaction can still see the
        // previous durable summary until the bulk window is published. Runtime
        // owners must publish the maintained live summary rather than making
        // status wait for a flush or fall back to a primary scan.
        applyCachedIdentityVisibilitySummary(&raw_identity_stats, self.core.identity_visibility.summary);
        const identity_stats = dbDocIdentityStats(raw_identity_stats, self.core.identity_namespace);
        // Operational status is polled frequently. Identity metadata is the
        // normal O(1) source of the live document count; retain the legacy
        // primary-store scan only as a lazy fallback for an old/incomplete
        // identity catalog and only when sparse-index capping needs it.
        var primary_doc_count_fallback: ?u64 = null;
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        var visible_doc_count: u64 = 0;
        var any_index_repair_degraded = false;
        var term_doc_freq_cache_hits: u64 = 0;
        var term_doc_freq_cache_misses: u64 = 0;
        for (configs) |cfg| {
            const projection_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const applied_sequence = try self.managedIndexAppliedSequence(alloc, cfg.name);
            const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg, applied_sequence);
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
                .replay_applied_sequence = applied_sequence,
                .replay_target_sequence = target_sequence,
                .replay_catch_up_required = applied_sequence < target_sequence,
                .catch_up_active = false,
                .catch_up_applied_sequence = applied_sequence,
                .catch_up_target_sequence = target_sequence,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            try self.populateIndexSourceReplayStats(alloc, cfg.name, applied_sequence, target_sequence, &item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            applyProjectionCheckpointStats(&item, projection_checkpoint, target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (target_sequence > 0) {
                item.backfill_progress = @min(
                    1.0,
                    @as(f64, @floatFromInt(applied_sequence)) / @as(f64, @floatFromInt(target_sequence)),
                );
                item.backfill_active = item.backfill_active or applied_sequence < target_sequence;
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                item.load_error = try alloc.dupe(u8, load_error);
                // A quarantined index has no runtime; it is broken, not warming.
                applyTerminalLoadFailureStatus(&item);
            }
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;

            var serving_observed = false;
            switch (cfg.kind) {
                .full_text => {
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        item.doc_count = text_snapshot.liveDocCount();
                        item.term_count = textSnapshotTermCount(text_snapshot);
                        serving_observed = true;
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                        term_doc_freq_cache_hits += text_snapshot.term_doc_freq_cache_hits;
                        term_doc_freq_cache_misses += text_snapshot.term_doc_freq_cache_misses;
                    }
                    item.text_merge = self.core.index_manager.textMergeStatsSnapshotForIndex(cfg.name);
                    if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
                    // Artifact-fed full-text projections carry the same
                    // durable per-document generation outcomes as embeddings
                    // indexes; surface them so terminal failures are settled
                    // coverage, not invisible pending work. Direct-document
                    // projections have no producer outcomes and stay
                    // coverage-silent instead of eternally pending.
                    if (self.derivedCoverageAppliesToIndex(.full_text, cfg.name))
                        try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .dense_vector => {
                    if (self.core.denseIndex(cfg.name)) |entry| {
                        const serving = denseServingCounts(entry.index);
                        item.doc_count = serving.doc_count;
                        item.node_count = serving.node_count;
                        item.root_node = serving.root_node;
                        item.serving_snapshot_revision = serving.revision;
                        item.serving_snapshot_owner_id = self.backend_owner_id;
                        serving_observed = true;
                        item.hbc_cache = dbHbcCacheStats(entry.index.hbcCacheStats());
                        item.hbc_posting.refresh_pending = entry.index.postingRefreshPending();
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                        try self.markDenseCoverageRegressionIfNeeded(alloc, cfg.name, &item);
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (async_indexing.dense_catch_up.active) {
                        item.catch_up_active = true;
                        item.backfill_active = true;
                    }
                    item.catch_up_phase = async_indexing.dense_catch_up.phase;
                    if (self.core.index_manager.vectorBlockProjectionRequiredForDenseIndex(cfg.name) and
                        !self.core.index_manager.vectorBlockReadyForDenseIndexAtSequence(
                            cfg.name,
                            item.replay_applied_sequence,
                            item.doc_count,
                        ))
                    {
                        item.backfill_active = true;
                        item.backfill_progress = @min(item.backfill_progress, 0.999);
                        item.dense_vector_projection_pending = true;
                    }
                },
                .sparse_vector => {
                    if (self.core.sparseIndex(cfg.name)) |entry| {
                        const sparse_snapshot = entry.index.stats();
                        const sparse_doc_cap = if (identity_stats.live_ordinals > 0)
                            identity_stats.live_ordinals
                        else fallback: {
                            if (primary_doc_count_fallback == null) {
                                primary_doc_count_fallback = self.scanPrimaryDocCount(self.core.byteRange()) catch 0;
                            }
                            break :fallback if (primary_doc_count_fallback.? > 0)
                                primary_doc_count_fallback.?
                            else
                                visible_doc_count;
                        };
                        item.doc_count = if (entry.chunk_name == null and sparse_doc_cap > 0)
                            @min(sparse_snapshot.doc_count, sparse_doc_cap)
                        else
                            sparse_snapshot.doc_count;
                        item.term_count = sparse_snapshot.term_count;
                        serving_observed = true;
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .graph => {
                    if (self.core.graphIndex(cfg.name)) |entry| {
                        {
                            const graph_snapshot = entry.index.operationalStats();
                            item.graph_counts_pending = graph_snapshot.counts_pending;
                            item.edge_count = graph_snapshot.edge_count;
                            item.node_count = graph_snapshot.node_count;
                            item.doc_count = graph_snapshot.node_count;
                            serving_observed = true;
                            if (!graph_snapshot.counts_pending) visible_doc_count = @max(visible_doc_count, item.doc_count);
                        }
                        applyGraphAlgebraicRuntimeStats(&item, &entry.index);
                        try populateGraphMetricStatusStats(alloc, &item, &entry.index);
                    }
                    // Extraction-fed graph indexes (the autoschema pipeline)
                    // record per-document generation outcomes under the
                    // consuming index's coverage generation; without this the
                    // knowledge graph's terminal extraction failures were
                    // reported nowhere on the index itself. Direct-document
                    // graphs have no producer outcomes and stay silent.
                    if (self.derivedCoverageAppliesToIndex(.graph, cfg.name))
                        try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .algebraic => {
                    try self.populateAlgebraicIndexStats(alloc, cfg.name, &item, false);
                    serving_observed = self.core.index_manager.algebraicIndex(cfg.name) != null;
                },
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                item.serving_snapshot_ready = self.vectorServingSnapshotReady(
                    alloc,
                    &item,
                    if (durable_index_repairs) |*state| state else null,
                );
            }
            // Coverage and rebuild accounting above describes serviceable
            // runtimes. A quarantined index has no worker that can make that
            // progress, so its terminal load state must take precedence.
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            self.stampIndexObservation(cfg, &item, if (durable_index_repairs) |*state| state else null, serving_observed);
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .runtime_owner_id = self.backend_owner_id,
            .storage_change_token = self.storageChangeTokenLocked(),
            .source_doc_count = identity_stats.live_ordinals,
            .schema_epoch = self.core.table_catalog.active_schema_version,
            .row_format_version = self.core.table_catalog.row_format_version,
            .table_catalog_generation = self.core.table_catalog.generation,
            .schema_index_state = @tagName(self.core.table_catalog.index_state),
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .visibility = self.snapshotVisibilityStats(),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
            .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStatsSnapshot(),
            .graph_metric_runtime = self.graphMetricRuntimeStats(),
            .term_doc_freq_cache_hits = term_doc_freq_cache_hits,
            .term_doc_freq_cache_misses = term_doc_freq_cache_misses,
            .async_indexing = async_indexing,
        };
    }

    fn stampIndexObservation(self: *DB, cfg: types.IndexConfig, item: *types.DBIndexStats, repairs: ?*const index_repair_state.State, serving_observed: bool) void {
        // Read-only and status-only DBs are observers, not successor writers.
        if (self.open_mode != .writer and self.open_mode != .writer_no_replay) return;
        if (!item.coverage_identity_ready or item.load_error != null) return;
        if (!serving_observed and !item.coverage_summary_ready) return;
        const recovered = self.observeResidentIndexAdmission(self.alloc, item.name, repairs) == .admitted and
            !item.repair_degraded and !item.index_repair_action_required and
            (std.mem.eql(u8, item.projection_checkpoint_status, "clean") or item.index_repair_active_generation_serviceable) and
            item.projection_checkpoint_config_hash == types.indexConfigHash(cfg) and
            item.projection_checkpoint_applied_sequence <= item.replay_applied_sequence;
        const stamp = publication_mod.Stamp{
            .owner_epoch = self.status_owner_epoch,
            .revision = self.status_publication_revision,
            .applied_through = item.replay_applied_sequence,
            .recovered_through = if (recovered) item.projection_checkpoint_applied_sequence else null,
        };
        if (serving_observed) {
            item.serving_publication = stamp;
            item.runtime_serving_applied_sequence = stamp.applied_through;
        }
        if (item.coverage_summary_ready) {
            item.coverage_publication = stamp;
            item.runtime_coverage_applied_sequence = stamp.applied_through;
            item.runtime_coverage_source_sequence = self.core.nextDerivedSequence();
        }
    }

    pub fn diagnosticStats(self: *DB, alloc: Allocator) !types.DBStats {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const byte_range = self.core.byteRange();
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        const replay_debt = try self.listDerivedReplayDebtAssumeApplyLockHeld(alloc);
        defer {
            for (replay_debt) |*status| status.deinit(alloc);
            alloc.free(replay_debt);
        }
        var indexed_doc_count: ?u64 = null;
        for (configs) |cfg| {
            if (cfg.kind != .full_text) continue;
            if (self.core.textIndex(cfg.name)) |entry| {
                indexed_doc_count = @max(indexed_doc_count orelse 0, entry.snapshot().liveDocCount());
            }
        }
        const visible_doc_count = indexed_doc_count orelse try self.scanPrimaryDocCount(byte_range);
        const async_indexing = self.async_context.stats.snapshot();
        const identity_stats = try self.diagnosticDocIdentityStats(byte_range);
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        var any_index_repair_degraded = false;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        for (configs) |cfg| {
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                item.load_error = try alloc.dupe(u8, load_error);
                applyTerminalLoadFailureStatus(&item);
            } else if (try self.loadPersistedIndexLoadFailure(alloc, cfg.name)) |load_error| {
                item.load_error = load_error;
                applyTerminalLoadFailureStatus(&item);
            }
            for (replay_debt) |status| {
                if (!std.mem.eql(u8, status.index_name, cfg.name)) continue;
                item.replay_applied_sequence = status.applied_sequence;
                item.replay_target_sequence = status.target_sequence;
                item.replay_catch_up_required = status.catch_up_required;
                item.catch_up_applied_sequence = status.applied_sequence;
                item.catch_up_target_sequence = status.target_sequence;
                item.catch_up_active = false;
                break;
            }
            try self.populateIndexSourceReplayStats(alloc, cfg.name, item.replay_applied_sequence, item.replay_target_sequence, &item);
            applyProjectionCheckpointStats(&item, try self.core.loadProjectionCheckpoint(alloc, cfg.name), item.replay_target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;
            switch (cfg.kind) {
                .full_text => {
                    if (self.core.textIndex(cfg.name)) |entry| {
                        item.doc_count = entry.snapshot().liveDocCount();
                        indexed_doc_count = @max(indexed_doc_count orelse 0, item.doc_count);
                    }
                    item.text_merge = self.core.index_manager.textMergeStatsForIndex(cfg.name);
                    if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
                    if (self.core.textIndexEntry(cfg.name)) |entry| {
                        const rebuild_state = self.core.index_manager.rebuildState(.full_text, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                },
                .dense_vector => {
                    if (self.core.denseIndex(cfg.name)) |entry| {
                        const serving = denseServingCounts(entry.index);
                        item.doc_count = serving.doc_count;
                        item.node_count = serving.node_count;
                        item.root_node = serving.root_node;
                        item.hbc_cache = dbHbcCacheStats(entry.index.hbcCacheStats());
                        item.hbc_posting = dbHbcPostingStats(try entry.index.postingBacklogStats(), entry.index.getWriteProfile());
                        item.hbc_posting.refresh_pending = entry.index.postingRefreshPending();
                        try self.markDenseCoverageRegressionIfNeeded(alloc, cfg.name, &item);
                        if (async_indexing.dense_catch_up.active) {
                            item.catch_up_active = true;
                            item.backfill_active = true;
                        }
                        const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, entry.config.name);
                        defer alloc.free(rebuild_root_path);
                        const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
                        if (item.doc_count < visible_doc_count) {
                            if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                                item.backfill_active = true;
                                item.backfill_progress = progress;
                            }
                        }
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (!item.backfill_active and item.replay_target_sequence > 0 and item.doc_count < visible_doc_count) {
                        item.backfill_progress = @min(
                            1.0,
                            @as(f64, @floatFromInt(item.replay_applied_sequence)) / @as(f64, @floatFromInt(item.replay_target_sequence)),
                        );
                        item.backfill_active = item.replay_applied_sequence < item.replay_target_sequence;
                    }
                },
                .sparse_vector => {
                    if (self.core.sparseIndex(cfg.name)) |entry| {
                        const sparse_stats = entry.index.stats();
                        const raw_identity_stats = doc_identity.fastStatsFromStore(self.core.store) catch null;
                        const sparse_doc_cap = if (identity_stats.live_ordinals > 0)
                            identity_stats.live_ordinals
                        else if (raw_identity_stats) |raw|
                            raw.live_ordinals
                        else
                            visible_doc_count;
                        item.doc_count = if (entry.chunk_name == null and sparse_doc_cap > 0)
                            @min(sparse_stats.doc_count, sparse_doc_cap)
                        else
                            sparse_stats.doc_count;
                        item.term_count = sparse_stats.term_count;
                        const rebuild_state = self.core.index_manager.rebuildState(.sparse_vector, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (!item.backfill_active and item.replay_target_sequence > 0) {
                        item.backfill_progress = @min(
                            1.0,
                            @as(f64, @floatFromInt(item.replay_applied_sequence)) / @as(f64, @floatFromInt(item.replay_target_sequence)),
                        );
                        item.backfill_active = item.replay_applied_sequence < item.replay_target_sequence;
                    }
                },
                .graph => {
                    if (self.core.graphIndex(cfg.name)) |entry| {
                        const graph_stats = try entry.index.stats(alloc);
                        item.edge_count = graph_stats.edge_count;
                        item.node_count = graph_stats.node_count;
                        item.doc_count = graph_stats.node_count;
                        applyGraphAlgebraicRuntimeStats(&item, &entry.index);
                        const rebuild_state = self.core.index_manager.rebuildState(.graph, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                },
                .algebraic => try self.populateAlgebraicIndexStats(alloc, cfg.name, &item, true),
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                item.serving_snapshot_ready = self.vectorServingSnapshotReady(
                    alloc,
                    &item,
                    if (durable_index_repairs) |*state| state else null,
                );
            }
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .source_doc_count = identity_stats.live_ordinals,
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .visibility = self.snapshotVisibilityStats(),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
            .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStats(),
            .graph_metric_runtime = self.graphMetricRuntimeStats(),
            .term_doc_freq_cache_hits = blk: {
                var total: u64 = 0;
                for (configs) |cfg| {
                    if (cfg.kind != .full_text) continue;
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        total += text_snapshot.term_doc_freq_cache_hits;
                    }
                }
                break :blk total;
            },
            .term_doc_freq_cache_misses = blk: {
                var total: u64 = 0;
                for (configs) |cfg| {
                    if (cfg.kind != .full_text) continue;
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        total += text_snapshot.term_doc_freq_cache_misses;
                    }
                }
                break :blk total;
            },
            .async_indexing = async_indexing,
        };
    }

    pub const applyStatusOnlyRebuildStateStats = db_apply.applyStatusOnlyRebuildStateStats;

    fn statusOnlyStats(self: *DB, alloc: Allocator) !types.DBStats {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        var visible_doc_count: u64 = 0;
        const identity_stats = dbDocIdentityStats(try doc_identity.fastStatsFromStore(self.core.store), self.core.identity_namespace);
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        var any_index_repair_degraded = false;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        for (configs) |cfg| {
            const projection_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const applied_sequence = try self.core.loadAppliedSequence(alloc, cfg.name);
            const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg, applied_sequence);
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
                .replay_applied_sequence = applied_sequence,
                .replay_target_sequence = target_sequence,
                .replay_catch_up_required = applied_sequence < target_sequence,
                .catch_up_active = false,
                .catch_up_applied_sequence = applied_sequence,
                .catch_up_target_sequence = target_sequence,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            try self.populateIndexSourceReplayStats(alloc, cfg.name, applied_sequence, target_sequence, &item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            if (comptime builtin.os.tag != .freestanding) {
                try self.applyStatusOnlyRebuildStateStats(alloc, cfg, &item);
            }
            applyProjectionCheckpointStats(&item, projection_checkpoint, target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (target_sequence > 0) {
                item.backfill_progress = @min(
                    1.0,
                    @as(f64, @floatFromInt(applied_sequence)) / @as(f64, @floatFromInt(target_sequence)),
                );
                item.backfill_active = item.backfill_active or applied_sequence < target_sequence;
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                if (item.load_error) |previous| alloc.free(previous);
                item.load_error = try alloc.dupe(u8, load_error);
                applyTerminalLoadFailureStatus(&item);
            } else if (try self.loadPersistedIndexLoadFailure(alloc, cfg.name)) |load_error| {
                if (item.load_error) |previous| alloc.free(previous);
                item.load_error = load_error;
                applyTerminalLoadFailureStatus(&item);
            }
            if (try self.loadIndexStatusSnapshot(alloc, cfg.name)) |status_snapshot| {
                applyIndexStatusSnapshot(&item, status_snapshot);
                visible_doc_count = @max(visible_doc_count, item.doc_count);
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                self.populateConfiguredDerivedCoverageCountsBestEffort(cfg.name, &item);
            }
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;
            if (cfg.kind == .full_text) {
                item.text_merge = self.core.index_manager.textMergeStatsSnapshotForIndex(cfg.name);
                if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
            }
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .source_doc_count = identity_stats.live_ordinals,
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .visibility = self.snapshotVisibilityStats(),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .async_indexing = self.async_context.stats.snapshot(),
        };
    }

    fn populateAlgebraicIndexStats(self: *DB, alloc: Allocator, index_name: []const u8, item: *types.DBIndexStats, include_adaptive_scans: bool) !void {
        const entry = self.core.index_manager.algebraicIndex(index_name) orelse return;
        const status_value = entry.index.status();
        const cfg = entry.index.config();
        item.algebraic_parse_error_count = status_value.parse_error_count;
        item.algebraic_schema_version = cfg.schema_version;
        if (cfg.capability_fingerprint.len > 0) {
            item.algebraic_capability_fingerprint = try alloc.dupe(u8, cfg.capability_fingerprint);
        }
        if (cfg.capability_lifecycle_status.len > 0) {
            item.algebraic_capability_lifecycle_status = try alloc.dupe(u8, cfg.capability_lifecycle_status);
        }
        item.algebraic_capability_change_added_fields = cfg.capability_change_added_fields;
        item.algebraic_capability_change_removed_fields = cfg.capability_change_removed_fields;
        item.algebraic_capability_change_changed_type_fields = cfg.capability_change_changed_type_fields;
        item.algebraic_skipped_dynamic_fields = cfg.skipped_dynamic_fields;
        item.algebraic_skipped_complex_fields = cfg.skipped_complex_fields;
        item.algebraic_skipped_unbounded_fields = cfg.skipped_unbounded_fields;
        item.algebraic_minmax_cache_hits = status_value.minmax_cache_hits;
        item.algebraic_minmax_cache_misses = status_value.minmax_cache_misses;
        item.algebraic_minmax_support_scans = status_value.minmax_support_scans;
        item.algebraic_planner_selected = status_value.planner_algebraic_selected;
        item.algebraic_planner_fallback_count = status_value.planner_fallback_count;
        if (status_value.planner_last_decision) |value| {
            item.algebraic_planner_last_decision = try alloc.dupe(u8, value);
        }
        if (status_value.planner_last_fallback_reason) |value| {
            item.algebraic_planner_last_fallback_reason = try alloc.dupe(u8, value);
        }
        item.algebraic_planner_last_estimated_scan_rows = if (status_value.planner_last_estimated_scan_rows) |value| @intCast(value) else null;
        item.algebraic_planner_last_estimated_result_buckets = if (status_value.planner_last_estimated_result_buckets) |value| @intCast(value) else null;
        item.algebraic_planner_lifecycle_ready = status_value.planner_lifecycle_ready;
        if (status_value.planner_lifecycle_blocking_reason) |value| {
            item.algebraic_planner_lifecycle_blocking_reason = try alloc.dupe(u8, value);
        }
        item.algebraic_dictionary_registry_claimed_count = status_value.dictionary_registry_claimed_count;
        item.algebraic_dictionary_registry_already_owned_count = status_value.dictionary_registry_already_owned_count;
        item.algebraic_dictionary_registry_owned_by_other_count = status_value.dictionary_registry_owned_by_other_count;
        item.algebraic_dictionary_registry_ready_hit_count = status_value.dictionary_registry_ready_hit_count;
        item.algebraic_dictionary_registry_ready_miss_count = status_value.dictionary_registry_ready_miss_count;
        item.algebraic_distributed_partial_validation_proven_count = status_value.distributed_partial_validation_proven_count;
        item.algebraic_distributed_partial_validation_rejected_count = status_value.distributed_partial_validation_rejected_count;
        item.algebraic_distributed_partial_rows_exported_count = status_value.distributed_partial_rows_exported_count;
        item.algebraic_vector_filter_attempt_count = status_value.vector_filter_attempt_count;
        item.algebraic_vector_filter_resolved_count = status_value.vector_filter_resolved_count;
        item.algebraic_vector_filter_unsupported_count = status_value.vector_filter_unsupported_count;
        item.algebraic_vector_filter_fail_closed_count = status_value.vector_filter_fail_closed_count;
        item.algebraic_vector_filter_include_doc_id_count = status_value.vector_filter_include_doc_id_count;
        item.algebraic_vector_filter_exclude_doc_id_count = status_value.vector_filter_exclude_doc_id_count;
        item.algebraic_observed_query_shape_count = status_value.observed_query_shape_count;
        item.algebraic_recommendation_count = status_value.recommendation_count;
        if (include_adaptive_scans) {
            const adaptive_candidates = try entry.index.scanPersistedAdaptiveCandidates(self.core.store);
            defer {
                for (adaptive_candidates) |*candidate| candidate.deinit(entry.index.alloc);
                if (adaptive_candidates.len > 0) entry.index.alloc.free(adaptive_candidates);
            }
            item.algebraic_adaptive_candidate_count = @intCast(adaptive_candidates.len);
            var top_candidate_index: ?usize = null;
            for (adaptive_candidates) |candidate| switch (candidate.lifecycle) {
                .backfilling => item.algebraic_adaptive_backfilling_count += 1,
                .ready => item.algebraic_adaptive_ready_count += 1,
                .stale => item.algebraic_adaptive_stale_count += 1,
                .dematerialize_recommended => item.algebraic_adaptive_dematerialize_recommended_count += 1,
                else => {},
            };
            for (adaptive_candidates, 0..) |candidate, i| {
                const selected_index = top_candidate_index orelse {
                    top_candidate_index = i;
                    continue;
                };
                const selected = adaptive_candidates[selected_index];
                if (candidate.score > selected.score or
                    (candidate.score == selected.score and candidate.observation_count > selected.observation_count))
                {
                    top_candidate_index = i;
                }
            }
            if (adaptive_candidates.len > 0) {
                const status_candidates = try alloc.alloc(types.AlgebraicCandidateStatus, adaptive_candidates.len);
                var initialized_candidates: usize = 0;
                errdefer {
                    for (status_candidates[0..initialized_candidates]) |candidate| {
                        alloc.free(candidate.recommendation);
                        alloc.free(candidate.materialization_id);
                        alloc.free(candidate.lifecycle);
                        alloc.free(candidate.decision);
                    }
                    alloc.free(status_candidates);
                }
                for (adaptive_candidates, 0..) |candidate, i| {
                    status_candidates[i] = try cloneAlgebraicCandidateStatusAlloc(
                        alloc,
                        candidate.recommendation,
                        candidate.materialization_id,
                        @tagName(candidate.lifecycle),
                        candidate.decision,
                        candidate.observation_count,
                        candidate.estimated_scan_rows_saved,
                        candidate.estimated_write_cost,
                        candidate.estimated_tensor_rows,
                        candidate.estimated_storage_bytes,
                        candidate.estimated_write_amplification,
                        candidate.score,
                        candidate.idle_miss_count,
                        candidate.generation,
                    );
                    initialized_candidates += 1;
                }
                item.algebraic_candidates = status_candidates;
            }
            if (top_candidate_index) |i| {
                const candidate = adaptive_candidates[i];
                item.algebraic_top_candidate = try cloneAlgebraicCandidateStatusAlloc(
                    alloc,
                    candidate.recommendation,
                    candidate.materialization_id,
                    @tagName(candidate.lifecycle),
                    candidate.decision,
                    candidate.observation_count,
                    candidate.estimated_scan_rows_saved,
                    candidate.estimated_write_cost,
                    candidate.estimated_tensor_rows,
                    candidate.estimated_storage_bytes,
                    candidate.estimated_write_amplification,
                    candidate.score,
                    candidate.idle_miss_count,
                    candidate.generation,
                );
            }
            const adaptive_decisions = try entry.index.scanPersistedAdaptiveDecisions(self.core.store, 16);
            defer {
                for (adaptive_decisions) |*decision| decision.deinit(entry.index.alloc);
                if (adaptive_decisions.len > 0) entry.index.alloc.free(adaptive_decisions);
            }
            item.algebraic_adaptive_decision_history_count = @intCast(adaptive_decisions.len);
            for (adaptive_decisions) |decision| {
                if (!std.mem.eql(u8, decision.previous_decision, decision.decision) or decision.score_delta != 0) {
                    item.algebraic_adaptive_policy_drift_count += 1;
                }
            }
            if (adaptive_decisions.len > 0) {
                const status_decisions = try alloc.alloc(types.AlgebraicCandidateDecisionStatus, adaptive_decisions.len);
                var initialized_decisions: usize = 0;
                errdefer {
                    for (status_decisions[0..initialized_decisions]) |decision| {
                        alloc.free(decision.recommendation);
                        alloc.free(decision.materialization_id);
                        alloc.free(decision.lifecycle);
                        alloc.free(decision.previous_decision);
                        alloc.free(decision.decision);
                    }
                    alloc.free(status_decisions);
                }
                for (adaptive_decisions, 0..) |decision, i| {
                    status_decisions[i] = try cloneAlgebraicCandidateDecisionStatusAlloc(
                        alloc,
                        decision.recommendation,
                        decision.materialization_id,
                        @tagName(decision.lifecycle),
                        decision.previous_decision,
                        decision.decision,
                        decision.observation_count,
                        decision.estimated_scan_rows_saved,
                        decision.estimated_write_cost,
                        decision.score,
                        decision.score_delta,
                        decision.idle_miss_count,
                        decision.generation,
                    );
                    initialized_decisions += 1;
                }
                item.algebraic_candidate_decision_history = status_decisions;
            }
            const adaptive_progress = try entry.index.scanPersistedAdaptiveProgress(self.core.store);
            defer {
                for (adaptive_progress) |*progress| progress.deinit(entry.index.alloc);
                if (adaptive_progress.len > 0) entry.index.alloc.free(adaptive_progress);
            }
            item.algebraic_adaptive_progress_count = @intCast(adaptive_progress.len);
            var active_progress_index: ?usize = null;
            if (adaptive_candidates.len == 0) {
                for (adaptive_progress) |progress| switch (progress.lifecycle) {
                    .backfilling => item.algebraic_adaptive_backfilling_count += 1,
                    .ready => item.algebraic_adaptive_ready_count += 1,
                    .stale => item.algebraic_adaptive_stale_count += 1,
                    .dematerialize_recommended => item.algebraic_adaptive_dematerialize_recommended_count += 1,
                    else => {},
                };
            }
            for (adaptive_progress, 0..) |progress, i| {
                const selected_index = active_progress_index orelse {
                    active_progress_index = i;
                    continue;
                };
                const selected = adaptive_progress[selected_index];
                if ((progress.lifecycle == .backfilling and selected.lifecycle != .backfilling) or
                    (progress.lifecycle == selected.lifecycle and progress.target_sequence > selected.target_sequence) or
                    (progress.lifecycle == selected.lifecycle and progress.target_sequence == selected.target_sequence and progress.rows_processed > selected.rows_processed))
                {
                    active_progress_index = i;
                }
            }
            if (adaptive_progress.len > 0) {
                const status_progress = try alloc.alloc(types.AlgebraicProgressStatus, adaptive_progress.len);
                var initialized_progress: usize = 0;
                errdefer {
                    for (status_progress[0..initialized_progress]) |progress| {
                        alloc.free(progress.recommendation);
                        alloc.free(progress.materialization_id);
                        alloc.free(progress.lifecycle);
                    }
                    alloc.free(status_progress);
                }
                for (adaptive_progress, 0..) |progress, i| {
                    status_progress[i] = try cloneAlgebraicProgressStatusAlloc(
                        alloc,
                        progress.recommendation,
                        progress.materialization_id,
                        @tagName(progress.lifecycle),
                        progress.target_sequence,
                        progress.applied_sequence,
                        progress.rows_processed,
                        progress.target_rows,
                    );
                    initialized_progress += 1;
                }
                item.algebraic_progress = status_progress;
            }
            if (active_progress_index) |i| {
                const progress = adaptive_progress[i];
                item.algebraic_active_progress = try cloneAlgebraicProgressStatusAlloc(
                    alloc,
                    progress.recommendation,
                    progress.materialization_id,
                    @tagName(progress.lifecycle),
                    progress.target_sequence,
                    progress.applied_sequence,
                    progress.rows_processed,
                    progress.target_rows,
                );
            }
        }
        if (status_value.last_error_doc_key) |value| {
            item.algebraic_last_error_doc_key = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_error_doc_key) |value| {
            alloc.free(value);
            item.algebraic_last_error_doc_key = null;
        };
        if (status_value.last_error_reason) |value| {
            item.algebraic_last_error_reason = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_error_reason) |value| {
            alloc.free(value);
            item.algebraic_last_error_reason = null;
        };
        if (status_value.last_observed_query_shape) |value| {
            item.algebraic_last_observed_query_shape = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_observed_query_shape) |value| {
            alloc.free(value);
            item.algebraic_last_observed_query_shape = null;
        };
        if (status_value.last_recommended_materialization) |value| {
            item.algebraic_last_recommended_materialization = try alloc.dupe(u8, value);
        }
    }

    fn scanPrimaryDocCount(self: *DB, byte_range: types.ByteRange) !u64 {
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var doc_count: u64 = 0;
        const CountState = struct {
            doc_count: *u64,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                _ = value;
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (isPrimaryDocumentStoreKey(key)) state.doc_count.* += 1;
                return .@"continue";
            }
        };

        var state = CountState{ .doc_count = &doc_count };
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, CountState.scanEntry);
        return doc_count;
    }

    pub fn initializeDerivedCoverageIdentity(cfg: types.IndexConfig, item: *types.DBIndexStats) void {
        item.coverage_generation = internal_keys.derivedCoverageGenerationForConfig(cfg.coverage_generation, cfg.config_json);
        if (cfg.coverage_config_fingerprint) |fingerprint| {
            item.coverage_config_hash = fingerprint;
            item.coverage_identity_ready = true;
        } else {
            // Catalog admission should make this state unreachable. Keep status
            // available and expose the missing identity as degraded coverage.
            item.coverage_summary_ready = false;
            item.repair_degraded = true;
        }
    }

    fn hydrateDerivedCoverageIdentities(self: *DB, alloc: Allocator, items: []types.DBIndexStats) !void {
        var needs_hydration = false;
        for (items) |item| {
            if (!item.coverage_identity_ready) {
                needs_hydration = true;
                break;
            }
        }
        if (!needs_hydration) return;

        var identities = try self.core.index_manager.coverageIdentityMapAlloc(alloc);
        defer identities.deinit(alloc);
        for (items) |*item| {
            const identity = identities.get(item.name) orelse {
                markMissingDerivedCoverageIdentity(item);
                continue;
            };
            item.coverage_generation = identity.generation;
            if (identity.config_fingerprint) |fingerprint| {
                item.coverage_config_hash = fingerprint;
                item.coverage_identity_ready = true;
            } else {
                markMissingDerivedCoverageIdentity(item);
            }
        }
    }

    fn hydrateDerivedCoverageIdentitiesBestEffort(self: *DB, alloc: Allocator, items: []types.DBIndexStats) void {
        self.hydrateDerivedCoverageIdentities(alloc, items) catch markMissingDerivedCoverageIdentities(items);
    }

    fn markMissingDerivedCoverageIdentities(items: []types.DBIndexStats) void {
        for (items) |*item| {
            markMissingDerivedCoverageIdentity(item);
        }
    }

    fn markMissingDerivedCoverageIdentity(item: *types.DBIndexStats) void {
        item.coverage_identity_ready = false;
        item.coverage_summary_ready = false;
        if (item.kind == .dense_vector) item.publication_target_ready = false;
        item.repair_degraded = true;
    }

    pub fn populateDerivedCoverageCounts(self: *DB, index_name: []const u8, generation: u64, config_hash: u64, item: *types.DBIndexStats) !DerivedCoverageCounters {
        item.coverage_config_hash = config_hash;
        const coverage_counts = try loadDerivedCoverageCounters(self.core.alloc, self.core.store, index_name, generation, null, if (builtin.is_test) self.async_context else null);
        const produced = coverage_counts.produced;
        const skipped = coverage_counts.skipped;
        const terminal_failed = coverage_counts.terminal_failed;

        const present_count: u2 = @as(u2, @intFromBool(produced != null)) +
            @as(u2, @intFromBool(skipped != null)) +
            @as(u2, @intFromBool(terminal_failed != null));
        // Counter creation and marker mutation share one atomic batch. No
        // counters means a new generation; a partial tuple means corruption or
        // an interrupted legacy write and must not be reported as complete.
        item.coverage_summary_ready = present_count == 0 or present_count == 3;
        item.coverage_produced_count = produced orelse 0;
        item.coverage_skipped_count = skipped orelse 0;
        item.coverage_terminal_failed_count = terminal_failed orelse 0;
        if (!item.coverage_summary_ready) item.repair_degraded = true;
        return coverage_counts;
    }

    /// Whether producer-outcome coverage is meaningful for a graph or
    /// full_text index: only artifact-sourced projections have producers
    /// that record per-document outcomes. Embeddings indexes always apply.
    pub const derivedCoverageAppliesToIndex = local_mutation.derivedCoverageAppliesToIndex;

    pub fn populateConfiguredDerivedCoverageCounts(self: *DB, index_name: []const u8, item: *types.DBIndexStats) !void {
        if (!item.coverage_identity_ready) {
            item.coverage_summary_ready = false;
            if (item.kind == .dense_vector) item.publication_target_ready = false;
            item.repair_degraded = true;
            return;
        }
        const coverage_counts = try self.populateDerivedCoverageCounts(index_name, item.coverage_generation, item.coverage_config_hash, item);
        // Publication cardinality and source outcomes belong to the same
        // committed revision. Re-reading the artifact counter here could
        // combine old source coverage with a newer publication target.
        try self.populateDensePublicationTarget(index_name, coverage_counts, item);
    }

    pub const populateDensePublicationTarget = db_dense.populateDensePublicationTarget;

    pub fn populateConfiguredDerivedCoverageCountsBestEffort(self: *DB, index_name: []const u8, item: *types.DBIndexStats) void {
        self.populateConfiguredDerivedCoverageCounts(index_name, item) catch {
            item.coverage_summary_ready = false;
            if (item.kind == .dense_vector) item.publication_target_ready = false;
            item.repair_degraded = true;
        };
    }

    fn scanPrimaryDocIdentityCoverage(self: *DB, byte_range: types.ByteRange) !DocIdentityCoverage {
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var doc_ids = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (doc_ids.items) |doc_id| self.core.alloc.free(doc_id);
            doc_ids.deinit(self.core.alloc);
        }

        var coverage = DocIdentityCoverage{};
        const ScanState = struct {
            alloc: Allocator,
            doc_ids: *std.ArrayListUnmanaged([]u8),
            coverage: *DocIdentityCoverage,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                _ = value;
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (!isPrimaryDocumentStoreKey(key)) return .@"continue";
                const raw_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.alloc, key)) orelse return .@"continue";
                errdefer state.alloc.free(raw_key);
                try state.doc_ids.append(state.alloc, raw_key);
                state.coverage.scanned_primary_docs += 1;
                return .@"continue";
            }
        };

        var scan_state = ScanState{
            .alloc = self.core.alloc,
            .doc_ids = &doc_ids,
            .coverage = &coverage,
        };
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &scan_state, ScanState.scanEntry);

        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();
        for (doc_ids.items) |doc_id| {
            const ordinal = (try doc_identity.lookupOrdinalTxn(self.core.alloc, &txn, doc_id)) orelse {
                coverage.primary_docs_missing_ordinals += 1;
                continue;
            };
            const state = (try doc_identity.lookupStateTxn(&txn, ordinal)) orelse {
                coverage.primary_docs_missing_identity_state += 1;
                continue;
            };
            if (!state.isLive()) coverage.primary_docs_with_tombstone_ordinals += 1;
        }
        return coverage;
    }

    pub fn primaryDocCount(self: *DB, alloc: Allocator) !u64 {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc });
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.scanPrimaryDocCount(self.core.byteRange());
    }

    pub const generatedCoverageRecoveryConfigsAlloc = db_enrichment.generatedCoverageRecoveryConfigsAlloc;

    pub const generatedCoverageReplayNeeded = db_enrichment.generatedCoverageReplayNeeded;

    pub const generatedCoverageRecoveryOwnedByInitialBuild = db_enrichment.generatedCoverageRecoveryOwnedByInitialBuild;

    pub const currentInitialBuildIntentMatches = db_transaction.currentInitialBuildIntentMatches;

    pub const currentNonInitialRepairIntentMatches = db_transaction.currentNonInitialRepairIntentMatches;

    pub const ensureGeneratedCoverageRecoveryIntents = db_transaction.ensureGeneratedCoverageRecoveryIntents;

    pub fn scan(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions) !types.ScanResult {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc, from_key, to_key, opts });
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var collector = result_collectors.Scan{ .alloc = alloc, .include_documents = opts.include_documents };
        defer collector.deinit();
        try self.scanVisit(alloc, from_key, to_key, opts, .{
            .context = &collector,
            .visit = result_collectors.Scan.visit,
        });
        return try collector.finish();
    }

    pub const StatementReadFence = struct {
        primary: snapshot_admission_mod.SnapshotAdmission.CaptureLease,
        replay: snapshot_admission_mod.SnapshotAdmission.CaptureLease,

        pub fn release(fence: *StatementReadFence) void {
            if (comptime storage_engine.enabled) return storage_engine.call("statementFenceRelease", .{fence}) catch @panic("incompatible storage owner");
            fence.replay.release();
            fence.primary.release();
        }
    };

    /// A short capture fence, not a transaction-long writer lock. The caller
    /// captures every participating owner, pins their read views, then releases
    /// every fence before reading rows. A busy participant requires releasing
    /// ALL earlier fences before retrying: a prepared transaction may need one
    /// of those owners to finish resolution. Never drain it under this fence.
    pub fn tryStatementReadFence(self: *DB) !?StatementReadFence {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self});
        return self.tryPrimaryReadFence(false);
    }

    pub const tryEmbeddedBackupReadFence = db_restore.tryEmbeddedBackupReadFence;

    pub fn tryPrimaryReadFence(self: *DB, allow_unresolved: bool) !?StatementReadFence {
        var primary = self.core.snapshot_admission.tryAcquireCapture() orelse return null;
        errdefer primary.release();
        var replay = self.core.snapshot_replay_admission.tryAcquireCapture() orelse {
            primary.release();
            return null;
        };
        errdefer replay.release();
        // SQL pins only the primary row store. External vector payloads are
        // irrelevant to this visibility cut; the full-backup capability gate
        // would incorrectly reject ordinary SQL on such tables.
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        if (!allow_unresolved and try manager.hasUnresolvedWriteIntents()) {
            replay.release();
            primary.release();
            return null;
        }
        return .{ .primary = primary, .replay = replay };
    }

    /// Owns a retained schema/store snapshot and its authorization predicate.
    /// The DB owner and request cancellation source must outlive this session;
    /// no query, projection, bound or filter bytes are borrowed from the caller.
    pub const RelationalReadSession = @import("relational_read_session.zig").Session;

    pub const DocumentReadSession = @import("document/rows.zig").Session;

    pub const openDocumentReadSession = db_document.openDocumentReadSession;

    pub const openRelationalReadSession = db_relational.openRelationalReadSession;

    pub fn openRelationalReadSessionAtSnapshot(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions, statement: ?*RelationalStatementSnapshot) !*RelationalReadSession {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc, from_key, to_key, opts, statement });
        try self.maybeFinalizePendingRowPolicyPublication();
        var verified_principal: ?std.json.Parsed(row_policy_authority_mod.Payload) = null;
        defer if (verified_principal) |*proof| proof.deinit();
        var row_policy_lease = if (opts.row_policy_principal_proof.len != 0) bound: {
            if (opts.row_policy_principal_proof.len > row_policy_authority_mod.maximum_token_bytes or
                opts.row_policy_database.len == 0) return error.RowPolicyAuthenticationRequired;
            if (statement) |cut| if (cut.row_policy_phase != .active) return error.RowPolicyCatalogChanged;
            const secret = self.local_execution.row_policy_authority_secret orelse return error.RowPolicyAuthorityUnavailable;
            const issuer = self.local_execution.row_policy_authority_issuer orelse return error.RowPolicyAuthorityUnavailable;
            const table = self.local_execution.row_policy_table_name orelse return error.RowPolicyAuthorityUnavailable;
            const now_seconds: i64 = @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s));
            verified_principal = try row_policy_authority_mod.verify(alloc, secret, issuer, .{
                .table_id = self.core.identity_namespace.table_id,
                .table = table,
                .database = opts.row_policy_database,
                .policy_generation = self.local_execution.row_policy_gate.generation.load(.acquire),
                .catalog_epoch = self.local_execution.row_policy_gate.catalog_epoch.load(.acquire),
            }, now_seconds, opts.row_policy_principal_proof);
            if (statement) |cut| if (cut.row_policy_generation != verified_principal.?.value.policy_generation or
                cut.row_policy_catalog_epoch != verified_principal.?.value.catalog_epoch) return error.RowPolicyCatalogChanged;
            break :bound try self.local_execution.row_policy_gate.enterVerifiedPrincipal(&verified_principal.?.value, now_seconds);
        } else if (statement) |pinned_statement| blk: {
            if (pinned_statement.row_policy_phase != .disabled) return error.RowPolicyAuthenticationRequired;
            const lease = if (pinned_statement.row_policy_lease) |*active| active else return error.RowPolicyAuthenticationRequired;
            break :blk lease.clone();
        } else try self.local_execution.row_policy_gate.enterRawRead();
        errdefer row_policy_lease.release();
        if (opts.relational_query_json.len > 1024 * 1024 or opts.limit > 4096) return error.InvalidRelationalRowsRequest;
        const session = try alloc.create(RelationalReadSession);
        errdefer alloc.destroy(session);
        session.* = .{ .alloc = alloc, .cancellation = opts.cancellation, .deadline_ns = opts.execution_deadline_ns };
        try session.checkpoint();
        const Input = types.RelationalRowQuery;
        var parsed_json: ?std.json.Parsed(Input) = if (opts.relational_query == null) std.json.parseFromSlice(Input, alloc, opts.relational_query_json, .{ .allocate = .alloc_always, .parse_numbers = false, .ignore_unknown_fields = true }) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidRelationalRowsRequest,
        } else null;
        defer if (parsed_json) |*owned| owned.deinit();
        const parsed = .{ .value = opts.relational_query orelse parsed_json.?.value };
        if (parsed.value.page_bytes == 0 or parsed.value.page_bytes > 16 * 1024 * 1024) return error.InvalidRelationalRowsRequest;
        session.page_bytes = parsed.value.page_bytes;
        if (parsed.value.conditions.len > 256 or parsed.value.fields.len > 256) return error.InvalidRelationalRowsRequest;
        var view = self.core.acquireSchemaView() orelse return error.RelationalTableRequired;
        defer view.release();
        if (view.storageMode() != .relational) return error.RelationalTableRequired;
        if (opts.include_range_proofs and view.tableSchema().ttl_duration_ns != 0) return error.UnsupportedSqlExecution;
        if (parsed.value.schema_version) |version| if (version != view.version()) return error.PreparedGenerationChanged;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const scratch = arena.allocator();
        if (parsed.value.index == null and (parsed.value.after != null or parsed.value.lower != null or parsed.value.upper != null)) return error.InvalidRelationalRowsRequest;
        if (parsed.value.index != null and (parsed.value.schema_version == null or from_key.len != 0 or to_key.len != 0)) return error.InvalidRelationalRowsRequest;
        var lower: ?RelationalRows.Bound = null;
        var upper: ?RelationalRows.Bound = null;
        if (parsed.value.index) |name| {
            var indexes = self.core.relational_indexes.acquire() orelse return error.IndexNotFound;
            defer indexes.deinit();
            if (indexes.plan.schemaView().epoch != view.epoch) return error.PreparedGenerationChanged;
            const index = for (indexes.plan.boundIndexes()) |candidate| {
                if (std.mem.eql(u8, candidate.name, name)) break candidate;
            } else return error.IndexNotFound;
            inline for (.{ "lower", "upper" }) |field| {
                if (@field(parsed.value, field)) |bound| {
                    if (bound.values.len == 0 or bound.values.len > index.tuple.keys.len) return error.InvalidRelationalIndexBound;
                    const values = try scratch.alloc(RelationalRows.Value, bound.values.len);
                    for (bound.values, values, index.tuple.keys[0..bound.values.len]) |value, *target, key| {
                        target.* = try relational_checks_mod.valueFromJson(scratch, key.column_type, value, true);
                    }
                    if (comptime std.mem.eql(u8, field, "lower")) lower = .{ .values = values, .inclusive = bound.inclusive } else upper = .{ .values = values, .inclusive = bound.inclusive };
                }
            }
        }
        const conditions = try scratch.alloc(RelationalRows.Condition, parsed.value.conditions.len);
        for (parsed.value.conditions, conditions) |condition, *compiled| {
            const ordinal = view.physicalLayout().ordinalForName(view.tableSchema().relational_columns, condition.column) orelse return error.RelationalIndexColumnNotFound;
            compiled.* = .{
                .column = condition.column,
                .op = condition.op,
                .value = try relational_checks_mod.valueFromJson(scratch, view.tableSchema().relational_columns[ordinal].column_type, condition.value orelse .null, true),
                .collation = condition.collation,
            };
        }
        const Filter = struct {
            alloc: Allocator,
            source: ?db_query_graph.PreparedPatternFilter = null,
            policy: ?*row_policy_bundle_mod.ReadEvaluation = null,
            bound: ?db_query_graph.PreparedOrdinalPatternFilter = null,
            version: ?u32 = null,

            pub fn deinit(filter: *@This()) void {
                if (filter.bound) |*bound| bound.deinit();
                if (filter.source) |*source| source.deinit();
                if (filter.policy) |policy| policy.deinit();
            }

            fn destroy(owner: Allocator, raw: *anyopaque) void {
                const filter: *@This() = @ptrCast(@alignCast(raw));
                filter.deinit();
                owner.destroy(filter);
            }

            fn matches(raw: *anyopaque, temporary: Allocator, key: []const u8, row: relational_row_codec.OrdinalRowView) !bool {
                const filter: *@This() = @ptrCast(@alignCast(raw));
                if (filter.policy) |policy| if (!try policy.permits(row)) return false;
                const source = if (filter.source) |*active| active else return true;
                if (filter.version == null or filter.version.? != row.table_schema.version) {
                    if (filter.bound) |*bound| bound.deinit();
                    filter.bound = null;
                    filter.version = null;
                    filter.bound = try db_query_graph.PreparedOrdinalPatternFilter.init(filter.alloc, source, row.table_schema, row.layout);
                    filter.version = row.table_schema.version;
                }
                if (try filter.bound.?.matches(temporary, key, row)) |matched| return matched;
                // Keep authorization semantics for filters which cannot yet
                // execute against ordinal cells. Never evaluate on the user's
                // projection or silently omit the security predicate.
                const json = try row.reconstructValueAlloc(temporary);
                defer temporary.free(json);
                return try source.matchesStored(temporary, key, json);
            }
        };
        const filter: ?*Filter = if (opts.filter_query_json.len != 0 or verified_principal != null) blk: {
            const active = try alloc.create(Filter);
            errdefer alloc.destroy(active);
            active.* = .{ .alloc = alloc };
            errdefer active.deinit();
            if (opts.filter_query_json.len != 0)
                active.source = try db_query_graph.PreparedPatternFilter.init(alloc, opts.filter_query_json);
            if (verified_principal) |*proof| {
                const bundle = if (self.local_execution.row_policy_bundle) |*installed| installed else return error.RowPolicyCatalogChanged;
                active.policy = try bundle.captureReadEvaluation(alloc, view.tableSchema().*, &proof.value);
            }
            break :blk active;
        } else null;
        errdefer if (filter) |active| Filter.destroy(alloc, active);
        session.reader = try self.beginRelationalRowsAtSnapshot(alloc, .{
            .index = parsed.value.index,
            .auto_index = parsed.value.auto_index,
            .include_primary_digest = opts.include_content_hashes,
            .include_cursor = parsed.value.index != null,
            .after = parsed.value.after,
            .lower = lower,
            .upper = upper,
            .fields = parsed.value.fields,
            .conditions = conditions,
            .primary_lower = if (from_key.len != 0) .{ .key = from_key, .inclusive = opts.inclusive_from } else null,
            .primary_upper = if (to_key.len != 0) .{ .key = to_key, .inclusive = !opts.exclusive_to } else null,
            .expected_schema_version = parsed.value.schema_version orelse view.version(),
            .row_filter = if (filter) |active| .{ .context = active, .matches = Filter.matches } else null,
        }, statement);
        session.filter_context = filter;
        session.destroy_filter = Filter.destroy;
        errdefer session.reader.deinit();
        if (opts.include_range_proofs) {
            const tracking = range_protection_mod;
            if (session.reader.index) |index| {
                const prefix = try relational_index_records.forwardPrefix(index.id());
                const next = if (parsed.value.after == null and lower != null and upper != null and
                    lower.?.inclusive and upper.?.inclusive and
                    lower.?.values.len == index.tuple.keys.len and upper.?.values.len == index.tuple.keys.len and
                    std.mem.startsWith(u8, session.reader.lower, &prefix) and session.reader.lower.len > prefix.len)
                    try internal_keys.nextPrefixAlloc(scratch, session.reader.lower)
                else
                    null;
                if (next) |exclusive_end| {
                    if (std.mem.eql(u8, exclusive_end, session.reader.upper)) {
                        session.range_proofs = try tracking.captureIndex(alloc, &session.reader.read, index.id().encode(), session.reader.lower[prefix.len..]);
                    }
                }
            }
            if (session.range_proofs == null) session.range_proofs = try tracking.capture(alloc, &session.reader.read, from_key, to_key);
        }
        session.row_policy_lease = row_policy_lease;
        return session;
    }

    pub const scanRelationalRowsVisit = db_relational.scanRelationalRowsVisit;

    /// Stream a scan directly from one storage snapshot. This is the bounded
    /// primitive for transports and maintenance jobs: only the current row and
    /// caller-owned output are resident, and callback failure aborts promptly.
    pub fn scanVisit(
        self: *DB,
        alloc: Allocator,
        from_key: []const u8,
        to_key: []const u8,
        opts: types.ScanOptions,
        visitor: types.ScanVisitor,
    ) !void {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc, from_key, to_key, opts, visitor });
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (opts.isRelational()) return self.scanRelationalRowsVisit(alloc, from_key, to_key, opts, visitor);
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        const projection_plan = db_query_projection.buildLookupFieldSelectionPlan(.{
            .fields = opts.fields,
            .include_all_fields = opts.include_all_fields,
        });
        const needs_catalog_projection = opts.include_documents and projection_plan.special.all_artifacts;
        // Briefly pin immutable request state. The storage transaction below,
        // rather than the DB-wide apply lock, owns row/TTL consistency for the
        // potentially long scan.
        lockApplyShared(self);
        var apply_shared_held = true;
        errdefer if (apply_shared_held) self.core.unlockApplyShared();
        var schema_view = self.core.acquireSchemaView();
        defer if (schema_view) |*view| view.release();
        const ttl_duration_ns = if (schema_view) |view| view.visibilityTtlDurationNs() else 0;
        const scan_now_ns = if (ttl_duration_ns == 0) 0 else currentTimeNs();

        const borrowed_range = self.core.byteRange();
        const range_start = try alloc.dupe(u8, borrowed_range.start);
        errdefer alloc.free(range_start);
        const range_end = try alloc.dupe(u8, borrowed_range.end);
        errdefer alloc.free(range_end);
        var artifact_catalog = if (needs_catalog_projection)
            try self.core.index_manager.assetContentTypeSnapshotAlloc(alloc)
        else
            null;
        defer if (artifact_catalog) |*artifact_snapshot| artifact_snapshot.deinit();
        self.core.unlockApplyShared();
        apply_shared_held = false;
        defer alloc.free(range_start);
        defer alloc.free(range_end);
        const byte_range = types.ByteRange{ .start = range_start, .end = range_end };
        const lower_raw = if (from_key.len == 0 or std.mem.order(u8, from_key, byte_range.start) == .lt) byte_range.start else from_key;
        const upper_raw = blk: {
            if (to_key.len == 0) break :blk byte_range.end;
            if (byte_range.end.len == 0 or std.mem.order(u8, to_key, byte_range.end) == .lt) break :blk to_key;
            break :blk byte_range.end;
        };
        const lower = try self.core.documentRangeLowerAlloc(lower_raw);
        defer self.core.alloc.free(lower);
        const upper = if (upper_raw.len > 0) try self.core.documentRangeUpperAlloc(upper_raw) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var prepared_filter = if (opts.filter_query_json.len > 0)
            try db_query_graph.PreparedPatternFilter.init(alloc, opts.filter_query_json)
        else
            null;
        defer if (prepared_filter) |*filter| filter.deinit();
        const direct_projection_fields = if (opts.include_documents)
            ordinalProjectionFields(opts.fields, opts.include_all_fields)
        else
            null;
        var read_txn = try self.core.store.beginReadTxn();
        defer read_txn.abort();
        var projection_context = TransactionProjectionContext{
            .source = .{ .core = self.core },
            .read_txn = &read_txn,
            .artifact_catalog = if (artifact_catalog) |*artifact_snapshot| artifact_snapshot else null,
        };

        var columnar_progress: relational_columns.Progress = .{};
        defer columnar_progress.last_key.deinit(alloc);
        var column_materializer = ColumnScanMaterializer{ .context = &projection_context, .opts = opts };
        const accelerated = if (schema_view != null and schema_view.?.storageMode() == .relational) relational_columns.scan(self, alloc, &read_txn, from_key, to_key, byte_range, opts, visitor, ttl_duration_ns, scan_now_ns, &columnar_progress, if (prepared_filter) |*filter| filter else null, .{ .context = &column_materializer, .project = ColumnScanMaterializer.project }) catch |err| switch (err) {
            error.InvalidColumnSegment, error.InvalidData, error.NotFound => blk: {
                if (columnar_progress.callback_failed) return err;
                // Disposable derived corruption never makes valid primary rows
                // unreadable. Resume in the same snapshot after the last row
                // actually delivered, preserving limits and avoiding duplicates.
                self.relational_columns_rebuild_requested.store(true, .release);
                break :blk false;
            },
            else => return err,
        } else false;
        if (accelerated) return;
        var fallback_opts = opts;
        if (columnar_progress.delivered != 0) fallback_opts.inclusive_from = false;

        var stream_plan = if (visitor.borrow_documents and opts.include_documents and !projection_plan.special.all_artifacts and !projection_plan.special.all_chunks and !projection_plan.special.all_embeddings)
            try document_query.SpanProjectionPlan.init(alloc, .{ .fields = opts.fields, .include_all_fields = opts.include_all_fields })
        else
            null;
        defer if (stream_plan) |*plan| plan.deinit();
        const ScanState = struct {
            const max_resident_schema_plans = 32;
            const SchemaPlan = struct {
                version: u32,
                access: u64,
                view: schema_registry_mod.SchemaView,
                filter: ?db_query_graph.PreparedOrdinalPatternFilter = null,
                projection: ?RelationalProjectionPlan = null,

                pub fn deinit(plan: *@This()) void {
                    if (plan.filter) |*filter| filter.deinit();
                    if (plan.projection) |*projection| projection.deinit();
                    plan.view.release();
                    plan.* = undefined;
                }
            };

            db: *DB,
            alloc: Allocator,
            byte_range: types.ByteRange,
            from_key: []const u8,
            to_key: []const u8,
            opts: types.ScanOptions,
            ttl_duration_ns: u64,
            now_ns: u64,
            filter: ?*db_query_graph.PreparedPatternFilter,
            direct_projection_fields: ?[]const []const u8,
            stream_plan: ?*const document_query.SpanProjectionPlan,
            read_txn: *docstore_mod.DocStore.Txn,
            projection_context: *TransactionProjectionContext,
            values_authenticated: bool,
            ttl_key_scratch: std.ArrayListUnmanaged(u8) = .empty,
            document_key_scratch: std.ArrayListUnmanaged(u8) = .empty,
            schema_plans: std.ArrayListUnmanaged(SchemaPlan) = .empty,
            schema_plan_indexes: std.AutoHashMapUnmanaged(u32, usize) = .empty,
            schema_plan_clock: u64 = 0,
            schema_admission: SchemaCacheAdmission = .{},
            transient_schema_plan: ?SchemaPlan = null,
            visitor: types.ScanVisitor,
            count: u32 = 0,
            resume_after_key: ?[]const u8 = null,

            pub fn deinit(state: *@This()) void {
                if (state.transient_schema_plan) |*plan| plan.deinit();
                state.ttl_key_scratch.deinit(state.alloc);
                state.document_key_scratch.deinit(state.alloc);
                for (state.schema_plans.items) |*plan| plan.deinit();
                state.schema_plans.deinit(state.alloc);
                state.schema_plan_indexes.deinit(state.alloc);
            }

            fn checkActive(state: *const @This()) !void {
                if (state.opts.cancellation) |cancellation|
                    if (cancellation.isCancelled()) return error.Canceled;
                if (state.opts.execution_deadline_ns) |deadline_ns|
                    if (platform_time.monotonicNs() >= deadline_ns) return error.DeadlineExceeded;
            }

            fn schemaPlan(state: *@This(), version: u32) !*SchemaPlan {
                state.schema_admission.record(version);
                state.schema_plan_clock +%= 1;
                if (state.schema_plan_clock == 0) {
                    for (state.schema_plans.items) |*resident| resident.access = 0;
                    state.schema_plan_clock = 1;
                }
                if (state.schema_plan_indexes.get(version)) |index| {
                    state.schema_plans.items[index].access = state.schema_plan_clock;
                    return &state.schema_plans.items[index];
                }
                if (state.transient_schema_plan) |*plan| {
                    if (plan.version == version) return plan;
                }

                try state.schema_plan_indexes.ensureUnusedCapacity(state.alloc, 1);
                var view = (try state.db.core.acquireSchemaVersionView(version)) orelse
                    return error.UnknownSchemaVersion;
                var view_owned = true;
                errdefer if (view_owned) view.release();
                if (view.storageMode() != .relational) return error.RelationalRowSchemaMismatch;
                var filter = if (state.filter) |prepared|
                    try db_query_graph.PreparedOrdinalPatternFilter.init(
                        state.alloc,
                        prepared,
                        view.tableSchema().*,
                        view.physicalLayout(),
                    )
                else
                    null;
                var filter_owned = filter != null;
                errdefer if (filter_owned) filter.?.deinit();
                var projection = if (state.direct_projection_fields) |fields|
                    try RelationalProjectionPlan.init(
                        state.alloc,
                        view.tableSchema().*,
                        view.physicalLayout(),
                        fields,
                    )
                else
                    null;
                var projection_owned = projection != null;
                errdefer if (projection_owned) projection.?.deinit();
                const new_plan = SchemaPlan{
                    .version = version,
                    .access = state.schema_plan_clock,
                    .view = view,
                    .filter = filter,
                    .projection = projection,
                };
                const plan_index = if (state.schema_plans.items.len < max_resident_schema_plans) blk: {
                    try state.schema_plans.append(state.alloc, new_plan);
                    break :blk state.schema_plans.items.len - 1;
                } else blk: {
                    var evicted_index: usize = 0;
                    var oldest_access = state.schema_plans.items[0].access;
                    for (state.schema_plans.items[1..], 1..) |candidate, index| {
                        const frequency = state.schema_admission.frequency(candidate.version);
                        const victim_frequency = state.schema_admission.frequency(state.schema_plans.items[evicted_index].version);
                        if (frequency < victim_frequency or (frequency == victim_frequency and candidate.access < oldest_access)) {
                            oldest_access = candidate.access;
                            evicted_index = index;
                        }
                    }
                    if (!state.schema_admission.admits(version, state.schema_plans.items[evicted_index].version)) {
                        if (state.transient_schema_plan) |*plan| plan.deinit();
                        state.transient_schema_plan = new_plan;
                        view_owned = false;
                        filter_owned = false;
                        projection_owned = false;
                        return &state.transient_schema_plan.?;
                    }
                    var evicted = state.schema_plans.items[evicted_index];
                    _ = state.schema_plan_indexes.remove(evicted.version);
                    state.schema_plans.items[evicted_index] = new_plan;
                    evicted.deinit();
                    break :blk evicted_index;
                };
                state.schema_plan_indexes.putAssumeCapacity(version, plan_index);
                view_owned = false;
                filter_owned = false;
                projection_owned = false;
                return &state.schema_plans.items[plan_index];
            }

            fn scanEntry(raw_ctx: ?*anyopaque, store_key: []const u8, stored_value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
                try state.checkActive();
                if (!isPrimaryDocumentStoreKey(store_key)) return .@"continue";
                const raw_key = (try internal_keys.decodeStoredDocumentRowKeyScratch(
                    &state.document_key_scratch,
                    state.alloc,
                    store_key,
                )) orelse
                    return .@"continue";

                if (state.resume_after_key) |key| if (std.mem.order(u8, raw_key, key) != .gt) return .@"continue";

                if (!state.byte_range.contains(raw_key)) return .@"continue";
                if (state.from_key.len > 0 and !state.opts.inclusive_from and std.mem.eql(u8, raw_key, state.from_key))
                    return .@"continue";
                if (state.to_key.len > 0) {
                    const order = std.mem.order(u8, raw_key, state.to_key);
                    if ((state.opts.exclusive_to and order != .lt) or (!state.opts.exclusive_to and order == .gt))
                        return .stop;
                }
                const relational = internal_keys.isRelationalRowKey(store_key);
                const row_plan = if (relational)
                    try state.schemaPlan(try relational_store.rowSchemaVersion(stored_value))
                else
                    null;
                // Authenticate and structurally parse the row exactly once for
                // this callback. Every downstream consumer receives the same
                // immutable verified view instead of independently rescanning
                // the physical checksum and header.
                const ordinal_row = if (row_plan) |plan|
                    if (state.values_authenticated)
                        try relational_row_codec.ordinalRowViewTrusted(
                            stored_value,
                            plan.view.tableSchema().*,
                            plan.view.physicalLayout(),
                        )
                    else
                        try relational_row_codec.ordinalRowView(
                            stored_value,
                            plan.view.tableSchema().*,
                            plan.view.physicalLayout(),
                        )
                else
                    null;
                if (state.ttl_duration_ns != 0) {
                    const timestamp = if (relational)
                        ordinal_row.?.writeTimestampNs()
                    else blk: {
                        state.ttl_key_scratch.clearRetainingCapacity();
                        try internal_keys.appendDocumentPrefix(&state.ttl_key_scratch, state.alloc, raw_key);
                        try state.ttl_key_scratch.append(state.alloc, internal_keys.ttl_kind);
                        const timestamp_bytes = try missingAsNull(state.read_txn.get(state.ttl_key_scratch.items));
                        break :blk if (timestamp_bytes) |value|
                            if (value.len >= @sizeOf(u64)) std.mem.readInt(u64, value[0..8], .little) else 0
                        else
                            0;
                    };
                    if (timestamp != 0 and ttl_mod.isExpired(timestamp, state.ttl_duration_ns, state.now_ns))
                        return .@"continue";
                }

                const semantic_hash = if (ordinal_row) |row| row.semanticHash() else null;
                var ordinal_filter_match: ?bool = null;
                if (row_plan) |plan| if (plan.filter) |*filter| {
                    ordinal_filter_match = try filter.matches(state.alloc, raw_key, ordinal_row.?);
                    if (ordinal_filter_match == false) return .@"continue";
                };
                const stream_whole_row = relational and state.visitor.borrow_documents and state.opts.include_documents and state.opts.fields.len == 0 and state.opts.include_all_fields;
                const needs_logical_value = !relational or semantic_hash == null or
                    (state.filter != null and ordinal_filter_match == null) or
                    (state.opts.include_documents and state.direct_projection_fields == null and !stream_whole_row);
                // Scan callbacks pin their borrowed storage slices until they
                // return. A synchronous plain-document producer can keep that
                // borrow instead of copying the entire input before projection.
                const borrow_plain = !relational and state.visitor.borrow_documents and state.stream_plan != null;
                const logical_value: ?[]const u8 = if (needs_logical_value)
                    if (ordinal_row) |row|
                        try row.reconstructValueAlloc(state.alloc)
                    else if (borrow_plain)
                        stored_value
                    else
                        try state.alloc.dupe(u8, stored_value)
                else
                    null;
                defer if (logical_value) |value| if (!borrow_plain) state.alloc.free(value);

                if (state.filter) |filter| if (ordinal_filter_match == null)
                    if (!(try filter.matchesStored(state.alloc, raw_key, logical_value.?)))
                        return .@"continue";

                var content_hash: ?document_content_hash.Digest = null;
                if (state.opts.include_content_hashes) {
                    content_hash = if (relational)
                        semantic_hash orelse try document_content_hash.hashJson(state.alloc, logical_value.?)
                    else
                        try document_content_hash.hashJson(state.alloc, logical_value.?);
                }
                var streamed: ?@import("query/streamed_projection.zig").Context = null;
                if (state.visitor.borrow_documents and state.opts.include_documents) {
                    if (ordinal_row) |row| {
                        if (stream_whole_row) {
                            streamed = .{ .scratch = state.alloc, .value = .{ .whole_row = row } };
                        } else if (row_plan.?.projection) |plan| streamed = .{ .scratch = state.alloc, .value = .{ .row = .{ .plan = plan, .row = row } } };
                    } else if (state.stream_plan) |plan| streamed = .{ .scratch = state.alloc, .value = .{ .document = .{ .plan = plan, .raw = logical_value.? } } };
                }
                const projected = if (state.opts.include_documents and streamed == null)
                    if (state.direct_projection_fields) |_|
                        if (ordinal_row) |row|
                            try row_plan.?.projection.?.project(state.alloc, row)
                        else
                            try projectLookupStoredBytesTxn(state.projection_context, state.alloc, raw_key, logical_value.?, .{
                                .fields = state.opts.fields,
                                .include_all_fields = state.opts.include_all_fields,
                            })
                    else
                        try projectLookupStoredBytesTxn(state.projection_context, state.alloc, raw_key, logical_value.?, .{
                            .fields = state.opts.fields,
                            .include_all_fields = state.opts.include_all_fields,
                        })
                else
                    null;
                defer if (projected) |document| state.alloc.free(document);
                if (streamed == null and state.visitor.borrow_documents) if (projected) |json| {
                    streamed = .{ .scratch = state.alloc, .value = .{ .json_fields = json } };
                };

                try state.visitor.visitEntry(.{
                    .id = raw_key,
                    // Relational hashes are the stable logical digest, not a
                    // hash of a transient JSON rendering. Document-mode rows
                    // retain the established byte-hash contract.
                    .hash = if (semantic_hash) |digest|
                        std.mem.readInt(u64, digest[0..8], .little)
                    else
                        std.hash.Wyhash.hash(0, logical_value.?),
                    .content_hash = content_hash,
                    .document_json = if (streamed == null) projected else null,
                    .document_stream = if (streamed) |*context| context.borrow() else null,
                });

                state.count += 1;
                return if (state.opts.limit > 0 and state.count >= state.opts.limit) .stop else .@"continue";
            }
        };

        var state = ScanState{
            .db = self,
            .alloc = alloc,
            .byte_range = byte_range,
            .from_key = if (columnar_progress.delivered != 0) columnar_progress.last_key.items else from_key,
            .to_key = to_key,
            .opts = fallback_opts,
            .ttl_duration_ns = ttl_duration_ns,
            .now_ns = scan_now_ns,
            .filter = if (prepared_filter) |*filter| filter else null,
            .direct_projection_fields = direct_projection_fields,
            .stream_plan = if (stream_plan) |*plan| plan else null,
            .read_txn = &read_txn,
            .projection_context = &projection_context,
            .values_authenticated = self.core.store.valuesAreAuthenticated(),
            .visitor = visitor,
            .count = columnar_progress.delivered,
            .resume_after_key = if (columnar_progress.delivered != 0) columnar_progress.last_key.items else null,
        };
        defer state.deinit();
        try state.checkActive();
        const resume_lower = if (columnar_progress.delivered != 0) try self.core.documentRangeLowerAlloc(columnar_progress.last_key.items) else null;
        defer if (resume_lower) |key| self.core.alloc.free(key);
        if (schema_view) |view| if (view.storageMode() == .relational) {
            const Check = struct {
                fn owner(ptr: ?*anyopaque, _: []const u8) !docstore_mod.DocStore.ScanAction {
                    const active: *ScanState = @ptrCast(@alignCast(ptr.?));
                    try active.checkActive();
                    if (active.opts.columnar_stats) |scan_stats| scan_stats.primary_owners_examined += 1;
                    return .@"continue";
                }
            };
            return self.core.store.scanRelationalRowsReadTxnWithContext(&read_txn, resume_lower orelse lower, upper orelse "", &state, Check.owner, ScanState.scanEntry);
        };
        try self.core.store.scanReadTxnWithContext(
            &read_txn,
            resume_lower orelse lower,
            if (upper) |buf| buf else "",
            .{},
            &state,
            ScanState.scanEntry,
        );
    }

    pub const search = db_search.search;

    pub const searchWithDenseProfile = db_dense.searchWithDenseProfile;

    pub const searchWithCapturedRequest = db_search.searchWithCapturedRequest;

    /// Delayed document hydration over the exact primary generation captured
    /// with ranking. A byte-bounded document window stays pinned; callers copy
    /// selected cells before the next lookup or page release retires it.
    pub const DocumentRows = struct {
        db: *DB,
        read: docstore_mod.DocStore.Txn,
        schema: schema_registry_mod.SchemaView,
        policy: row_policy_gate_mod.Gate.Lease,
        window: DocumentPrimaryReadWindow,
        metadata: std.heap.ArenaAllocator,
        keys: [64][]const u8 = undefined,
        ids: [64][]const u8 = undefined,
        sizes: [64]?u64 = undefined,
        proofs: [64]?@import("../document_mutation_revision.zig").Content = undefined,
        cached: usize = 0,
        next_cached: usize = 0,
        repair_requested: bool = false,
        directory_arena: std.heap.ArenaAllocator,
        directory_scope: ?@import("../backend_erased.zig").ReadScope = null,
        directories: [64]?[]const u8 = @splat(null),
        directories_loaded: [64]bool = @splat(false),
        values: [64]?[]const u8 = undefined,
        sources: [64]Source = undefined,
        pub const Batch = struct { values: []const ?[]const u8, consumed: usize };
        pub const Source = @import("../document_projection.zig").Source;
        pub const ProjectedBatch = struct { values: []const Source, consumed: usize };

        fn retireDirectories(self: *@This()) void {
            if (self.directory_scope) |*scope| scope.close();
            self.directory_scope = null;
            _ = self.directory_arena.reset(.free_all);
            @memset(&self.directories_loaded, false);
            @memset(&self.directories, null);
        }

        // Keep keys and scalar size proofs separate from body scratch: sorted
        // reads retire body scratch, and a small byte target can consume this
        // metadata window over several calls. Never reuse proofs across pages.
        fn prepare(self: *@This(), documents: []const []const u8) !void {
            const available = self.cached - self.next_cached;
            const common = @min(available, documents.len);
            if (common != 0) {
                const matches = for (documents[0..common], self.ids[self.next_cached..][0..common]) |wanted, cached_id| {
                    if (!std.mem.eql(u8, wanted, cached_id)) break false;
                } else true;
                if (matches) return;
            }
            self.cached = 0;
            self.next_cached = 0;
            self.retireDirectories();
            _ = self.metadata.reset(.free_all);
            const a = self.metadata.allocator();
            const count = @min(documents.len, self.keys.len);
            for (documents[0..count], 0..) |id, index| {
                self.ids[index] = try a.dupe(u8, id);
                self.keys[index] = try encodeStoreLookupKeyWithPinnedSchemaAlloc(self.db, a, id, self.schema);
            }
            var contents: [64]?@import("../document_mutation_revision.zig").Content = undefined;
            var timestamps: [64]u64 = undefined;
            var scope = try self.read.openReadScope(a);
            defer scope.close();
            try @import("../document_mutation_revision.zig").loadWindow(&scope, a, self.keys[0..count], self.ids[0..count], contents[0..count], timestamps[0..count]);
            for (contents[0..count], 0..) |content, index| self.sizes[index] = if (content) |proof| proof.bytes else null;
            @memcpy(self.proofs[0..count], contents[0..count]);
            self.cached = count;
        }

        /// Sorted physical reads restore caller order. Metadata lengths are
        /// revision-bound to this snapshot; unknown or oversized rows read in
        /// isolation. A legal single document may exceed the soft byte target.
        /// Results expire on the next lookup, batch or page release.
        pub fn lookupBatch(self: *@This(), documents: []const []const u8, max_bytes: usize) !Batch {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsLookupBatch", .{ self, documents, max_bytes });
            const hydrated = try self.lookupBatchImpl(documents, &.{}, max_bytes);
            return .{ .values = self.values[0..hydrated.consumed], .consumed = hydrated.consumed };
        }
        pub fn lookupProjectedBatch(self: *@This(), documents: []const []const u8, fields: []const []const u8, max_bytes: usize) !ProjectedBatch {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsLookupProjectedBatch", .{ self, documents, fields, max_bytes });
            return self.lookupBatchImpl(documents, fields, max_bytes);
        }
        fn lookupBatchImpl(self: *@This(), documents: []const []const u8, fields: []const []const u8, max_bytes: usize) !ProjectedBatch {
            if (documents.len == 0 or documents.len > 64 or max_bytes == 0) return error.InvalidBatch;
            self.window.retire();
            errdefer self.window.retire();
            if (documents.len == 1 and fields.len == 0) {
                self.values[0] = try self.lookup(documents[0]);
                self.sources[0] = .{ .bytes = self.values[0].? };
                return .{ .values = self.sources[0..1], .consumed = 1 };
            }
            try self.prepare(documents);
            if (fields.len != 0) if (try self.projectBatch(documents.len, fields, max_bytes)) |projected| return projected;
            // A declined projection must not retain its metadata/range buffers
            // beside the full body. The proof cache has a separate owner.
            self.window.retire();
            const available = @min(documents.len, self.cached - self.next_cached);
            const limit = @min(max_bytes, DocumentPrimaryReadWindow.max_bytes);
            var count: usize = 0;
            var bytes: u64 = 0;
            while (count < available) : (count += 1) {
                const length = self.sizes[self.next_cached + count] orelse break;
                if (count != 0 and fields.len != 0 and length >= @import("../document_projection.zig").minimum_bytes) break;
                if (length > limit -| bytes) break;
                bytes += length;
            }
            count = @max(count, 1);
            const keys = self.keys[self.next_cached..][0..count];
            if (count == 1) {
                self.values[0] = self.window.get(&self.read, keys[0], self.sizes[self.next_cached]) catch |err| switch (err) {
                    error.NotFound => return error.StorageReadTemporarilyUnavailable,
                    else => return err,
                };
            } else try self.window.getMany(&self.read, keys, self.values[0..count]);
            for (self.values[0..count]) |value| if (value == null) return error.StorageReadTemporarilyUnavailable;
            self.next_cached += count;
            for (self.sources[0..count], self.values[0..count]) |*source, value| source.* = .{ .bytes = value.? };
            return .{ .values = self.sources[0..count], .consumed = count };
        }

        fn requestRepair(self: *@This()) void {
            if (self.repair_requested or openModeRequiresReadOnlyBackends(self.db.open_mode)) return;
            self.repair_requested = true;
            self.db.document_authority_backfill_requested.store(true, .release);
        }
        fn projectBatch(self: *@This(), maximum: usize, fields: []const []const u8, max_bytes: usize) !?ProjectedBatch {
            const projection = @import("../document_projection.zig");
            const revision = @import("../document_mutation_revision.zig");
            const ranges_mod = @import("../value_ranges.zig");
            const available = @min(maximum, self.cached - self.next_cached);
            const limit = @min(max_bytes, DocumentPrimaryReadWindow.max_bytes);
            const a = self.window.arena.allocator();
            self.window.scope = try self.read.openReadScope(a);
            const scope = &self.window.scope.?;
            // Directory metadata is separately bounded by 64 * 32 KiB. Only
            // projected payload cohorts enter the caller's soft byte window.
            var directory_keys: [64]projection.Key = undefined;
            var keys: [64][]const u8 = undefined;
            var pending: [64]usize = undefined;
            var pending_count: usize = 0;
            var fetched: [64]?[]const u8 = @splat(null);
            var candidates: usize = 0;
            for (0..available) |i| {
                const proof = self.proofs[self.next_cached + i] orelse {
                    self.requestRepair();
                    break;
                };
                if (proof.bytes < projection.minimum_bytes) break;
                if (!self.directories_loaded[self.next_cached + i]) {
                    directory_keys[pending_count] = projection.keyForRevision(revision.keyForPhysical(self.keys[self.next_cached + i]).?);
                    keys[pending_count] = &directory_keys[pending_count];
                    pending[pending_count] = self.next_cached + i;
                    pending_count += 1;
                }
                candidates += 1;
            }
            if (candidates == 0) return null;
            if (pending_count != 0) {
                // Keep this bounded metadata lease across payload windows. A
                // one-row byte limit must not re-read all remaining directories.
                errdefer self.retireDirectories();
                if (self.directory_scope == null) self.directory_scope = try self.read.openReadScope(self.directory_arena.allocator());
                _ = try DocumentPrimaryReadWindow.readMany(&self.directory_scope.?, keys[0..pending_count], fetched[0..pending_count]);
                for (pending[0..pending_count], fetched[0..pending_count]) |index, raw| {
                    self.directories[index] = raw;
                    self.directories_loaded[index] = true;
                }
            }
            const Prepared = struct { fields: []projection.FieldValue, ranges: []ranges_mod.Range, values: [][]const u8, hashes: [][32]u8, duplicate: bool = false };
            var prepared: [64]Prepared = undefined;
            var requests: [64]ranges_mod.Request = undefined;
            var request_count: usize = 0;
            var count: usize = 0;
            var retained: usize = 0;
            while (count < candidates) : (count += 1) {
                const physical = self.keys[self.next_cached + count];
                const duplicate = for (0..count) |prior| {
                    if (std.mem.eql(u8, physical, self.keys[self.next_cached + prior])) break prior;
                } else null;
                if (duplicate) |prior| {
                    prepared[count] = prepared[prior];
                    prepared[count].duplicate = true;
                    continue;
                }
                const proof = self.proofs[self.next_cached + count].?;
                const raw = self.directories[self.next_cached + count] orelse {
                    self.requestRepair();
                    break;
                };
                const directory = (try projection.Directory.open(a, raw, proof)) orelse {
                    if (!try projection.isCurrent(a, raw, proof)) self.requestRepair();
                    break;
                };
                var selected_bytes: u64 = 0;
                var selected_count: usize = 0;
                for (fields) |name| if (directory.find(name)) |field| {
                    selected_bytes +|= field.length;
                    selected_count += 1;
                };
                if (selected_bytes >= proof.bytes / 2 or selected_count > ranges_mod.maximum_ranges) break;
                const ranges = try a.alloc(ranges_mod.Range, selected_count);
                var slot: usize = 0;
                for (fields) |name| if (directory.find(name)) |field| {
                    ranges[slot] = .{ .offset = field.offset, .length = std.math.cast(usize, field.length) orelse return error.InvalidDocumentContentAuthority };
                    slot += 1;
                };
                const cost = if (scope.supportsRange()) try ranges_mod.retainedBytes(std.math.cast(usize, proof.bytes) orelse return error.InvalidDocumentContentAuthority, ranges) else if (selected_count == 0) 0 else proof.bytes;
                if (count != 0 and cost > limit -| retained) break;
                retained +|= std.math.cast(usize, cost) orelse return error.InvalidDocumentContentAuthority;
                const output = try a.alloc(projection.FieldValue, selected_count);
                const values = try a.alloc([]const u8, selected_count);
                const hashes = try a.alloc([32]u8, selected_count);
                slot = 0;
                for (fields) |name| if (directory.find(name)) |field| {
                    output[slot] = .{ .name = field.name, .value = undefined };
                    hashes[slot] = field.digest;
                    slot += 1;
                };
                prepared[count] = .{ .fields = output, .ranges = ranges, .values = values, .hashes = hashes };
                if (selected_count != 0) {
                    requests[request_count] = .{ .key = physical, .ranges = ranges, .output = values };
                    request_count += 1;
                }
            }
            if (count == 0) return null;
            std.mem.sort(ranges_mod.Request, requests[0..request_count], {}, struct {
                fn less(_: void, left: ranges_mod.Request, right: ranges_mod.Request) bool {
                    return std.mem.order(u8, left.key, right.key) == .lt;
                }
            }.less);
            scope.getRangesMany(requests[0..request_count]) catch |err| return if (err == error.NotFound) error.StorageReadTemporarilyUnavailable else err;
            for (prepared[0..count], self.sources[0..count]) |item, *source| {
                if (!item.duplicate) for (item.values, item.hashes, item.fields) |value, hash, *field| {
                    var digest: [32]u8 = undefined;
                    std.crypto.hash.sha2.Sha256.hash(value, &digest, .{});
                    if (!std.mem.eql(u8, &digest, &hash)) return error.InvalidDocumentContentAuthority;
                    field.value = value;
                };
                source.* = .{ .fields = item.fields };
            }
            self.window.bytes = retained;
            self.next_cached += count;
            return .{ .values = self.sources[0..count], .consumed = count };
        }

        pub fn lookup(self: *@This(), key: []const u8) ![]const u8 {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsLookup", .{ self, key });
            self.window.retire();
            const a = self.window.arena.allocator();
            const physical = try encodeStoreLookupKeyWithPinnedSchemaAlloc(self.db, a, key, self.schema);
            // Ranking already applied visibility/TTL at the captured cut.
            // Never fall back to a fresh read if the captured row is absent.
            return self.window.get(&self.read, physical, 0) catch |err| switch (err) {
                error.NotFound => error.StorageReadTemporarilyUnavailable,
                else => err,
            };
        }
        /// Page cells already own their selected payloads. Retire the last
        /// source scope before a portal suspends, keeping only the snapshot.
        pub fn releasePage(self: *@This()) void {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsReleasePage", .{self}) catch @panic("incompatible storage owner");
            self.window.retire();
            self.retireDirectories();
            _ = self.metadata.reset(.free_all);
            self.cached = 0;
            self.next_cached = 0;
        }
        pub fn deinit(self: *@This()) void {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsDeinit", .{self}) catch @panic("incompatible storage owner");
            self.window.deinit();
            self.retireDirectories();
            self.directory_arena.deinit();
            self.metadata.deinit();
            self.read.abort();
            self.schema.release();
            self.policy.release();
            self.* = undefined;
        }
    };

    /// Own one primary read generation across a local query's selection and
    /// aggregation collection. Acquire only after the Raft read barrier; never
    /// wait for another apply barrier while this lease excludes writers.
    pub const QueryReadLease = struct {
        db: *DB,
        row_policy_lease: row_policy_gate_mod.Gate.Lease,

        /// Capture a primary typed reader under this lease's existing apply
        /// fence. Do not recursively acquire the fence behind a queued writer.
        pub fn relationalRows(self: *const QueryReadLease, alloc: Allocator, fields: []const []const u8, schema_version: u32) !RelationalRows.Reader {
            if (comptime storage_engine.enabled) return storage_engine.call("relationalRowsUnderLease", .{ self, alloc, fields, schema_version });
            var view = self.db.core.acquireSchemaView() orelse return error.RelationalTableRequired;
            defer view.release();
            var reader = try RelationalRows.Reader.open(alloc, self.db.core.store, view, null, .{
                .fields = fields,
                .expected_schema_version = schema_version,
            }, currentTimeNs());
            reader.row_policy_lease = self.row_policy_lease.clone();
            return reader;
        }

        pub fn documentRows(self: *const QueryReadLease, alloc: Allocator, schema_version: u32) !DocumentRows {
            if (comptime storage_engine.enabled) return storage_engine.call("documentRowsUnderLease", .{ self, alloc, schema_version });
            var view = self.db.core.acquireSchemaView() orelse return error.PreparedGenerationChanged;
            errdefer view.release();
            if (view.storageMode() != .document or view.version() != schema_version) return error.PreparedGenerationChanged;
            var read = try self.db.core.store.beginReadTxn();
            errdefer read.abort();
            return .{ .db = self.db, .read = read, .schema = view, .policy = self.row_policy_lease.clone(), .window = .init(alloc), .directory_arena = .init(@import("antfly_platform").allocator.reclaimingScratch(alloc)), .metadata = .init(@import("antfly_platform").allocator.reclaimingScratch(alloc)) };
        }

        pub fn search(self: QueryReadLease, alloc: Allocator, req: types.SearchRequest) !SearchWithDenseProfileResult {
            if (comptime storage_engine.enabled) return storage_engine.call("searchLease", .{ self, alloc, req });
            const db = self.db;
            const snapshot_req = try db.searchRequestAtCurrentIdentityGeneration(req);
            if (!types.canonicalHierarchyExecutionWithinBudget(snapshot_req)) return error.InvalidQueryRequest;
            var identity_prefix = try db.searchRequestWithIdentityPrefixFilterAlloc(snapshot_req);
            defer identity_prefix.deinit();
            var profile: db_query_search.DenseSearchProfile = .{};
            const result = try db.searchLockedWithExecutionContextImpl(alloc, identity_prefix.req, .{}, true, if (req.profile) &profile else null);
            return .{
                .request = snapshot_req,
                .result = result,
                .dense_profile = if (profile.search_route.len > 0) profile else null,
            };
        }

        pub fn release(self: *QueryReadLease) void {
            if (comptime storage_engine.enabled) return storage_engine.call("queryReadLeaseRelease", .{self}) catch @panic("incompatible storage owner");
            const db = self.db;
            db.core.unlockApplyShared();
            if (db.async_context.resource_manager) |manager| manager.finishForegroundQuery();
            self.row_policy_lease.release();
            self.* = undefined;
        }
    };

    pub fn beginQueryReadLease(self: *DB) !QueryReadLease {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{self});
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterUnsupportedSearch();
        errdefer row_policy_lease.release();
        if (self.async_context.resource_manager) |manager| manager.beginForegroundQuery();
        errdefer if (self.async_context.resource_manager) |manager| manager.finishForegroundQuery();
        try self.enforcePortableRuntimeGate();
        lockApplyShared(self);
        errdefer self.core.unlockApplyShared();
        try self.enforcePortableRuntimeGate();
        return .{ .db = self, .row_policy_lease = row_policy_lease };
    }

    pub const searchWithExecutionContext = db_search.searchWithExecutionContext;

    pub const searchWithCapturedRequestAndExecutionContext = db_search.searchWithCapturedRequestAndExecutionContext;

    pub const searchLocked = db_search.searchLocked;

    pub const searchRequestAtCurrentIdentityGeneration = db_search.searchRequestAtCurrentIdentityGeneration;

    pub fn validateResolvedDocFilterWireContext(self: *DB, req: types.SearchRequest) !void {
        const ctx = req.resolved_doc_filter_wire_context orelse return;
        if (req.resolved_doc_filter == null) return error.InvalidQueryRequest;
        if (!ctx.namespace.eql(self.core.identity_namespace)) return error.DocIdentityNamespaceMismatch;
        if (req.identity_read_generation == null or req.identity_read_generation.? != ctx.identity_read_generation) {
            self.local_execution.doc_set_planning_stats.recordStaleIdentityGenerationRejection();
            return error.UnsupportedQueryRequest;
        }
    }

    pub const searchLockedWithExecutionContext = db_search.searchLockedWithExecutionContext;

    pub const searchLockedWithExecutionContextImpl = db_search.searchLockedWithExecutionContextImpl;

    pub const attachDistributedDocumentAuthority = db_document.attachDistributedDocumentAuthority;

    pub const attachDistributedDocumentAuthorityAtSnapshot = db_restore.attachDistributedDocumentAuthorityAtSnapshot;

    pub const searchLockedWithExecutionContextRaw = db_search.searchLockedWithExecutionContextRaw;

    pub const attachSearchHighlights = db_search.attachSearchHighlights;

    pub const executeGraphMetricQueries = db_graph.executeGraphMetricQueries;

    pub const applyGraphMetricRerank = db_graph.applyGraphMetricRerank;

    pub const executeGraphMetricQuery = db_graph.executeGraphMetricQuery;

    fn hierarchyChildrenInaccessibleParentResult(
        alloc: Allocator,
        req: types.SearchRequest,
    ) !types.SearchResult {
        if (req.search_after.len == 0) {
            return .{ .alloc = alloc, .hits = &.{}, .total_hits = 0, .graph_results = &.{} };
        }
        // Keep absent, expired, and authorization-hidden parents externally
        // indistinguishable. Cursor shape is still validated so callers receive
        // actionable 400 versus 409 behavior without learning whether the parent
        // exists behind their current row policy.
        if (req.search_after.len != 2 or req.search_after[0] != .string or req.search_after[1] != .string) {
            return error.InvalidQueryRequest;
        }
        _ = hierarchy_navigation.parsePosition(req.search_after[0].string) catch |err| switch (err) {
            error.HierarchyNavigationPositionVersionStale => return error.HierarchyCursorStale,
            error.InvalidHierarchyNavigationPosition => return error.InvalidQueryRequest,
        };
        return error.HierarchyCursorStale;
    }

    pub fn navigateHierarchyChildren(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
    ) !types.SearchResult {
        if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ self, alloc, req });
        const navigation = req.hierarchy_children orelse return error.InvalidQueryRequest;
        if (navigation.parent_level != .source or navigation.level != .unit) return error.UnsupportedQueryRequest;

        const source_key = try encodeStoreLookupKeyAlloc(self, alloc, navigation.parent_id);
        defer alloc.free(source_key);
        const maybe_raw_source = try self.core.getStoreValue(alloc, source_key);
        const maybe_stored_source = if (maybe_raw_source) |raw_source| blk: {
            defer alloc.free(raw_source);
            break :blk try self.core.index_manager.materializeStoredValueAlloc(alloc, source_key, raw_source);
        } else null;
        if (maybe_stored_source == null) {
            // Distributed traversal is fanned out across table groups. Parent
            // absence on one shard only means that shard does not own the plan;
            // the outer coordinator decides whether every shard was empty.
            if (req.defer_hierarchy_child_hydration) {
                return .{ .alloc = alloc, .hits = &.{}, .total_hits = 0, .graph_results = &.{} };
            }
            return try hierarchyChildrenInaccessibleParentResult(alloc, req);
        }
        var source_hits = try alloc.alloc(types.SearchHit, 1);
        source_hits[0] = .{
            .id = try alloc.dupe(u8, navigation.parent_id),
            .stored_data = maybe_stored_source.?,
        };
        var visible_source = try db_query_result_shape.filterVisibleSearchResult(alloc, .{
            .alloc = alloc,
            .hits = source_hits,
            .total_hits = 1,
        }, .{
            .ctx = self,
            .func = isVisibleSearchHitCallback,
            .filter_many = filterVisibleSearchHitsManyCallback,
        });
        defer visible_source.deinit();
        visible_source = try db_query_result_shape.applyStoredSearchPatternFilters(alloc, req, visible_source, .{
            .ctx = self,
            .load_stored = loadStoredForHitCallback,
            .load_many_stored = loadStoredSearchDocumentManyCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
        });
        const parent_visible = visible_source.hits.len == 1;
        if (!parent_visible) {
            return try hierarchyChildrenInaccessibleParentResult(alloc, req);
        }

        var artifacts = std.ArrayListUnmanaged(HierarchyNavigationArtifact).empty;
        defer {
            for (artifacts.items) |*artifact| artifact.deinit(alloc);
            artifacts.deinit(alloc);
        }
        // Unit payloads share the asset key prefix with their top-level
        // manifest. Scanning that prefix would materialize every page body on
        // every traversal request. The enrichment catalog is the authoritative
        // namespace list, so probe only configured document-extraction
        // manifests and read unit payloads later for the selected page.
        for (self.core.index_manager.enrichments.items, 0..) |entry, entry_index| {
            if (entry_index % hierarchy_navigation_cancel_stride == 0) try checkHierarchyNavigationCancelled(req);
            if (entry.kind != .asset) continue;
            var producer_cfg = try asset_producer_mod.parseProducerConfig(alloc, entry.producer_json);
            defer producer_cfg.deinit(alloc);
            if (producer_cfg.type != .document_extraction) continue;

            const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, navigation.parent_id, "asset", entry.name);
            defer alloc.free(manifest_key);
            const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse continue;
            defer alloc.free(manifest);
            const manifest_info = try documentUnitHierarchyManifestInfo(alloc, manifest);
            if (manifest_info.failed) return error.DocumentArtifactPublicationFailed;
            const generation = manifest_info.published_generation orelse
                return error.StorageReadTemporarilyUnavailable;
            const state_key = try assetStateKeyAlloc(alloc, navigation.parent_id, entry.name);
            defer alloc.free(state_key);
            const summary_key = try internal_keys.documentUnitNavigationSummaryKeyAlloc(alloc, navigation.parent_id, entry.name);
            defer alloc.free(summary_key);
            const summary_raw = try self.core.getStoreValue(alloc, summary_key);
            defer if (summary_raw) |value| alloc.free(value);
            var legacy_units: ?[]DocumentExtractionUnitDescriptor = null;
            var digest: []u8 = undefined;
            var unit_count: u32 = 0;
            var block_count: u32 = 0;
            var block_size: u32 = hierarchy_navigation_block_size;
            if (summary_raw) |value| {
                const summary = try hierarchyNavigationSummaryParseAlloc(alloc, value);
                if (summary.generation != generation) {
                    alloc.free(summary.digest);
                    return error.StorageReadTemporarilyUnavailable;
                }
                // Transfer the digest allocation to the artifact descriptor;
                // Zig values have no implicit destructor, so this is a single
                // explicit ownership handoff rather than a clone.
                digest = summary.digest;
                unit_count = summary.unit_count;
                block_count = summary.block_count;
                block_size = summary.block_size;
            } else {
                const state = try self.core.getStoreValue(alloc, state_key) orelse return error.InvalidDocumentExtractionState;
                defer alloc.free(state);
                // Only state records with no navigation-era markers are
                // provably legacy. A current-format record without its summary
                // is an incomplete/corrupt publication and must fail closed;
                // synthesizing a revision from its descriptors could otherwise
                // issue cursors for a mixed artifact generation.
                if (try documentExtractionStateHasNavigationMetadata(alloc, state)) {
                    return error.StorageReadTemporarilyUnavailable;
                }
                // Rolling-upgrade fallback. A subsequent extraction writes the
                // compact summary and blocks; until then, preserve correctness
                // with the legacy state representation.
                const units = try documentExtractionStateUnitDescriptorsAlloc(alloc, state);
                errdefer freeDocumentExtractionUnitDescriptors(alloc, units);
                for (units) |unit| {
                    try validateHierarchyNavigationUnitDescriptor(alloc, navigation.parent_id, entry.name, unit);
                }
                legacy_units = units;
                digest = try hierarchyNavigationArtifactDigestAlloc(alloc, units);
                unit_count = std.math.cast(u32, units.len) orelse return error.QueryCandidateBudgetExceeded;
                block_count = hierarchyNavigationBlockCount(unit_count);
            }
            errdefer alloc.free(digest);
            try artifacts.append(alloc, .{
                .name = try alloc.dupe(u8, entry.name),
                .generation = generation,
                .digest = digest,
                .unit_count = unit_count,
                .block_count = block_count,
                .block_size = block_size,
                .legacy_units = legacy_units,
            });
        }
        std.mem.sort(HierarchyNavigationArtifact, artifacts.items, {}, hierarchyNavigationArtifactLessThan);
        if (artifacts.items.len > 1) {
            for (artifacts.items[1..], artifacts.items[0 .. artifacts.items.len - 1]) |current, previous| {
                if (std.mem.eql(u8, current.name, previous.name)) return error.InvalidDocumentExtractionState;
            }
        }
        const source_revision = try hierarchyNavigationSourceRevisionAlloc(alloc, artifacts.items);
        defer alloc.free(source_revision);

        // Validate the complete opaque position before classifying it. A
        // malformed cursor is a bad request; a well-formed cursor bound to a
        // different source hierarchy revision is an actionable conflict that
        // requires restarting traversal without search_after.
        const cursor_position: ?hierarchy_navigation.Position = if (req.search_after.len > 0)
            hierarchy_navigation.parsePosition(req.search_after[0].string) catch |err| switch (err) {
                error.HierarchyNavigationPositionVersionStale => return error.HierarchyCursorStale,
                error.InvalidHierarchyNavigationPosition => return error.InvalidQueryRequest,
            }
        else
            null;
        if (cursor_position) |cursor| {
            if (!std.mem.eql(u8, cursor.source_revision, source_revision)) return error.HierarchyCursorStale;
        }

        var units = std.ArrayListUnmanaged(types.SearchHit).empty;
        var units_owns_hits = true;
        errdefer if (units_owns_hits) {
            for (units.items) |*hit| hit.deinit(alloc);
            units.deinit(alloc);
        };
        var total_units_u64: u64 = 0;
        for (artifacts.items) |artifact| total_units_u64 += @as(u64, artifact.unit_count);
        const total = std.math.cast(u32, total_units_u64) orelse return error.QueryCandidateBudgetExceeded;

        var start_artifact_index: usize = 0;
        var start_ordinal: u64 = 0;
        var cursor_needs_validation = cursor_position != null;
        if (cursor_position) |cursor| {
            var found = false;
            for (artifacts.items, 0..) |artifact, artifact_index| {
                if (!hierarchy_navigation.encodedComponentMatches(cursor.artifact_name_hex, artifact.name)) continue;
                if (artifact.generation != cursor.generation or cursor.ordinal >= @as(u64, artifact.unit_count)) {
                    return error.InvalidQueryRequest;
                }
                start_artifact_index = artifact_index;
                start_ordinal = cursor.ordinal;
                found = true;
                break;
            }
            if (!found) return error.InvalidQueryRequest;
        }

        var remaining_offset: u64 = if (cursor_position == null) req.offset else 0;
        artifact_loop: for (artifacts.items[start_artifact_index..], start_artifact_index..) |artifact, artifact_index| {
            var ordinal: u64 = if (artifact_index == start_artifact_index) start_ordinal else 0;
            const artifact_remaining = @as(u64, artifact.unit_count) - ordinal;
            if (!cursor_needs_validation and remaining_offset >= artifact_remaining) {
                remaining_offset -= artifact_remaining;
                continue;
            }
            ordinal += remaining_offset;
            remaining_offset = 0;

            while (ordinal < @as(u64, artifact.unit_count)) {
                try checkHierarchyNavigationCancelled(req);
                const block_index: u32 = @intCast(ordinal / artifact.block_size);
                const block_start = @as(u64, block_index) * @as(u64, artifact.block_size);
                const block_units = try hierarchyNavigationArtifactBlockUnitsAlloc(
                    self,
                    alloc,
                    navigation.parent_id,
                    artifact,
                    block_index,
                );
                defer freeDocumentExtractionUnitDescriptors(alloc, block_units);
                var block_offset: usize = @intCast(ordinal - block_start);
                while (block_offset < block_units.len) : (block_offset += 1) {
                    const unit = block_units[block_offset];
                    const unit_ordinal = block_start + @as(u64, block_offset);
                    var unit_ref = (try artifact_ids.decodeArtifactRefAlloc(alloc, unit.key)) orelse
                        return error.InvalidDocumentExtractionState;
                    defer unit_ref.deinit(alloc);
                    const public_id = try artifact_ids.artifactPublicIdAlloc(alloc, unit_ref);
                    defer alloc.free(public_id);

                    if (cursor_needs_validation) {
                        const cursor = cursor_position.?;
                        if (unit_ordinal != cursor.ordinal or
                            !hierarchy_navigation.positionUnitFingerprintMatches(cursor, artifact.name, unit.fingerprint) or
                            !std.mem.eql(u8, public_id, req.search_after[1].string))
                        {
                            return error.InvalidQueryRequest;
                        }
                        cursor_needs_validation = false;
                        ordinal = unit_ordinal + 1;
                        continue;
                    }
                    if (units.items.len >= @as(usize, req.limit)) break :artifact_loop;

                    const position = try hierarchyNavigationPositionAlloc(
                        alloc,
                        source_revision,
                        artifact.name,
                        artifact.generation,
                        @intCast(unit_ordinal),
                        unit.fingerprint,
                    );
                    defer alloc.free(position);
                    var unit_hit = types.SearchHit{
                        .id = try alloc.dupe(u8, unit.key),
                        .score = 1,
                    };
                    errdefer unit_hit.deinit(alloc);
                    unit_hit.sort_values = try alloc.alloc(std.json.Value, 2);
                    unit_hit.sort_values[0] = .null;
                    unit_hit.sort_values[1] = .null;
                    unit_hit.sort_values[0] = .{ .string = try alloc.dupe(u8, position) };
                    unit_hit.sort_values[1] = .{ .string = try alloc.dupe(u8, public_id) };
                    unit_hit.artifact_ref = try unit_ref.clone(alloc);
                    try units.append(alloc, unit_hit);
                    ordinal = unit_ordinal + 1;
                }
            }
        }
        if (cursor_needs_validation) return error.InvalidQueryRequest;

        const page = try units.toOwnedSlice(alloc);
        units_owns_hits = false;
        var page_initialized: usize = 0;
        errdefer {
            for (page[0..page_initialized]) |*hit| hit.deinit(alloc);
            if (page.len > 0) alloc.free(page);
        }
        if (!req.include_stored) {
            page_initialized = page.len;
            try self.ensureHierarchyNavigationArtifactsStillPublished(
                alloc,
                navigation.parent_id,
                artifacts.items,
                req,
            );
            return .{
                .alloc = alloc,
                .hits = page,
                .total_hits = total,
                .total_hits_relation = .exact,
                .graph_results = &.{},
            };
        }
        for (page) |*hit| {
            page_initialized += 1;
            const artifact_ref = hit.artifact_ref orelse return error.InvalidDocumentExtractionState;
            const unit_id = artifact_ref.unit_id orelse return error.InvalidDocumentExtractionState;
            const unit_key = try internal_keys.documentUnitArtifactKeyAlloc(alloc, artifact_ref.document_id, artifact_ref.name, unit_id);
            defer alloc.free(unit_key);
            const stored = try self.core.getStoreValue(alloc, unit_key) orelse {
                if (req.defer_hierarchy_child_hydration) continue;
                return error.InvalidDocumentExtractionState;
            };
            defer alloc.free(stored);
            const position = hit.sort_values[0].string;
            const parsed_position = try hierarchyNavigationPositionParse(artifact_ref.name, position);
            if (!(try hierarchyNavigationStoredUnitMatchesPosition(alloc, stored, artifact_ref.name, parsed_position))) {
                return error.InvalidDocumentExtractionState;
            }
            const projected = if (req.fields.len > 0 or !req.include_all_fields)
                try projectLookupStoredBytes(self, alloc, unit_key, stored, .{
                    .fields = req.fields,
                    .include_all_fields = req.include_all_fields,
                })
            else
                try alloc.dupe(u8, stored);
            defer alloc.free(projected);
            hit.stored_data = try hierarchy_navigation.stripUnitFingerprintAlloc(alloc, projected);
        }
        // Close the read-publication race after all selected payloads are in
        // owned memory. If extraction started or completed since the initial
        // manifest read, discard the page rather than returning a hybrid.
        try self.ensureHierarchyNavigationArtifactsStillPublished(
            alloc,
            navigation.parent_id,
            artifacts.items,
            req,
        );
        return .{
            .alloc = alloc,
            .hits = page,
            .total_hits = total,
            .total_hits_relation = .exact,
            .graph_results = &.{},
        };
    }

    pub const ensureHierarchyNavigationArtifactsStillPublished = db_artifact.ensureHierarchyNavigationArtifactsStillPublished;

    /// Canonical hierarchy grouping uses a collapse-and-expand execution plan:
    /// the primary query selects the requested source-group page, and a second
    /// bounded query per returned source obtains that group's exact top
    /// matches. This prevents a source with fewer than the requested maximum
    /// from forcing the primary query to exhaust the global candidate set.
    pub fn populateCanonicalGroupedMatches(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
        result: *types.SearchResult,
    ) anyerror!void {
        if (!req.hierarchy_grouped_matches or
            (req.return_mode != .parent_with_chunks and req.return_mode != .unit_with_chunks) or
            req.max_chunks_per_parent == 0 or
            result.hits.len == 0)
        {
            return;
        }
        for (result.hits) |*group_hit| {
            const parent_id = if (req.hierarchy_group_level == .unit)
                (group_hit.artifact_ref orelse return error.InvalidChunkArtifact).document_id
            else
                group_hit.id;
            const parent_filter = [_][]const u8{parent_id};
            const match_req = types.canonicalGroupedMatchDescendantRequest(req, &parent_filter);
            var scoped_match_req = match_req;
            const unit_filter_json = if (req.hierarchy_group_level == .unit) blk: {
                _ = group_hit.artifact_ref orelse return error.InvalidChunkArtifact;
                break :blk try hierarchyUnitMatchFilterJsonAlloc(alloc, req.filter_query_json, group_hit.id);
            } else null;
            defer if (unit_filter_json) |value| alloc.free(value);
            if (unit_filter_json) |value| scoped_match_req.filter_query_json = value;

            var matches = try self.searchLockedWithExecutionContextImpl(alloc, scoped_match_req, exec_ctx, false, null);
            defer matches.deinit();

            const nested_matches: []types.ChunkHit = if (matches.hits.len == 0)
                &.{}
            else
                try alloc.alloc(types.ChunkHit, matches.hits.len);
            var initialized: usize = 0;
            errdefer {
                for (nested_matches[0..initialized]) |*match| match.deinit(alloc);
                if (nested_matches.len > 0) alloc.free(nested_matches);
            }
            for (matches.hits, 0..) |match, i| {
                nested_matches[i] = try chunkHitFromSearchHitAlloc(alloc, match);
                initialized += 1;
            }

            for (group_hit.chunk_hits) |*match| match.deinit(alloc);
            if (group_hit.chunk_hits.len > 0) alloc.free(group_hit.chunk_hits);
            group_hit.chunk_hits = nested_matches;
        }
    }

    pub const chunkHitFromSearchHitAlloc = db_search.chunkHitFromSearchHitAlloc;

    pub const searchRequestRequiresComposedSearch = db_search.searchRequestRequiresComposedSearch;

    pub fn directSingleVectorRequest(req: types.SearchRequest) ?types.SearchRequest {
        if (req.merge_config != null or req.reranker != null or req.pruner != null) return null;
        if (req.full_text_queries.len != 0) return null;
        if (req.full_text) |text| switch (text) {
            .match_all => {},
            else => return null,
        };
        if (!db_query_search.isDefaultMatchAll(req.query)) return null;
        if (req.graph_queries.len != 0 or req.graph_metric_queries.len != 0 or req.expand_strategy != null) return null;
        if (req.dense != null or req.sparse != null) return null;
        if (req.dense_queries.len == 1 and req.sparse_queries.len == 0) {
            var next = req;
            next.index_name = req.dense_queries[0].index_name;
            next.full_text = null;
            next.dense = req.dense_queries[0].query;
            next.dense_queries = &.{};
            return next;
        }
        if (req.sparse_queries.len == 1 and req.dense_queries.len == 0) {
            var next = req;
            next.index_name = req.sparse_queries[0].index_name;
            next.full_text = null;
            next.sparse = req.sparse_queries[0].query;
            next.sparse_queries = &.{};
            return next;
        }
        return null;
    }

