    pub const searchText = db_search.searchText;

    /// Owned filter_query_json/exclusion_query_json produced by lifting
    /// query.bool.filter/must_not (filter_text/exclusion_text) clauses out of
    /// the native per-arm query for chunk-backed member/chunk-mode search.
    /// Empty when there was nothing to lift.
    pub const ChunkBoolFilterLowering = struct {
        filter_query_json: ?[]u8 = null,
        exclusion_query_json: ?[]u8 = null,

        pub fn deinit(self: *ChunkBoolFilterLowering, alloc: Allocator) void {
            if (self.filter_query_json) |owned| alloc.free(owned);
            if (self.exclusion_query_json) |owned| alloc.free(owned);
        }
    };

    pub const ChunkBoolFilterLoweringBudget = struct {
        remaining_nodes: usize = 256,
    };

    const StoredPatternCombinator = enum { conjuncts, disjuncts };

    pub const liftChunkBoolFilterClausesAlloc = db_enrichment.liftChunkBoolFilterClausesAlloc;

    /// Combines an (optionally empty) existing stored-pattern-filter JSON
    /// string with a newly lowered node into one filter, returning an owned
    /// string allocated with `alloc`. `existing_json` is parsed with the
    /// caller's transient `arena_alloc`; only the final serialized string is
    /// durably allocated.
    pub fn combineStoredPatternJsonAlloc(
        alloc: Allocator,
        arena_alloc: Allocator,
        existing_json: []const u8,
        addition: std.json.Value,
        combinator: StoredPatternCombinator,
    ) ![]u8 {
        if (existing_json.len == 0) {
            return try std.json.Stringify.valueAlloc(alloc, addition, .{});
        }
        const existing = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, existing_json, .{});
        var items = std.json.Array.init(arena_alloc);
        try items.ensureTotalCapacity(2);
        items.appendAssumeCapacity(existing);
        items.appendAssumeCapacity(addition);
        var body = std.json.ObjectMap.empty;
        try body.put(arena_alloc, switch (combinator) {
            .conjuncts => "conjuncts",
            .disjuncts => "disjuncts",
        }, .{ .array = items });
        return try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .object = body }, .{});
    }

    fn storedPatternWrappedPredicate(alloc: Allocator, name: []const u8, body: std.json.Value) !std.json.Value {
        var root = std.json.ObjectMap.empty;
        try root.put(alloc, name, body);
        return .{ .object = root };
    }

    fn storedPatternEmptyPredicate(alloc: Allocator, name: []const u8) !std.json.Value {
        return storedPatternWrappedPredicate(alloc, name, .{ .object = std.json.ObjectMap.empty });
    }

    fn storedPatternJsonTimestamp(a: Allocator, ns: i128) !std.json.Value {
        return if (std.math.cast(i64, ns)) |v| .{ .integer = v } else .{ .number_string = try std.fmt.allocPrint(a, "{d}", .{ns}) };
    }

    fn storedPatternJsonU64(value: u64) std.json.Value {
        if (value <= std.math.maxInt(i64)) return .{ .integer = @intCast(value) };
        // Stored-pattern date_range compares numerically; values this large
        // fall outside any representable nanosecond timestamp we accept
        // elsewhere, so this branch is unreachable in practice but kept for
        // exhaustiveness rather than risking silent truncation.
        return .{ .float = @floatFromInt(value) };
    }

    /// Lowers the subset of `TextQuery` that `graph_exec.compilePatternFilter`
    /// can also express (match_all/match_none/term/bool_field/numeric_range/
    /// date_range/doc_id, and bool_query composed of those) into the
    /// equivalent stored-pattern-filter JSON value. Analyzed/tokenized shapes
    /// (match, phrase, multi_phrase, match_phrase, multi_match_bool_prefix)
    /// and shapes the stored-pattern matcher does not yet lower this way
    /// (fuzzy, prefix, wildcard, regexp, term_range, ip_range, geo_*) return
    /// error.UnsupportedQueryRequest rather than a wrong or partial result.
    pub fn lowerTextQueryToStoredPatternValueAlloc(
        alloc: Allocator,
        query: types.TextQuery,
        depth: u8,
        budget: *ChunkBoolFilterLoweringBudget,
    ) anyerror!std.json.Value {
        if (depth > 16 or budget.remaining_nodes == 0) return error.UnsupportedQueryRequest;
        budget.remaining_nodes -= 1;
        return switch (query) {
            .match_all => try storedPatternEmptyPredicate(alloc, "match_all"),
            .match_none => try storedPatternEmptyPredicate(alloc, "match_none"),
            .term => |term| blk: {
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, term.field, .{ .string = term.term });
                break :blk try storedPatternWrappedPredicate(alloc, "term", .{ .object = body });
            },
            .bool_field => |bool_field| blk: {
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = bool_field.field });
                try body.put(alloc, "value", .{ .bool = bool_field.value });
                break :blk try storedPatternWrappedPredicate(alloc, "bool_field", .{ .object = body });
            },
            .numeric_range => |range| blk: {
                if (range.min == null and range.max == null) return error.UnsupportedQueryRequest;
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = range.field });
                if (range.min) |bound| try body.put(alloc, "min", .{ .float = bound });
                if (range.max) |bound| try body.put(alloc, "max", .{ .float = bound });
                try body.put(alloc, "inclusive_min", .{ .bool = range.inclusive_min });
                try body.put(alloc, "inclusive_max", .{ .bool = range.inclusive_max });
                break :blk try storedPatternWrappedPredicate(alloc, "numeric_range", .{ .object = body });
            },
            .date_range => |range| blk: {
                if (range.start_ns == null and range.end_ns == null) return error.UnsupportedQueryRequest;
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = range.field });
                if (range.start_ns) |ns| try body.put(alloc, "start_ns", try storedPatternJsonTimestamp(alloc, ns));
                if (range.end_ns) |ns| try body.put(alloc, "end_ns", try storedPatternJsonTimestamp(alloc, ns));
                try body.put(alloc, "inclusive_start", .{ .bool = range.inclusive_start });
                try body.put(alloc, "inclusive_end", .{ .bool = range.inclusive_end });
                break :blk try storedPatternWrappedPredicate(alloc, "date_range", .{ .object = body });
            },
            .doc_id => |doc_id| blk: {
                if (doc_id.ids.len == 0) return error.UnsupportedQueryRequest;
                var ids = std.json.Array.init(alloc);
                try ids.ensureTotalCapacity(doc_id.ids.len);
                for (doc_id.ids) |id| ids.appendAssumeCapacity(.{ .string = id });
                break :blk try storedPatternWrappedPredicate(alloc, "doc_id", .{ .array = ids });
            },
            .bool_query => |bool_query| blk: {
                if (bool_query.must.len == 0 and bool_query.should.len == 0 and bool_query.must_not.len == 0) {
                    return error.UnsupportedQueryRequest;
                }
                var body = std.json.ObjectMap.empty;
                // A pure, explicitly-optional should-disjunction has no
                // must/filter clause to anchor it; the stored-pattern bool
                // contract always floors a pure should to a minimum of one
                // match, so make the match-all requirement explicit instead
                // of weakening that shared invariant.
                const needs_optional_anchor = bool_query.pure_should_optional and bool_query.must.len == 0;
                if (bool_query.must.len > 0 or needs_optional_anchor) {
                    var must = std.json.Array.init(alloc);
                    try must.ensureTotalCapacity(bool_query.must.len + @as(usize, if (needs_optional_anchor) 1 else 0));
                    if (needs_optional_anchor) must.appendAssumeCapacity(try storedPatternEmptyPredicate(alloc, "match_all"));
                    for (bool_query.must) |child| {
                        must.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "must", .{ .array = must });
                }
                if (bool_query.should.len > 0) {
                    var should = std.json.Array.init(alloc);
                    try should.ensureTotalCapacity(bool_query.should.len);
                    for (bool_query.should) |child| {
                        should.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "should", .{ .array = should });
                    if (bool_query.min_should > 0) {
                        try body.put(alloc, "minimum_should_match", .{ .integer = bool_query.min_should });
                    }
                }
                if (bool_query.must_not.len > 0) {
                    var must_not = std.json.Array.init(alloc);
                    try must_not.ensureTotalCapacity(bool_query.must_not.len);
                    for (bool_query.must_not) |child| {
                        must_not.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "must_not", .{ .array = must_not });
                }
                break :blk try storedPatternWrappedPredicate(alloc, "bool", .{ .object = body });
            },
            else => error.UnsupportedQueryRequest,
        };
    }

    pub fn searchLogicalValuesWithoutTextIndex(self: *DB, alloc: Allocator, req: types.SearchRequest, query: types.TextQuery) !types.SearchResult {
        const values = @import("../../search/value_query.zig");
        if (!req.value_search_execution.allow_scan) return error.ValueSearchRequiresScan;
        var preparation = std.heap.ArenaAllocator.init(alloc);
        defer preparation.deinit();
        const must = try preparation.allocator().alloc(types.TextQuery, if (req.filter_text != null) 2 else 1);
        must[0] = query;
        if (req.filter_text) |filter| must[1] = filter;
        const must_not = try preparation.allocator().alloc(types.TextQuery, if (req.exclusion_text != null) 1 else 0);
        if (req.exclusion_text) |filter| must_not[0] = filter;
        var tree = try values.Tree.prepare(preparation.allocator(), types.TextQuery{ .bool_query = .{ .must = must, .must_not = must_not } });
        if (req.profile) if (req.value_search_work) |work| try recordLogicalScanPlans(alloc, work, query);

        const Scan = struct {
            db: *DB,
            a: Allocator,
            req: types.SearchRequest,
            tree: *values.Tree,
            projection: ?@import("../../search/value_source.zig").Plan = null,
            projection_attempted: bool = false,
            allowed: ?*const std.StringHashMapUnmanaged(void) = null,
            ids: std.ArrayListUnmanaged([]const u8) = .empty,
            local_work: values.Work = .{},
            fn consume(raw: ?*anyopaque, candidate: db_query_search.MatchAllCandidate) anyerror!void {
                const value_scan: *@This() = @ptrCast(@alignCast(raw.?));
                var owned = candidate;
                defer owned.deinit(value_scan.a);
                if (value_scan.allowed) |allowed| if (!allowed.contains(owned.id)) return;
                if (value_scan.req.cancellation) |token| try token.check();
                const work = value_scan.req.value_search_work orelse &value_scan.local_work;
                try values.Work.charge(&work.documents, 1, value_scan.req.value_search_execution.max_documents);
                var scratch = std.heap.ArenaAllocator.init(@import("../../sql/memory_budget.zig").reclaimingAllocator(value_scan.a));
                defer scratch.deinit();
                const read_start = if (value_scan.req.profile) platform_time.monotonicNs() else 0;
                const stored = try value_scan.db.loadStoredSearchDocumentProbe(scratch.allocator(), owned.id);
                if (value_scan.req.profile) {
                    _ = work.source_read_ns.fetchAdd(platform_time.monotonicNs() - read_start, .monotonic);
                    _ = work.source_scalar_reads.fetchAdd(1, .monotonic);
                }
                const bytes = stored orelse return;
                try values.Work.charge(&work.bytes, bytes.len, value_scan.req.value_search_execution.max_bytes);
                if (bytes.len >= 1024 and !value_scan.projection_attempted) {
                    value_scan.projection_attempted = true;
                    value_scan.projection = value_scan.tree.sourcePlan(value_scan.a) catch null;
                }
                const parse_start = if (value_scan.req.profile) platform_time.monotonicNs() else 0;
                const parsed = try @import("../../search/value_source.zig").parse(scratch.allocator(), bytes, if (value_scan.projection) |*plan| plan else null);
                if (value_scan.req.profile) {
                    _ = work.source_parse_ns.fetchAdd(platform_time.monotonicNs() - parse_start, .monotonic);
                    if (parsed.projected) _ = work.projected_sources.fetchAdd(1, .monotonic);
                }
                if (!try value_scan.tree.matches(parsed.value)) return;
                const id = try value_scan.a.dupe(u8, owned.id);
                errdefer value_scan.a.free(id);
                try value_scan.ids.append(value_scan.a, id);
            }
        };
        var allowed = std.StringHashMapUnmanaged(void).empty;
        defer allowed.deinit(alloc);
        for (req.filter_doc_ids) |id| try allowed.put(alloc, id, {});
        var value_scan = Scan{ .db = self, .a = alloc, .req = req, .tree = &tree, .allowed = if (req.filter_doc_ids_positive or req.filter_doc_ids.len != 0) &allowed else null };
        defer value_scan.local_work.deinit(alloc);
        defer if (value_scan.projection) |*plan| plan.deinit();
        tree.bindWork(req.value_search_work orelse &value_scan.local_work, req.value_search_execution);
        defer {
            for (value_scan.ids.items) |id| alloc.free(id);
            value_scan.ids.deinit(alloc);
        }
        // Reuse the primary identity stream: no expanded index payloads, no
        // artifacts mistaken for documents, and bounded source lifetimes.
        _ = try streamSearchMatchAllCandidatesCallback(self, alloc, req, .{}, &value_scan, Scan.consume);
        var next = req;
        next.full_text = null;
        next.filter_text = null;
        next.exclusion_text = null;
        next.query = .{ .match_all = {} };
        next.filter_doc_ids = value_scan.ids.items;
        next.filter_doc_ids_positive = true;
        return self.searchMatchAll(alloc, next);
    }

    pub const searchTextQuery = db_search.searchTextQuery;

    pub fn proveTextQueryAccessPaths(self: *DB, index_name: ?[]const u8, text_query: types.TextQuery) !void {
        switch (text_query) {
            .term => |term| try self.proveTextFieldAccessPath(index_name, term.field, null, .slice),
            .match => |match| try self.proveTextFieldAccessPath(index_name, match.field, match.analyzer, .slice),
            .multi_match_bool_prefix => |multi_match| {
                for (multi_match.fields) |field| try self.proveMultiMatchBoolPrefixAccessPaths(index_name, field.field);
            },
            .prefix => |prefix| try self.proveTextFieldAccessPath(index_name, prefix.field, null, .automaton_select),
            .wildcard => |wildcard| try self.proveTextFieldAccessPath(index_name, wildcard.field, null, .automaton_select),
            .regexp => |regexp| try self.proveTextFieldAccessPath(index_name, regexp.field, null, .automaton_select),
            .fuzzy => |fuzzy| try self.proveTextFieldAccessPath(index_name, fuzzy.field, null, .automaton_select),
            .bool_query => |bool_query| {
                for (bool_query.must) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.should) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.must_not) |child| try self.proveTextQueryAccessPaths(index_name, child);
            },
            else => {},
        }
    }

    fn proveTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, analyzer: ?[]const u8, fragment: algebraic_mod.ir.TensorFragment) !void {
        _ = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, analyzer, fragment) orelse return error.IndexNotFound;
    }

    fn proveOptionalTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, fragment: algebraic_mod.ir.TensorFragment) !bool {
        const plan = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, null, fragment);
        return plan != null;
    }

    fn proveMultiMatchBoolPrefixAccessPaths(self: *DB, index_name: ?[]const u8, field: []const u8) !void {
        if (std.mem.endsWith(u8, field, "._index_prefix")) {
            try self.proveTextFieldAccessPath(index_name, field, null, .slice);
            return;
        }

        try self.proveTextFieldAccessPath(index_name, field, null, .slice);
        try self.proveTextFieldAccessPath(index_name, field, null, .automaton_select);
        if (isSearchAsYouTypeGeneratedFieldName(field)) return;

        const two_gram = try std.fmt.allocPrint(self.alloc, "{s}._2gram", .{field});
        defer self.alloc.free(two_gram);
        const has_two_gram = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .slice);
        if (has_two_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .automaton_select);

        const three_gram = try std.fmt.allocPrint(self.alloc, "{s}._3gram", .{field});
        defer self.alloc.free(three_gram);
        const has_three_gram = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .slice);
        if (has_three_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .automaton_select);

        const index_prefix = try std.fmt.allocPrint(self.alloc, "{s}._index_prefix", .{field});
        defer self.alloc.free(index_prefix);
        _ = try self.proveOptionalTextFieldAccessPath(index_name, index_prefix, .slice);
    }

    pub const isSearchAsYouTypeGeneratedFieldName = db_search.isSearchAsYouTypeGeneratedFieldName;

    pub fn textQueryMetricIndexName(self: *DB, req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        const entry = self.core.textIndexEntry(null) orelse return null;
        return entry.config.name;
    }

