pub fn computeChunkRequest(
    alloc: Allocator,
    db: anytype,
    doc_value: []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(types.EnrichmentDocumentWrite),
    cache: *std.ArrayListUnmanaged(ChunkCacheEntry),
) !void {
    if (!requestHasChunking(request)) return;

    const artifact_name = requestArtifactName(request);
    const chunks = try getOrCreateChunks(alloc, db, doc_value, request, cache);
    if (chunks.len == 0) return;

    const persist_chunks = try shouldStoreChunkArtifacts(alloc, request);
    if (persist_chunks) {
        try appendChunkArtifactWrites(alloc, request.doc_key, request.source_field, artifact_name, chunks, artifact_writes, true);
    }

    const text_indexes: []const []const u8 = request.consumer_indexes;
    if (text_indexes.len == 0) return;

    var arena_state = std.heap.ArenaAllocator.init(alloc);
    defer arena_state.deinit();
    const scratch = arena_state.allocator();

    for (chunks) |chunk| {
        if (!chunk.isText()) continue;
        const key = try internal_keys.chunkArtifactKeyAlloc(alloc, request.doc_key, artifact_name, @intCast(chunk.chunk_id));
        defer alloc.free(key);

        const payload = try buildChunkArtifactPayloadAlloc(scratch, request.doc_key, artifact_name, request.source_field, chunk, true);
        try result_collectors.appendDocument(alloc, documents, key, payload, text_indexes);

        _ = arena_state.reset(.retain_capacity);
    }
}

// Null source hashes also occur in multimodal provider output. Require callers
// to name the origin rather than inferring authorship from hash availability.
const EmbeddingArtifactOrigin = execution_resources.EmbeddingArtifactOrigin;

pub fn testEmbeddingArtifactOrigins(alloc: Allocator) !void {
    var writes: std.ArrayListUnmanaged(types.BatchWrite) = .empty;
    defer {
        for (writes.items) |write| {
            alloc.free(write.key);
            alloc.free(write.value);
        }
        writes.deinit(alloc);
    }
    for ([_]EmbeddingArtifactOrigin{ .authored, .{ .generated = null }, .{ .generated = 42 } }) |origin| {
        const dense_key = try appendEmbeddingArtifactWrite(alloc, &writes, "doc", "doc", "dense", "_embeddings", null, origin, &.{ 1, 2 });
        defer alloc.free(dense_key);
        const sparse_key = try appendSparseEmbeddingArtifactWrite(alloc, &writes, "doc", "sparse", origin, &.{ 3, 7 }, &.{ 1, 2 });
        defer alloc.free(sparse_key);
        for (writes.items[writes.items.len - 2 ..]) |write| {
            const header = try enrichment_artifact_codec.decodeHeader(write.value);
            try std.testing.expectEqual(origin == .authored, header.flags.authored);
            try std.testing.expectEqual(switch (origin) {
                .authored => @as(?u64, null),
                .generated => |hash| hash,
            }, try enrichment_artifact_codec.sourceHash(write.value));
        }
    }
}

