fn shouldDeferAppliedSequenceFlush(ctx: *const AsyncContext, force: bool) bool {
    if (force) return false;
    return ctx.dense_admission.sessions.active.load(.monotonic) != 0;
}

fn shouldLogTargetAdvanceDebt(ctx: *AsyncContext, index_name: []const u8, now_ns: u64) bool {
    return ctx.target_advance.shouldLog(index_name, now_ns, denseCatchUpMaintenanceCooldownNs());
}

fn noteTargetAdvanceDebtLogged(ctx: *AsyncContext, index_name: []const u8, now_ns: u64) !void {
    return ctx.target_advance.noteLogged(ctx.alloc, index_name, now_ns);
}

test "async dense catch-up tokens bind one exact session" {
    var apply_mutex: WriterPreferringRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    var no_snapshot: ?snapshot_admission_mod.SnapshotAdmission.MutationLease = null;
    const first_token = try installAsyncDenseCatchUpSession(&ctx, "vec", 11, null, &no_snapshot);
    try std.testing.expect(!first_token.isNone());
    try std.testing.expectError(
        error.DenseCatchUpSessionSuperseded,
        takeAsyncDenseCatchUpSession(&ctx, "other", first_token),
    );
    const first = try takeAsyncDenseCatchUpSession(&ctx, "vec", first_token);
    defer ctx.alloc.free(first.index_name);
    try std.testing.expectEqual(@as(u64, 11), first.index_incarnation);

    const second_token = try installAsyncDenseCatchUpSession(&ctx, "vec", 12, null, &no_snapshot);
    try std.testing.expect(second_token.value > first_token.value);
    try std.testing.expectError(
        error.DenseCatchUpSessionSuperseded,
        takeAsyncDenseCatchUpSession(&ctx, "vec", first_token),
    );
    const second = try takeAsyncDenseCatchUpSession(&ctx, "vec", second_token);
    defer ctx.alloc.free(second.index_name);
    try std.testing.expectEqual(@as(u64, 12), second.index_incarnation);
}

test "async dense catch-up token owns snapshot admission through close" {
    var apply_mutex: WriterPreferringRwLock = .{};
    var snapshot_admission: snapshot_admission_mod.SnapshotAdmission = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    var mutation: ?snapshot_admission_mod.SnapshotAdmission.MutationLease = snapshot_admission.acquireMutation();
    const token = try installAsyncDenseCatchUpSession(&ctx, "vec", 17, null, &mutation);
    try std.testing.expect(mutation == null);
    try std.testing.expect(!snapshot_admission.lock.tryLockExclusive());

    try std.testing.expectError(error.DenseCatchUpSessionSuperseded, retainAsyncDenseCatchUpAdmission(&ctx, "other", token));
    var retained = (try retainAsyncDenseCatchUpAdmission(&ctx, "vec", token)).?;
    defer retained.release();
    var session = try takeAsyncDenseCatchUpSession(&ctx, "vec", token);
    defer ctx.alloc.free(session.index_name);
    try std.testing.expect(!snapshot_admission.lock.tryLockExclusive());
    if (session.snapshot_replay) |*lease| lease.release();
    session.snapshot_replay = null;

    try std.testing.expect(!snapshot_admission.lock.tryLockExclusive());
    try std.testing.expectError(error.DenseCatchUpSessionSuperseded, retainAsyncDenseCatchUpAdmission(&ctx, "vec", token));
    retained.release();
    try std.testing.expect(snapshot_admission.lock.tryLockExclusive());
    snapshot_admission.lock.unlockExclusive();
}

fn recordTargetAdvanceMaintenanceDebt(
    ctx: *AsyncContext,
    index_name: []const u8,
    debt: TargetAdvanceMaintenanceDebt,
) !void {
    return ctx.target_advance.recordDebt(ctx.alloc, index_name, debt);
}

fn targetAdvanceMaintenanceDebtPending(
    ctx: *AsyncContext,
    index_name: []const u8,
    identity: TargetAdvanceMaintenanceDebt,
) bool {
    return ctx.target_advance.debtPending(index_name, identity);
}

pub fn clearTargetAdvanceMaintenanceDebt(ctx: *AsyncContext, index_name: []const u8) void {
    return ctx.target_advance.clearDebt(ctx.alloc, index_name);
}

/// Called every time `canAdvanceDerivedToTargetAsync` cannot advance an
/// artifact-backed dense index's replay target, and read back from
/// `checkTargetAdvanceNoProgress` on a foreground `runUntilIdle` drain. Both
/// sites may run on different threads from a background derived-executor
/// worker's callback invocation (hosted/multi-worker profiles), so this map
/// uses the tracker mutex
/// rather than relying on the caller's transient apply-exclusive hold.
fn noteTargetAdvanceStuck(ctx: *AsyncContext, index_name: []const u8, now_ns: u64, indexed: u64, expected: u64) !void {
    return ctx.target_advance.noteStuck(ctx.alloc, index_name, now_ns, indexed, expected);
}

fn clearTargetAdvanceStuck(ctx: *AsyncContext, index_name: []const u8) void {
    return ctx.target_advance.clearStuck(ctx.alloc, index_name);
}

/// Snapshot of the target tracker’s stuck observations older than `timeout_ns`, or null if
/// none. Copies out under the shared mutex so the caller can log/stash the
/// diagnostic and return without holding it.
const TargetAdvanceStuckSnapshot = target_advance_tracker.Snapshot;

fn oldestTargetAdvanceStuck(ctx: *AsyncContext, timeout_ns: u64, now_ns: u64) !?TargetAdvanceStuckSnapshot {
    return ctx.target_advance.oldestStuck(ctx.alloc, timeout_ns, now_ns);
}

test "async context dense catch-up session tracking suppresses local bulk sessions" {
    var apply_mutex: WriterPreferringRwLock = .{};
    var resource_manager = resource_manager_mod.ResourceManager.init(.{});
    defer resource_manager.deinit(std.testing.allocator);
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .resource_manager = &resource_manager,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(!shouldDeferAppliedSequenceFlush(&ctx, false));
    try std.testing.expect(denseApplyUsesLocalStreamingSession(&ctx, "vec"));
    try beginDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expectEqual(@as(u32, 1), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(ctx.stats.dense_catch_up.active.load(.monotonic) != 0);
    try std.testing.expect(asyncContextHasActiveDenseBulkWork(&ctx));
    try std.testing.expect(resource_manager.shouldDeferSoftCompactionForDerivedReplay());
    try std.testing.expect(ctx.text_merge_deferred.load(.acquire));
    try std.testing.expect(shouldDeferAppliedSequenceFlush(&ctx, false));
    try std.testing.expect(!shouldDeferAppliedSequenceFlush(&ctx, true));
    try std.testing.expect(!denseApplyUsesLocalStreamingSession(&ctx, "vec"));
    try std.testing.expectError(error.ReplayDocumentNotVisible, beginExternalDenseBulkSessionTracked(&ctx));
    finishDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(ctx.stats.dense_catch_up.active.load(.monotonic) == 0);
    try std.testing.expect(!ctx.text_merge_deferred.load(.acquire));
    // Session-owned deferral has ended, but the short quiet period still
    // protects the just-completed publication from an immediate soft rewrite.
    try std.testing.expect(resource_manager.shouldDeferSoftCompactionForDerivedReplay());
    try std.testing.expect(!shouldDeferAppliedSequenceFlush(&ctx, false));
    try std.testing.expect(denseApplyUsesLocalStreamingSession(&ctx, "vec"));

    try beginExternalDenseBulkSessionTracked(&ctx);
    try std.testing.expectEqual(@as(u32, 1), ctx.dense_admission.external_sessions.load(.monotonic));
    try std.testing.expect(asyncContextHasActiveDenseBulkWork(&ctx));
    try std.testing.expect(ctx.text_merge_deferred.load(.acquire));
    try std.testing.expect(!denseApplyUsesLocalStreamingSession(&ctx, "vec"));
    try std.testing.expectError(error.ReplayDocumentNotVisible, beginDenseCatchUpSessionTracked(&ctx, "vec"));
    try std.testing.expect(deferExternalBulkExecutorNotification(&ctx, .write, 7));
    try std.testing.expectEqual(@as(u64, 7), ctx.dense_admission.deferred_sequence.load(.monotonic));
    try std.testing.expect(deferExternalBulkExecutorNotification(&ctx, .propose, 11));
    try std.testing.expectEqual(@as(u64, 11), ctx.dense_admission.deferred_sequence.load(.monotonic));
    try std.testing.expect(deferExternalBulkExecutorNotification(&ctx, .enrichments, 13));
    try std.testing.expectEqual(@as(u64, 13), ctx.dense_admission.deferred_sequence.load(.monotonic));
    try std.testing.expect(!deferExternalBulkExecutorNotification(&ctx, .full_text, 17));
    try std.testing.expectEqual(@as(u64, 13), ctx.dense_admission.deferred_sequence.load(.monotonic));
    try std.testing.expect(!deferExternalBulkExecutorNotification(&ctx, .full_index, 23));
    try std.testing.expectEqual(@as(u64, 13), ctx.dense_admission.deferred_sequence.load(.monotonic));
    finishExternalDenseBulkSessionTracked(&ctx);
    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.external_sessions.load(.monotonic));
    try std.testing.expect(!asyncContextHasActiveDenseBulkWork(&ctx));
    try std.testing.expect(!ctx.text_merge_deferred.load(.acquire));
    try std.testing.expect(denseApplyUsesLocalStreamingSession(&ctx, "vec"));
    try std.testing.expect(!deferExternalBulkExecutorNotification(&ctx, .write, 13));

    ctx.dense_bulk_session_scope = .external;
    try std.testing.expect(!denseApplyUsesLocalStreamingSession(&ctx, "vec"));

    var finalization_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    try std.testing.expect(tryClaimDenseProjectionFinalizationLocked(&ctx));
    finalization_lock.unlock();
    try std.testing.expect(ctx.dense_admission.mutex.tryLock());
    ctx.dense_admission.mutex.unlock();
    // Optimistic generation construction owns the finalization worker but no
    // longer fences writers for the duration of a corpus scan.
    try beginDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expect(!try finishDenseCatchUpSessionTrackedAndFinalize(&ctx, "vec"));
    try std.testing.expect(ctx.dense_admission.finalization_requested);
    ctx.dense_admission.finalization_requested = false;
    try beginExternalDenseBulkSessionTracked(&ctx);
    try std.testing.expect(!try finishExternalDenseBulkSessionTrackedAndFinalize(&ctx));
    try std.testing.expect(ctx.dense_admission.finalization_requested);
    try std.testing.expect(tryBeginDenseProjectionCommit(&ctx));
    try std.testing.expectError(error.ReplayDocumentNotVisible, beginDenseCatchUpSessionTracked(&ctx, "vec"));
    finishDenseProjectionCommit(&ctx);
    finishDenseProjectionFinalization(&ctx);
    try std.testing.expect(!ctx.dense_admission.finalization_requested);
    try std.testing.expect(!ctx.dense_admission.finalizing.load(.acquire));
}

test "native publication reports contention separately from an empty pass" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/native-publication-contention", .{tmp.sub_path});
    defer alloc.free(path);
    var db = try DB.open(alloc, path, .{ .start_index_workers = false, .start_optional_runtimes = false });
    defer db.close();
    db.async_context.dense_admission.finalizing.store(true, .release);
    const busy = try db.publishVectorBlockBasesOnlineReported(.{});
    try std.testing.expect(busy.busy);
    try std.testing.expectEqual(@as(usize, 0), busy.published);
    db.async_context.dense_admission.finalizing.store(false, .release);
    const idle = try db.publishVectorBlockBasesOnlineReported(.{});
    try std.testing.expect(!idle.busy);
    try std.testing.expectEqual(@as(usize, 0), idle.published);
}

test "native publication finalization forwards raced source completion" {
    const alloc = std.testing.allocator;
    var runtime = std.Io.Threaded.init(alloc, .{});
    defer runtime.deinit();
    const io = runtime.io();
    var apply_mutex: WriterPreferringRwLock = .{};
    var ctx = AsyncContext{
        .alloc = alloc,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
        .io = io,
        .native_projection_owner = .{ .enabled = true },
    };
    defer ctx.deinit(alloc);
    // Keep an owned task installed without a consumer racing the observation.
    // Its only purpose is to exercise the real scheduler's wakeup path.
    ctx.native_projection_owner.future = try io.concurrent(struct {
        fn run() void {}
    }.run, .{});
    var guard = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    try std.testing.expect(tryClaimDenseProjectionFinalizationLocked(&ctx));
    try std.testing.expect(!tryClaimOrRequestDenseProjectionFinalizationLocked(&ctx));
    guard.unlock();
    finishDenseProjectionFinalization(&ctx);
    try std.testing.expect(ctx.native_projection_owner.wake.isSet());
    try std.testing.expect(!ctx.dense_admission.finalization_requested);
    try std.testing.expect(!ctx.dense_admission.finalizing.load(.acquire));
    ctx.native_projection_owner.wake.reset();
    guard = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    try std.testing.expect(tryClaimOrRequestDenseProjectionFinalizationLocked(&ctx));
    guard.unlock();
    finishDenseProjectionFinalization(&ctx);
    try std.testing.expect(!ctx.native_projection_owner.wake.isSet());
}

test "external dense bulk waiter owns admission across catch-up handoff" {
    var apply_mutex: WriterPreferringRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    try beginDenseCatchUpSessionTracked(&ctx, "vec");

    const Waiter = struct {
        ctx: *AsyncContext,
        result: ?anyerror = null,

        fn run(waiter: *@This()) void {
            beginExternalDenseBulkSessionTrackedWait(waiter.ctx, null) catch |err| {
                waiter.result = err;
            };
        }
    };
    var waiter = Waiter{ .ctx = &ctx };
    var waiter_thread = try std.testing.io.concurrent(Waiter.run, .{&waiter});
    defer waiter_thread.await(std.testing.io);

    const wait_deadline = monotonicTimeNs() + 5 * std.time.ns_per_s;
    while (ctx.dense_admission.waiters.load(.acquire) == 0) {
        if (monotonicTimeNs() >= wait_deadline) return error.TestUnexpectedResult;
        sleepNs(std.time.ns_per_ms);
    }

    try std.testing.expect(asyncContextHasActiveDenseBulkWork(&ctx));
    try std.testing.expectError(error.ReplayDocumentNotVisible, beginDenseCatchUpSessionTracked(&ctx, "late"));
    finishDenseCatchUpSessionTracked(&ctx, "vec");

    const admission_deadline = monotonicTimeNs() + 5 * std.time.ns_per_s;
    while (ctx.dense_admission.external_sessions.load(.acquire) == 0) {
        if (monotonicTimeNs() >= admission_deadline) return error.TestUnexpectedResult;
        sleepNs(std.time.ns_per_ms);
    }
    try std.testing.expect(waiter.result == null);
    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.waiters.load(.acquire));
    try std.testing.expect(ctx.text_merge_deferred.load(.acquire));

    finishExternalDenseBulkSessionTracked(&ctx);
    try std.testing.expect(!asyncContextHasActiveDenseBulkWork(&ctx));
    try std.testing.expect(!ctx.text_merge_deferred.load(.acquire));
}

test "async context dense catch-up session finish is idempotent when already closed" {
    var apply_mutex: WriterPreferringRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    finishDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(ctx.stats.dense_catch_up.active.load(.monotonic) == 0);

    try beginDenseCatchUpSessionTracked(&ctx, "vec");
    try beginDenseCatchUpSessionTracked(&ctx, "vec");
    finishDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expectEqual(@as(u32, 1), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(ctx.stats.dense_catch_up.active.load(.monotonic) != 0);
    finishDenseCatchUpSessionTracked(&ctx, "vec");
    finishDenseCatchUpSessionTracked(&ctx, "vec");
    try std.testing.expectEqual(@as(u32, 0), ctx.dense_admission.sessions.active.load(.monotonic));
    try std.testing.expect(ctx.stats.dense_catch_up.active.load(.monotonic) == 0);
    try std.testing.expect(denseApplyUsesLocalStreamingSession(&ctx, "vec"));
}

test "dense target advance is not blocked by local catch-up session" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_background_test_open);
    defer db.close();

    try db.addIndex(.{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\",\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"semantic_idx\"}}",
    });

    const resources = db.core.asyncResources();
