fn applyDerivedBatchToIndexReplay(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !bool {
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    const self = replay_ctx.db;
    const resources = self.core.asyncResources();
    if (!try batchAdvancesManagedIndexApplyStateForReplay(resources.index_manager, batch, index_ref)) return false;
    // See applyDerivedBatchToIndexReplayContext: irrelevant tail windows must
    // not manufacture coverage before the target-advance completeness gate.
    if (index_ref.kind == .dense_vector) {
        replay_ctx.dense_window_sequence = @max(replay_ctx.dense_window_sequence, batch.sequence);
    }
    const ctx = AsyncContext{
        .alloc = self.alloc,
        .io = self.backend_runtime.io(),
        .store = resources.store,
        .relational_base_rows = relationalColumns(self) != null,
        .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
        .index_manager = resources.index_manager,
        .apply_mutex = resources.apply_mutex,
        .snapshot_replay_admission = resources.snapshot_replay_admission,
        .dense_bulk_session_scope = replay_ctx.dense_bulk_session_scope,
        .require_graph_resolution_contract = true,
    };
    applyDerivedBatchToIndexContextProfiled(&ctx, batch, index_ref, null, true, null) catch |err| switch (err) {
        // External-vector dense indexes can discover a missing artifact while
        // replaying an otherwise valid journal window. Existing generations
        // turn that into durable repair debt; initial materialization keeps it
        // as an expected producer dependency so startup can retry without
        // falsely reporting corruption.
        error.NotFound => if (index_ref.kind == .dense_vector) {
            if (try self.markDenseReplayArtifactRepairRequired(self.alloc, index_ref.name))
                return error.ArtifactRepairRequired;
            return error.ReplayDocumentNotVisible;
        } else return err,
        error.ArtifactRepairRequired => if (index_ref.kind == .dense_vector) {
            try self.markDenseReplayArtifactCoverageRepairRequired(self.alloc, index_ref.name);
            return err;
        } else return err,
        else => return err,
    };
    return true;
}

fn finishReplayCapture(
    replay_ctx: *ReplayApplyContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    sequence: u64,
) !void {
    const lease = replay_ctx.dense_capture_lease orelse return;
    if (!lease.ownsLifecycle()) {
        replay_ctx.dense_capture_lease = null;
        return;
    }
    const manager = replay_ctx.db.core.batchExecutionResources().index_manager;
    try manager.finishDensePostingSidecarCaptureLeaseByName(index_ref.name, lease, sequence);
    replay_ctx.dense_capture_lease = null;
}

fn abortReplayCapture(
    replay_ctx: *ReplayApplyContext,
    index_ref: index_manager_mod.ManagedIndexRef,
) !void {
    const lease = replay_ctx.dense_capture_lease orelse return;
    defer replay_ctx.dense_capture_lease = null;
    if (!lease.ownsLifecycle()) return;
    const manager = replay_ctx.db.core.batchExecutionResources().index_manager;
    manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| switch (err) {
        error.PostingWalCaptureSuperseded, error.ExperimentalPostingCaptureNotActive => {},
        else => return err,
    };
}

fn finishReplayCaptureContext(
    replay_ctx: *ReplayApplyContextBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
    sequence: u64,
) !void {
    const lease = replay_ctx.dense_capture_lease orelse return;
    if (!lease.ownsLifecycle()) {
        replay_ctx.dense_capture_lease = null;
        return;
    }
    try replay_ctx.batch.index_manager.finishDensePostingSidecarCaptureLeaseByName(index_ref.name, lease, sequence);
    replay_ctx.dense_capture_lease = null;
}

fn abortReplayCaptureContext(
    replay_ctx: *ReplayApplyContextBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !void {
    const lease = replay_ctx.dense_capture_lease orelse return;
    defer replay_ctx.dense_capture_lease = null;
    if (!lease.ownsLifecycle()) return;
    replay_ctx.batch.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| switch (err) {
        error.PostingWalCaptureSuperseded, error.ExperimentalPostingCaptureNotActive => {},
        else => return err,
    };
}

fn beginDerivedCatchUpWindow(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    const resources = replay_ctx.db.core.batchExecutionResources();
    replay_ctx.dense_window_sequence = 0;
    // Capture ownership and the streaming-session lease are one lifecycle
    // transition. Serialize both against posting maintenance and foreground
    // apply; otherwise a maintenance capture can be observed here and finish
    // before the first replay mutation, leaving that mutation outside either
    // WAL transaction boundary.
    var index_apply_guard = try resources.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    const capture = try resources.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(
        index_ref.name,
        .{ .borrow_active_source = true },
    );
    replay_ctx.dense_capture_lease = capture;
    errdefer if (capture) |lease| if (lease.ownsLifecycle()) {
        resources.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
        replay_ctx.dense_capture_lease = null;
    };
    try resources.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
}

fn finishDerivedCatchUpWindow(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, success: bool) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    const resources = replay_ctx.db.core.batchExecutionResources();
    if (!success) {
        if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
            resources.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| {
                if (err != error.PostingWalCaptureSuperseded and err != error.ExperimentalPostingCaptureNotActive) return err;
            };
        replay_ctx.dense_capture_lease = null;
        replay_ctx.dense_window_sequence = 0;
        resources.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    if (replay_ctx.dense_window_sequence == 0) {
        // The matching journal window contained no mutation applicable to
        // this index. Discard its empty transaction; the caller may advance
        // coverage only after canAdvanceDerivedToTargetAsync proves the
        // current physical corpus complete.
        if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
            resources.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| switch (err) {
                error.PostingWalCaptureSuperseded, error.ExperimentalPostingCaptureNotActive => {},
                else => return err,
            };
        replay_ctx.dense_capture_lease = null;
        resources.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    errdefer if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
        resources.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
    errdefer resources.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
    const finish_start_ns = monotonicTimeNs();
    // Session retirement and source-capture publication are one transaction.
    // Keeping the per-index apply fence across both operations prevents
    // stable-tip or maintenance work from consuming the handoff between them.
    {
        var index_apply_guard = try resources.index_manager.lockManagedIndexApply(index_ref);
        defer index_apply_guard.unlock();
        try resources.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, denseCatchUpFinishOptions());
        if (replay_ctx.dense_capture_lease) |lease| {
            if (lease.ownsLifecycle()) {
                if (replay_ctx.dense_window_sequence == 0) return error.InvalidDerivedApplyState;
                try resources.index_manager.finishDensePostingSidecarCaptureLeaseByName(
                    index_ref.name,
                    lease,
                    replay_ctx.dense_window_sequence,
                );
            }
        }
        replay_ctx.dense_capture_lease = null;
        replay_ctx.dense_window_sequence = 0;
    }
    try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
    if (resources.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(.{ .finish_ns = elapsedSince(finish_start_ns) });
    }
}

fn beginDerivedCatchUpWindowContext(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    replay_ctx.dense_window_sequence = 0;
    var index_apply_guard = try replay_ctx.batch.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    const capture = try replay_ctx.batch.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(
        index_ref.name,
        .{ .borrow_active_source = true },
    );
    replay_ctx.dense_capture_lease = capture;
    errdefer if (capture) |lease| if (lease.ownsLifecycle()) {
        replay_ctx.batch.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
        replay_ctx.dense_capture_lease = null;
    };
    try replay_ctx.batch.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
}

fn finishDerivedCatchUpWindowContext(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, success: bool) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    if (!success) {
        if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
            replay_ctx.batch.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| {
                if (err != error.PostingWalCaptureSuperseded and err != error.ExperimentalPostingCaptureNotActive) return err;
            };
        replay_ctx.dense_capture_lease = null;
        replay_ctx.dense_window_sequence = 0;
        replay_ctx.batch.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    if (replay_ctx.dense_window_sequence == 0) {
        if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
            replay_ctx.batch.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| switch (err) {
                error.PostingWalCaptureSuperseded, error.ExperimentalPostingCaptureNotActive => {},
                else => return err,
            };
        replay_ctx.dense_capture_lease = null;
        replay_ctx.batch.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    errdefer if (replay_ctx.dense_capture_lease) |lease| if (lease.ownsLifecycle())
        replay_ctx.batch.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
    errdefer replay_ctx.batch.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
    const finish_start_ns = monotonicTimeNs();
    {
        var index_apply_guard = try replay_ctx.batch.index_manager.lockManagedIndexApply(index_ref);
        defer index_apply_guard.unlock();
        try replay_ctx.batch.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, denseCatchUpFinishOptions());
        if (replay_ctx.dense_capture_lease) |lease| {
            if (lease.ownsLifecycle()) {
                if (replay_ctx.dense_window_sequence == 0) return error.InvalidDerivedApplyState;
                try replay_ctx.batch.index_manager.finishDensePostingSidecarCaptureLeaseByName(
                    index_ref.name,
                    lease,
                    replay_ctx.dense_window_sequence,
                );
            }
        }
        replay_ctx.dense_capture_lease = null;
        replay_ctx.dense_window_sequence = 0;
    }
    try replay_ctx.batch.index_manager.checkpointLsmWalForManagedIndex(index_ref);
    if (replay_ctx.batch.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(.{ .finish_ns = elapsedSince(finish_start_ns) });
    }
}

fn truncateReplayJournalIfSafe(self: *DB) !void {
    var ctx = self.batchContext();
    return try truncateReplayJournalIfSafeContext(&ctx);
}

const truncateReplayLogs = local_mutation.truncateReplayLogs;

const resolverReplayRetentionRequired = local_mutation.resolverReplayRetentionRequired;

fn clampReplayTruncationForReplayStage(
    effective: u64,
    index_manager: *const index_manager_mod.IndexManager,
    stats: types.ReplayStageStats,
) u64 {
    if (!resolverReplayRetentionRequired(index_manager, stats)) return effective;
    return @min(effective, stats.applied_sequence);
}

const clampReplayTruncationForRepairPins = local_mutation.clampReplayTruncationForRepairPins;

pub fn truncateReplaySequenceAsync(ctx_ptr: *anyopaque, sequence: u64) !void {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (ctx.repair_replay_mutex) |mutex| mutex.lockUncancelable(ctx.index_manager.checkpointIo());
    defer if (ctx.repair_replay_mutex) |mutex| mutex.unlock(ctx.index_manager.checkpointIo());
    var effective = sequence;
    // Generated enrichment consumes the same durable replay journal as the
    // managed-index executor, but advances independently. The executor may
    // reach `sequence` while a provider outage leaves enrichment behind. Clamp
    // to the persisted checkpoint (written before the in-memory watermark) so
    // a restart can always replay every ungenerated artifact.
    if (ctx.index_manager.hasGeneratedEnrichmentTargets()) {
        const enrichment_applied = try enrichment_state.loadAppliedSequence(
            ctx.alloc,
            ctx.store,
            enrichment_runtime_mod.scope_name,
        );
        effective = @min(effective, enrichment_applied);
    }
    // The resolution/promotion stages consume the replay journal but are not
    // executor workers. Clamp truncation to their applied watermarks whenever a
    // resolver is configured, even before the synchronous driver has raised the
    // stage target for the newest write. Resolver removal drains or refuses
    // pending stage work before deleting catalog state, so a never-configured
    // resolver pipeline does not pin generic replay hints.
    if (ctx.resolution_runtime) |runtime| {
        effective = clampReplayTruncationForReplayStage(effective, ctx.index_manager, runtime.stats());
    }
    if (ctx.promotion_runtime) |runtime| {
        effective = clampReplayTruncationForReplayStage(effective, ctx.index_manager, runtime.stats());
    }
    effective = try ctx.index_manager.clampReplayForGraphReplacementBuilds(ctx.store, effective);
    effective = try clampReplayTruncationForRepairPins(ctx.alloc, ctx.index_repair_checkpoint, effective);
    try ctx.store.truncateReplayUpTo(ctx.alloc, effective);
}

pub const truncateReplayJournalIfSafeContext = local_mutation.truncateReplayJournalIfSafeContext;

fn startAsyncWorkers(self: *DB) !void {
    const managed_indexes = try self.core.managedIndexes(self.alloc);
    defer {
        for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
        self.alloc.free(managed_indexes);
    }

    for (managed_indexes) |index_ref| {
        const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
        try self.executor.addWorker(index_ref.name, index_ref, applied);
    }
}

const activeSplitShadow = local_mutation.activeSplitShadow;

const reserveSplitShadowApplyTicket = local_mutation.reserveSplitShadowApplyTicket;

const applyCommittedBatchToShadowOrdered = local_mutation.applyCommittedBatchToShadowOrdered;

const applyCommittedBatchToShadow = local_mutation.applyCommittedBatchToShadow;

/// Called with the primary apply fence held. No later primary commit can reserve
/// a ticket, while already-committed owners need only the shadow-local mutex and
/// can therefore drain without a lock cycle.
pub fn waitForSplitShadowDrainLocked(self: *DB, require_clean: bool) !void {
    const shadow = activeSplitShadow(self) orelse return;
    const io = self.backend_runtime.io() orelse self.backend_runtime.filesystemIo() orelse std.Options.debug_io;
    shadow.apply_mutex.lockUncancelable(io);
    while (shadow.applied_ticket != shadow.next_ticket) {
        shadow.apply_advanced.waitUncancelable(io, &shadow.apply_mutex);
    }
    defer shadow.apply_mutex.unlock(io);
    if (require_clean and shadow.repair_required) return error.ShadowIndexRepairRequired;
}

const OpenedSplitDestinationStore = struct {
    store: docstore_mod.DocStore,
    owner: db_core.PrimaryStoreOwner = .none,

    fn close(self: *OpenedSplitDestinationStore, alloc: Allocator) void {
        self.store.close();
        self.owner.close(alloc);
        self.* = undefined;
    }
};

fn openSplitDestinationStore(self: *DB, dest_dir: []const u8) !OpenedSplitDestinationStore {
    return switch (splitDestinationStorePlan(self)) {
        .lsm => |split_opts| blk: {
            var dest_opts = split_opts;
            dest_opts.background_executor = null;
            var handle = try lsm_backend_mod.BackendHandle.open(self.alloc, dest_dir, dest_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(self.alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :blk .{
                .store = try docstore_mod.DocStore.openRuntime(self.alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = null,
                } },
            };
        },
        .unsupported => error.Unsupported,
    };
}

fn tryPreparePrimarySplitFast(self: *DB, split_lower: []const u8, dest_dir: []const u8) !bool {
    const owner_fast = try self.core.primary_store_owner.prepareSplitRightToDir(split_lower, dest_dir);
    if (owner_fast) return true;

    return try self.core.splitRightStoreToDir(split_lower, dest_dir);
}

fn tryFinalizePrimarySplitFast(self: *DB, split_lower: []const u8) !bool {
    const owner_fast = try self.core.primary_store_owner.rewriteLeftInPlace(split_lower);
    if (owner_fast) return true;

    return try self.core.rewriteLeftStoreInPlace(split_lower);
}

fn identityMetadataRange() struct { lower: [1]u8, upper: [1]u8 } {
    return .{
        .lower = .{internal_keys.identity_namespace},
        .upper = .{internal_keys.identity_namespace + 1},
    };
}

fn putIdentityMetadataRows(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    rows: []const docstore_mod.OwnedKVPair,
) !void {
    if (rows.len == 0) return;

    var writes = try alloc.alloc(docstore_mod.KVPair, rows.len);
    defer alloc.free(writes);
    for (rows, 0..) |row, i| {
        writes[i] = .{
            .key = row.key,
            .value = row.value,
        };
    }
    try store.putBatch(writes, &.{});
}

fn copyIdentityMetadataToStore(
    alloc: Allocator,
    src_store: *docstore_mod.DocStore,
    dest_store: *docstore_mod.DocStore,
) !void {
    const range = identityMetadataRange();
    const rows = try src_store.scanRange(alloc, range.lower[0..], range.upper[0..]);
    defer docstore_mod.DocStore.freeResults(alloc, rows);
    try putIdentityMetadataRows(alloc, dest_store, rows);
}

fn copyDerivedCoverageMetadataToStore(
    alloc: Allocator,
    src_store: *docstore_mod.DocStore,
    dest_store: *docstore_mod.DocStore,
) !void {
    const lower = [_]u8{ internal_keys.replay_namespace, 0xff, internal_keys.derived_coverage_kind };
    const upper = try internal_keys.nextPrefixAlloc(alloc, &lower);
    defer if (upper) |key| alloc.free(key);

    const CopyState = struct {
        alloc: Allocator,
        dest: *docstore_mod.DocStore,
        writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty,
        owned: std.ArrayListUnmanaged(docstore_mod.OwnedKVPair) = .empty,

        pub fn deinit(state: *@This()) void {
            state.freeOwned();
            state.writes.deinit(state.alloc);
            state.owned.deinit(state.alloc);
        }

        fn freeOwned(state: *@This()) void {
            for (state.owned.items) |item| {
                state.alloc.free(item.key);
                state.alloc.free(item.value);
            }
            state.owned.clearRetainingCapacity();
        }

        fn flush(state: *@This()) !void {
            if (state.writes.items.len == 0) return;
            try state.dest.putBatch(state.writes.items, &.{});
            state.writes.clearRetainingCapacity();
            state.freeOwned();
        }

        fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            const owned_key = try state.alloc.dupe(u8, key);
            const owned_value = state.alloc.dupe(u8, value) catch |err| {
                state.alloc.free(owned_key);
                return err;
            };
            state.owned.append(state.alloc, .{ .key = owned_key, .value = owned_value }) catch |err| {
                state.alloc.free(owned_key);
                state.alloc.free(owned_value);
                return err;
            };
            try state.writes.append(state.alloc, .{ .key = owned_key, .value = owned_value });
            if (state.writes.items.len >= 8192) try state.flush();
            return .@"continue";
        }
    };

    var state = CopyState{ .alloc = alloc, .dest = dest_store };
    defer state.deinit();
    try src_store.scanWithContext(&lower, if (upper) |key| key else "", .{}, &state, CopyState.scanEntry);
    try state.flush();
}

pub fn rebaseRangeCoverageMetadata(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    byte_range: types.ByteRange,
    extra_writes: []const docstore_mod.KVPair,
) !void {
    try index_manager.validateRangeTransition(byte_range);
    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(alloc);
    var owned_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_keys.items) |key| alloc.free(key);
        owned_keys.deinit(alloc);
    }
    var owned_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_values.items) |value| alloc.free(value);
        owned_values.deinit(alloc);
    }
    var seen_indexes = std.StringHashMapUnmanaged(void).empty;
    defer seen_indexes.deinit(alloc);
    try writes.appendSlice(alloc, extra_writes);

    const append_index = struct {
        fn run(
            inner_alloc: Allocator,
            inner_store: *docstore_mod.DocStore,
            inner_manager: *index_manager_mod.IndexManager,
            range: types.ByteRange,
            index_name: []const u8,
            seen: *std.StringHashMapUnmanaged(void),
            out: *std.ArrayListUnmanaged(docstore_mod.KVPair),
            keys: *std.ArrayListUnmanaged([]u8),
            values: *std.ArrayListUnmanaged([]u8),
        ) !void {
            const gop = try seen.getOrPut(inner_alloc, index_name);
            if (gop.found_existing) return;
            const generation = inner_manager.coverageGenerationForIndex(index_name) orelse return;
            const prefix = try internal_keys.derivedCoverageOutcomeMarkerPrefixAlloc(inner_alloc, index_name, generation);
            defer inner_alloc.free(prefix);
            const upper = try internal_keys.nextPrefixAlloc(inner_alloc, prefix);
            defer if (upper) |key| inner_alloc.free(key);

            const ScanState = struct {
                alloc: Allocator,
                index_name: []const u8,
                generation: u64,
                byte_range: types.ByteRange,
                counts: [std.meta.tags(DerivedCoverageOutcome).len]u64 =
                    @as([std.meta.tags(DerivedCoverageOutcome).len]u64, @splat(0)),

                fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                    const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                    const doc_key = try internal_keys.derivedCoverageOutcomeDocKeyAlloc(
                        state.alloc,
                        state.index_name,
                        state.generation,
                        key,
                    );
                    defer state.alloc.free(doc_key);
                    if (!state.byte_range.contains(doc_key)) return .@"continue";
                    const outcome = std.meta.stringToEnum(DerivedCoverageOutcome, value) orelse
                        return error.InvalidDerivedCoverageOutcome;
                    const outcome_index = @backingInt(outcome);
                    state.counts[outcome_index] = std.math.add(u64, state.counts[outcome_index], 1) catch
                        return error.InvalidDerivedCoverageCounter;
                    return .@"continue";
                }
            };

            var state = ScanState{
                .alloc = inner_alloc,
                .index_name = index_name,
                .generation = generation,
                .byte_range = range,
            };
            try inner_store.scanWithContext(prefix, if (upper) |key| key else "", .{}, &state, ScanState.scanEntry);

            inline for (std.meta.tags(DerivedCoverageOutcome), 0..) |outcome, i| {
                const key = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(inner_alloc, index_name, generation, @tagName(outcome));
                keys.append(inner_alloc, key) catch |err| {
                    inner_alloc.free(key);
                    return err;
                };
                const value = try inner_alloc.alloc(u8, 8);
                std.mem.writeInt(u64, value[0..8], state.counts[i], .little);
                values.append(inner_alloc, value) catch |err| {
                    inner_alloc.free(value);
                    return err;
                };
                try out.append(inner_alloc, .{ .key = key, .value = value });
            }
        }
    }.run;

    for (index_manager.dense_indexes.items) |entry| {
        try append_index(alloc, store, index_manager, byte_range, entry.config.name, &seen_indexes, &writes, &owned_keys, &owned_values);
    }
    for (index_manager.sparse_indexes.items) |entry| {
        try append_index(alloc, store, index_manager, byte_range, entry.config.name, &seen_indexes, &writes, &owned_keys, &owned_values);
    }

    const document_count = try range_cardinality.countPrimaryDocuments(alloc, store, byte_range);
    const count_key = try alloc.dupe(u8, &internal_keys.range_document_count_key);
    owned_keys.append(alloc, count_key) catch |err| {
        alloc.free(count_key);
        return err;
    };
    const count_value = try alloc.alloc(u8, 8);
    std.mem.writeInt(u64, count_value[0..8], document_count, .little);
    owned_values.append(alloc, count_value) catch |err| {
        alloc.free(count_value);
        return err;
    };
    try writes.append(alloc, .{ .key = count_key, .value = count_value });

    try store.putBatch(writes.items, &.{});
}

pub const graph_edge_ttl_due_rebuild_marker = "\x00\x00__metadata__:graph_edge_ttl_due_rebuild";
pub const graph_merge_import_recovery_key = "\x00\x00__metadata__:graph_merge_import_recovery:v1";
const GraphMergeImportIndex = struct { name: []const u8, generation: u64 };
pub const GraphMergeImportRecovery = struct {
    version: u32 = 1,
    indexes: []const GraphMergeImportIndex,
    replay_sequence: u64,
    source_artifact_keys: []const []const u8 = &.{},
};

/// Capture source work before certifying a snapshot. The recovery record owns
/// the deduplicated keys, so journal truncation cannot discard a withdrawal.
/// Reconciliation reads current inputs rather than replaying historical edges.
fn collectGraphMergeSourceWork(db: anytype, moved: types.ByteRange, donor: bool, keys: *std.StringHashMapUnmanaged(void), alloc: Allocator) !void {
    var from_sequence: u64 = std.math.maxInt(u64);
    for (db.core.index_manager.graph_indexes.items) |entry| {
        if (db.core.index_manager.graphArtifactSources(entry.config.name).len == 0) continue;
        from_sequence = @min(from_sequence, try db.core.loadAppliedSequence(alloc, entry.config.name));
    }
    if (from_sequence == std.math.maxInt(u64)) return;
    const Capture = struct {
        alloc: Allocator,
        moved: types.ByteRange,
        owned: types.ByteRange,
        donor: bool,
        tip: u64,
        keys: *std.StringHashMapUnmanaged(void),
        fn consume(ptr: *anyopaque, sequence: u64, payload: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (sequence > self.tip) return error.StopReplayChunk;
            var decoded = try change_journal_mod.decodeRecord(self.alloc, payload);
            defer decoded.deinit();
            for (decoded.record.changed_artifact_keys) |key| {
                if (!internal_keys.isAssetArtifactKey(key) and !internal_keys.isResolutionArtifactKey(key)) continue;
                const owner = (try internal_keys.decodeDocumentComponentAlloc(self.alloc, key)) orelse return error.InvalidGraphArtifact;
                defer self.alloc.free(owner);
                if (!self.owned.contains(owner) or self.moved.contains(owner) != self.donor or self.keys.contains(key)) continue;
                const copy = try self.alloc.dupe(u8, key);
                errdefer self.alloc.free(copy);
                try self.keys.put(self.alloc, copy, {});
            }
        }
    };
    var capture = Capture{ .alloc = alloc, .moved = moved, .owned = db.core.byteRange(), .donor = donor, .tip = db.core.store.nextReplaySequence(1) -| 1, .keys = keys };
    var cursor = try db.core.batchExecutionResources().replay_source.openMatchingCursor(alloc, from_sequence, .graph);
    defer cursor.deinit(alloc);
    while (true) {
        const stats = cursor.forEachNext(128, &capture, Capture.consume) catch |err| switch (err) {
            error.StopReplayChunk => break,
            else => return err,
        };
        if (stats.last_sequence == 0 or stats.last_sequence >= capture.tip) break;
    }
}

fn reconcileGraphMergeSourceInput(db: anytype, key: []const u8, sequence: u64) !void {
    if (!internal_keys.isAssetArtifactKey(key) and !internal_keys.isResolutionArtifactKey(key)) return error.InvalidGraphMergeImportRecovery;
    for (db.core.index_manager.graph_indexes.items) |entry| {
        const changed = try materializeGraphSourceArtifactsForIndex(db.alloc, db.core.store, db.core.index_manager, &.{key}, entry.config.name, .{ .require_resolution_contract = true, .repair_ctx = db.async_context, .sequence = sequence });
        defer freeOwnedKeySlice(db.alloc, changed);
    }
}

/// Complete both live import and writable startup recovery from the same
/// authoritative snapshot. Live callers hold the exclusive receiver apply
/// lock; startup calls this before admitting readers or maintenance workers.
/// The durable record fences admission until all disposable graph stores are
/// rebuilt and synced, without consulting the donor or regenerating lifetimes.
fn finishGraphMergeImport(db: anytype, existing_lease: ?*index_manager_mod.IndexManager.GraphArtifactRebuildLease) !void {
    const raw = db.core.store.get(db.alloc, graph_merge_import_recovery_key) catch |err| switch (err) {
        error.NotFound => return,
        else => return err,
    };
    defer db.alloc.free(raw);
    db.local_execution.graph_merge_import_recovery_pending.store(true, .release);
    var record = try std.json.parseFromSlice(GraphMergeImportRecovery, db.alloc, raw, .{});
    defer record.deinit();
    if (record.value.version != 1 or record.value.indexes.len != db.core.index_manager.graph_indexes.items.len)
        return error.InvalidGraphMergeImportRecovery;
    var seen = std.StringHashMapUnmanaged(void).empty;
    defer seen.deinit(db.alloc);
    for (record.value.indexes) |identity| {
        const entry = db.core.index_manager.graphIndex(identity.name) orelse return error.InvalidGraphMergeImportRecovery;
        if (entry.config.coverage_generation != identity.generation or seen.contains(identity.name)) return error.InvalidGraphMergeImportRecovery;
        try seen.put(db.alloc, identity.name, {});
    }
    var owned_lease: ?index_manager_mod.IndexManager.GraphArtifactRebuildLease = if (existing_lease == null) db.core.index_manager.beginGraphArtifactRebuild() else null;
    defer if (owned_lease) |*lease| lease.deinit();
    const rebuild = existing_lease orelse &owned_lease.?;
    // Drain source debt from current inputs before clearing/replaying the
    // disposable graph. Each source uses the existing bounded materializer
    // and TTL lifetime/tombstone rules; repeat recovery is idempotent.
    for (record.value.source_artifact_keys) |key| {
        const owner = (try internal_keys.decodeDocumentComponentAlloc(db.alloc, key)) orelse return error.InvalidGraphMergeImportRecovery;
        defer db.alloc.free(owner);
        if (!db.core.index_manager.byte_range.contains(owner)) return error.InvalidGraphMergeImportRecovery;
        try reconcileGraphMergeSourceInput(db, key, record.value.replay_sequence);
    }
    for (record.value.indexes) |identity| try rebuild.reset(identity.name);
    if (builtin.is_test and (test_graph_merge_import_abort_during_projection.swap(false, .monotonic) or
        test_graph_merge_import_abort_during_recovery.swap(false, .monotonic))) return error.TestInjectedGraphMergeImportFailure;
    const range = db.core.index_manager.byte_range;
    try applySplitGraphArtifactsStreaming(db.alloc, db.core.store, db.core.index_manager, range.start, range.end, graph_repair_rebuild_batch_size);
    for (db.core.index_manager.graph_indexes.items) |*entry| {
        try entry.index.publishContributionOrderingReady();
        try entry.index.publishArtifactRebuildSequence(record.value.replay_sequence);
    }
    try rebuildGraphTtlDueIndexInRange(db.alloc, db.core.store, db.core.index_manager, range);
    try db.core.index_manager.syncAll(true);
    // The rebuild includes all committed owned artifacts at the import's
    // replay floor. Older journal entries must not overwrite it on startup.
    for (record.value.indexes) |identity| {
        const applied = try db.core.loadAppliedSequence(db.alloc, identity.name);
        const entry = db.core.index_manager.graphIndex(identity.name) orelse return error.InvalidGraphMergeImportRecovery;
        // The rebuild lease already owns the catalog exclusively. Publish
        // coverage without reacquiring the catalog through the generic helper.
        try entry.index.checkpointLsmWalAfterDurableBoundary();
        try apply_state.saveAppliedSequenceUpdateWithCheckpoint(db.alloc, db.core.index_manager.checkpointIo(), db.core.store, db.core.applied_sequence_checkpoint_path, .{
            .index_name = identity.name,
            .sequence = @max(applied, record.value.replay_sequence),
            .config_hash = types.indexConfigHash(entry.config),
        });
    }
    try db.core.syncStore(true);
    try db.core.store.putBatch(&.{}, &.{ graph_merge_import_recovery_key, graph_edge_ttl_due_rebuild_marker });
    try db.core.syncStore(true);
    rebuild.complete();
    db.local_execution.graph_merge_import_recovery_pending.store(false, .release);
}
pub const graph_split_retire_cursor_key = "\x00\x00__metadata__:graph_split_retire_cursor";

/// The deadline index is sorted by time rather than document owner. A shard
/// split therefore reconstructs it from the document-owned contender rows on
/// each side. Both passes are bounded by a fixed mutation page.
fn rebuildGraphTtlDueIndexInRange(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    byte_range: types.ByteRange,
) !void {
    const due_prefix = &internal_keys.graph_edge_expiration_index_prefix;
    const due_upper = try internal_keys.nextPrefixAlloc(alloc, due_prefix);
    defer if (due_upper) |key| alloc.free(key);
    const Clear = struct {
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        keys: std.ArrayListUnmanaged([]u8) = .empty,

        fn flush(self: *@This()) !void {
            if (self.keys.items.len == 0) return;
            var deletes = try self.alloc.alloc([]const u8, self.keys.items.len);
            defer self.alloc.free(deletes);
            for (self.keys.items, 0..) |key, i| deletes[i] = key;
            try self.store.putBatch(&.{}, deletes);
            for (self.keys.items) |key| self.alloc.free(key);
            self.keys.clearRetainingCapacity();
        }
        pub fn deinit(self: *@This()) void {
            for (self.keys.items) |key| self.alloc.free(key);
            self.keys.deinit(self.alloc);
        }
        fn scan(ptr: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const self: *@This() = @ptrCast(@alignCast(ptr orelse return error.InvalidArgument));
            const owned = try self.alloc.dupe(u8, key);
            self.keys.append(self.alloc, owned) catch |err| {
                self.alloc.free(owned);
                return err;
            };
            if (self.keys.items.len == 512) try self.flush();
            return .@"continue";
        }
    };
    var clear = Clear{ .alloc = alloc, .store = store };
    defer clear.deinit();
    try store.scanWithContext(due_prefix, due_upper orelse "", .{}, &clear, Clear.scan);
    try clear.flush();
    var has_ttl_graph = false;
    for (index_manager.graph_indexes.items) |entry| {
        if (entry.ttl_duration_ns != 0) {
            has_ttl_graph = true;
            break;
        }
    }
    if (!has_ttl_graph) return;

    const lower = try documentRangeLowerAlloc(alloc, byte_range.start);
    defer alloc.free(lower);
    const upper = if (byte_range.end.len > 0) try documentRangeUpperAlloc(alloc, byte_range.end) else null;
    defer if (upper) |key| alloc.free(key);
    const Build = struct {
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        manager: *index_manager_mod.IndexManager,
        writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty,

        fn flush(self: *@This()) !void {
            if (self.writes.items.len == 0) return;
            try self.store.putBatch(self.writes.items, &.{});
            for (self.writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            self.writes.clearRetainingCapacity();
        }
        pub fn deinit(self: *@This()) void {
            for (self.writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            self.writes.deinit(self.alloc);
        }
        fn scan(ptr: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const self: *@This() = @ptrCast(@alignCast(ptr orelse return error.InvalidArgument));
            if (internal_keys.isGraphEdgeArtifactKey(key)) {
                for (self.manager.graph_indexes.items) |entry| {
                    if (entry.ttl_duration_ns == 0 or
                        self.manager.graphArtifactSources(entry.config.name).len != 0 or
                        !internal_keys.matchesGraphEdgeIndexName(key, entry.config.name)) continue;
                    var edge = try enrichment_artifact_codec.decodeGraphEdgeAlloc(self.alloc, value);
                    defer edge.deinit(self.alloc);
                    if (edge.generation != entry.config.coverage_generation) continue;
                    if (edge.ttl_created_ns == 0) return error.GraphEdgeTtlMigrationRequired;
                    const deadline = std.math.add(u64, edge.ttl_created_ns, entry.ttl_duration_ns) catch std.math.maxInt(u64);
                    var digest: [32]u8 = undefined;
                    GraphTtlSha256.hash(value, &digest, .{});
                    const candidate: DirectGraphTtlCandidate = .{
                        .index_name = entry.config.name,
                        .generation = entry.config.coverage_generation,
                        .artifact_key = key,
                        .deadline_ns = deadline,
                        .artifact_digest = digest,
                    };
                    const due_key = try graph_edge_ttl_expiration.directIndexKeyAlloc(self.alloc, deadline, key);
                    var due_key_owned = true;
                    errdefer if (due_key_owned) self.alloc.free(due_key);
                    const due_value = try graph_edge_ttl_expiration.encodeDirectAlloc(self.alloc, candidate);
                    var due_value_owned = true;
                    errdefer if (due_value_owned) self.alloc.free(due_value);
                    try self.writes.append(self.alloc, .{ .key = due_key, .value = due_value });
                    due_key_owned = false;
                    due_value_owned = false;
                    if (self.writes.items.len == 512) try self.flush();
                    break;
                }
                return .@"continue";
            }
            if (!internal_keys.isGraphGlobalEdgeContenderKey(key)) return .@"continue";
            for (self.manager.graph_indexes.items) |entry| {
                if (entry.ttl_duration_ns == 0 or
                    !internal_keys.matchesGraphGlobalEdgeContenderIndexName(key, entry.config.name)) continue;
                const generation = entry.config.coverage_generation;
                const contender = (try graph_edge_contender.decode(value, generation)) orelse continue;
                const expected_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(self.alloc, entry.config.name, generation, contender.edge_key, contender.source_priority, contender.state_key);
                defer self.alloc.free(expected_key);
                if (!std.mem.eql(u8, key, expected_key)) return error.InvalidGraphEdgeContender;
                var edge = try enrichment_artifact_codec.decodeGraphEdgeAlloc(self.alloc, contender.payload);
                defer edge.deinit(self.alloc);
                if (edge.ttl_created_ns == 0) return error.GraphEdgeTtlMigrationRequired;
                const deadline = std.math.add(u64, edge.ttl_created_ns, entry.ttl_duration_ns) catch std.math.maxInt(u64);
                var digest: [32]u8 = undefined;
                GraphTtlSha256.hash(value, &digest, .{});
                const candidate: GraphTtlCandidate = .{
                    .index_name = entry.config.name,
                    .generation = generation,
                    .edge_key = contender.edge_key,
                    .state_key = contender.state_key,
                    .source_priority = contender.source_priority,
                    .deadline_ns = deadline,
                    .contender_digest = digest,
                };
                const due_key = try graph_edge_ttl_expiration.indexKeyAlloc(self.alloc, deadline, key);
                var due_key_owned = true;
                errdefer if (due_key_owned) self.alloc.free(due_key);
                const due_value = try graph_edge_ttl_expiration.encodeAlloc(self.alloc, candidate);
                var due_value_owned = true;
                errdefer if (due_value_owned) self.alloc.free(due_value);
                try self.writes.append(self.alloc, .{ .key = due_key, .value = due_value });
                due_key_owned = false;
                due_value_owned = false;
                if (self.writes.items.len == 512) try self.flush();
                break;
            }
            return .@"continue";
        }
    };
    var build = Build{ .alloc = alloc, .store = store, .manager = index_manager };
    defer build.deinit();
    try store.scanWithContext(lower, upper orelse "", .{}, &build, Build.scan);
    try build.flush();
}

fn finalizePrimarySplitPreservingMetadata(
    self: *DB,
    split_lower: []const u8,
    retained_range: types.ByteRange,
) !void {
    try self.core.store.put(graph_edge_ttl_due_rebuild_marker, "1");
    const range = identityMetadataRange();
    const identity_rows = try self.core.store.scanRange(self.alloc, range.lower[0..], range.upper[0..]);
    defer docstore_mod.DocStore.freeResults(self.alloc, identity_rows);

    try merge_state_mod.protectForSplit(self.alloc, self.core.store);
    // Persist invalidation before the physical rewrite. A crash after pruning
    // must leave a resumable rebuild, never a ready directory for the old range.
    try self.core.store.invalidateGraphDirectories();
    _ = try tryFinalizePrimarySplitFast(self, split_lower);
    try self.core.store.ensureGraphIncomingDirectory();
    try putIdentityMetadataRows(self.alloc, self.core.store, identity_rows);
    try reconcileRelationalIndexRange(self, self.core.store, retained_range);
    try relational_integrity_range.pruneOutside(self.alloc, self.backend_runtime.io(), self.core.store, retained_range.start, retained_range.end);
    try rebaseRangeCoverageMetadata(
        self.alloc,
        self.core.store,
        self.core.index_manager,
        retained_range,
        &.{},
    );
    try rebuildGraphTtlDueIndexInRange(self.alloc, self.core.store, self.core.index_manager, retained_range);
    try self.core.store.delete(graph_edge_ttl_due_rebuild_marker);
}

pub fn prepareSplitDestination(self: *DB, byte_range: types.ByteRange, dest_dir: []const u8) !void {
    try ensureDirPath(dest_dir);
    const split_lower = try documentRangeLowerAlloc(self.alloc, byte_range.start);
    defer self.alloc.free(split_lower);

    try merge_state_mod.protectForSplit(self.alloc, self.core.store);
    const page_split_built = try tryPreparePrimarySplitFast(self, split_lower, dest_dir);

    var opened_dest_store = try openSplitDestinationStore(self, dest_dir);
    defer opened_dest_store.close(self.alloc);
    const dest_store = &opened_dest_store.store;
    if (page_split_built) try dest_store.rebuildGraphDirectories();
    var dest_indexes = try index_manager_mod.IndexManager.initWithOptions(
        self.alloc,
        dest_dir,
        self.index_backends,
    );
    defer dest_indexes.deinit();
    dest_indexes.setIo(self.core.index_manager.io);
    dest_indexes.setRelaxedSplitDurability(true);
    const dest_applied_sequence_checkpoint_path = try apply_state.checkpointPathAlloc(self.alloc, dest_dir);
    defer self.alloc.free(dest_applied_sequence_checkpoint_path);
    dest_indexes.setAppliedSequenceCheckpointPath(dest_applied_sequence_checkpoint_path);

    try clearSplitMetadataFromStore(self.alloc, dest_store);
    try clearSystemMetadataFromSplitDestination(self.alloc, dest_store);
    try copyIdentityMetadataToStore(self.alloc, self.core.store, dest_store);
    if (!page_split_built) try copyDerivedCoverageMetadataToStore(self.alloc, self.core.store, dest_store);
    const replay_floor = self.core.nextDerivedAppendSequence();
    try ensureReplayFloor(dest_store, replay_floor);

    const split_doc_frontier = if (page_split_built)
        try collectSplitFrontierDocKeys(self.alloc, dest_store, byte_range.start, byte_range.end)
    else
        &.{};
    defer {
        for (split_doc_frontier) |key| self.alloc.free(key);
        if (split_doc_frontier.len > 0) self.alloc.free(split_doc_frontier);
    }

    dest_indexes.updateRange(byte_range);
    try range_state_mod.saveRange(dest_store, byte_range);
    try self.core.saveSchemaCloneTo(dest_store);
    try relational_index_catalog.copyToUnpublished(self.alloc, self.core.store, dest_store);
    try relational_integrity_range.copyToUnpublished(self.alloc, self.backend_runtime.io(), self.core.store, dest_store, byte_range.start, byte_range.end);
    // Replicated apply reopens prepared shards from their local manifest;
    // it cannot consult metadata while metadata is waiting for that apply.
    // Keep public validation/provenance alongside the internal runtime schema.
    const schema_json = try self.core.getStoreValue(self.alloc, public_schema_json_key);
    defer if (schema_json) |value| self.alloc.free(value);
    const public_schema_versions = try self.core.store.scanPrefix(self.alloc, public_table_schema.versioned_schema_key_prefix);
    defer docstore_mod.DocStore.freeResults(self.alloc, public_schema_versions);
    if (schema_json != null or public_schema_versions.len != 0) {
        var txn = try dest_store.beginWriteTxn();
        errdefer txn.abort();
        if (schema_json) |value| try txn.put(public_schema_json_key, value);
        for (public_schema_versions) |entry| try txn.put(entry.key, entry.value);
        try txn.commit();
    }
    try dest_indexes.seedSplitArtifactCatalogsFrom(dest_store, self.core.index_manager);

    const configs = try self.core.listIndexes(self.alloc);
    defer types.freeIndexConfigs(self.alloc, configs);
    try registerSplitDestinationIndexesDirect(self.alloc, dest_store, dest_applied_sequence_checkpoint_path, &dest_indexes, configs, replay_floor -| 1);
    const collect_skip_doc_keys = true;
    var split_handoffs = try self.core.collectSplitIndexHandoffs(
        &dest_indexes,
        dest_store,
        split_doc_frontier,
        byte_range,
        collect_skip_doc_keys,
    );
    defer split_handoffs.deinit(self.alloc);
    _ = try dest_indexes.copyGraphSplitDestinationFrom(self.core.index_manager, byte_range.start, byte_range.end);
    _ = try dest_indexes.rebuildGraphSplitDestination(byte_range.start, byte_range.end);
    if (page_split_built) {
        try applySplitEmbeddingArtifactsInRange(
            self.alloc,
            byte_range.start,
            byte_range.end,
            dest_store,
            &dest_indexes,
            split_handoffs.dense,
            split_handoffs.sparse,
        );
    }
    if (page_split_built) {
        if (dest_indexes.splitDestinationNeedsDocumentIndexing(split_handoffs.dense, split_handoffs.text, split_handoffs.sparse)) {
            if (!collect_skip_doc_keys) return error.UnexpectedSplitResidualIndexing;
            try indexExistingSplitDestinationDirect(
                self.alloc,
                byte_range.start,
                byte_range.end,
                dest_store,
                &dest_indexes,
                split_handoffs.dense,
                split_handoffs.text,
                split_handoffs.sparse,
            );
        }
    } else {
        try streamRangeIntoSplitDestinationDirect(
            self.alloc,
            self,
            byte_range.start,
            byte_range.end,
            dest_store,
            &dest_indexes,
            split_handoffs.dense,
            split_handoffs.text,
            split_handoffs.sparse,
        );
    }
    try applySplitGraphArtifactsInRange(
        self.alloc,
        byte_range.start,
        byte_range.end,
        dest_store,
        &dest_indexes,
    );
    try rebuildGraphTtlDueIndexInRange(self.alloc, dest_store, &dest_indexes, byte_range);

    try reconcileRelationalIndexRange(self, dest_store, byte_range);
    try rebaseRangeCoverageMetadata(self.alloc, dest_store, &dest_indexes, byte_range, &.{});

    try dest_indexes.syncAll(true);
    try dest_store.sync(true);
}

fn reconcileRelationalIndexRange(self: *DB, store: *docstore_mod.DocStore, byte_range: types.ByteRange) !void {
    var index_snapshot = self.core.relational_indexes.acquire() orelse return;
    defer index_snapshot.deinit();
    var repair = relational_index_records.RangeRepair{ .alloc = self.alloc };
    defer repair.deinit();
    while (!repair.done()) _ = try repair.step(store, byte_range.start, byte_range.end);
}

fn collectSplitFrontierDocKeys(alloc: Allocator, store: *docstore_mod.DocStore, lower: []const u8, upper: []const u8) ![][]u8 {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var keys = std.ArrayListUnmanaged([]u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(key);
        keys.deinit(alloc);
    }

    for (scanned) |entry| {
        if (!isPrimaryDocumentStoreKey(entry.key)) continue;
        const raw = (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, entry.key)) orelse continue;
        try keys.append(alloc, raw);
    }

    return try keys.toOwnedSlice(alloc);
}

fn registerSplitDestinationIndexesDirect(
    alloc: Allocator,
    dest_store: *docstore_mod.DocStore,
    applied_sequence_checkpoint_path: ?[]const u8,
    dest_indexes: *index_manager_mod.IndexManager,
    configs: []const types.IndexConfig,
    applied_sequence: u64,
) !void {
    if (configs.len == 0) return;

    try dest_indexes.addAllNoBackfill(dest_store, configs);
    var updates = try alloc.alloc(apply_state.AppliedSequenceUpdate, configs.len);
    defer alloc.free(updates);
    for (configs, 0..) |cfg, i| {
        updates[i] = .{
            .index_name = cfg.name,
            .sequence = applied_sequence,
            .config_hash = types.indexConfigHash(cfg),
        };
    }
    try savePhysicalProjectionMetadataForAppliedSequenceUpdates(dest_indexes, updates);
    try apply_state.saveAppliedSequencesWithCheckpoint(
        alloc,
        dest_indexes.checkpointIo(),
        dest_store,
        applied_sequence_checkpoint_path,
        updates,
    );
}

fn streamRangeIntoSplitDestinationDirect(
    alloc: Allocator,
    src: *DB,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const batch_size = 8192;

    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try src.core.scanStoreRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (isSplitMetadataKey(entry.key) or std.mem.startsWith(u8, entry.key, "\x00\x00__metadata__:")) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
}

fn copyGraphEdgeRangeIntoSplitDestination(
    alloc: Allocator,
    src: *DB,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
) !void {
    const batch_size = 1024;

    const scanned = try src.core.scanStoreRange(alloc, lower, upper);
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (!docstore_mod.KeyEncoder.isEdgeKey(entry.key)) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try dest_store.putBatch(writes.items, &.{});
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try dest_store.putBatch(writes.items, &.{});
}

// Mutation planning fields are not part of physical key/value storage. An
// explicit borrowed projection keeps these layers independent of Zig layout.
fn rawStoreWritesAlloc(alloc: Allocator, writes: []const types.BatchWrite) ![]docstore_mod.KVPair {
    const raw = try alloc.alloc(docstore_mod.KVPair, writes.len);
    for (writes, raw) |write, *item| item.* = .{ .key = write.key, .value = write.value };
    return raw;
}

fn putIndexedSplitBatchDirect(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    writes: []const types.BatchWrite,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    if (writes.len == 0) return;

    const raw_writes = try rawStoreWritesAlloc(dest_indexes.alloc, writes);
    defer dest_indexes.alloc.free(raw_writes);
    try dest_store.putBatch(raw_writes, &.{});

    try applySplitEmbeddingArtifactsFromBatch(dest_store, dest_indexes, writes, dense_handoffs, sparse_handoffs);

    var logical_writes = try dest_indexes.alloc.alloc(types.BatchWrite, writes.len);
    defer dest_indexes.alloc.free(logical_writes);
    var owned_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_keys.items) |key| dest_indexes.alloc.free(key);
        owned_keys.deinit(dest_indexes.alloc);
    }

    for (writes, 0..) |write, i| {
        if (internal_keys.isStoredDocumentRowKey(write.key)) {
            const raw = (try internal_keys.decodeStoredDocumentRowKeyAlloc(dest_indexes.alloc, write.key)) orelse return error.InvalidInternalUserKey;
            try owned_keys.append(dest_indexes.alloc, raw);
            logical_writes[i] = .{
                .key = raw,
                .value = write.value,
            };
        } else {
            logical_writes[i] = write;
        }
    }

    try dest_indexes.indexSplitBatch(dest_store, logical_writes, dense_handoffs, text_handoffs, sparse_handoffs);
}

fn findDenseSplitHandoffLocal(handoffs: []const index_manager_mod.DenseSplitHandoff, index_name: []const u8) ?*const index_manager_mod.DenseSplitHandoff {
    for (handoffs) |*handoff| {
        if (std.mem.eql(u8, handoff.index_name, index_name)) return handoff;
    }
    return null;
}

fn findSparseSplitHandoffLocal(handoffs: []const index_manager_mod.SparseSplitHandoff, index_name: []const u8) ?*const index_manager_mod.SparseSplitHandoff {
    for (handoffs) |*handoff| {
        if (std.mem.eql(u8, handoff.index_name, index_name)) return handoff;
    }
    return null;
}

fn collectEmbeddingArtifactKeysFromBatch(
    alloc: Allocator,
    writes: []const types.BatchWrite,
) ![][]const u8 {
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer keys.deinit(alloc);

    for (writes) |write| {
        if (!internal_keys.isEmbeddingArtifactKey(write.key) and !internal_keys.isDerivedEmbeddingArtifactKey(write.key)) continue;
        try keys.append(alloc, write.key);
    }

    return try keys.toOwnedSlice(alloc);
}

fn collectEmbeddingArtifactKeysInRangeAlloc(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    lower: []const u8,
    upper: []const u8,
) ![][]const u8 {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }

    for (scanned) |entry| {
        if (!internal_keys.isEmbeddingArtifactKey(entry.key) and !internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) continue;
        const owned = try alloc.dupe(u8, entry.key);
        try keys.append(alloc, owned);
    }

    return try keys.toOwnedSlice(alloc);
}

fn freeOwnedConstStringSlice(alloc: Allocator, keys: []const []const u8) void {
    for (keys) |key| alloc.free(@constCast(key));
    if (keys.len > 0) alloc.free(keys);
}

fn applySplitDenseEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
    handoff: ?*const index_manager_mod.DenseSplitHandoff,
) !void {
    var dense_embeddings = try collectDenseEmbeddingWritesForArtifacts(
        dest_indexes.alloc,
        dest_indexes,
        artifact_keys,
        index_name,
    );
    defer dense_embeddings.deinit();
    if (dense_embeddings.writes.len == 0) return;

    if (handoff) |skip| {
        var filtered = std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite).empty;
        defer filtered.deinit(dest_indexes.alloc);
        for (dense_embeddings.writes) |write| {
            if (skip.shouldSkip(write.doc_key)) continue;
            try filtered.append(dest_indexes.alloc, write);
        }
        if (filtered.items.len == 0) return;
        try dest_indexes.applyDenseEmbeddingWritesByNameWithOptions(dest_store, index_name, filtered.items, .{ .mode = .bulk_ingest });
        return;
    }

    try dest_indexes.applyDenseEmbeddingWritesByNameWithOptions(dest_store, index_name, dense_embeddings.writes, .{ .mode = .bulk_ingest });
}

fn applySplitSparseEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
    handoff: ?*const index_manager_mod.SparseSplitHandoff,
) !void {
    var sparse_embeddings = try collectSparseEmbeddingWritesForArtifacts(
        dest_indexes.alloc,
        dest_indexes,
        artifact_keys,
        index_name,
    );
    defer sparse_embeddings.deinit();
    if (sparse_embeddings.writes.len == 0) return;

    if (handoff) |skip| {
        var filtered = std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite).empty;
        defer filtered.deinit(dest_indexes.alloc);
        for (sparse_embeddings.writes) |write| {
            if (skip.shouldSkip(write.doc_key)) continue;
            try filtered.append(dest_indexes.alloc, write);
        }
        if (filtered.items.len == 0) return;
        try dest_indexes.applySparseEmbeddingWritesByNameWithOptions(dest_store, index_name, filtered.items, .{ .mode = .bulk_ingest });
        return;
    }

    try dest_indexes.applySparseEmbeddingWritesByNameWithOptions(dest_store, index_name, sparse_embeddings.writes, .{ .mode = .bulk_ingest });
}

fn applySplitEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    if (artifact_keys.len == 0) return;

    for (dest_indexes.dense_indexes.items) |entry| {
        try applySplitDenseEmbeddingArtifacts(
            dest_store,
            dest_indexes,
            artifact_keys,
            entry.config.name,
            findDenseSplitHandoffLocal(dense_handoffs, entry.config.name),
        );
    }

    for (dest_indexes.sparse_indexes.items) |entry| {
        try applySplitSparseEmbeddingArtifacts(
            dest_store,
            dest_indexes,
            artifact_keys,
            entry.config.name,
            findSparseSplitHandoffLocal(sparse_handoffs, entry.config.name),
        );
    }
}

fn applySplitEmbeddingArtifactsFromBatch(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    writes: []const types.BatchWrite,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const artifact_keys = try collectEmbeddingArtifactKeysFromBatch(dest_indexes.alloc, writes);
    defer if (artifact_keys.len > 0) dest_indexes.alloc.free(artifact_keys);
    try applySplitEmbeddingArtifacts(dest_store, dest_indexes, artifact_keys, dense_handoffs, sparse_handoffs);
}

fn applySplitEmbeddingArtifactsInRange(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const artifact_keys = try collectEmbeddingArtifactKeysInRangeAlloc(alloc, dest_store, lower, upper);
    defer freeOwnedConstStringSlice(alloc, artifact_keys);
    try applySplitEmbeddingArtifacts(dest_store, dest_indexes, artifact_keys, dense_handoffs, sparse_handoffs);
}

fn applySplitGraphArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
) !void {
    if (artifact_keys.len == 0) return;

    for (dest_indexes.graph_indexes.items) |entry| {
        _ = try applySplitGraphArtifactsForIndex(dest_store, dest_indexes, artifact_keys, entry.config.name);
    }
}

fn applySplitGraphArtifactsForIndex(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
) !usize {
    const graph_entry = dest_indexes.graphIndex(index_name) orelse return error.IndexNotFound;
    if (artifact_keys.len == 0) return 0;

    var graph_mutations = try collectGraphMutationsForArtifacts(
        dest_indexes.alloc,
        dest_store,
        artifact_keys,
        index_name,
        .{ .expected_generation = graph_entry.config.coverage_generation },
    );
    defer graph_mutations.deinit();
    const mutation_count = graph_mutations.writes.len + graph_mutations.deletes.len;
    if (graph_mutations.generation_bindings.len > 0) {
        try dest_store.putBatch(graph_mutations.generation_bindings, &.{});
    }
    try dest_indexes.applyGraphMutationsByName(index_name, graph_mutations.writes, graph_mutations.deletes);
    return mutation_count;
}

fn applySplitGraphArtifactsStreaming(
    alloc: Allocator,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    lower: []const u8,
    upper: []const u8,
    batch_size: usize,
) !void {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);
    const effective_batch_size = @max(batch_size, 1);

    const IndexBuffer = struct {
        index_name: []const u8,
        writes: std.ArrayListUnmanaged(types.GraphEdgeWrite) = .empty,

        fn freeWrites(buffer: *@This(), buffer_alloc: Allocator) void {
            for (buffer.writes.items) |write| {
                buffer_alloc.free(@constCast(write.index_name));
                buffer_alloc.free(@constCast(write.source));
                buffer_alloc.free(@constCast(write.target));
                buffer_alloc.free(@constCast(write.edge_type));
                if (write.edge_id.len > 0) buffer_alloc.free(@constCast(write.edge_id));
                if (write.owner_document.len > 0) buffer_alloc.free(@constCast(write.owner_document));
                if (write.owner.len > 0) buffer_alloc.free(@constCast(write.owner));
                if (write.metadata_json.len > 0) buffer_alloc.free(@constCast(write.metadata_json));
            }
            buffer.writes.clearRetainingCapacity();
        }

        pub fn deinit(buffer: *@This(), buffer_alloc: Allocator) void {
            buffer.freeWrites(buffer_alloc);
            buffer.writes.deinit(buffer_alloc);
        }
    };

    const ScanState = struct {
        alloc: Allocator,
        dest_indexes: *index_manager_mod.IndexManager,
        batch_size: usize,
        buffers: []IndexBuffer = &.{},
        initialized_buffers: usize = 0,
        indexes_by_name: std.StringHashMapUnmanaged(usize) = .empty,
        pending_writes: usize = 0,

        fn initBuffers(state: *@This()) !void {
            if (state.dest_indexes.graph_indexes.items.len == 0) return;
            state.buffers = try state.alloc.alloc(IndexBuffer, state.dest_indexes.graph_indexes.items.len);
            for (state.dest_indexes.graph_indexes.items, 0..) |entry, i| {
                state.buffers[i] = .{ .index_name = entry.config.name };
                state.initialized_buffers += 1;
                const slot = try state.indexes_by_name.getOrPut(state.alloc, entry.config.name);
                if (slot.found_existing) return error.InvalidIndexConfig;
                slot.value_ptr.* = i;
            }
        }

        pub fn deinit(state: *@This()) void {
            for (state.buffers[0..state.initialized_buffers]) |*buffer| buffer.deinit(state.alloc);
            if (state.buffers.len > 0) state.alloc.free(state.buffers);
            state.indexes_by_name.deinit(state.alloc);
        }

        fn flush(state: *@This()) !void {
            if (state.pending_writes == 0) return;
            if (comptime builtin.is_test) {
                _ = test_graph_repair_stream_flushes.fetchAdd(1, .monotonic);
            }
            for (state.buffers[0..state.initialized_buffers]) |*buffer| {
                if (buffer.writes.items.len == 0) continue;
                try state.dest_indexes.applyGraphMutationsByName(buffer.index_name, buffer.writes.items, &.{});
                state.pending_writes -= buffer.writes.items.len;
                buffer.freeWrites(state.alloc);
            }
            std.debug.assert(state.pending_writes == 0);
        }

        fn appendDecodedWrite(
            state: *@This(),
            buffer_index: usize,
            parsed: anytype,
            decoded: *enrichment_artifact_codec.GraphEdge,
        ) !void {
            const buffer = &state.buffers[buffer_index];
            try buffer.writes.ensureUnusedCapacity(state.alloc, 1);
            const index_name = try state.alloc.dupe(u8, parsed.index_name);
            errdefer state.alloc.free(index_name);
            const source = try state.alloc.dupe(u8, if (parsed.logical_source.len > 0) parsed.logical_source else parsed.doc_key);
            errdefer state.alloc.free(source);
            const target = try state.alloc.dupe(u8, parsed.target_doc_key);
            errdefer state.alloc.free(target);
            const edge_type = try state.alloc.dupe(u8, parsed.edge_type);
            errdefer state.alloc.free(edge_type);
            const edge_id = try state.alloc.dupe(u8, parsed.edge_id);
            errdefer state.alloc.free(edge_id);
            const owner_document = if (parsed.edge_id.len > 0 and parsed.logical_source.len > 0) try state.alloc.dupe(u8, parsed.doc_key) else "";
            errdefer if (owner_document.len > 0) state.alloc.free(owner_document);
            const owner = if (parsed.edge_id.len == 0 and parsed.source_node != null) try state.alloc.dupe(u8, parsed.doc_key) else "";
            errdefer if (owner.len > 0) state.alloc.free(owner);
            buffer.writes.appendAssumeCapacity(.{
                .index_name = index_name,
                .source = source,
                .target = target,
                .edge_type = edge_type,
                .edge_id = edge_id,
                .owner_document = owner_document,
                .owner = owner,
                .weight = decoded.weight,
                .created_at = decoded.created_at,
                .updated_at = decoded.updated_at,
                .ttl_created_ns = decoded.ttl_created_ns,
                .metadata_json = decoded.metadata_json,
            });
            decoded.metadata_json = &.{};
            state.pending_writes += 1;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isGraphEdgeArtifactKey(key)) return .@"continue";
            const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(state.alloc, key)) orelse return .@"continue";
            defer {
                state.alloc.free(parsed.doc_key);
                state.alloc.free(parsed.index_name);
                state.alloc.free(parsed.edge_type);
                state.alloc.free(parsed.target_doc_key);
                state.alloc.free(parsed.edge_id);
                state.alloc.free(parsed.logical_source);
            }
            const buffer_index = state.indexes_by_name.get(parsed.index_name) orelse return .@"continue";
            var decoded = try enrichment_artifact_codec.decodeGraphEdgeAlloc(state.alloc, value);
            defer decoded.deinit(state.alloc);
            try state.appendDecodedWrite(buffer_index, parsed, &decoded);
            if (state.pending_writes >= state.batch_size) try state.flush();
            return .@"continue";
        }
    };

    var state = ScanState{
        .alloc = alloc,
        .dest_indexes = dest_indexes,
        .batch_size = effective_batch_size,
    };
    defer state.deinit();
    try state.initBuffers();
    if (state.initialized_buffers == 0) return;

    if (comptime builtin.is_test) {
        _ = test_graph_repair_stream_scans.fetchAdd(1, .monotonic);
    }
    try dest_store.scanWithContext(
        store_lower,
        if (store_upper) |buf| buf else "",
        .{},
        &state,
        ScanState.scanEntry,
    );
    try state.flush();
}

/// Reuse ordinary graph materialization for a renamed logical index, not the
/// old index's already-materialized edge keys. This keeps changed source
/// mappings, mention edges and relation endpoints on the public semantics.
fn rebuildGraphReplacementDocumentWithRead(ctx: *AsyncContext, name: []const u8, key: []const u8, read: *docstore_mod.DocStore.Txn) !void {
    return rebuildGraphReplacementDocumentsWithRead(ctx, name, &.{key}, read);
}

pub fn rebuildGraphReplacementDocumentsWithRead(ctx: *AsyncContext, name: []const u8, keys: []const []const u8, read: *docstore_mod.DocStore.Txn) !void {
    if (builtin.is_test) DB.test_graph_replacement_document_batches += 1;
    var arena = std.heap.ArenaAllocator.init(ctx.alloc);
    defer arena.deinit();
    const a = arena.allocator();
    var plan = try ctx.index_manager.writePlanSnapshotAlloc(a);
    defer plan.deinit();
    var cursor = try read.openCursor();
    defer cursor.close();
    var sources: std.ArrayList([]const u8) = .empty;
    var deletes: std.ArrayListUnmanaged([]const u8) = .empty;
    var owned_deletes: std.ArrayListUnmanaged([]u8) = .empty;
    var writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty;
    var direct: std.ArrayListUnmanaged(types.BatchWrite) = .empty;
    var owned_keys: std.ArrayListUnmanaged([]u8) = .empty;
    var owned_values: std.ArrayListUnmanaged([]u8) = .empty;
    for (keys) |key| {
        const prefix = try internal_keys.documentExactPrefixAlloc(a, key);
        var row = try cursor.seekAtOrAfter(prefix);
        while (row) |kv| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            if (internal_keys.isGraphEdgeArtifactKey(kv.key)) {
                const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(a, kv.key)).?;
                if (std.mem.eql(u8, parsed.index_name, name)) try deletes.append(a, try a.dupe(u8, kv.key));
            } else if (internal_keys.isAssetArtifactKey(kv.key) or internal_keys.isChunkArtifactRecordKey(kv.key) or internal_keys.isResolutionArtifactKey(kv.key)) {
                try sources.append(a, try a.dupe(u8, kv.key));
            }
        }
        const stored_key = if (ctx.relational_base_rows) try internal_keys.relationalRowKeyAlloc(a, key) else try internal_keys.documentKeyAlloc(a, key);
        const raw = try missingAsNull(read.get(stored_key));
        if (raw) |value| {
            const json = try ctx.index_manager.materializeStoredValueAlloc(a, stored_key, value);
            const root = try std.json.parseFromSliceLeaky(std.json.Value, a, json, .{});
            var extracted = try mapper.extractWrite(a, key, json);
            try local_mutation.augmentExtractedWriteWithGraphFieldEdgesFromSnapshotParsed(plan, a, key, root, &extracted);
            const graph = ctx.index_manager.graphIndex(name).?;
            for (extracted.graph_writes) |write| {
                if (!std.mem.eql(u8, write.index_name, name)) continue;
                const artifact = try internal_keys.graphRelationshipArtifactKeyAlloc(a, key, name, write.edge_type, write.target, write.source, write.edge_id);
                const payload = try encodeGraphSourceEdgeArtifactWithTtlAlloc(a, ctx.store, artifact, graph.config.coverage_generation, graph.ttl_duration_ns, currentTimeNs(), write);
                try direct.append(a, .{ .key = artifact, .value = payload });
                try writes.append(a, .{ .key = artifact, .value = payload });
            }
        }
    }
    try local_mutation.appendMixedDirectGraphContenderMutations(a, ctx.store, ctx.index_manager, direct.items, &writes, &deletes, &owned_keys, &owned_values, &owned_deletes);
    if (writes.items.len > 0 or deletes.items.len > 0) try ctx.store.putBatch(writes.items, deletes.items);
    try ctx.index_manager.deleteGraphDocsByName(name, keys);
    const changed = try materializeGraphSourceArtifactsForIndex(a, ctx.store, ctx.index_manager, sources.items, name, .{ .require_resolution_contract = true });
    var changed_keys: std.ArrayList([]const u8) = .empty;
    try changed_keys.appendSlice(a, changed);
    for (direct.items) |write| try changed_keys.append(a, write.key);
    try applyDerivedBatchToIndexContextProfiled(ctx, .{ .changed_artifact_keys = changed_keys.items }, .{ .name = name, .kind = .graph }, null, false, null);
}

fn applySplitGraphArtifactsForIndexStreamingContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    batch_size: usize,
) !usize {
    const graph_entry = ctx.index_manager.graphIndex(index_name) orelse return error.IndexNotFound;
    const store_lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(store_lower);
    const effective_batch_size = @max(batch_size, 1);

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        batch_size: usize,
        expected_generation: u64,
        writes: std.ArrayListUnmanaged(types.GraphEdgeWrite) = .empty,
        generation_bindings: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty,
        mutation_count: usize = 0,

        fn freeWrites(state: *@This()) void {
            for (state.writes.items) |write| {
                state.ctx.alloc.free(@constCast(write.index_name));
                state.ctx.alloc.free(@constCast(write.source));
                state.ctx.alloc.free(@constCast(write.target));
                state.ctx.alloc.free(@constCast(write.edge_type));
                if (write.edge_id.len > 0) state.ctx.alloc.free(@constCast(write.edge_id));
                if (write.owner_document.len > 0) state.ctx.alloc.free(@constCast(write.owner_document));
                if (write.metadata_json.len > 0) state.ctx.alloc.free(@constCast(write.metadata_json));
                if (write.owner.len > 0) state.ctx.alloc.free(@constCast(write.owner));
            }
            state.writes.clearRetainingCapacity();
        }

        fn freeGenerationBindings(state: *@This()) void {
            for (state.generation_bindings.items) |binding| {
                state.ctx.alloc.free(@constCast(binding.key));
                state.ctx.alloc.free(@constCast(binding.value));
            }
            state.generation_bindings.clearRetainingCapacity();
        }

        pub fn deinit(state: *@This()) void {
            state.freeWrites();
            state.writes.deinit(state.ctx.alloc);
            state.freeGenerationBindings();
            state.generation_bindings.deinit(state.ctx.alloc);
        }

        fn flush(state: *@This()) !void {
            try checkAsyncRepairCancelled(state.ctx);
            if (state.writes.items.len == 0 and state.generation_bindings.items.len == 0) return;
            try checkAsyncRepairCapacityBoundary(state.ctx);
            if (comptime builtin.is_test) {
                _ = test_graph_repair_stream_flushes.fetchAdd(1, .monotonic);
            }
            if (state.generation_bindings.items.len > 0) {
                try state.ctx.store.putBatch(state.generation_bindings.items, &.{});
                state.freeGenerationBindings();
            }
            try state.ctx.index_manager.applyGraphMutationsByName(state.index_name, state.writes.items, &.{});
            state.mutation_count += state.writes.items.len;
            state.freeWrites();
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isGraphEdgeArtifactKey(key)) return .@"continue";
            try checkAsyncRepairCancelled(state.ctx);
            const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(state.ctx.alloc, key)) orelse return .@"continue";
            defer {
                state.ctx.alloc.free(parsed.doc_key);
                state.ctx.alloc.free(parsed.index_name);
                state.ctx.alloc.free(parsed.edge_type);
                state.ctx.alloc.free(parsed.target_doc_key);
                state.ctx.alloc.free(parsed.edge_id);
                state.ctx.alloc.free(parsed.logical_source);
            }
            if (!std.mem.eql(u8, parsed.index_name, state.index_name)) return .@"continue";

            var decoded = enrichment_artifact_codec.decodeGraphEdgeAlloc(state.ctx.alloc, value) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => {
                    const artifact_name = try std.fmt.allocPrint(state.ctx.alloc, "{s}:{s}", .{ parsed.edge_type, parsed.target_doc_key });
                    defer state.ctx.alloc.free(artifact_name);
                    try recordArtifactRepairIssueContextForIndexSource(
                        state.ctx,
                        .graph,
                        parsed.index_name,
                        parsed.doc_key,
                        "",
                        "",
                        "",
                        "",
                        artifact_name,
                        key,
                        null,
                        state.ctx.repair_sequence,
                        .corrupt_artifact,
                    );
                    return .@"continue";
                },
            };
            if (enrichment_artifact_codec.isLegacyUnboundGraphEdge(value)) {
                decoded.deinit(state.ctx.alloc);
                return .@"continue";
            }
            const generation_unbound = enrichment_artifact_codec.isPortableUnboundGraphEdge(value);
            if (decoded.generation != state.expected_generation and !generation_unbound) {
                decoded.deinit(state.ctx.alloc);
                return .@"continue";
            }
            if (generation_unbound) {
                const bound_value = try enrichment_artifact_codec.bindGraphEdgeGenerationAlloc(
                    state.ctx.alloc,
                    value,
                    state.expected_generation,
                );
                errdefer state.ctx.alloc.free(bound_value);
                const bound_key = try state.ctx.alloc.dupe(u8, key);
                errdefer state.ctx.alloc.free(bound_key);
                try state.generation_bindings.append(state.ctx.alloc, .{ .key = bound_key, .value = bound_value });
            }
            errdefer decoded.deinit(state.ctx.alloc);
            try state.writes.append(state.ctx.alloc, .{
                .index_name = try state.ctx.alloc.dupe(u8, parsed.index_name),
                // Entity-sourced relations rebuild from the key's embedded
                // source node; the owning document keys the rebuilt row.
                .source = try state.ctx.alloc.dupe(u8, parsed.source_node orelse parsed.doc_key),
                .owner = if (parsed.edge_id.len == 0 and parsed.source_node != null) try state.ctx.alloc.dupe(u8, parsed.doc_key) else "",
                .target = try state.ctx.alloc.dupe(u8, parsed.target_doc_key),
                .edge_type = try state.ctx.alloc.dupe(u8, parsed.edge_type),
                .edge_id = try state.ctx.alloc.dupe(u8, parsed.edge_id),
                .owner_document = if (parsed.edge_id.len > 0 and parsed.logical_source.len > 0) try state.ctx.alloc.dupe(u8, parsed.doc_key) else "",
                .weight = decoded.weight,
                .created_at = decoded.created_at,
                .updated_at = decoded.updated_at,
                .ttl_created_ns = decoded.ttl_created_ns,
                .metadata_json = decoded.metadata_json,
            });
            decoded.metadata_json = &.{};
            decoded.deinit(state.ctx.alloc);
            if (state.writes.items.len >= state.batch_size) try state.flush();
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .batch_size = effective_batch_size,
        .expected_generation = graph_entry.config.coverage_generation,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, store_lower, "", .{}, &state, ScanState.scanEntry);
    try state.flush();
    return state.mutation_count;
}

pub fn applySplitGraphArtifactsInRange(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
) !void {
    // Restore and split repair must stay bounded by one global mutation batch,
    // even when a table contains millions of durable graph artifacts. Parse
    // each artifact once and route it to its configured index so adding graph
    // indexes does not multiply the complete document-range scan.
    try applySplitGraphArtifactsStreaming(
        alloc,
        dest_store,
        dest_indexes,
        lower,
        upper,
        graph_repair_rebuild_batch_size,
    );
}

fn indexExistingSplitDestinationDirect(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const batch_size = 8192;

    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try dest_store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (isSplitMetadataKey(entry.key)) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
}

pub fn finalizeSplitLocked(self: *DB, new_range: types.ByteRange) !void {
    try self.requireSupportedRelationalTopology();
    var transaction_manager = try self.core.initTxnManager();
    defer transaction_manager.deinit();
    if (try transaction_manager.hasSchemaLeases()) return error.SchemaInUse;
    const split_state = self.core.splitState() orelse return error.SplitInProgress;
    if (!std.mem.eql(u8, split_state.split_key, new_range.end)) return error.KeyOutOfRange;
    // A committed user write must never make a split publish an incomplete
    // secondary generation. Drain every post-commit ticket and fail closed if
    // any shadow index needs replay repair.
    try waitForSplitShadowDrainLocked(self, true);
    const replay_floor = self.core.nextDerivedAppendSequence();
    // On a live handle, restore precommit ownership before releasing the apply
    // lock. If restoration fails, the durable marker keeps subsequent reads
    // closed until writable reopen can finish it.
    errdefer recoverInterruptedGraphSplitRetirement(self) catch |recovery_err| {
        std.log.err("split graph restoration failed path={s} err={s}; reads remain fenced", .{ self.core.path, @errorName(recovery_err) });
    };

    // Prepare all private ownership tasks before the authoritative range can
    // narrow. Partial preparation/failure leaves the old graph visible, and
    // primary range adoption activates the prepared fences infallibly.
    //
    // Withdraw moved graph artifacts while their owners remain admitted here.
    // Source-keyed pruning cannot account for entity sources on either side
    // of the split, and direct contributions can share a retained owner edge.
    try retireSplitEntitySourcedEdgesLocked(self, split_state);
    // Reproject retained owners before publishing the narrower primary range.
    // A moved direct or entity owner may have supplied the old shared physical
    // winner; the retained owner's artifact is the authoritative replacement.
    try applySplitGraphArtifactsStreaming(
        self.alloc,
        self.core.store,
        self.core.index_manager,
        self.core.byteRange().start,
        split_state.split_key,
        graph_repair_rebuild_batch_size,
    );
    try self.core.index_manager.fenceGraphSplitRange(split_state.split_key, split_state.original_range_end);
    const split_lower = try documentRangeLowerAlloc(self.alloc, split_state.split_key);
    defer self.alloc.free(split_lower);
    try markSplitOffDocumentArtifactChildRangesLocked(self, split_state, split_lower);
    try finalizePrimarySplitPreservingMetadata(self, split_lower, new_range);
    try ensureReplayFloor(self.core.store, replay_floor);
    try self.core.pruneSplitRangeFromPrimaryIndexes(split_state.split_key, split_state.original_range_end);
    try self.rebaseManagedIndexAppliedSequencesIfNeeded();

    if (split_state.phase == .prepare) {
        try self.core.completeSplitTransition(split_state.new_shard_id, split_state.split_key);
    } else if (split_state.phase != .splitting and split_state.phase != .finalizing) {
        return error.SplitInProgress;
    }

    try self.core.finalizeSplitState();
    try self.core.store.delete(graph_split_retire_cursor_key);
    try self.core.store.sync(true);
    // The authoritative range transition activates the source fence. Finish
    // its durable pages before returning; a retained owner's source may lie
    // in the moved range and must be visible as soon as this split completes.
    while (try self.core.index_manager.runGraphOwnershipCleanupStep()) {}
    try self.refreshManagedIndexWorkersLocked();
    try self.closeShadowIndexManagerLocked();
    try self.refreshManagedIndexWorkersLocked();
}

/// Withdraw moved graph artifact contributions from this shard. The
/// destination re-applies them from its copied primary artifacts. A split
/// retirement clears each private TTL snapshot even though the artifact is
/// still present here until the primary range commits.
pub fn retireSplitEntitySourcedEdgesLocked(self: *DB, split_state: shard_mod.SplitState) !void {
    const alloc = self.alloc;
    const lower = try documentRangeLowerAlloc(alloc, split_state.split_key);
    defer alloc.free(lower);
    const upper = if (split_state.original_range_end.len > 0)
        try documentRangeUpperAlloc(alloc, split_state.original_range_end)
    else
        null;
    defer if (upper) |key| alloc.free(key);

    const State = struct {
        alloc: Allocator,
        indexes: *index_manager_mod.IndexManager,
        store: *docstore_mod.DocStore,
        deletes: std.ArrayListUnmanaged(types.GraphEdgeDelete) = .empty,
        bytes: usize = 0,
        last_key: ?[]u8 = null,

        fn clear(state: *@This()) void {
            for (state.deletes.items) |*delete| delete.deinit(state.alloc);
            state.deletes.clearRetainingCapacity();
            state.bytes = 0;
        }

        fn flush(state: *@This()) !void {
            if (state.deletes.items.len == 0) return;
            try state.indexes.retireSplitGraphOwners(state.deletes.items);
            if (comptime builtin.is_test) {
                if (test_graph_split_retire_abort_before_cursor.swap(false, .monotonic))
                    return error.TestInjectedBackfillFailure;
            }
            // Never persist progress ahead of the graph mutation. Replaying a
            // page is safe; skipping a non-durable page would lose edges.
            try state.indexes.syncGraphIndexes(true);
            try state.store.put(graph_split_retire_cursor_key, state.last_key orelse return error.InvalidSplitRetirementCursor);
            try state.store.sync(true);
            if (comptime builtin.is_test) _ = test_graph_split_retire_flushes.fetchAdd(1, .monotonic);
            state.clear();
            state.alloc.free(state.last_key.?);
            state.last_key = null;
            if (comptime builtin.is_test) {
                if (test_graph_split_retire_abort_after_flush.swap(false, .monotonic))
                    return error.TestInjectedBackfillFailure;
            }
        }

        fn visit(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            if (!internal_keys.isGraphEdgeArtifactKey(key)) return .@"continue";
            const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(state.alloc, key)) orelse return .@"continue";
            defer {
                state.alloc.free(parsed.doc_key);
                state.alloc.free(parsed.index_name);
                state.alloc.free(parsed.edge_type);
                state.alloc.free(parsed.target_doc_key);
                state.alloc.free(parsed.edge_id);
                if (parsed.source_node) |source| state.alloc.free(source);
            }
            var mutation = try (types.GraphEdgeDelete{
                .index_name = parsed.index_name,
                .source = parsed.source_node orelse parsed.doc_key,
                .target = parsed.target_doc_key,
                .edge_type = parsed.edge_type,
                .edge_id = parsed.edge_id,
                .owner_document = if (parsed.edge_id.len > 0 and parsed.source_node != null) parsed.doc_key else "",
                .owner = if (parsed.edge_id.len == 0 and parsed.source_node != null) parsed.doc_key else "",
            }).cloneAlloc(state.alloc);
            var transferred = false;
            errdefer if (!transferred) mutation.deinit(state.alloc);
            // Count every retained identity field, including its ownership mode.
            // Both the workspace and the replay cursor remain page bounded.
            const retained_bytes = mutation.retainedBytes();
            try state.deletes.append(state.alloc, mutation);
            // Ownership moved into the page; later failures unwind through State.clear.
            transferred = true;
            const next_key = try state.alloc.dupe(u8, key);
            if (state.last_key) |previous| state.alloc.free(previous);
            state.last_key = next_key;
            state.bytes +|= retained_bytes;
            if (state.deletes.items.len >= graph_repair_rebuild_batch_size or state.bytes >= 4 * 1024 * 1024)
                try state.flush();
            return .@"continue";
        }
    };
    var state = State{ .alloc = alloc, .indexes = self.core.index_manager, .store = self.core.store };
    defer {
        state.clear();
        state.deletes.deinit(alloc);
        if (state.last_key) |key| alloc.free(key);
    }
    const cursor = try missingAsNull(self.core.store.get(alloc, graph_split_retire_cursor_key));
    defer if (cursor) |key| alloc.free(key);
    if (cursor) |key| {
        if (key.len != 0 and (std.mem.order(u8, key, lower) == .lt or
            (upper != null and std.mem.order(u8, key, upper.?) != .lt)))
            return error.InvalidSplitRetirementCursor;
    } else {
        // Arm recovery before the first graph mutation. The empty value means
        // no page has committed; a crash in the first page is now recoverable.
        try self.core.store.put(graph_split_retire_cursor_key, "");
        try self.core.store.sync(true);
    }
    // The split state and owner artifacts stay durable until the primary range
    // commits. The persisted cursor resumes after the last synced graph page.
    try self.core.store.scanWithContext(
        if (cursor) |key| if (key.len > 0) key else lower else lower,
        if (upper) |key| key else "",
        .{ .lower_exclusive = if (cursor) |key| key.len > 0 else false },
        &state,
        State.visit,
    );
    try state.flush();
    // Retain the marker until the primary range commits. A crash between this
    // scan and that commit must restore the withdrawn graph on writable open.
}

pub fn recoverInterruptedGraphSplitRetirement(self: *DB) !void {
    const cursor = self.core.store.get(self.alloc, graph_split_retire_cursor_key) catch |err| switch (err) {
        error.NotFound => return,
        else => return err,
    };
    defer self.alloc.free(cursor);
    if (self.core.splitState()) |split_state| {
        if (!std.mem.eql(u8, self.core.byteRange().end, split_state.split_key)) {
            // Before the primary range commits, all moved-owner artifacts
            // remain here. Reproject them before serving reads or cancelling
            // the split. After the range narrows, the prepared graph fence
            // owns cleanup and moved owners must stay withdrawn.
            try applySplitGraphArtifactsStreaming(
                self.alloc,
                self.core.store,
                self.core.index_manager,
                split_state.split_key,
                split_state.original_range_end,
                graph_repair_rebuild_batch_size,
            );
            try self.core.index_manager.syncGraphIndexes(true);
        }
    }
    try self.core.store.delete(graph_split_retire_cursor_key);
    try self.core.store.sync(true);
}

fn markSplitOffDocumentArtifactChildRangesLocked(
    self: *DB,
    split_state: shard_mod.SplitState,
    split_lower: []const u8,
) !void {
    if (split_state.new_shard_id == 0) return;

    const parent_lower = try documentRangeLowerAlloc(self.alloc, self.core.byteRange().start);
    defer self.alloc.free(parent_lower);
    const parent_upper = split_lower;
    const split_upper = if (split_state.original_range_end.len > 0)
        try documentRangeUpperAlloc(self.alloc, split_state.original_range_end)
    else
        null;
    defer if (split_upper) |upper| self.alloc.free(upper);

    const scanned = try self.core.scanStoreRange(self.alloc, parent_lower, parent_upper);
    defer docstore_mod.DocStore.freeResults(self.alloc, scanned);

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(self.alloc);
    var owned_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_values.items) |value| self.alloc.free(value);
        owned_values.deinit(self.alloc);
    }
    var changed_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (changed_artifact_keys.items) |key| self.alloc.free(key);
        changed_artifact_keys.deinit(self.alloc);
    }

    for (scanned) |entry| {
        if (std.mem.indexOf(u8, entry.value, "\"child_ranges\"") == null) continue;
        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(self.alloc, entry.key)) orelse continue;
        defer artifact_ref.deinit(self.alloc);
        if (artifact_ref.kind != .asset or artifact_ref.unit_id != null) continue;

        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();
        var manifest_value = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, entry.value, .{ .allocate = .alloc_always });
        if (manifest_value != .object) continue;
        const child_ranges = manifest_value.object.getPtr("child_ranges") orelse continue;
        if (child_ranges.* != .array) continue;

        var changed = false;
        for (child_ranges.array.items) |*item| {
            if (item.* != .object) continue;
            if (!documentArtifactChildRangeMovedBySplit(item.object, split_lower, split_upper)) continue;
            try putLeakyJsonStringField(arena_alloc, &item.object, "placement", "remote");
            try putLeakyJsonU64Field(arena_alloc, &item.object, "owner_group_id", split_state.new_shard_id);
            try putLeakyJsonU64Field(arena_alloc, &item.object, "placement_generation", (try jsonObjectOptionalU64(item.object, "placement_generation") orelse 0) + 1);
            try putLeakyJsonStringField(arena_alloc, &item.object, "route_status", "remote_committed");
            try item.object.put(arena_alloc, "split_eligible", .{ .bool = false });
            changed = true;
        }
        if (!changed) continue;

        const updated_manifest = try std.json.Stringify.valueAlloc(self.alloc, manifest_value, .{});
        errdefer self.alloc.free(updated_manifest);
        try owned_values.append(self.alloc, updated_manifest);
        try writes.append(self.alloc, .{
            .key = entry.key,
            .value = updated_manifest,
        });
        try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, entry.key);
    }

    if (writes.items.len == 0) return;
    const sequence = self.core.reserveDerivedAppendSequence();
    const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
        .sequence = sequence,
        .changed_artifact_keys = changed_artifact_keys.items,
    }, sequence);
    defer self.alloc.free(replay_payload);
    var backlog_admission = try self.executor.admitBacklogBytes(@intCast(replay_payload.len));
    defer backlog_admission.cancel();
    try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes.items, &.{}, .{
        .sequence = sequence,
        .payload = replay_payload,
    });
    self.executor.commitBacklogAdmission(sequence, &backlog_admission);
    DB.notifyQueryVisibilityTargetAdvanced(self.async_context, sequence);
    self.mirrorReplicationReplayPayloadBestEffort(replay_payload);
    if (shouldAppendSplitDelta(self)) {
        try self.core.appendSplitDelta(currentTimeNs(), writes.items, &.{});
    }
}

fn documentArtifactChildRangeMovedBySplit(
    object: std.json.ObjectMap,
    split_lower: []const u8,
    split_upper: ?[]const u8,
) bool {
    const split_eligible = blk: {
        const value = object.get("split_eligible") orelse break :blk false;
        if (value != .bool) return false;
        break :blk value.bool;
    };
    if (!split_eligible) return false;

    const placement = object.get("placement") orelse return false;
    if (placement != .string) return false;
    if (std.mem.eql(u8, placement.string, "remote")) return false;

    if (object.get("owner_group_id")) |owner| {
        if (owner == .integer and owner.integer > 0) return false;
    }

    const route_status = object.get("route_status") orelse null;
    if (route_status) |status| {
        if (status != .string) return false;
        if (std.mem.eql(u8, status.string, "remote_committed")) return false;
    }

    const start_key = object.get("start_key") orelse return false;
    if (start_key != .string) return false;
    if (std.mem.order(u8, start_key.string, split_lower) == .lt) return false;
    const end_key = object.get("end_key_exclusive") orelse return false;
    if (end_key != .string) return false;
    if (split_upper) |upper| {
        if (end_key.string.len == 0) return false;
        if (std.mem.order(u8, end_key.string, upper) == .gt) return false;
    }
    return true;
}

pub fn byteRangesEqual(a: types.ByteRange, b: types.ByteRange) bool {
    return std.mem.eql(u8, a.start, b.start) and std.mem.eql(u8, a.end, b.end);
}

const isSplitMetadataKey = execution_resources.isSplitMetadataKey;

fn clearSplitMetadataFromStore(alloc: Allocator, dest_store: *docstore_mod.DocStore) !void {
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "splitstate:");
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "splitdelta:");
}

fn clearSystemMetadataFromSplitDestination(alloc: Allocator, dest_store: *docstore_mod.DocStore) !void {
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "\x00\x00__metadata__:");
    // Split destinations register and populate their index generations
    // synchronously below. A physical LSM split also carries replay-namespace
    // control rows, including a tombstone-shadowed admission marker from the
    // source's history. Never let source-generation admission state quarantine
    // an independently constructed destination generation.
    const admission_prefix = try internal_keys.managedIndexAdmissionRootPrefixAlloc(alloc);
    defer alloc.free(admission_prefix);
    try deleteKeysWithPrefixFromStore(alloc, dest_store, admission_prefix);
    // The destination owns an independent Raft log. A physical page split can
    // copy the source's higher applied index; retaining it would suppress valid
    // low-index entries in the new group.
    // A destination prepared from an older layout must not inherit the
    // parent's merge ownership or retired-transition fences either.
    try dest_store.putBatch(&.{}, &.{
        internal_keys.ordered_document_applied_entry_key[0..],
        merge_state_mod.legacy_key,
    });
}

fn ensureReplayFloor(store: *docstore_mod.DocStore, next_sequence: u64) !void {
    try store.ensureReplayNextSequenceAtLeast(next_sequence);
}

fn deleteKeysWithPrefixFromStore(alloc: Allocator, dest_store: *docstore_mod.DocStore, prefix: []const u8) !void {
    const keys = try dest_store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, keys);
    if (keys.len == 0) return;

    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(alloc);
    for (keys) |item| {
        try deletes.append(alloc, item.key);
    }
    try dest_store.putBatch(&.{}, deletes.items);
}

fn copyFileIfPresent(src_dir: []const u8, dst_dir: []const u8, name: []const u8) !u64 {
    const src_path = try std.fmt.allocPrint(std.heap.page_allocator, "{s}/{s}", .{ src_dir, name });
    defer std.heap.page_allocator.free(src_path);
    const dst_path = try std.fmt.allocPrint(std.heap.page_allocator, "{s}/{s}", .{ dst_dir, name });
    defer std.heap.page_allocator.free(dst_path);

    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();

    std.Io.Dir.accessAbsolute(io, src_path, .{}) catch |err| switch (err) {
        error.FileNotFound => return 0,
        else => return err,
    };

    var src_file = try std.Io.Dir.openFileAbsolute(io, src_path, .{});
    defer src_file.close(io);
    const src_stat = try src_file.stat(io);

    var dst_file = try fs_paths.createFilePortable(io, dst_path, .{ .truncate = true });
    defer dst_file.close(io);

    var writer_buf: [1024]u8 = undefined;
    var writer = dst_file.writer(io, &writer_buf);
    var src_reader: std.Io.File.Reader = .initSize(src_file, io, &.{}, src_stat.size);
    _ = writer.interface.sendFileAll(&src_reader, .unlimited) catch |err| switch (err) {
        error.ReadFailed => return src_reader.err.?,
        error.WriteFailed => return writer.err.?,
    };
    try writer.flush();
    return src_stat.size;
}

pub fn ensureDirPath(path: []const u8) !void {
    if (path.len == 0) return;
    var io_impl = threadedIo();
    defer io_impl.deinit();
    try fs_paths.createDirPathPortable(io_impl.io(), path);
}

pub fn validateSnapshotId(id: []const u8) !void {
    if (id.len == 0 or id.len > 255 or
        std.mem.eql(u8, id, ".") or
        std.mem.eql(u8, id, "..") or
        std.mem.indexOfScalar(u8, id, '/') != null or
        std.mem.indexOfScalar(u8, id, '\\') != null)
    {
        return error.InvalidSnapshotId;
    }
}

pub fn snapshotPathExists(io: Io, path: []const u8) !bool {
    if (std.fs.path.isAbsolute(path)) {
        std.Io.Dir.accessAbsolute(io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
    } else {
        std.Io.Dir.cwd().access(io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
    }
    return true;
}

pub fn createSnapshotStagingRoot(alloc: Allocator, io: Io, parent: []const u8, id: []const u8) ![]u8 {
    return snapshot_staging.createRoot(alloc, io, parent, id);
}

pub fn publishSnapshotStaging(io: Io, parent: []const u8, staging: []const u8, destination: []const u8) !void {
    if (try snapshotPathExists(io, destination)) return error.SnapshotAlreadyExists;
    if (std.fs.path.isAbsolute(destination))
        try std.Io.Dir.renameAbsolute(staging, destination, io)
    else
        try std.Io.Dir.rename(std.Io.Dir.cwd(), staging, std.Io.Dir.cwd(), destination, io);
    try fs_paths.syncDirPortable(io, parent);
}



fn repairCandidateStorageBytes(
    alloc: Allocator,
    cfg: types.IndexConfig,
    manager: *index_manager_mod.IndexManager,
    shadow_base: []const u8,
) !u64 {
    if (cfg.kind == .algebraic) return try manager.activeIndexStorageBytes(cfg.name);
    _ = alloc;
    return try manager.generationStorageBytes(shadow_base);
}

fn createUniqueRepairShadowBaseWithStorage(alloc: Allocator, base_path: []const u8, storage: ?lsm_backend_mod.Storage) ![]u8 {
    const files = storage orelse return createUniqueRepairShadowBase(alloc, base_path);
    // The random repair identity reserves a namespace without relying on host
    // directory existence or process-local counters surviving a restart.
    const identity = try index_repair_state.newRepairId(alloc);
    const candidate = try std.fmt.allocPrint(alloc, "{s}/.repair-shadow-{x}", .{ base_path, identity });
    errdefer alloc.free(candidate);
    try files.createDirPath(candidate);
    return candidate;
}

pub fn createUniqueRepairShadowBase(alloc: Allocator, base_path: []const u8) ![]u8 {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    try fs_paths.createDirPathPortable(io, base_path);

    for (0..64) |_| {
        const candidate = try std.fmt.allocPrint(alloc, "{s}/.repair-shadow-{d}-{x}", .{
            base_path,
            monotonicTimeNs(),
            repair_shadow_nonce.fetchAdd(1, .monotonic),
        });
        errdefer alloc.free(candidate);
        std.Io.Dir.cwd().createDir(io, candidate, .default_dir) catch |err| switch (err) {
            error.PathAlreadyExists => {
                alloc.free(candidate);
                continue;
            },
            else => return err,
        };
        errdefer std.Io.Dir.cwd().deleteTree(io, candidate) catch {};
        try fs_paths.syncDirPortable(io, base_path);
        return candidate;
    }
    return error.PathAlreadyExists;
}

const PortableImportStageLocation = struct {
    path: []u8,
    lease_file: std.Io.File,
};

pub fn createUniquePortableImportStageBase(alloc: Allocator, target_path: []const u8) !PortableImportStageLocation {
    if (comptime builtin.os.tag == .freestanding) return error.UnsupportedOperation;

    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    const parent = std.fs.path.dirname(target_path) orelse ".";
    const target_name = std.fs.path.basename(target_path);
    try fs_paths.createDirPathPortable(io, parent);
    scavengePortableImportStages(alloc, io, parent, target_name) catch |err| {
        // Cleanup is opportunistic and must never make a valid restore
        // unavailable. Locked/unknown entries remain untouched.
        std.log.warn("portable restore scratch scavenging failed parent={s} class={s}", .{ parent, @errorName(err) });
    };

    for (0..64) |_| {
        const candidate = try std.fmt.allocPrint(alloc, "{s}/.{s}.portable-import-{d}-{x}", .{
            parent,
            if (target_name.len == 0) "antfly" else target_name,
            monotonicTimeNs(),
            portable_import_stage_nonce.fetchAdd(1, .monotonic),
        });
        errdefer alloc.free(candidate);
        var lease_file = acquirePortableImportStageLease(alloc, candidate) catch |err| switch (err) {
            error.PathAlreadyExists => {
                alloc.free(candidate);
                continue;
            },
            else => return err,
        };
        var lease_open = true;
        var lease_owned = true;
        errdefer if (lease_owned) {
            if (lease_open) lease_file.close(io);
            deletePortableImportStageLease(alloc, io, candidate) catch {};
        };
        if (builtin.is_test and test_fail_portable_import_stage_directory_creation) {
            test_fail_portable_import_stage_directory_creation = false;
            return error.InjectedPortableImportStageDirectoryCreationFailure;
        }
        std.Io.Dir.cwd().createDir(io, candidate, .default_dir) catch |err| switch (err) {
            error.PathAlreadyExists => {
                lease_file.close(io);
                lease_open = false;
                deletePortableImportStageLease(alloc, io, candidate) catch {};
                lease_owned = false;
                alloc.free(candidate);
                continue;
            },
            else => return err,
        };
        errdefer {
            std.Io.Dir.cwd().deleteTree(io, candidate) catch {};
        }
        try fs_paths.syncDirPortable(io, parent);
        lease_open = false;
        lease_owned = false;
        return .{ .path = candidate, .lease_file = lease_file };
    }
    return error.PathAlreadyExists;
}

pub fn portableImportStageLeasePathAlloc(alloc: Allocator, stage_path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}{s}", .{ stage_path, portable_import_stage_lease_suffix });
}

pub fn acquirePortableImportStageLease(alloc: Allocator, stage_path: []const u8) !std.Io.File {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    const lease_path = try portableImportStageLeasePathAlloc(alloc, stage_path);
    defer alloc.free(lease_path);
    var file = try std.Io.Dir.cwd().createFile(io, lease_path, .{
        .read = true,
        .truncate = true,
        .exclusive = true,
        .lock = .exclusive,
        .lock_nonblocking = true,
    });
    errdefer file.close(io);
    try file.writePositionalAll(io, portable_import_stage_lease_magic, 0);
    try file.sync(io);
    return file;
}

pub fn deletePortableImportStageLease(alloc: Allocator, io: Io, stage_path: []const u8) !void {
    const lease_path = try portableImportStageLeasePathAlloc(alloc, stage_path);
    defer alloc.free(lease_path);
    std.Io.Dir.cwd().deleteFile(io, lease_path) catch |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    };
}

fn scavengePortableImportStages(
    alloc: Allocator,
    io: Io,
    parent: []const u8,
    target_name: []const u8,
) !void {
    const prefix = try std.fmt.allocPrint(alloc, ".{s}.portable-import-", .{
        if (target_name.len == 0) "antfly" else target_name,
    });
    defer alloc.free(prefix);

    var dir = try std.Io.Dir.cwd().openDir(io, parent, .{ .iterate = true });
    defer dir.close(io);
    var iterator = dir.iterateAssumeFirstIteration();
    while (try iterator.next(io)) |entry| {
        if (entry.kind != .file) continue;
        if (!std.mem.startsWith(u8, entry.name, prefix) or
            !std.mem.endsWith(u8, entry.name, portable_import_stage_lease_suffix)) continue;

        const lease_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ parent, entry.name });
        defer alloc.free(lease_path);
        var lease = std.Io.Dir.cwd().openFile(io, lease_path, .{
            .mode = .read_write,
            .lock = .exclusive,
            .lock_nonblocking = true,
        }) catch |err| switch (err) {
            // Darwin reports a contended advisory lock as AccessDenied while
            // other platforms commonly use FileBusy. Both mean the lease is
            // live and must be left alone.
            error.AccessDenied, error.FileBusy, error.WouldBlock, error.FileLocksUnsupported, error.FileNotFound => continue,
            else => return err,
        };
        var lease_open = true;
        defer if (lease_open) lease.close(io);

        const lease_stat = lease.stat(io) catch continue;
        if (lease_stat.size != portable_import_stage_lease_magic.len) continue;
        var magic: [portable_import_stage_lease_magic.len]u8 = undefined;
        _ = lease.readPositionalAll(io, &magic, 0) catch continue;
        if (!std.mem.eql(u8, &magic, portable_import_stage_lease_magic)) continue;

        const stage_name = entry.name[0 .. entry.name.len - portable_import_stage_lease_suffix.len];
        const stage_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ parent, stage_name });
        defer alloc.free(stage_path);
        // deleteTree is idempotent when the directory is absent, which also
        // covers a crash after the durable lease but before directory creation.
        try std.Io.Dir.cwd().deleteTree(io, stage_path);
        lease.close(io);
        lease_open = false;
        std.Io.Dir.cwd().deleteFile(io, lease_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };
        std.log.info("removed abandoned portable restore scratch path={s}", .{stage_path});
    }
}

fn resetPath(path: []const u8) !void {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    std.Io.Dir.cwd().deleteTree(io, path) catch {};
    try fs_paths.createDirPathPortable(io, path);
}

pub fn applyDerivedBatchToIndexAsync(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef, token: derived_executor_mod.CatchUpSessionToken) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (comptime storage_engine.enabled) return storage_engine.call(@src().fn_name, .{ ctx, batch, index_ref, token });
    if (!try batchAffectsManagedIndexForReplay(ctx.index_manager, batch, index_ref)) return false;
    if (index_ref.kind == .dense_vector and ctx.dense_admission.external_sessions.load(.acquire) != 0) {
        return error.ReplayDocumentNotVisible;
    }

    var admitted_replay = if (index_ref.kind == .dense_vector)
        try retainAsyncDenseCatchUpAdmission(ctx, index_ref.name, token)
    else
        null;
    defer if (admitted_replay) |*lease| lease.release();
    const admission = if (admitted_replay) |*lease| lease else null;

    // The executor opened the source capture in
    // beginDerivedCatchUpSessionAsync; this callback alone owns the right to
    // append to it. Foreground/enrichment callers use the non-borrowing path
    // and yield if this window is still active.
    if (benchMetricsEnabled()) {
        var profile = BatchProfile{};
        const start = monotonicTimeNs();
        try applyDerivedBatchToIndexContextProfiled(ctx, batch, index_ref, &profile, true, admission);
        profile.total_ns = monotonicTimeNs() - start;
        logDerivedWorkerProfile(index_ref, batch, profile);
    } else {
        try applyDerivedBatchToIndexContextProfiled(ctx, batch, index_ref, null, true, admission);
    }

    if (index_ref.kind == .dense_vector) {
        setDenseCatchUpProgress(ctx, .{
            .sequence = batch.sequence,
            .target_sequence = ctx.store.lastReplaySequence(0),
            .scanned_entries = 0,
            .applied_entries = 1,
            .active = true,
        });
    }
    if (index_ref.kind == .full_text) if (ctx.text_merge_runtime) |runtime| {
        runtime.notify();
    };
    if (index_ref.kind == .sparse_vector) if (ctx.sparse_compaction_runtime) |runtime| {
        runtime.notify();
    };
    return true;
}

fn installAsyncDenseCatchUpSession(ctx: *AsyncContext, index_name: []const u8, index_incarnation: u64, lease: ?index_manager_mod.IndexManager.DensePostingCaptureLease, snapshot_replay: *?snapshot_admission_mod.SnapshotAdmission.MutationLease) !derived_executor_mod.CatchUpSessionToken {
    return ctx.dense_admission.sessions.install(ctx.alloc, index_name, index_incarnation, lease, snapshot_replay);
}
fn retainAsyncDenseCatchUpAdmission(ctx: *AsyncContext, index_name: []const u8, token: derived_executor_mod.CatchUpSessionToken) !?snapshot_admission_mod.SnapshotAdmission.MutationLease {
    return ctx.dense_admission.sessions.retainAdmission(index_name, token);
}
fn takeAsyncDenseCatchUpSession(ctx: *AsyncContext, index_name: []const u8, token: derived_executor_mod.CatchUpSessionToken) !AsyncDenseCatchUpSession {
    return ctx.dense_admission.sessions.take(index_name, token);
}

fn beginDensePostingCaptureAndStreamingReplaySessionForAsyncCatchUp(
    ctx: *AsyncContext,
    index_ref: index_manager_mod.ManagedIndexRef,
) !derived_executor_mod.CatchUpSessionToken {
    // Acquire before any derived mutation and transfer the lease into the
    // opaque catch-up token. Each batch explicitly retains that token's lease,
    // closing the apply/finish gap without ambient thread ownership.
    var snapshot_replay = try acquireSnapshotReplayAsyncContext(ctx);
    defer if (snapshot_replay) |*lease| lease.release();
    var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    const capture = try ctx.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(index_ref.name, .{});
    const index_incarnation = if (capture) |lease|
        lease.index_incarnation
    else
        try ctx.index_manager.denseIndexIncarnationByName(index_ref.name);
    var capture_transferred = false;
    errdefer if (!capture_transferred) if (capture) |lease| if (lease.ownsLifecycle())
        ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
    try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
    errdefer ctx.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
    const token = try installAsyncDenseCatchUpSession(
        ctx,
        index_ref.name,
        index_incarnation,
        capture,
        &snapshot_replay,
    );
    capture_transferred = true;
    return token;
}

fn abortDenseStreamingReplaySessionForAsyncCatchUp(
    ctx: *AsyncContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    index_incarnation: u64,
) void {
    var index_apply_guard = ctx.index_manager.lockManagedIndexApply(index_ref) catch return;
    defer index_apply_guard.unlock();
    ctx.index_manager.validateDenseIndexIncarnationByName(index_ref.name, index_incarnation) catch return;
    ctx.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
}

fn beginDerivedCatchUpSessionAsync(
    ctx_ptr: *anyopaque,
    index_ref: index_manager_mod.ManagedIndexRef,
) !derived_executor_mod.CatchUpSessionToken {
    if (index_ref.kind != .dense_vector) return .{};
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));

    // Register the process-local lease under a stable catalog generation. Once
    // visible, portable publication's final emptiness check rejects the swap;
    // the lock is not held across index startup or any blocking replay work.
    {
        try lockApplySharedForPortableRuntimeAsync(ctx);
        defer ctx.apply_mutex.unlockShared();
        try beginDenseCatchUpSessionTracked(ctx, index_ref.name);
    }
    errdefer finishDenseCatchUpSessionTrackedBestEffort(ctx, index_ref.name);
    const token = try beginDensePostingCaptureAndStreamingReplaySessionForAsyncCatchUp(ctx, index_ref);
    _ = ctx.stats.dense_catch_up.begin_calls.fetchAdd(1, .monotonic);
    return token;
}

fn finishDerivedCatchUpSessionAsync(
    ctx_ptr: *anyopaque,
    index_ref: index_manager_mod.ManagedIndexRef,
    token: derived_executor_mod.CatchUpSessionToken,
    applied_sequence: u64,
    success: bool,
) !derived_executor_mod.CatchUpFinishResult {
    if (index_ref.kind != .dense_vector) return .{};
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));

    if (!success) {
        // A delayed close cannot act on a newer session. Its exact token has
        // already been retired, so even coalescer cleanup must happen only
        // after this callback proves ownership of the exact session.
        var session = takeAsyncDenseCatchUpSession(ctx, index_ref.name, token) catch return .{};
        defer ctx.alloc.free(session.index_name);
        defer if (session.snapshot_replay) |*lease| lease.release();
        defer if (session.lease) |lease| if (lease.ownsLifecycle())
            ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
        _ = ctx.stats.dense_catch_up.abort_calls.fetchAdd(1, .monotonic);
        var seq_lock = lockAtomicWithBackoffProfiled(&ctx.applied_sequence_mutex, &ctx.stats.applied_sequence_mutex);
        ctx.applied_sequence_coalescer.removePending(ctx.alloc, index_ref.name);
        seq_lock.unlock();
        var catch_up_tracked = true;
        defer if (catch_up_tracked) finishDenseCatchUpSessionTracked(ctx, index_ref.name);
        {
            var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
            defer index_apply_guard.unlock();
            ctx.index_manager.validateDenseIndexIncarnationByName(index_ref.name, session.index_incarnation) catch |err| switch (err) {
                error.PostingWalCaptureSuperseded, error.IndexNotFound => return .{},
            };
            if (session.lease) |lease| if (lease.ownsLifecycle()) {
                ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch |err| switch (err) {
                    error.PostingWalCaptureSuperseded => return .{},
                    error.ExperimentalPostingCaptureNotActive => {},
                    else => return err,
                };
                session.lease = null;
            };
            ctx.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        }
        catch_up_tracked = false;
        const lifecycle_completed = try finishDenseCatchUpSessionTrackedAndFinalize(ctx, index_ref.name);
        if (lifecycle_completed) DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
        return .{};
    }
    var session = try takeAsyncDenseCatchUpSession(ctx, index_ref.name, token);
    defer ctx.alloc.free(session.index_name);
    defer if (session.snapshot_replay) |*lease| lease.release();
    var catch_up_tracked = true;
    errdefer if (catch_up_tracked) finishDenseCatchUpSessionTrackedBestEffort(ctx, index_ref.name);
    errdefer if (session.lease) |lease| if (lease.ownsLifecycle())
        ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_ref.name, lease) catch {};
    var streaming_session_finished = false;
    errdefer if (!streaming_session_finished)
        abortDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref, session.index_incarnation);
    const finish_start_ns = monotonicTimeNs();
    const before_lsm_stats = denseLsmWriteStatsSnapshot(ctx, index_ref.name);
    const capture_advances_applied_sequence = if (session.lease) |lease|
        lease.ownsLifecycle() and applied_sequence > lease.capture.base_coverage
    else
        false;

    // Keep async dense catch-up finishes bounded and durable, but leave LSM maintenance
    // to the explicit maintenance paths instead of paying it on every replay catch-up finish.
    const maintenance_steps: usize = 0;
    const maintenance_ns: u64 = 0;
    // Dense catch-up finish needs a durable watermark for the completed dense index itself.
    // Flushing every unrelated pending index here turns one dense session close into a
    // source-wide sync storm. Leave other indexes on the normal coalesced flush path.
    setDenseCatchUpPhase(ctx, .bulk_finish);
    var finish_options = denseCatchUpFinishOptions();
    finish_options.progress_ctx = ctx;
    finish_options.progress_fn = noteDenseBulkFinishProgress;
    const finalize_start_ns = monotonicTimeNs();
    var streaming_finish_ns: u64 = 0;
    var capture_finish_ns: u64 = 0;
    var apply_lock_wait_ns: u64 = 0;
    {
        var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
        defer index_apply_guard.unlock();
        apply_lock_wait_ns = elapsedSince(finalize_start_ns);
        try ctx.index_manager.validateDenseIndexIncarnationByName(index_ref.name, session.index_incarnation);
        if (session.lease) |lease|
            try ctx.index_manager.validateDensePostingCaptureLeaseByName(index_ref.name, lease);
        const streaming_started_ns = monotonicTimeNs();
        try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, finish_options);
        streaming_finish_ns = elapsedSince(streaming_started_ns);
        streaming_session_finished = true;
        const capture_started_ns = monotonicTimeNs();
        if (session.lease) |lease| if (lease.ownsLifecycle())
            try ctx.index_manager.finishDensePostingSidecarCaptureLeaseByName(index_ref.name, lease, applied_sequence);
        capture_finish_ns = elapsedSince(capture_started_ns);
        session.lease = null;
    }
    const finalize_ns = elapsedSince(finalize_start_ns);
    if (@import("../dense_perf_experiments.zig").enabled("ANTFLY_EXPERIMENT_REPLAY_FINALIZE")) {
        std.log.info("dense replay finalize stages index={s} sequence={d} lock_ns={d} streaming_ns={d} capture_ns={d} total_ns={d}", .{
            index_ref.name, applied_sequence, apply_lock_wait_ns, streaming_finish_ns, capture_finish_ns, finalize_ns,
        });
    }
    setDenseCatchUpPhase(ctx, .applied_sequence_flush);
    // The owned posting-WAL commit is itself the authoritative dense applied
    // watermark. Report that fact explicitly to the executor instead of
    // replaying the same boundary through the capability-free coalescer. The
    // lifecycle finalizer below remains the sole readiness/publication pass.
    const posting_applied_sequence_persisted = capture_advances_applied_sequence and
        ctx.index_manager.densePostingCoverageIncludesByName(index_ref.name, applied_sequence);
    var lifecycle_completed = false;
    const lifecycle_handoff_persisted = blk: {
        var seq_lock = lockAtomicWithBackoffProfiled(
            &ctx.applied_sequence_mutex,
            &ctx.stats.applied_sequence_mutex,
        );
        defer seq_lock.unlock();
        // The native capture commit above owns posting durability. It must
        // still hand the covered sequence to projection finalization before
        // the executor may skip its generic persistence callback. Without
        // this explicit note the finished-index flush has nothing to consume,
        // leaving a durably caught-up index stuck in rebuilding forever.
        if (posting_applied_sequence_persisted) {
            _ = ctx.stats.applied_sequence.note_calls.fetchAdd(1, .monotonic);
            _ = ctx.stats.applied_sequence.forced_flush_calls.fetchAdd(1, .monotonic);
            try ctx.applied_sequence_coalescer.note(ctx.alloc, index_ref.name, applied_sequence);
        }
        const published = try flushFinishedDenseAppliedSequenceLocked(
            ctx,
            index_ref.name,
            if (posting_applied_sequence_persisted) applied_sequence else null,
            &lifecycle_completed,
        );
        break :blk published;
    };
    const after_lsm_stats = denseLsmWriteStatsSnapshot(ctx, index_ref.name);
    const finish_ns = elapsedSince(finish_start_ns);

    _ = ctx.stats.dense_catch_up.finish_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.dense_catch_up.finish_ns.fetchAdd(finish_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_finish_ns, finish_ns);
    _ = ctx.stats.dense_catch_up.finalize_ns.fetchAdd(finalize_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_finalize_ns, finalize_ns);
    _ = ctx.stats.dense_catch_up.maintenance_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.dense_catch_up.maintenance_steps.fetchAdd(@intCast(maintenance_steps), .monotonic);
    _ = ctx.stats.dense_catch_up.maintenance_ns.fetchAdd(maintenance_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_maintenance_ns, maintenance_ns);
    var dense_window_result = resource_manager_mod.DenseReplayWindowResult{ .finish_ns = finish_ns };
    if (before_lsm_stats) |before| if (after_lsm_stats) |after| {
        const delta = denseLsmWriteStatsDelta(after, before);
        _ = ctx.stats.dense_catch_up.manifest_writes.fetchAdd(delta.manifest_writes, .monotonic);
        _ = ctx.stats.dense_catch_up.manifest_ns.fetchAdd(delta.manifest_ns, .monotonic);
        _ = ctx.stats.dense_catch_up.write_pressure_compactions.fetchAdd(delta.write_pressure_compactions, .monotonic);
        _ = ctx.stats.dense_catch_up.write_pressure_ns.fetchAdd(delta.write_pressure_ns, .monotonic);
        dense_window_result.write_pressure_compactions = delta.write_pressure_compactions;
        dense_window_result.write_pressure_ns = delta.write_pressure_ns;
    };
    if (ctx.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(dense_window_result);
    }
    catch_up_tracked = false;
    // Closing the last lease and publishing every covered generation share one
    // admission boundary, so an external bulk session cannot appear between
    // the idle observation and durable lifecycle completion.
    lifecycle_completed = try finishDenseCatchUpSessionTrackedAndFinalize(ctx, index_ref.name) or lifecycle_completed;
    if (lifecycle_completed) DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
    return .{
        .applied_sequence_persisted = posting_applied_sequence_persisted and lifecycle_handoff_persisted,
    };
}

fn storeHasReplayRecordForHintAfter(
    store: *docstore_mod.DocStore,
    hint: change_journal_mod.TargetHint,
    from_sequence: u64,
) !bool {
    const Context = struct {
        found: bool = false,

        fn handle(self: *@This(), sequence: u64, payload: []const u8) !void {
            _ = sequence;
            _ = payload;
            self.found = true;
        }
    };

    var ctx = Context{};
    const stats = store.forEachReplayLaneFrom(
        @intCast(@backingInt(hint)),
        from_sequence + 1,
        1,
        &ctx,
        Context.handle,
    ) catch |err| switch (err) {
        error.ReplayIndexUnavailable => return false,
        else => return err,
    };
    return ctx.found or stats.matched_entries != 0;
}

fn replayRangeHasManagedIndexApplicableRecord(
    ctx: *AsyncContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    from_sequence: u64,
    target_sequence: u64,
) !bool {
    const Context = struct {
        alloc: Allocator,
        index_manager: *index_manager_mod.IndexManager,
        index_ref: index_manager_mod.ManagedIndexRef,
        target_sequence: u64,
        found: bool = false,

        fn handle(self: *@This(), sequence: u64, payload: []const u8) !void {
            if (sequence > self.target_sequence) return replay_source_mod.StopReplayChunk.StopReplayChunk;
            var decoded = try change_journal_mod.decodeRecord(self.alloc, payload);
            defer decoded.deinit();
            switch (managedIndexRecordApplicability(self.index_manager, decoded.record, self.index_ref)) {
                .irrelevant => {},
                .relevant, .missing_dependency => {
                    self.found = true;
                    return replay_source_mod.StopReplayChunk.StopReplayChunk;
                },
            }
        }
    };

    var scan_ctx = Context{
        .alloc = ctx.alloc,
        .index_manager = ctx.index_manager,
        .index_ref = index_ref,
        .target_sequence = target_sequence,
    };
    _ = ctx.store.forEachReplayLaneFrom(
        @intCast(@backingInt(managedIndexReplayHint(index_ref.kind))),
        from_sequence + 1,
        0,
        &scan_ctx,
        Context.handle,
    ) catch |err| switch (err) {
        error.ReplayIndexUnavailable => return try storeHasReplayRecordForHintAfter(ctx.store, managedIndexReplayHint(index_ref.kind), from_sequence),
        replay_source_mod.StopReplayChunk.StopReplayChunk => return scan_ctx.found,
        else => return err,
    };
    return scan_ctx.found;
}

pub fn canAdvanceDerivedToTargetAsync(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, from_sequence: u64, target_sequence: u64) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    const persisted_applied = try loadManagedAppliedSequenceContext(
        ctx.alloc,
        ctx.index_manager,
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        index_ref,
    );
    if (persisted_applied >= target_sequence) {
        if (index_ref.kind == .dense_vector) clearTargetAdvanceStuck(ctx, index_ref.name);
        return true;
    }

    if (try replayRangeHasManagedIndexApplicableRecord(ctx, index_ref, from_sequence, target_sequence)) return false;
    if (!ctx.index_manager.indexLoadComplete(index_ref.name)) return false;
    if (index_ref.kind != .dense_vector) return true;

    try lockApplyForPortableRuntimeAsync(ctx);
    defer ctx.apply_mutex.unlockExclusive();

    const entry = ctx.index_manager.denseIndex(index_ref.name) orelse return true;
    if (!denseIndexIsArtifactBacked(entry)) return true;
    if (asyncContextHasActiveExternalDenseBulkWork(ctx)) return false;

    const expected_doc_count = (try denseTargetCountForIndexContextWithCoverage(ctx, index_ref.name, .materialized)) orelse {
        std.log.warn(
            "dense replay target advance deferred by unavailable materialized coverage index={s}",
            .{index_ref.name},
        );
        return false;
    };
    const active_count = entry.index.stats().active_count;
    if (denseCoverageMatchesTarget(active_count, expected_doc_count)) {
        clearTargetAdvanceStuck(ctx, index_ref.name);
        return true;
    }

    // The derived executor has no stable DB pointer: DB.open returns its
    // wrapper by value, while this AsyncContext is independently allocated and
    // stable. Record an exact-name handoff here and let the DB-owned
    // maintenance lane persist the appropriate cursor/intent after open.
    const checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_ref.name);
    try recordTargetAdvanceMaintenanceDebt(ctx, index_ref.name, .{
        .config_hash = types.indexConfigHash(entry.config),
        .generation = if (checkpoint) |value| value.generation else 0,
    });

    const now_ns = monotonicTimeNs();
    // Cheap upsert every call (unlike the cooldown-gated log below): this is
    // the only durable record of how long this index has been stuck, which
    // `runUntilIdle`'s opt-in no-progress guard needs to fail fast instead of
    // spinning on this exact deferred check indefinitely (see
    // `checkTargetAdvanceNoProgress`).
    try noteTargetAdvanceStuck(ctx, index_ref.name, now_ns, active_count, expected_doc_count);
    if (shouldLogTargetAdvanceDebt(ctx, index_ref.name, now_ns)) {
        try noteTargetAdvanceDebtLogged(ctx, index_ref.name, now_ns);
        std.log.warn(
            "dense replay target advance deferred to artifact maintenance index={s} indexed={} expected_docs={}",
            .{ index_ref.name, active_count, expected_doc_count },
        );
    }

    // This callback is a watermark proof on the replay hot path. It must stay
    // bounded and side-effect free with respect to index contents: rebuilding
    // here used to make DB.open synchronously scan and reconstruct every
    // embedding artifact before the serving owner could publish status.
    //
    // A deficit is resumable in-place publication work, owned by
    // runDenseArtifactRebuildMaintenanceWithProgress and its durable cursor.
    // A surplus is unsafe reset-class debt, owned by the durable shadow-
    // generation repair planner. Both owners publish progress and retain the
    // exact generation fences; neither belongs in target validation.
    return false;
}

pub const denseIndexIsArtifactBacked = local_mutation.denseIndexIsArtifactBacked;

/// Select the durable cardinality authority independently from artifact
/// storage. Caller-populated, one-to-many chunked, and multi-source projections
/// need the physical artifact counter. Managed projections which can produce
/// at most one vector per source document use the current incarnation's
/// outcome tuple even when vectors live in artifacts.
pub fn densePublicationTargetUsesArtifactCounter(entry: anytype) bool {
    return entry.external or entry.chunk_name != null or entry.embedding_names.len > 1;
}

pub fn denseCoverageMatchesTarget(active_count: u64, expected_count: u64) bool {
    return active_count == expected_count;
}

pub fn denseTargetCountForIndexContext(ctx: *AsyncContext, index_name: []const u8) !?u64 {
    return try denseTargetCountForIndexContextWithCoverage(ctx, index_name, .all_sources);
}

const DenseTargetCoverage = enum { all_sources, materialized };

pub var test_dense_target_after_coverage_capture: ?*const fn (*AsyncContext) anyerror!void = null;

pub fn denseTargetCountForIndexContextWithCoverage(
    ctx: *AsyncContext,
    index_name: []const u8,
    coverage: DenseTargetCoverage,
) !?u64 {
    // Inline external vectors have no generated-enrichment incarnation, while
    // one source document can produce multiple chunk-backed or multi-source
    // vectors. Their durable artifact counter remains authoritative.
    if (ctx.index_manager.denseIndex(index_name)) |entry| {
        if (densePublicationTargetUsesArtifactCounter(entry)) {
            return try DB.loadDenseArtifactTargetCounter(ctx.alloc, ctx.store, index_name);
        }
    }
    const generation = ctx.index_manager.coverageGenerationForIndex(index_name) orelse return null;
    const coverage_counts = try loadDerivedCoverageCounters(ctx.alloc, ctx.store, index_name, generation, ctx.index_manager.byte_range, ctx);
    return denseTargetCountFromCoverage(ctx, index_name, coverage, coverage_counts);
}

// Keep the explicitly pinned entry point for epoch-transition regressions.
// Production uses readManyConsistent above to avoid a full snapshot when the
// maintained range counter is present.
pub fn denseTargetCountForIndexSnapshot(ctx: *AsyncContext, index_name: []const u8, snapshot: *docstore_mod.DocStore.Txn) !?u64 {
    if (ctx.index_manager.denseIndex(index_name)) |entry| {
        if (densePublicationTargetUsesArtifactCounter(entry)) {
            return try DB.loadDenseArtifactTargetCounterFromTxn(ctx.alloc, snapshot, index_name);
        }
    }
    const generation = ctx.index_manager.coverageGenerationForIndex(index_name) orelse return null;
    var counters = try DerivedCoverageCounters.load(ctx.alloc, snapshot, index_name, generation);
    if (counters.source_total == null) {
        counters.source_total = try range_cardinality.loadOrCountFromTxn(ctx.alloc, ctx.store, snapshot, ctx.index_manager.byte_range);
    }
    return denseTargetCountFromCoverage(ctx, index_name, .all_sources, counters);
}

fn denseTargetCountFromCoverage(
    ctx: *AsyncContext,
    index_name: []const u8,
    coverage: DenseTargetCoverage,
    coverage_counts: DerivedCoverageCounters,
) !?u64 {
    const produced = coverage_counts.produced;
    const skipped = coverage_counts.skipped;
    const terminal_failed = coverage_counts.terminal_failed;
    const present_count: u2 = @as(u2, @intFromBool(produced != null)) +
        @as(u2, @intFromBool(skipped != null)) +
        @as(u2, @intFromBool(terminal_failed != null));
    if (present_count == 0) {
        // Name-scoped artifact counters predate generation-scoped outcomes and
        // remain a bootstrap fallback before a fresh incarnation processes its
        // first source. Once any outcome exists, it is the only counter fenced
        // to the current catalog generation.
        const requires_artifact_coverage = if (ctx.index_manager.get(index_name)) |cfg|
            cfg.kind == .dense_vector and try index_manager_mod.denseConfigRequiresArtifactCoverage(ctx.alloc, cfg.*)
        else if (ctx.index_manager.denseIndex(index_name)) |entry|
            denseIndexIsArtifactBacked(entry)
        else
            false;
        if (requires_artifact_coverage) {
            return try coverage_counts.artifactCount();
        }
        // A fresh generation on an empty table has no outcome rows to create
        // the counter tuple. The range-local primary cardinality distinguishes
        // that valid zero target from missing accounting on a non-empty range.
        const source_count = coverage_counts.source_total.?;
        return if (source_count == 0) 0 else null;
    }
    if (present_count != 3) return error.InvalidDerivedCoverageCounter;

    // Outcome counters are created as a complete tuple by the first processed
    // document, so tuple presence alone is not a completion proof. Keep this
    // O(1) by comparing the maintained generation outcome summary with the
    // maintained range-local primary summary. All-source certification remains
    // fail-closed until every source owned by this range has one terminal
    // outcome. The namespace-wide ordinal summary deliberately remains shared
    // across split descendants so it cannot serve as this ownership proof.
    const accounted_without_failures = std.math.add(u64, produced.?, skipped.?) catch
        return error.InvalidDerivedCoverageCounter;
    const accounted = std.math.add(u64, accounted_without_failures, terminal_failed.?) catch
        return error.InvalidDerivedCoverageCounter;
    const source_count = coverage_counts.source_total.?;
    if (accounted > source_count) return null;
    if (coverage == .all_sources and accounted != source_count) return null;
    // Replay consumes available artifacts, independently of provider work
    // that has not produced one yet. Its materialized target may advance a
    // certified generation while source coverage remains explicitly pending.
    // Initial-build/repair cutover continues to require all_sources.
    return produced.?;
}

fn denseArtifactTargetCountForIndexContext(ctx: *AsyncContext, index_name: []const u8) !u64 {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return 0;
    const expected_dims = entry.dims;

    const lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const ScanState = struct {
        alloc: Allocator,
        ctx: *AsyncContext,
        index_name: []const u8,
        expected_dims: u32,
        count: u64 = 0,

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isInternalUserKey(key)) return .@"continue";

            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
            defer artifact_ref.deinit(state.alloc);
            if (artifact_ref.kind != .embedding) return .@"continue";
            if (!state.ctx.index_manager.denseIndexConsumesEmbedding(state.index_name, artifact_ref.name)) return .@"continue";

            const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                return err;
            };
            if (dims != state.expected_dims) return .@"continue";

            state.count += 1;
            return .@"continue";
        }
    };

    var state = ScanState{
        .alloc = ctx.alloc,
        .ctx = ctx,
        .index_name = index_name,
        .expected_dims = expected_dims,
    };
    try scanStoreForRebuildContext(ctx, lower, "", .{}, &state, ScanState.scanEntry);
    return state.count;
}

fn scanStoreForRebuildContext(
    ctx: *AsyncContext,
    lower: []const u8,
    upper: []const u8,
    options: docstore_mod.DocStore.ScanOptions,
    scan_ctx: ?*anyopaque,
    callback: docstore_mod.DocStore.ScanWithContextCallback,
) !void {
    if (ctx.snapshot_read_txn) |txn| {
        return try ctx.store.scanReadTxnWithContext(txn, lower, upper, options, scan_ctx, callback);
    }
    return try ctx.store.scanWithContext(lower, upper, options, scan_ctx, callback);
}

fn freePrimaryVectorRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(types.BatchWrite)) void {
    for (writes.items) |write| {
        alloc.free(@constCast(write.key));
        alloc.free(@constCast(write.value));
    }
    writes.clearRetainingCapacity();
}

const AlgebraicRebuildSliceResult = struct {
    rebuilt: usize = 0,
    resume_key: ?[]u8 = null,

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        if (self.resume_key) |key| alloc.free(key);
        self.* = undefined;
    }

    fn complete(self: @This()) bool {
        return self.resume_key == null;
    }
};

fn rebuildAlgebraicIndexFromSnapshotSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_batch_size: usize,
    resume_key: ?[]const u8,
) !AlgebraicRebuildSliceResult {
    if (rebuild_batch_size == 0) return error.InvalidArgument;
    const upper = (try documentRangeUpperAlloc(ctx.alloc, "")) orelse return error.InvalidAppliedDataRange;
    defer ctx.alloc.free(upper);
    var lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);
    var lower_exclusive = resume_key != null;
    var rebuilt: usize = 0;
    const cooperative = ctx.repair_options.yield_check != null;

    while (true) {
        const ScanState = struct {
            alloc: Allocator,
            index_manager: *index_manager_mod.IndexManager,
            batch_size: usize,
            documents: std.ArrayListUnmanaged(derived_types.DerivedDocument) = .empty,
            resume_key: ?[]u8 = null,

            pub fn deinit(state: *@This()) void {
                for (state.documents.items) |doc| derived_types.deinitDerivedDocument(state.alloc, doc);
                state.documents.deinit(state.alloc);
                if (state.resume_key) |key| state.alloc.free(key);
            }

            fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
                const logical_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.alloc, key)) orelse
                    return .@"continue";
                errdefer state.alloc.free(logical_key);
                const cleaned_value = try state.index_manager.materializeStoredValueAlloc(state.alloc, key, value);
                errdefer state.alloc.free(cleaned_value);
                try state.documents.append(state.alloc, .{
                    .key = logical_key,
                    .cleaned_value = cleaned_value,
                });
                if (state.documents.items.len < state.batch_size) return .@"continue";
                state.resume_key = try state.alloc.dupe(u8, key);
                return .stop;
            }
        };

        var state = ScanState{
            .alloc = ctx.alloc,
            .index_manager = ctx.index_manager,
            .batch_size = rebuild_batch_size,
        };
        defer state.deinit();
        try scanStoreForRebuildContext(
            ctx,
            lower,
            upper,
            .{ .lower_exclusive = lower_exclusive },
            &state,
            ScanState.scanEntry,
        );
        if (state.documents.items.len > 0) {
            try checkAsyncRepairCancelled(ctx);
            if (ctx.repair_options.capacity_check) |check| {
                try check.current(try ctx.index_manager.activeIndexStorageBytes(index_name));
            }
            try applyDerivedBatchToIndexContext(ctx, .{
                .sequence = ctx.repair_sequence,
                .documents = state.documents.items,
            }, .{ .name = index_name, .kind = .algebraic });
            if (ctx.repair_options.capacity_check) |check| {
                // Algebraic generations materialize in the primary store, not
                // beneath the shadow marker directory. Reconcile the exact
                // transaction-maintained namespace counter after every batch.
                try check.current(try ctx.index_manager.activeIndexStorageBytes(index_name));
            }
            rebuilt += state.documents.items.len;
        }
        const next_resume_key = state.resume_key orelse break;
        if (cooperative and ctx.repair_options.yield_check.?.requested()) {
            return .{
                .rebuilt = rebuilt,
                .resume_key = try ctx.alloc.dupe(u8, next_resume_key),
            };
        }
        const next_lower = try ctx.alloc.dupe(u8, next_resume_key);
        ctx.alloc.free(lower);
        lower = next_lower;
        lower_exclusive = true;
    }
    return .{ .rebuilt = rebuilt };
}

fn flushDensePrimaryVectorRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(types.BatchWrite),
) !void {
    defer freePrimaryVectorRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.indexDenseBatchByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

const DenseRebuildSliceResult = struct {
    rebuilt: usize = 0,
    /// Owned source-store key. A non-null value means the candidate was
    /// durably closed at a cooperative yield boundary and the next pass must
    /// resume strictly after this key.
    resume_key: ?[]u8 = null,

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        if (self.resume_key) |key| alloc.free(key);
        self.* = undefined;
    }

    fn complete(self: @This()) bool {
        return self.resume_key == null;
    }
};

fn denseRepairYieldRequested(ctx: *AsyncContext) bool {
    if (ctx.repair_options.yield_check) |check| return check.requested();
    return false;
}

fn rebuildDenseIndexFromPrimaryVectorsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexFromPrimaryVectorsSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexFromPrimaryVectorsSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    const field_name = entry.field_name;
    const dims = entry.dims;
    // Primary rows and fallback vector payloads must come from one cut, even
    // for callers which do not supply the durable repair snapshot themselves.
    var owned_snapshot: ?docstore_mod.DocStore.Txn = if (ctx.snapshot_read_txn == null) try ctx.store.beginReadTxn() else null;
    defer if (owned_snapshot) |*txn| txn.abort();
    const source_read = ctx.snapshot_read_txn orelse &owned_snapshot.?;

    const lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const resumable = ctx.repair_options.yield_check != null;
    const posting_capture = try ctx.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(index_name, .{});
    var posting_capture_owned = if (posting_capture) |lease| lease.ownsLifecycle() else false;
    if (posting_capture == null and ctx.index_manager.densePostingSidecarCaptureRequiredByName(index_name))
        return error.PostingWalCaptureOwnershipConflict;
    errdefer if (posting_capture_owned) if (posting_capture) |lease|
        ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_name, lease) catch {};
    if (resumable) {
        try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_name);
    } else {
        try ctx.index_manager.beginDenseBulkIngestSessionByName(index_name);
    }
    var session_open = true;
    errdefer if (session_open) {
        if (resumable) {
            ctx.index_manager.abortDenseStreamingReplaySessionByName(index_name);
        } else {
            ctx.index_manager.abortDenseBulkIngestSessionByName(index_name);
        }
    };

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        field_name: []const u8,
        dims: u32,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(types.BatchWrite) = .empty,
        artifact_writes: std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite) = .empty,
        source_read: *docstore_mod.DocStore.Txn,
        rebuilt: usize = 0,
        scanned_since_yield_check: usize = 0,
        resume_key: ?[]u8 = null,

        pub fn deinit(state: *@This()) void {
            freePrimaryVectorRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
            DB.freeDenseArtifactRebuildWrites(state.ctx.alloc, &state.artifact_writes);
            state.artifact_writes.deinit(state.ctx.alloc);
            if (state.resume_key) |key| state.ctx.alloc.free(key);
        }

        fn flush(state: *@This()) !void {
            try flushDensePrimaryVectorRebuildChunkContext(state.ctx, state.index_name, &state.writes);
            try flushDenseArtifactRebuildChunkContext(state.ctx, state.index_name, &state.artifact_writes);
        }

        fn yieldAfter(state: *@This(), key: []const u8) !docstore_mod.DocStore.ScanAction {
            if (!denseRepairYieldRequested(state.ctx)) return .@"continue";
            try state.flush();
            state.resume_key = try state.ctx.alloc.dupe(u8, key);
            return .stop;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            state.scanned_since_yield_check += 1;
            if (!isPrimaryDocumentStoreKey(key)) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            try checkAsyncRepairCancelled(state.ctx);
            const logical_value = try state.ctx.index_manager.materializeStoredValueAlloc(state.ctx.alloc, key, value);
            defer state.ctx.alloc.free(logical_value);
            if (try mapper.extractDenseVectorField(state.ctx.alloc, logical_value, state.field_name, state.dims)) |vector| {
                state.ctx.alloc.free(vector);
            } else {
                const doc_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.ctx.alloc, key)) orelse return error.InvalidBatchRequest;
                var transferred = false;
                defer if (!transferred) state.ctx.alloc.free(doc_key);
                const artifact_key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(state.ctx.alloc, doc_key, state.index_name);
                defer state.ctx.alloc.free(artifact_key);
                const artifact = try missingAsNull(state.source_read.get(artifact_key));
                if (artifact) |raw| {
                    const vector = try enrichment_artifact_codec.decodeDenseEmbeddingAlloc(state.ctx.alloc, raw);
                    errdefer if (!transferred) state.ctx.alloc.free(vector);
                    if (vector.len != state.dims) return error.InvalidVectorDimensions;
                    const index_name_copy = try state.ctx.alloc.dupe(u8, state.index_name);
                    errdefer if (!transferred) state.ctx.alloc.free(index_name_copy);
                    try state.artifact_writes.append(state.ctx.alloc, .{ .index_name = index_name_copy, .doc_key = doc_key, .vector = vector });
                    transferred = true;
                    state.rebuilt += 1;
                    if (state.writes.items.len + state.artifact_writes.items.len >= state.rebuild_chunk_size) {
                        try state.flush();
                        state.scanned_since_yield_check = 0;
                        return try state.yieldAfter(key);
                    }
                }
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            const doc_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.ctx.alloc, key)) orelse return .@"continue";
            var write_transferred = false;
            errdefer if (!write_transferred) state.ctx.alloc.free(doc_key);
            const doc_value = try state.ctx.alloc.dupe(u8, logical_value);
            errdefer if (!write_transferred) state.ctx.alloc.free(doc_value);
            try state.writes.append(state.ctx.alloc, .{
                .key = doc_key,
                .value = doc_value,
            });
            write_transferred = true;
            state.rebuilt += 1;

            if (state.writes.items.len + state.artifact_writes.items.len >= state.rebuild_chunk_size) {
                try state.flush();
                state.scanned_since_yield_check = 0;
                return try state.yieldAfter(key);
            }
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .field_name = field_name,
        .dims = dims,
        .rebuild_chunk_size = rebuild_chunk_size,
        .source_read = source_read,
    };
    defer state.deinit();

    try ctx.store.scanReadTxnWithContext(source_read, lower, "", .{ .lower_exclusive = resume_key != null }, &state, ScanState.scanEntry);
    if (state.writes.items.len != 0 or state.artifact_writes.items.len != 0) try state.flush();

    if (resumable) {
        try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    } else {
        try ctx.index_manager.finishDenseBulkIngestSessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    }
    session_open = false;
    if (posting_capture) |lease| if (posting_capture_owned) {
        // A repair slice reads from its pinned source snapshot. Publishing the
        // process's newer live tip here would certify journal mutations the
        // candidate has not replayed yet and make its next capture reject the
        // missing prefix. One-shot rebuilds also read an owned snapshot.
        const capture_sequence = if (ctx.snapshot_read_txn != null)
            ctx.repair_sequence
        else
            try ctx.store.lastReplaySequenceFromTxn(source_read, 0);
        try ctx.index_manager.finishDensePostingSidecarCaptureLeaseByName(index_name, lease, capture_sequence);
        posting_capture_owned = false;
    };
    const owned_resume_key = state.resume_key;
    state.resume_key = null;
    return .{ .rebuilt = state.rebuilt, .resume_key = owned_resume_key };
}

fn flushDenseArtifactRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite),
) !void {
    defer DB.freeDenseArtifactRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.applyDenseEmbeddingWritesByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

fn rebuildDenseIndexFromStoredEmbeddingArtifactsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    const expected_dims = entry.dims;

    const lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const resumable = ctx.repair_options.yield_check != null;
    const posting_capture = try ctx.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(index_name, .{});
    var posting_capture_owned = if (posting_capture) |lease| lease.ownsLifecycle() else false;
    if (posting_capture == null and ctx.index_manager.densePostingSidecarCaptureRequiredByName(index_name))
        return error.PostingWalCaptureOwnershipConflict;
    errdefer if (posting_capture_owned) if (posting_capture) |lease|
        ctx.index_manager.cancelDensePostingSidecarCaptureLeaseByName(index_name, lease) catch {};
    if (resumable) {
        try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_name);
    } else {
        try ctx.index_manager.beginDenseBulkIngestSessionByName(index_name);
    }
    var session_open = true;
    errdefer if (session_open) {
        if (resumable) {
            ctx.index_manager.abortDenseStreamingReplaySessionByName(index_name);
        } else {
            ctx.index_manager.abortDenseBulkIngestSessionByName(index_name);
        }
    };

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        expected_dims: u32,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite) = .empty,
        rebuilt: usize = 0,
        scanned_since_yield_check: usize = 0,
        resume_key: ?[]u8 = null,

        pub fn deinit(state: *@This()) void {
            DB.freeDenseArtifactRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
            if (state.resume_key) |key| state.ctx.alloc.free(key);
        }

        fn flush(state: *@This()) !void {
            try flushDenseArtifactRebuildChunkContext(state.ctx, state.index_name, &state.writes);
        }

        fn yieldAfter(state: *@This(), key: []const u8) !docstore_mod.DocStore.ScanAction {
            if (!denseRepairYieldRequested(state.ctx)) return .@"continue";
            try state.flush();
            state.resume_key = try state.ctx.alloc.dupe(u8, key);
            return .stop;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            state.scanned_since_yield_check += 1;
            if (!internal_keys.isInternalUserKey(key)) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            try checkAsyncRepairCancelled(state.ctx);

            const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) {
                    if (state.scanned_since_yield_check >= 1024) {
                        state.scanned_since_yield_check = 0;
                        return try state.yieldAfter(key);
                    }
                    return .@"continue";
                }
                return err;
            };
            if (dims != state.expected_dims) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }

            const index_ref = index_manager_mod.ManagedIndexRef{ .name = state.index_name, .kind = .dense_vector };
            var identity = (try decodeEmbeddingArtifactWriteIdentityForManagedIndexAlloc(state.ctx.alloc, state.ctx.index_manager, index_ref, key)) orelse {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            };
            var write_transferred = false;
            errdefer if (!write_transferred) identity.deinit(state.ctx.alloc);

            const owned_index_name = try state.ctx.alloc.dupe(u8, state.index_name);
            errdefer if (!write_transferred) state.ctx.alloc.free(owned_index_name);
            const artifact_key = try state.ctx.alloc.dupe(u8, key);
            errdefer if (!write_transferred) state.ctx.alloc.free(artifact_key);
            try state.writes.append(state.ctx.alloc, .{
                .index_name = owned_index_name,
                .doc_key = identity.doc_key,
                .parent_doc_key = identity.parent_doc_key,
                .artifact_key = artifact_key,
                .vector = &.{},
            });
            write_transferred = true;
            state.rebuilt += 1;

            if (state.writes.items.len >= state.rebuild_chunk_size) {
                try state.flush();
                state.scanned_since_yield_check = 0;
                return try state.yieldAfter(key);
            }
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .expected_dims = expected_dims,
        .rebuild_chunk_size = rebuild_chunk_size,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, lower, "", .{ .lower_exclusive = resume_key != null }, &state, ScanState.scanEntry);
    if (state.writes.items.len > 0) try state.flush();

    if (resumable) {
        try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    } else {
        try ctx.index_manager.finishDenseBulkIngestSessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    }
    session_open = false;
    if (posting_capture) |lease| if (posting_capture_owned) {
        // Durable repair cursors are relative to the pinned source generation,
        // not the current journal tip. Later source sequences belong to the
        // explicit catch-up phase and must not be claimed by this snapshot.
        const capture_sequence = if (ctx.snapshot_read_txn != null)
            ctx.repair_sequence
        else
            ctx.store.lastReplaySequence(0);
        try ctx.index_manager.finishDensePostingSidecarCaptureLeaseByName(index_name, lease, capture_sequence);
        posting_capture_owned = false;
    };
    const owned_resume_key = state.resume_key;
    state.resume_key = null;
    return .{ .rebuilt = state.rebuilt, .resume_key = owned_resume_key };
}

pub fn rebuildDenseIndexForTargetCoverageContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexForTargetCoverageSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexForTargetCoverageSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    if (!denseIndexIsArtifactBacked(entry)) {
        return try rebuildDenseIndexFromPrimaryVectorsSliceContext(ctx, index_name, rebuild_chunk_size, resume_key);
    }
    return try rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(ctx, index_name, rebuild_chunk_size, resume_key);
}

fn flushSparseArtifactRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite),
) !void {
    defer DB.freeSparseArtifactRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.applySparseEmbeddingWritesByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

fn rebuildSparseIndexFromStoredEmbeddingArtifactsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildSparseIndexFromStoredEmbeddingArtifactsSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildSparseIndexFromStoredEmbeddingArtifactsSliceContext(ctx: *AsyncContext, index_name: []const u8, rebuild_chunk_size: usize, resume_key: ?[]const u8) !DenseRebuildSliceResult {
    const index_entry = ctx.index_manager.sparseIndex(index_name) orelse return .{};
    const lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);
    var owned_snapshot: ?docstore_mod.DocStore.Txn = if (ctx.snapshot_read_txn == null) try ctx.store.beginReadTxn() else null;
    defer if (owned_snapshot) |*txn| txn.abort();
    const source_read = ctx.snapshot_read_txn orelse &owned_snapshot.?;

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite) = .empty,
        rebuilt: usize = 0,
        source_read: *docstore_mod.DocStore.Txn,
        direct: bool,
        field_name: []const u8,
        scanned: usize = 0,
        resume_key: ?[]u8 = null,

        pub fn deinit(state: *@This()) void {
            DB.freeSparseArtifactRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
            if (state.resume_key) |key| state.ctx.alloc.free(key);
        }

        fn flush(state: *@This()) !void {
            try flushSparseArtifactRebuildChunkContext(state.ctx, state.index_name, &state.writes);
        }

        fn yieldAfter(state: *@This(), key: []const u8) !docstore_mod.DocStore.ScanAction {
            if (!denseRepairYieldRequested(state.ctx)) return .@"continue";
            try state.flush();
            // WAL durability precedes publication of the source cursor.
            const entry = state.ctx.index_manager.sparseIndex(state.index_name) orelse return error.IndexNotFound;
            try entry.index.syncReplayState();
            state.resume_key = try state.ctx.alloc.dupe(u8, key);
            return .stop;
        }

        fn primary(state: *@This(), key: []const u8, value: []const u8) !void {
            const logical = try state.ctx.index_manager.materializeStoredValueAlloc(state.ctx.alloc, key, value);
            defer state.ctx.alloc.free(logical);
            const doc = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.ctx.alloc, key)) orelse return error.InvalidBatchRequest;
            var transferred = false;
            defer if (!transferred) state.ctx.alloc.free(doc);
            var vector = try mapper.extractSparseVectorField(state.ctx.alloc, logical, state.field_name);
            if (vector == null) {
                const artifact_key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(state.ctx.alloc, doc, state.index_name);
                defer state.ctx.alloc.free(artifact_key);
                const raw = state.source_read.get(artifact_key) catch |err| switch (err) {
                    error.NotFound => return,
                    else => return err,
                };
                const decoded = try enrichment_artifact_codec.decodeSparseEmbeddingAlloc(state.ctx.alloc, raw);
                vector = .{ .indices = decoded.indices, .values = decoded.values };
            }
            defer if (!transferred) vector.?.deinit(state.ctx.alloc);
            if (vector.?.indices.len == 0) return;
            try state.writes.append(state.ctx.alloc, .{ .index_name = @constCast(state.index_name), .doc_key = doc, .indices = vector.?.indices, .values = vector.?.values });
            transferred = true;
            state.rebuilt += 1;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            state.scanned += 1;
            if (state.direct) {
                if (isPrimaryDocumentStoreKey(key)) {
                    try checkAsyncRepairCancelled(state.ctx);
                    try state.primary(key, value);
                }
                if (state.writes.items.len >= state.rebuild_chunk_size or state.scanned >= 1024) {
                    try state.flush();
                    state.scanned = 0;
                    return state.yieldAfter(key);
                }
                return .@"continue";
            }
            try state.artifact(key, value);
            if (state.writes.items.len >= state.rebuild_chunk_size or state.scanned >= 1024) {
                try state.flush();
                state.scanned = 0;
                return state.yieldAfter(key);
            }
            return .@"continue";
        }

        fn artifact(state: *@This(), key: []const u8, value: []const u8) !void {
            if (!internal_keys.isInternalUserKey(key)) return;
            try checkAsyncRepairCancelled(state.ctx);

            var sparse = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(state.ctx.alloc, value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) return;
                return err;
            };
            errdefer sparse.deinit(state.ctx.alloc);
            const index_ref = index_manager_mod.ManagedIndexRef{ .name = state.index_name, .kind = .sparse_vector };
            var identity = (try decodeEmbeddingArtifactWriteIdentityForManagedIndexAlloc(
                state.ctx.alloc,
                state.ctx.index_manager,
                index_ref,
                key,
            )) orelse {
                sparse.deinit(state.ctx.alloc);
                return;
            };
            var write_transferred = false;
            errdefer if (!write_transferred) identity.deinit(state.ctx.alloc);
            const artifact_key = try state.ctx.alloc.dupe(u8, key);
            errdefer if (!write_transferred) state.ctx.alloc.free(artifact_key);
            const indices = sparse.indices;
            sparse.indices = &.{};
            errdefer if (!write_transferred) state.ctx.alloc.free(indices);
            const values = sparse.values;
            sparse.values = &.{};
            errdefer if (!write_transferred) state.ctx.alloc.free(values);

            try state.writes.append(state.ctx.alloc, .{
                .index_name = @constCast(state.index_name),
                .doc_key = identity.doc_key,
                .artifact_key = artifact_key,
                .indices = indices,
                .values = values,
            });
            write_transferred = true;
            if (identity.parent_doc_key) |parent_doc_key| state.ctx.alloc.free(parent_doc_key);
            identity.parent_doc_key = null;
            identity.doc_key = identity.doc_key[0..0];
            state.rebuilt += 1;
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .rebuild_chunk_size = rebuild_chunk_size,
        .source_read = source_read,
        .direct = index_entry.managed_direct_field,
        .field_name = index_entry.field_name,
    };
    defer state.deinit();

    try ctx.store.scanReadTxnWithContext(source_read, lower, "", .{ .lower_exclusive = resume_key != null }, &state, ScanState.scanEntry);
    if (state.writes.items.len > 0) try state.flush();
    try index_entry.index.syncReplayState();
    const next_key = state.resume_key;
    state.resume_key = null;
    return .{ .rebuilt = state.rebuilt, .resume_key = next_key };
}

pub fn persistAppliedSequenceAsync(ctx_ptr: *anyopaque, index_name: []const u8, sequence: u64, force: bool) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (force) {
        var lifecycle_completed = false;
        const published = blk: {
            var seq_lock = lockAtomicWithBackoffProfiled(&ctx.applied_sequence_mutex, &ctx.stats.applied_sequence_mutex);
            defer seq_lock.unlock();
            _ = ctx.stats.applied_sequence.note_calls.fetchAdd(1, .monotonic);
            _ = ctx.stats.applied_sequence.forced_flush_calls.fetchAdd(1, .monotonic);
            try ctx.applied_sequence_coalescer.note(ctx.alloc, index_name, sequence);
            break :blk try flushPendingAppliedSequencesLocked(ctx, true, &lifecycle_completed);
        };
        const dense_index = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) != null;
        if (published and !dense_index) {
            DB.notifyQueryVisibilityHook(ctx, .publish_consistent);
        }
        return published;
    }
    if (!ctx.applied_sequence_mutex.tryLock()) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        return false;
    }
    errdefer ctx.applied_sequence_mutex.unlock();
    var lifecycle_completed = false;
    _ = ctx.stats.applied_sequence.note_calls.fetchAdd(1, .monotonic);
    try ctx.applied_sequence_coalescer.note(ctx.alloc, index_name, sequence);
    if (shouldDeferAppliedSequenceFlush(ctx, false)) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        ctx.applied_sequence_mutex.unlock();
        return false;
    }
    if (!ctx.applied_sequence_coalescer.shouldFlush(monotonicTimeNs())) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        ctx.applied_sequence_mutex.unlock();
        return false;
    }
    const published = try flushPendingAppliedSequencesLocked(ctx, false, &lifecycle_completed);
    ctx.applied_sequence_mutex.unlock();
    const dense_index = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) != null;
    if (published and !dense_index) {
        DB.notifyQueryVisibilityHook(ctx, .publish_consistent);
    }
    return published;
}

pub fn finalizeCoveredDenseProjectionCheckpoint(
    ctx: *AsyncContext,
    index_name: []const u8,
    applied_sequence: u64,
) !bool {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    const checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) orelse {
        session_lock.unlock();
        return false;
    };
    if (checkpoint.status != .rebuilding) {
        session_lock.unlock();
        // A clean replay checkpoint is not proof of native acceleration.
        // Finite loads must wake their maintenance owner even when no repair
        // generation is being rebuilt and no subsequent write will arrive.
        if (checkpoint.status == .clean and
            ctx.index_manager.vectorBlockProjectionRequiredForDenseIndex(index_name) and
            !ctx.index_manager.vectorBlockReadyForDenseIndexAtSequence(index_name, applied_sequence, ctx.index_manager.denseIndex(index_name).?.index.stats().active_count))
        {
            scheduleNativeProjectionMaintenance(ctx);
        }
        return false;
    }
    if (!tryClaimDenseProjectionFinalizationLocked(ctx)) {
        queueDenseProjectionFinalizationLocked(ctx, index_name, applied_sequence) catch |err| {
            session_lock.unlock();
            return err;
        };
        session_lock.unlock();
        return false;
    }
    session_lock.unlock();
    errdefer finishDenseProjectionFinalization(ctx);

    const finalized = try finalizeCoveredDenseProjectionCheckpointClaimed(ctx, index_name, applied_sequence);
    if (finalized) clearPendingDenseProjectionFinalization(ctx, index_name);
    return try drainClaimedDenseProjectionFinalizations(ctx) or finalized;
}

fn queueDenseProjectionFinalizationLocked(
    ctx: *AsyncContext,
    index_name: []const u8,
    applied_sequence: u64,
) !void {
    ctx.dense_admission.requestFinalizationLocked();
    try ctx.dense_admission.deferCheckpointLocked(ctx.alloc, index_name, applied_sequence);
}

fn pendingDenseProjectionFinalizationSequence(ctx: *AsyncContext, index_name: []const u8) u64 {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    defer session_lock.unlock();
    return ctx.dense_admission.pendingCheckpointSequenceLocked(index_name);
}

fn clearPendingDenseProjectionFinalization(ctx: *AsyncContext, index_name: []const u8) void {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    defer session_lock.unlock();
    ctx.dense_admission.clearCheckpointLocked(ctx.alloc, index_name);
}

fn finalizeCoveredDenseProjectionCheckpointClaimed(
    ctx: *AsyncContext,
    index_name: []const u8,
    applied_sequence: u64,
) !bool {
    std.log.debug(
        "dense projection stable-tip claim evaluating index={s} sequence={}",
        .{ index_name, applied_sequence },
    );
    const checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) orelse return false;
    if (checkpoint.status != .rebuilding) return false;

    std.log.debug(
        "dense projection stable-tip target lookup started index={s} sequence={}",
        .{ index_name, applied_sequence },
    );
    const expected_count = (try denseTargetCountForIndexContext(ctx, index_name)) orelse return false;
    std.log.debug(
        "dense projection stable-tip target lookup completed index={s} sequence={} vectors={}",
        .{ index_name, applied_sequence, expected_count },
    );
    const entry = ctx.index_manager.denseIndex(index_name) orelse return false;
    if (entry.index.stats().active_count != expected_count) return false;

    std.log.debug(
        "dense projection stable-tip finalization started index={s} sequence={} vectors={}",
        .{ index_name, applied_sequence, expected_count },
    );

    // Lifecycle finalizers can run under shared apply ownership from source
    // completion. They only certify a published generation; corpus staging,
    // posting repair, and builder joins belong to the online maintenance owner
    // (or an explicit isolated/full-index drain). Shared apply excludes primary
    // writes just as surely as exclusive apply during that expensive work.
    if (!ctx.index_manager.vectorBlockReadyForDenseIndexAtSequence(index_name, applied_sequence, expected_count)) {
        scheduleNativeProjectionMaintenance(ctx);
        return false;
    }

    // Snapshot encoding and native-file validation intentionally run with
    // admission open. Close it only for the stable-tip recheck and durable
    // lifecycle marker, then immediately release waiting writers.
    if (!tryBeginDenseProjectionCommit(ctx)) return false;
    defer finishDenseProjectionCommit(ctx);
    const current_checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) orelse return false;
    if (current_checkpoint.status != .rebuilding or
        current_checkpoint.applied_sequence != checkpoint.applied_sequence or
        current_checkpoint.generation != checkpoint.generation or
        current_checkpoint.config_hash != checkpoint.config_hash)
        return false;
    const current_expected_count = (try denseTargetCountForIndexContext(ctx, index_name)) orelse return false;
    const serving_count = entry.index.servingActiveCountForCheckpoint() orelse return false;
    if (current_expected_count != expected_count or
        serving_count != current_expected_count or
        entry.index.experimentalPostingDurableAppliedSequence() != applied_sequence or
        !ctx.index_manager.vectorBlockReadyForDenseIndexAtSequence(index_name, applied_sequence, current_expected_count))
        return false;

    const clean_checkpoint: apply_state.ProjectionCheckpoint = .{
        .applied_sequence = applied_sequence,
        .status = .clean,
        .generation = checkpoint.generation +| 1,
        .config_hash = checkpoint.config_hash,
        .published_count = serving_count,
    };
    try ctx.index_manager.saveDenseProjectionCheckpointMetadata(index_name, clean_checkpoint);
    try apply_state.saveProjectionCheckpointWithSidecarWithStorage(
        ctx.index_manager.generation_storage,
        ctx.alloc,
        ctx.index_manager.checkpointIo(),
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        index_name,
        clean_checkpoint,
    );
    // Stable-tip finalization can race ahead of the applied-sequence flush
    // which normally refreshes this advisory restart snapshot. Persist the
    // live cardinality at the lifecycle boundary itself so a later failed
    // open never falls back to the empty creation-time snapshot. The clean
    // projection marker remains correctness authority; status-cache failure
    // must not roll it back or fail an otherwise complete user write.
    DB.saveIndexStatusSnapshots(
        ctx.alloc,
        ctx.store,
        ctx.index_manager,
        &.{.{ .index_name = index_name, .sequence = applied_sequence }},
    ) catch |err| {
        std.log.warn("dense status snapshot persistence deferred index={s} sequence={} err={s}", .{
            index_name,
            applied_sequence,
            @errorName(err),
        });
    };
    std.log.info(
        "dense projection stable-tip finalization completed index={s} sequence={} vectors={}",
        .{ index_name, applied_sequence, expected_count },
    );
    return true;
}

/// Source callbacks only signal this independently owned maintenance lane.
/// AsyncContext and IndexManager have stable addresses even while DB.open's
/// by-value wrapper moves. The catalog read pin protects lifetime, not primary
/// write admission; no apply or mutation lock is held across file staging.
fn scheduleNativeProjectionMaintenance(ctx: *AsyncContext) void {
    const io = ctx.io orelse return;
    ctx.native_projection_owner.schedule(.{ .ptr = ctx, .io = io, .closing = &ctx.background_closing, .round = nativeProjectionRound });
}
fn nativeProjectionRound(ptr: *anyopaque) !bool {
    return nativeProjectionMaintenanceRound(@ptrCast(@alignCast(ptr)));
}
const stopNativeProjectionMaintenance = execution_resources.stopNativeProjectionMaintenance;

fn nativeProjectionMaintenanceRound(ctx: *AsyncContext) !bool {
    const manager = ctx.index_manager;
    if (!manager.tryAcquireCatalogRead()) return true;
    defer manager.releaseCatalogRead();
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    const claimed = tryClaimDenseProjectionFinalizationLocked(ctx);
    session_lock.unlock();
    if (!claimed) return true;
    defer finishDenseProjectionFinalization(ctx);
    var pending = false;
    for (manager.dense_indexes.items) |entry| {
        if (ctx.background_closing.load(.acquire)) return false;
        const checkpoint = manager.denseProjectionCheckpointMetadata(entry.config.name) orelse continue;
        if (checkpoint.status != .rebuilding and checkpoint.status != .clean) continue;
        const expected = (try denseTargetCountForIndexContextWithCoverage(
            ctx,
            entry.config.name,
            if (checkpoint.status == .clean) .materialized else .all_sources,
        )) orelse continue;
        if (entry.index.stats().active_count != expected) continue;
        const sequence = entry.index.experimentalPostingDurableAppliedSequence() orelse continue;
        if (manager.vectorBlockReadyForDenseIndexAtSequence(entry.config.name, sequence, expected) and
            checkpoint.status == .clean) continue;
        _ = try manager.publishVectorBlockBasesOnline(.{
            // Ordinary finite loads wait for a stable tip instead of building
            // a new corpus projection after each small foreground batch.
            .require_quiescence = checkpoint.status == .clean,
            .covered_rebuilding_index = entry.config.name,
            .only_index = entry.config.name,
        });
        if (!manager.vectorBlockReadyForDenseIndexAtSequence(entry.config.name, sequence, expected)) {
            pending = true;
            continue;
        }
        if (checkpoint.status == .clean) {
            DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
            continue;
        }
        const completed = blk: {
            ctx.apply_mutex.lockShared();
            defer ctx.apply_mutex.unlockShared();
            break :blk try finalizeCoveredDenseProjectionCheckpointClaimed(ctx, entry.config.name, sequence);
        };
        if (completed) {
            clearPendingDenseProjectionFinalization(ctx, entry.config.name);
            DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
        }
    }
    return pending;
}

pub fn finalizeCoveredDenseProjectionCheckpointsIfIdle(ctx: *AsyncContext) !bool {
    try lockApplySharedForPortableRuntimeAsync(ctx);
    defer ctx.apply_mutex.unlockShared();

    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    const claimed = tryClaimDenseProjectionFinalizationLocked(ctx);
    session_lock.unlock();
    if (!claimed) return false;
    errdefer finishDenseProjectionFinalization(ctx);

    return drainClaimedDenseProjectionFinalizations(ctx);
}

// The finalization owner drains requests that raced its preceding scan.
// Incomplete pending generations do not cause a busy loop: only a new request
// flips the handoff bit, and future replay/session completion requests another
// pass. Each clean-marker commit has its own short admission fence.
pub fn drainClaimedDenseProjectionFinalizations(ctx: *AsyncContext) !bool {
    var completed = false;
    while (true) {
        completed = try finalizeCoveredDenseProjectionCheckpointsClaimed(ctx) or completed;

        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        const repeat = ctx.dense_admission.completeFinalizationPassLocked();
        session_lock.unlock();
        if (!repeat) return completed;
    }
}

fn denseProjectionCheckpointNeedsFinalization(manager: *index_manager_mod.IndexManager, index_name: []const u8) bool {
    const checkpoint = manager.denseProjectionCheckpointMetadata(index_name) orelse return false;
    return checkpoint.status == .rebuilding;
}

// Requires a shared apply lease and an active finalization claim. Session
// admission remains open during scans and native-file construction; the final
// stable-tip check closes it only around clean-marker durability.
fn finalizeCoveredDenseProjectionCheckpointsClaimed(ctx: *AsyncContext) !bool {
    // Pending work is only a wake-up optimization. Remove entries whose
    // catalog generation disappeared or completed through another path so a
    // long-running process cannot retain obsolete index names indefinitely.
    {
        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        defer session_lock.unlock();
        ctx.dense_admission.pruneCheckpointsLocked(ctx.alloc, ctx.index_manager, denseProjectionCheckpointNeedsFinalization);
    }

    var completed = false;
    for (ctx.index_manager.dense_indexes.items) |*entry| {
        const index_name = entry.config.name;
        const checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) orelse {
            continue;
        };
        if (checkpoint.status != .rebuilding) continue;
        const finalized = try finalizeCoveredDenseProjectionCheckpointClaimed(
            ctx,
            index_name,
            @max(checkpoint.applied_sequence, pendingDenseProjectionFinalizationSequence(ctx, index_name)),
        );
        completed = finalized or completed;
        if (finalized) clearPendingDenseProjectionFinalization(ctx, index_name);
    }
    return completed;
}

fn flushFinishedDenseAppliedSequenceLocked(
    ctx: *AsyncContext,
    index_name: []const u8,
    posting_persisted_through: ?u64,
    lifecycle_completed: *bool,
) !bool {
    const pending = ctx.applied_sequence_coalescer.takePending(index_name) orelse return false;
    defer ctx.alloc.free(pending.owned_name);

    const flush_start_ns = monotonicTimeNs();
    const save_start_ns = monotonicTimeNs();
    var posting_publish_ns: u64 = 0;
    var projection_metadata_ns: u64 = 0;
    var checkpoint_file_ns: u64 = 0;
    var status_snapshot_ns: u64 = 0;
    // Checkpointing managed projection effects reaches into live index
    // backends. Hold a shared apply lease so concurrent persistence remains
    // parallel while catalog replacement's exclusive lease cannot retire a
    // backend underneath this durability boundary.
    const save_ns = blk: {
        try lockApplySharedForPortableRuntimeAsync(ctx);
        defer ctx.apply_mutex.unlockShared();
        const raw_update = [_]apply_state.AppliedSequenceUpdate{.{
            .index_name = pending.owned_name,
            .sequence = pending.sequence,
        }};
        const enriched_updates = try appliedSequenceUpdatesWithConfigHashes(ctx.alloc, ctx.index_manager, &raw_update);
        defer ctx.alloc.free(enriched_updates);
        const hbc_authoritative = ctx.index_manager.densePostingWalAuthoritativeByName(pending.owned_name);
        if (hbc_authoritative) {
            // The posting WAL commit footer is the dense applied watermark.
            // Persist the captured mutation and publish its immutable query
            // generation, but do not rewrite the generic checkpoint or source
            // LSM status row for every replay window.
            // The coalescer may already contain a newer sequence than the
            // capture which invoked this flush. Skip posting I/O only when
            // that exact pending boundary is known durable.
            if (posting_persisted_through == null or posting_persisted_through.? < pending.sequence) {
                const posting_started = monotonicTimeNs();
                // Applied-sequence/status work has no mutation authority. The
                // owning catch-up callback publishes its exact capture token
                // before reaching this coverage-only checkpoint.
                try ctx.index_manager.persistDensePostingSidecarByName(pending.owned_name, pending.sequence);
                posting_publish_ns +|= elapsedSince(posting_started);
            }
        } else {
            const posting_started = monotonicTimeNs();
            try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
            posting_publish_ns +|= elapsedSince(posting_started);
            const metadata_started = monotonicTimeNs();
            try savePhysicalProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
            projection_metadata_ns +|= elapsedSince(metadata_started);
            const checkpoint_started = monotonicTimeNs();
            try apply_state.saveAppliedSequencesWithCheckpointWithStorage(
                ctx.index_manager.generation_storage,
                ctx.alloc,
                ctx.index_manager.checkpointIo(),
                ctx.store,
                ctx.applied_sequence_checkpoint_path,
                enriched_updates,
            );
            checkpoint_file_ns +|= elapsedSince(checkpoint_started);
        }
        const lifecycle_completed_now = try finalizeCoveredDenseProjectionCheckpoint(ctx, pending.owned_name, pending.sequence);
        lifecycle_completed.* = lifecycle_completed_now or lifecycle_completed.*;
        if (!hbc_authoritative or lifecycle_completed_now) {
            const status_started = monotonicTimeNs();
            try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
            status_snapshot_ns +|= elapsedSince(status_started);
        }
        break :blk elapsedSince(save_start_ns);
    };

    ctx.applied_sequence_coalescer.last_flush_ns = monotonicTimeNs();
    const flush_ns = elapsedSince(flush_start_ns);
    _ = ctx.stats.applied_sequence.flush_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.flushed_indexes.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.posting_publish_ns.fetchAdd(posting_publish_ns, .monotonic);
    _ = ctx.stats.applied_sequence.projection_metadata_ns.fetchAdd(projection_metadata_ns, .monotonic);
    _ = ctx.stats.applied_sequence.checkpoint_file_ns.fetchAdd(checkpoint_file_ns, .monotonic);
    _ = ctx.stats.applied_sequence.status_snapshot_ns.fetchAdd(status_snapshot_ns, .monotonic);
    _ = ctx.stats.applied_sequence.save_ns.fetchAdd(save_ns, .monotonic);
    _ = ctx.stats.applied_sequence.flush_ns.fetchAdd(flush_ns, .monotonic);
    atomicMaxU64(&ctx.stats.applied_sequence.max_flush_ns, flush_ns);
    return true;
}

fn flushPendingAppliedSequencesLocked(
    ctx: *AsyncContext,
    force: bool,
    lifecycle_completed: *bool,
) !bool {
    if (ctx.applied_sequence_coalescer.pending.count() == 0) return false;

    const flush_start_ns = monotonicTimeNs();
    var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer updates.deinit(ctx.alloc);

    var it = ctx.applied_sequence_coalescer.pending.iterator();
    while (it.next()) |entry| {
        if (!force and shouldDeferAppliedSequenceFlush(ctx, false)) continue;
        try updates.append(ctx.alloc, .{
            .index_name = entry.key_ptr.*,
            .sequence = entry.value_ptr.*,
        });
    }
    if (updates.items.len == 0) return false;
    const enriched_updates = try appliedSequenceUpdatesWithConfigHashes(ctx.alloc, ctx.index_manager, updates.items);
    defer ctx.alloc.free(enriched_updates);
    const sync_ns: u64 = 0;
    var posting_publish_ns: u64 = 0;
    var projection_metadata_ns: u64 = 0;
    var checkpoint_file_ns: u64 = 0;
    var status_snapshot_ns: u64 = 0;

    const save_start_ns = monotonicTimeNs();
    // Keep the complete metadata/checkpoint/status transaction on one stable
    // index generation. Shared holders may proceed concurrently; index
    // replacement and teardown require the exclusive lease.
    const save_ns = blk: {
        try lockApplySharedForPortableRuntimeAsync(ctx);
        defer ctx.apply_mutex.unlockShared();
        var generic_updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
        defer generic_updates.deinit(ctx.alloc);
        try generic_updates.ensureTotalCapacity(ctx.alloc, enriched_updates.len);
        for (enriched_updates) |update| {
            if (ctx.index_manager.densePostingWalAuthoritativeByName(update.index_name)) {
                const posting_started = monotonicTimeNs();
                try ctx.index_manager.persistDensePostingSidecarByName(update.index_name, update.sequence);
                posting_publish_ns +|= elapsedSince(posting_started);
            } else {
                generic_updates.appendAssumeCapacity(update);
            }
        }
        if (generic_updates.items.len > 0) {
            const posting_started = monotonicTimeNs();
            try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
            posting_publish_ns +|= elapsedSince(posting_started);
            const metadata_started = monotonicTimeNs();
            try savePhysicalProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
            projection_metadata_ns +|= elapsedSince(metadata_started);
            const checkpoint_started = monotonicTimeNs();
            try apply_state.saveAppliedSequencesWithCheckpointWithStorage(
                ctx.index_manager.generation_storage,
                ctx.alloc,
                ctx.index_manager.checkpointIo(),
                ctx.store,
                ctx.applied_sequence_checkpoint_path,
                generic_updates.items,
            );
            checkpoint_file_ns +|= elapsedSince(checkpoint_started);
        }
        var authoritative_lifecycle_completed = false;
        for (enriched_updates) |update| {
            const completed_now = try finalizeCoveredDenseProjectionCheckpoint(ctx, update.index_name, update.sequence);
            lifecycle_completed.* = completed_now or lifecycle_completed.*;
            authoritative_lifecycle_completed = authoritative_lifecycle_completed or
                (completed_now and ctx.index_manager.densePostingWalAuthoritativeByName(update.index_name));
        }
        if (generic_updates.items.len > 0) {
            const status_started = monotonicTimeNs();
            try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, generic_updates.items);
            status_snapshot_ns +|= elapsedSince(status_started);
        }
        if (authoritative_lifecycle_completed) {
            const status_started = monotonicTimeNs();
            try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
            status_snapshot_ns +|= elapsedSince(status_started);
        }
        break :blk elapsedSince(save_start_ns);
    };
    ctx.applied_sequence_coalescer.clearPending(ctx.alloc);
    ctx.applied_sequence_coalescer.last_flush_ns = monotonicTimeNs();
    const flush_ns = elapsedSince(flush_start_ns);
    _ = ctx.stats.applied_sequence.flush_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.flushed_indexes.fetchAdd(@intCast(updates.items.len), .monotonic);
    _ = ctx.stats.applied_sequence.sync_ns.fetchAdd(sync_ns, .monotonic);
    _ = ctx.stats.applied_sequence.posting_publish_ns.fetchAdd(posting_publish_ns, .monotonic);
    _ = ctx.stats.applied_sequence.projection_metadata_ns.fetchAdd(projection_metadata_ns, .monotonic);
    _ = ctx.stats.applied_sequence.checkpoint_file_ns.fetchAdd(checkpoint_file_ns, .monotonic);
    _ = ctx.stats.applied_sequence.status_snapshot_ns.fetchAdd(status_snapshot_ns, .monotonic);
    _ = ctx.stats.applied_sequence.save_ns.fetchAdd(save_ns, .monotonic);
    _ = ctx.stats.applied_sequence.flush_ns.fetchAdd(flush_ns, .monotonic);
    atomicMaxU64(&ctx.stats.applied_sequence.max_flush_ns, flush_ns);
    return true;
}

fn engineBatch(ptr: *anyopaque, req: types.BatchRequest) !void {
    const self: *DB = @ptrCast(@alignCast(ptr));
    return try self.batch(req);
}

fn engineLookup(ptr: *anyopaque, alloc: Allocator, key: []const u8, opts: types.LookupOptions) !?types.LookupResult {
    const self: *DB = @ptrCast(@alignCast(ptr));
    return try self.lookup(alloc, key, opts);
}

fn engineScan(ptr: *anyopaque, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions) !types.ScanResult {
    const self: *DB = @ptrCast(@alignCast(ptr));
    return try self.scan(alloc, from_key, to_key, opts);
}

fn engineSearch(ptr: *anyopaque, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
    const self: *DB = @ptrCast(@alignCast(ptr));
    return try self.search(alloc, req);
}

fn engineStats(ptr: *anyopaque, alloc: Allocator) !types.DBStats {
    const self: *DB = @ptrCast(@alignCast(ptr));
    return try self.stats(alloc);
}

fn engineListIndexes(ptr: *anyopaque, alloc: Allocator) ![]types.IndexConfig {
