test "generated document embeddings batch across rows and memoize retry work" {
    const alloc = std.testing.allocator;
    const BatchProbe = struct {
        deterministic: embedder_mod.DeterministicDenseEmbedder = .{},
        batch_calls: usize = 0,
        items: usize = 0,

        fn embedDense(_: *anyopaque, _: Allocator, _: []const u8, _: []const u8, _: u32) ![]f32 {
            return error.TestUnexpectedResult;
        }

        fn embedDenseBatch(
            raw: *anyopaque,
            batch_alloc: Allocator,
            embedding_name: []const u8,
            texts: []const []const u8,
            dims: u32,
        ) ![]const []const f32 {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.batch_calls += 1;
            self.items += texts.len;
            const vectors = try batch_alloc.alloc([]const f32, texts.len);
            var initialized: usize = 0;
            errdefer {
                for (vectors[0..initialized]) |vector| batch_alloc.free(@constCast(vector));
                batch_alloc.free(vectors);
            }
            for (texts, vectors) |text, *vector| {
                vector.* = try embedder_mod.DeterministicDenseEmbedder.embedDense(
                    &self.deterministic,
                    batch_alloc,
                    embedding_name,
                    text,
                    dims,
                );
                initialized += 1;
            }
            return vectors;
        }

        fn interface(self: *@This()) embedder_mod.DenseEmbedder {
            return .{
                .ptr = self,
                .dense_embed_fn = embedDense,
                .dense_embed_batch_fn = embedDenseBatch,
                .deinit_fn = null,
            };
        }
    };

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var probe = BatchProbe{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{ .owner_id = "batch-probe", .dense_embedder = probe.interface() },
    });
    defer db.close();

    var consumers_a = [_][]u8{@constCast("dense_v1")};
    var consumers_b = [_][]u8{@constCast("dense_v1")};
    var requests_a = [_]enrichment_types.GeneratedEnrichmentRequest{.{
        .kind = .dense_embedding,
        .index_name = "dense_v1",
        .embedding_name = "model_v1",
        .doc_key = "doc:a",
        .source_field = "body",
        .expected_dims = 3,
        .producer_json = "{\"model\":\"v1\"}",
        .consumer_indexes = &consumers_a,
    }};
    var requests_b = [_]enrichment_types.GeneratedEnrichmentRequest{.{
        .kind = .dense_embedding,
        .index_name = "dense_v1",
        .embedding_name = "model_v1",
        .doc_key = "doc:b",
        .source_field = "body",
        .expected_dims = 3,
        .producer_json = "{\"model\":\"v1\"}",
        .consumer_indexes = &consumers_b,
    }};
    var rows = [_]index_manager_mod.IndexManager.WritePlanSnapshot.BorrowedGeneratedRowPlan{
        .{ .alloc = alloc, .requests = &requests_a },
        .{ .alloc = alloc, .requests = &requests_b },
    };
    const plan = GeneratedBatchWritePlan{ .alloc = alloc, .rows = &rows, .initialized = rows.len };
    const writes = [_]types.BatchWrite{
        .{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" },
        .{ .key = "doc:b", .value = "{\"body\":\"beta\"}" },
    };
    const extracted = [_]mapper.ExtractedWrite{
        .{ .cleaned_value = @constCast(writes[0].value), .cleaned_value_owned = false, .graph_writes = &.{}, .mentioned_graph_indexes = &.{}, .dense_embeddings = &.{}, .sparse_embeddings = &.{} },
        .{ .cleaned_value = @constCast(writes[1].value), .cleaned_value_owned = false, .graph_writes = &.{}, .mentioned_graph_indexes = &.{}, .dense_embeddings = &.{}, .sparse_embeddings = &.{} },
    };
    var memo = GeneratedEmbeddingMemo.init(alloc);
    defer memo.deinit();
    const request = types.BatchRequest{ .writes = &writes };
    try prewarmGeneratedDenseMemo(&db, request, &extracted, .all, &plan, &memo);
    try std.testing.expectEqual(@as(usize, 1), probe.batch_calls);
    try std.testing.expectEqual(@as(usize, 2), probe.items);
    try std.testing.expectEqual(@as(usize, 2), memo.dense.count());

    // The same semantic request on an optimistic retry performs no provider IO.
    try prewarmGeneratedDenseMemo(&db, request, &extracted, .all, &plan, &memo);
    try std.testing.expectEqual(@as(usize, 1), probe.batch_calls);
}

const ValidatingChunkDenseEmbedder = struct {
    deterministic: embedder_mod.DeterministicDenseEmbedder = .{},

    fn embedDense(ptr: *anyopaque, alloc: Allocator, embedding_name: []const u8, text: []const u8, dims: u32) ![]f32 {
        const self: *ValidatingChunkDenseEmbedder = @ptrCast(@alignCast(ptr));
        return try embedder_mod.DeterministicDenseEmbedder.embedDense(&self.deterministic, alloc, embedding_name, text, dims);
    }

    fn embedDenseBatch(ptr: *anyopaque, alloc: Allocator, embedding_name: []const u8, texts: []const []const u8, dims: u32) ![]const []const f32 {
        const self: *ValidatingChunkDenseEmbedder = @ptrCast(@alignCast(ptr));
        const expected_chunks = [_][]const u8{ "abcdefgh", "ghijklmn", "mno" };
        for (texts) |text| {
            for (expected_chunks) |expected| {
                if (std.mem.eql(u8, text, expected)) break;
            } else return error.TestUnexpectedResult;
        }

        const batch = try alloc.alloc([]const f32, texts.len);
        var initialized: usize = 0;
        errdefer {
            for (batch[0..initialized]) |vector| alloc.free(@constCast(vector));
            alloc.free(batch);
        }
        for (texts, 0..) |text, i| {
            batch[i] = try embedder_mod.DeterministicDenseEmbedder.embedDense(&self.deterministic, alloc, embedding_name, text, dims);
            initialized += 1;
        }
        return batch;
    }

    fn interface(self: *ValidatingChunkDenseEmbedder) embedder_mod.DenseEmbedder {
        return .{
            .ptr = self,
            .dense_embed_fn = embedDense,
            .dense_embed_batch_fn = embedDenseBatch,
            .deinit_fn = null,
        };
    }
};

pub const ImageDecodingPartsEmbedder = struct {
    calls: usize = 0,

    fn embedDense(_: *anyopaque, _: Allocator, _: []const u8, _: []const u8, _: u32) ![]f32 {
        return error.ExpectedContentParts;
    }

    fn embedDenseParts(ptr: *anyopaque, alloc: Allocator, _: []const u8, parts: []const template_mod.ContentPart, dims: u32) ![]f32 {
        const self: *ImageDecodingPartsEmbedder = @ptrCast(@alignCast(ptr));
        self.calls += 1;
        if (dims != 3) return error.InvalidVectorDimensions;

        for (parts) |part| {
            const binary = switch (part) {
                .binary => |binary| binary,
                else => continue,
            };

            if (std.mem.eql(u8, binary.mime_type, "image/bmp")) {
                const decoded = antfly_image.bmp.decodeRgbaLimited(alloc, binary.data, antfly_image.DecodeLimits.inference_default) catch |err| switch (err) {
                    error.BmpDecodeFailed, error.UnsupportedBmpFormat, error.ImageTooLarge => return error.EmbedRequestFailed,
                    else => return err,
                };
                defer alloc.free(decoded.rgba);
                if (decoded.width == 0 or decoded.height == 0) return error.EmbedRequestFailed;
                return try dupeTestVector(alloc, &.{ 1.0, 0.0, 0.0 });
            }

            if (std.mem.eql(u8, binary.mime_type, "image/webp")) {
                const decoded = antfly_image.webp.decodeRgbaLimited(alloc, binary.data, antfly_image.DecodeLimits.inference_default) catch |err| switch (err) {
                    error.WebpDecodeFailed,
                    error.UnsupportedWebpFormat,
                    error.AnimatedWebpUnsupported,
                    error.ImageTooLarge,
                    => return error.EmbedRequestFailed,
                    else => return err,
                };
                defer alloc.free(decoded.rgba);
                return try dupeTestVector(alloc, &.{ 0.0, 1.0, 0.0 });
            }

            if (std.ascii.startsWithIgnoreCase(binary.mime_type, "image/")) return error.EmbedRequestFailed;
        }

        return error.EmbedRequestFailed;
    }

    fn dupeTestVector(alloc: Allocator, values: *const [3]f32) ![]f32 {
        const vector = try alloc.alloc(f32, 3);
        @memcpy(vector, values);
        return vector;
    }

    pub fn interface(self: *ImageDecodingPartsEmbedder) embedder_mod.DenseEmbedder {
        return .{
            .ptr = self,
            .dense_embed_fn = embedDense,
            .dense_embed_parts_fn = embedDenseParts,
            .deinit_fn = null,
        };
    }
};

