pub fn dataUriAlloc(alloc: Allocator, mime_type: []const u8, bytes: []const u8) ![]u8 {
    const encoded_len = std.base64.standard.Encoder.calcSize(bytes.len);
    const encoded = try alloc.alloc(u8, encoded_len);
    defer alloc.free(encoded);
    _ = std.base64.standard.Encoder.encode(encoded, bytes);
    return try std.fmt.allocPrint(alloc, "data:{s};base64,{s}", .{ mime_type, encoded });
}

pub const GateDenseEmbedder = struct {
    allowed_successes: std.atomic.Value(usize) = .init(1),
    successful_requests: std.atomic.Value(usize) = .init(0),
    total_requests: std.atomic.Value(usize) = .init(0),
    blocked_requests: std.atomic.Value(usize) = .init(0),
    blocked_error: anyerror = error.EmbedRateLimited,
    blocked_event: ?*std.Io.Event = null,

    pub fn containsIgnoreCase(haystack: []const u8, needle: []const u8) bool {
        if (needle.len == 0) return true;
        if (needle.len > haystack.len) return false;
        var i: usize = 0;
        while (i + needle.len <= haystack.len) : (i += 1) {
            var matched = true;
            for (needle, 0..) |needle_ch, j| {
                if (std.ascii.toLower(haystack[i + j]) != needle_ch) {
                    matched = false;
                    break;
                }
            }
            if (matched) return true;
        }
        return false;
    }

    pub fn vectorForText(text: []const u8) [3]f32 {
        if (containsIgnoreCase(text, "alpha") or containsIgnoreCase(text, "concept")) {
            return .{ 1.0, 0.0, 0.0 };
        }
        if (containsIgnoreCase(text, "beta")) {
            return .{ 0.0, 1.0, 0.0 };
        }
        if (containsIgnoreCase(text, "retrieval") or containsIgnoreCase(text, "semantic")) {
            return .{ 0.8, 0.2, 0.0 };
        }
        return .{ 0.0, 0.0, 1.0 };
    }

    pub fn embedDense(ptr: *anyopaque, alloc: Allocator, _: []const u8, text: []const u8, dims: u32) ![]f32 {
        const self: *GateDenseEmbedder = @ptrCast(@alignCast(ptr));
        _ = self.total_requests.fetchAdd(1, .monotonic);
        const previous_successes = self.successful_requests.fetchAdd(1, .acq_rel);
        if (previous_successes >= self.allowed_successes.load(.acquire)) {
            _ = self.successful_requests.fetchSub(1, .acq_rel);
            _ = self.blocked_requests.fetchAdd(1, .monotonic);
            if (self.blocked_event) |event| event.set(std.testing.io);
            return self.blocked_error;
        }
        if (dims != 3) return error.InvalidVectorDimensions;
        const vector = try alloc.alloc(f32, 3);
        const values = vectorForText(text);
        @memcpy(vector, &values);
        return vector;
    }

    pub fn interface(self: *GateDenseEmbedder) embedder_mod.DenseEmbedder {
        return .{
            .ptr = self,
            .dense_embed_fn = embedDense,
            .deinit_fn = null,
        };
    }

    pub fn allowAll(self: *GateDenseEmbedder) void {
        self.allowed_successes.store(std.math.maxInt(usize), .release);
    }

    pub fn snapshot(self: *GateDenseEmbedder) struct {
        total_requests: usize,
        blocked_requests: usize,
        successful_requests: usize,
    } {
        return .{
            .total_requests = self.total_requests.load(.acquire),
            .blocked_requests = self.blocked_requests.load(.acquire),
            .successful_requests = self.successful_requests.load(.acquire),
        };
    }
};

const SelectiveGateDenseEmbedder = struct {
    deterministic: embedder_mod.DeterministicDenseEmbedder = .{},
    blocked_embedding_name: []const u8,
    blocked: std.atomic.Value(bool) = .init(true),
    blocked_requests: std.atomic.Value(usize) = .init(0),
    successful_requests: std.atomic.Value(usize) = .init(0),

    fn embedDense(ptr: *anyopaque, alloc: Allocator, embedding_name: []const u8, text: []const u8, dims: u32) ![]f32 {
        const self: *SelectiveGateDenseEmbedder = @ptrCast(@alignCast(ptr));
        if (self.blocked.load(.acquire) and std.mem.eql(u8, embedding_name, self.blocked_embedding_name)) {
            _ = self.blocked_requests.fetchAdd(1, .monotonic);
            return error.EmbedRateLimited;
        }
        _ = self.successful_requests.fetchAdd(1, .monotonic);
        return try embedder_mod.DeterministicDenseEmbedder.embedDense(
            &self.deterministic,
            alloc,
            embedding_name,
            text,
            dims,
        );
    }

    fn interface(self: *@This()) embedder_mod.DenseEmbedder {
        return .{
            .ptr = self,
            .dense_embed_fn = embedDense,
            .deinit_fn = null,
        };
    }

    fn allowAll(self: *@This()) void {
        self.blocked.store(false, .release);
    }
};

pub const GateAssetProducer = struct {
    blocked: std.atomic.Value(bool) = .init(true),
    blocked_requests: std.atomic.Value(usize) = .init(0),
    successful_requests: std.atomic.Value(usize) = .init(0),

    pub fn produce(ptr: *anyopaque, alloc: Allocator, request: asset_producer_mod.Request) ![]u8 {
        const self: *GateAssetProducer = @ptrCast(@alignCast(ptr));
        if (self.blocked.load(.acquire)) {
            _ = self.blocked_requests.fetchAdd(1, .monotonic);
            return error.EmbedRateLimited;
        }
        _ = self.successful_requests.fetchAdd(1, .monotonic);
        return try std.fmt.allocPrint(alloc, "asset:{s}", .{request.source_text});
    }

    pub fn interface(self: *@This()) asset_producer_mod.Producer {
        return .{
            .ptr = self,
            .vtable = &.{
                .produce = produce,
                .invocation_memory_for_requests = invocationMemory,
            },
        };
    }

    pub fn invocationMemory(
        _: *anyopaque,
        _: Allocator,
        _: []const asset_producer_mod.Request,
    ) !inference_work.InvocationMemoryPlan {
        return .{
            .attachment_transport = .borrowed_binary,
            .fixed_bytes = 8 << 20,
            .allocator_limit_bytes = 8 << 20,
            .max_result_bytes_per_item = 4 << 20,
            .max_result_bytes = 4 << 20,
        };
    }

    pub fn allowAll(self: *@This()) void {
        self.blocked.store(false, .release);
    }
};

/// An asset producer whose `produce` call parks on `allowed` until the test
/// explicitly releases it, tracking whether a call has started and whether
/// it has returned. Used to prove cross-quantum lane pipelining: dispatching
/// a later quantum (of either lane) must not depend on this call returning.
const SlowGatedAssetProducer = struct {
    allowed: std.atomic.Value(bool) = .init(false),
    calls: std.atomic.Value(usize) = .init(0),
    started: std.atomic.Value(bool) = .init(false),
    finished: std.atomic.Value(bool) = .init(false),

    fn produce(ptr: *anyopaque, alloc: Allocator, request: asset_producer_mod.Request) ![]u8 {
        const self: *SlowGatedAssetProducer = @ptrCast(@alignCast(ptr));
        self.started.store(true, .release);
        _ = self.calls.fetchAdd(1, .monotonic);
        while (!self.allowed.load(.acquire)) sleepNs(2 * std.time.ns_per_ms);
        const out = try std.fmt.allocPrint(alloc, "asset:{s}", .{request.source_text});
        self.finished.store(true, .release);
        return out;
    }

    fn interface(self: *@This()) asset_producer_mod.Producer {
        return .{ .ptr = self, .vtable = &.{
            .produce = produce,
            .invocation_memory_for_requests = GateAssetProducer.invocationMemory,
        } };
    }

    fn allow(self: *@This()) void {
        self.allowed.store(true, .release);
    }
};

pub const CountingSparseEmbedder = struct {
    deterministic: embedder_mod.DeterministicSparseEmbedder = .{},
    calls: usize = 0,

    fn embedSparse(ptr: *anyopaque, alloc: Allocator, embedding_name: []const u8, text: []const u8) !embedder_mod.SparseEmbedding {
        const self: *CountingSparseEmbedder = @ptrCast(@alignCast(ptr));
        self.calls += 1;
        return try embedder_mod.DeterministicSparseEmbedder.embedSparse(&self.deterministic, alloc, embedding_name, text);
    }

    pub fn interface(self: *CountingSparseEmbedder) embedder_mod.SparseEmbedder {
        return .{
            .ptr = self,
            .sparse_embed_fn = embedSparse,
            .deinit_fn = null,
        };
    }
};

pub const GateSparseEmbedder = struct {
    deterministic: embedder_mod.DeterministicSparseEmbedder = .{},
    allowed_successes: std.atomic.Value(usize) = .init(0),
    successful_requests: std.atomic.Value(usize) = .init(0),
    blocked_requests: std.atomic.Value(usize) = .init(0),
    blocked_error: anyerror = error.ResourceTemporarilyUnavailable,

    fn embedSparse(ptr: *anyopaque, alloc: Allocator, embedding_name: []const u8, text: []const u8) !embedder_mod.SparseEmbedding {
        const self: *GateSparseEmbedder = @ptrCast(@alignCast(ptr));
        const previous_successes = self.successful_requests.fetchAdd(1, .acq_rel);
        if (previous_successes >= self.allowed_successes.load(.acquire)) {
            _ = self.successful_requests.fetchSub(1, .acq_rel);
            _ = self.blocked_requests.fetchAdd(1, .monotonic);
            return self.blocked_error;
        }
        return try embedder_mod.DeterministicSparseEmbedder.embedSparse(&self.deterministic, alloc, embedding_name, text);
    }

    pub fn interface(self: *GateSparseEmbedder) embedder_mod.SparseEmbedder {
        return .{
            .ptr = self,
            .sparse_embed_fn = embedSparse,
            .deinit_fn = null,
        };
    }

    pub fn allowAll(self: *GateSparseEmbedder) void {
        self.allowed_successes.store(std.math.maxInt(usize), .release);
    }
};

const DbSplitSimAction = db_split_sim_fixture.Action;
const DbSplitSimDocSpec = db_split_sim_fixture.DocSpec;
pub const VoprSplitAction = DbSplitSimAction;
pub const db_split_sim_index_name = "ft_v1";
pub const db_split_sim_split_key = "doc:m";

const DbSplitTerm = enum {
    alpha,
    beta,
    gamma,
};

pub const VoprSplitSummary = struct {
    source_doc_count: u32 = 0,
    dest_doc_count: u32 = 0,
    source_alpha_hits: u32 = 0,
    source_beta_hits: u32 = 0,
    source_gamma_hits: u32 = 0,
    dest_alpha_hits: u32 = 0,
    dest_beta_hits: u32 = 0,
    dest_gamma_hits: u32 = 0,
};
const DbSplitSimSummary = VoprSplitSummary;

const DbSplitExpectedDoc = struct {
    side: enum { source, dest },
    term: DbSplitTerm,
};

const DbSplitOwnedWrite = struct {
    key: []u8,
    value: []u8,
    term: DbSplitTerm,

    pub fn deinit(self: *DbSplitOwnedWrite, alloc: Allocator) void {
        alloc.free(self.key);
        alloc.free(self.value);
        self.* = undefined;
    }
};

pub const DbSplitSimRuntime = struct {
    alloc: Allocator,
    source_path: [*:0]const u8,
    dest_path: [*:0]const u8,
    open_options: OpenOptions,
    source_db: ?DB,
    dest_db: ?DB,
    split_complete: bool,

    pub fn init(alloc: Allocator, source_path: [*:0]const u8, dest_path: [*:0]const u8) !DbSplitSimRuntime {
        return try initWithOptions(alloc, source_path, dest_path, .{});
    }

    fn initWithOptions(
        alloc: Allocator,
        source_path: [*:0]const u8,
        dest_path: [*:0]const u8,
        open_options: OpenOptions,
    ) !DbSplitSimRuntime {
        var runtime = DbSplitSimRuntime{
            .alloc = alloc,
            .source_path = source_path,
            .dest_path = dest_path,
            .open_options = open_options,
            .source_db = try DB.open(alloc, std.mem.span(source_path), open_options),
            .dest_db = null,
            .split_complete = false,
        };
        errdefer if (runtime.source_db) |*db| db.close();

        try ensureDbSplitSimIndexDir(alloc, std.mem.span(source_path));
        try runtime.source_db.?.addIndex(.{
            .name = db_split_sim_index_name,
            .kind = .full_text,
            .config_json = "{\"field\":\"title\"}",
        });
        return runtime;
    }

    pub fn deinit(self: *DbSplitSimRuntime) void {
        if (self.dest_db) |*db| {
            db.close();
            self.dest_db = null;
        }
        if (self.source_db) |*db| {
            db.close();
            self.source_db = null;
        }
        self.* = undefined;
    }

    pub fn reopenSource(self: *DbSplitSimRuntime) !void {
        if (self.source_db) |*db| {
            db.close();
            self.source_db = null;
        }
        self.source_db = try DB.open(self.alloc, std.mem.span(self.source_path), self.open_options);
    }

    pub fn reopenDest(self: *DbSplitSimRuntime) !void {
        if (!self.split_complete) return error.InvalidFixture;
        if (self.dest_db) |*db| {
            db.close();
            self.dest_db = null;
        }
        self.dest_db = try DB.open(self.alloc, std.mem.span(self.dest_path), self.open_options);
    }

    fn splitFull(self: *DbSplitSimRuntime) !void {
        if (self.split_complete) return error.InvalidFixture;
        try self.source_db.?.split(self.source_db.?.getRange(), db_split_sim_split_key, "", std.mem.span(self.dest_path), false);
        try ensureDbSplitSimIndexDir(self.alloc, std.mem.span(self.dest_path));
        self.dest_db = try DB.open(self.alloc, std.mem.span(self.dest_path), self.open_options);
        self.split_complete = true;
    }

    pub fn applyAction(self: *DbSplitSimRuntime, action: DbSplitSimAction, step: usize) !void {
        switch (action) {
            .reopen_source => try self.reopenSource(),
            .reopen_dest => try self.reopenDest(),
            .split_full => try self.splitFull(),
            .add_doc => |spec| try self.applyWrite(spec, step),
        }
    }

    fn applyWrite(self: *DbSplitSimRuntime, spec: DbSplitSimDocSpec, step: usize) !void {
        const writes = try buildDbSplitWrites(self.alloc, spec, step);
        defer {
            for (writes) |*write| write.deinit(self.alloc);
            self.alloc.free(writes);
        }

        if (!self.split_complete) {
            try applyDbSplitWritesToDb(self.alloc, &self.source_db.?, writes);
            return;
        }

        var source_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer source_writes.deinit(self.alloc);
        var dest_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer dest_writes.deinit(self.alloc);

        for (writes) |write| {
            if (std.mem.order(u8, write.key, db_split_sim_split_key) == .lt) {
                try source_writes.append(self.alloc, .{ .key = write.key, .value = write.value });
            } else {
                try dest_writes.append(self.alloc, .{ .key = write.key, .value = write.value });
            }
        }

        if (source_writes.items.len != 0) try self.source_db.?.batch(.{
            .writes = source_writes.items,
            .sync_level = .full_text,
        });
        if (dest_writes.items.len != 0) try self.dest_db.?.batch(.{
            .writes = dest_writes.items,
            .sync_level = .full_text,
        });
    }

    pub fn summary(self: *DbSplitSimRuntime, alloc: Allocator) !DbSplitSimSummary {
        return try summarizeDbSplitDatabases(alloc, &self.source_db.?, if (self.dest_db) |*db| db else null);
    }
};

/// Live DB split seam for the common VOPR adapter. The harness owns the real
/// DBs and their shared ModeledDevice; the adapter owns exploration policy.
pub const VoprSplitHarness = struct {
    alloc: Allocator,
    source_directory: TestDirectory,
    dest_directory: TestDirectory,
    source_path: [*:0]const u8,
    dest_path: [*:0]const u8,
    modeled_device: storage_sim.ModeledDevice,
    open_options: OpenOptions,
    runtime: DbSplitSimRuntime,
    runtime_open: bool,
    actions: std.ArrayListUnmanaged(VoprSplitAction) = .empty,
    recovered_summary: VoprSplitSummary = .{},
    recovered: bool = false,

    pub fn init(alloc: Allocator) !*VoprSplitHarness {
        const self = try alloc.create(VoprSplitHarness);
        errdefer alloc.destroy(self);
        self.alloc = alloc;
        self.source_directory = try TestDirectory.init("source");
        errdefer self.source_directory.cleanup();
        self.dest_directory = try TestDirectory.init("destination");
        errdefer self.dest_directory.cleanup();
        self.source_path = self.source_directory.path().ptr;
        self.dest_path = self.dest_directory.path().ptr;
        try ensureDirPath(std.mem.span(self.source_path));
        try ensureDirPath(std.mem.span(self.dest_path));
        self.modeled_device = storage_sim.ModeledDevice.init(alloc);
        errdefer self.modeled_device.deinit();
        try prepareModeledDbSplitRoot(&self.modeled_device, std.mem.span(self.source_path));
        try prepareModeledDbSplitRoot(&self.modeled_device, std.mem.span(self.dest_path));
        self.open_options = dbSplitModeledOpenOptions(&self.modeled_device);
        self.runtime = try DbSplitSimRuntime.initWithOptions(alloc, self.source_path, self.dest_path, self.open_options);
        self.runtime_open = true;
        self.actions = .empty;
        self.recovered_summary = .{};
        self.recovered = false;
        return self;
    }

    pub fn deinit(self: *VoprSplitHarness) void {
        if (self.runtime_open) self.runtime.deinit();
        self.actions.deinit(self.alloc);
        self.modeled_device.deinit();
        self.source_directory.cleanup();
        self.dest_directory.cleanup();
        const alloc = self.alloc;
        self.* = undefined;
        alloc.destroy(self);
    }

    pub fn apply(self: *VoprSplitHarness, action: VoprSplitAction) !void {
        try self.runtime.applyAction(action, self.actions.items.len);
        try self.actions.append(self.alloc, action);
    }

    pub fn crashAndRecover(self: *VoprSplitHarness) !void {
        self.runtime.deinit();
        self.runtime_open = false;
        try self.modeled_device.device().crash();
        self.recovered_summary = try summarizeDbSplitPathsWithOptions(
            self.alloc,
            self.source_path,
            self.dest_path,
            self.open_options,
        );
        self.recovered = true;
    }

    pub fn summary(self: *VoprSplitHarness) !VoprSplitSummary {
        return if (self.recovered) self.recovered_summary else self.runtime.summary(self.alloc);
    }

    pub fn expected(self: *const VoprSplitHarness) !VoprSplitSummary {
        return expectedDbSplitSummaryAlloc(self.alloc, self.actions.items);
    }

    pub fn splitComplete(self: *const VoprSplitHarness) bool {
        return if (self.recovered) true else self.runtime.split_complete;
    }
};

fn summarizeDbSplitDatabases(alloc: Allocator, source_db: *DB, dest_db: ?*DB) !DbSplitSimSummary {
    const source_text = source_db.core.textIndex(db_split_sim_index_name).?;
    const source_snapshot = source_text.snapshot();
    const dest_snapshot = if (dest_db) |db|
        db.core.textIndex(db_split_sim_index_name).?.snapshot()
    else
        null;

    return .{
        .source_doc_count = source_snapshot.liveDocCount(),
        .dest_doc_count = if (dest_snapshot) |snapshot| snapshot.liveDocCount() else 0,
        .source_alpha_hits = try source_snapshot.termDocFreq(alloc, "title", "alpha"),
        .source_beta_hits = try source_snapshot.termDocFreq(alloc, "title", "beta"),
        .source_gamma_hits = try source_snapshot.termDocFreq(alloc, "title", "gamma"),
        .dest_alpha_hits = if (dest_snapshot) |snapshot| try snapshot.termDocFreq(alloc, "title", "alpha") else 0,
        .dest_beta_hits = if (dest_snapshot) |snapshot| try snapshot.termDocFreq(alloc, "title", "beta") else 0,
        .dest_gamma_hits = if (dest_snapshot) |snapshot| try snapshot.termDocFreq(alloc, "title", "gamma") else 0,
    };
}

fn applyDbSplitWritesToDb(alloc: Allocator, db: *DB, writes: []const DbSplitOwnedWrite) !void {
    var batch_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer batch_writes.deinit(alloc);
    for (writes) |write| {
        try batch_writes.append(alloc, .{
            .key = write.key,
            .value = write.value,
        });
    }
    try db.batch(.{
        .writes = batch_writes.items,
        .sync_level = .full_text,
    });
}

fn buildDbSplitWrites(alloc: Allocator, spec: DbSplitSimDocSpec, step: usize) ![]DbSplitOwnedWrite {
    var writes = std.ArrayListUnmanaged(DbSplitOwnedWrite).empty;
    errdefer {
        for (writes.items) |*write| write.deinit(alloc);
        writes.deinit(alloc);
    }

    switch (spec) {
        .left_alpha => try writes.append(alloc, try dbSplitWrite(alloc, "doc:b", step, "alpha")),
        .left_gamma => try writes.append(alloc, try dbSplitWrite(alloc, "doc:c", step, "gamma")),
        .right_beta => try writes.append(alloc, try dbSplitWrite(alloc, "doc:z", step, "beta")),
        .mixed_alpha_beta => {
            try writes.append(alloc, try dbSplitWrite(alloc, "doc:b", step, "alpha"));
            try writes.append(alloc, try dbSplitWrite(alloc, "doc:z", step, "beta"));
        },
    }

    return writes.toOwnedSlice(alloc);
}

fn dbSplitWrite(alloc: Allocator, prefix: []const u8, step: usize, term: []const u8) !DbSplitOwnedWrite {
    return .{
        .key = try std.fmt.allocPrint(alloc, "{s}:{d}", .{ prefix, step }),
        .value = try std.fmt.allocPrint(alloc, "{{\"title\":\"{s}\"}}", .{term}),
        .term = std.meta.stringToEnum(DbSplitTerm, term) orelse unreachable,
    };
}

fn expectedDbSplitSummary(actions: []const DbSplitSimAction) !DbSplitSimSummary {
    return expectedDbSplitSummaryAlloc(std.testing.allocator, actions);
}

fn expectedDbSplitSummaryAlloc(alloc: Allocator, actions: []const DbSplitSimAction) !DbSplitSimSummary {
    var docs = std.StringHashMapUnmanaged(DbSplitExpectedDoc).empty;
    defer docs.deinit(alloc);

    var split_complete = false;
    for (actions, 0..) |action, step| {
        switch (action) {
            .reopen_source, .reopen_dest => {},
            .split_full => {
                if (split_complete) return error.InvalidFixture;
                split_complete = true;
                var it = docs.iterator();
                while (it.next()) |entry| {
                    entry.value_ptr.side = if (std.mem.order(u8, entry.key_ptr.*, db_split_sim_split_key) == .lt) .source else .dest;
                }
            },
            .add_doc => |spec| {
                const writes = try buildDbSplitWrites(alloc, spec, step);
                defer {
                    for (writes) |*write| write.deinit(alloc);
                    alloc.free(writes);
                }

                for (writes) |write| {
                    const gop = try docs.getOrPut(alloc, write.key);
                    if (!gop.found_existing) {
                        gop.key_ptr.* = try alloc.dupe(u8, write.key);
                    }
                    gop.value_ptr.* = .{
                        .side = if (split_complete and std.mem.order(u8, write.key, db_split_sim_split_key) != .lt) .dest else .source,
                        .term = write.term,
                    };
                }
            },
        }
    }

    var summary = DbSplitSimSummary{};
    var it = docs.iterator();
    while (it.next()) |entry| {
        switch (entry.value_ptr.side) {
            .source => {
                summary.source_doc_count += 1;
                switch (entry.value_ptr.term) {
                    .alpha => summary.source_alpha_hits += 1,
                    .beta => summary.source_beta_hits += 1,
                    .gamma => summary.source_gamma_hits += 1,
                }
            },
            .dest => {
                summary.dest_doc_count += 1;
                switch (entry.value_ptr.term) {
                    .alpha => summary.dest_alpha_hits += 1,
                    .beta => summary.dest_beta_hits += 1,
                    .gamma => summary.dest_gamma_hits += 1,
                }
            },
        }
    }

    var cleanup_it = docs.keyIterator();
    while (cleanup_it.next()) |key| alloc.free(key.*);
    return summary;
}

fn expectDbSplitSummaryEqual(case_label: []const u8, expected: DbSplitSimSummary, actual: DbSplitSimSummary) !void {
    if (!std.meta.eql(expected, actual)) {
        std.debug.print(
            "db split summary mismatch {s}\nexpected={any}\nactual={any}\n",
            .{ case_label, expected, actual },
        );
    }
    try sim_fixture.expectFieldEqual(case_label, "source_doc_count", expected.source_doc_count, actual.source_doc_count);
    try sim_fixture.expectFieldEqual(case_label, "dest_doc_count", expected.dest_doc_count, actual.dest_doc_count);
    try sim_fixture.expectFieldEqual(case_label, "source_alpha_hits", expected.source_alpha_hits, actual.source_alpha_hits);
    try sim_fixture.expectFieldEqual(case_label, "source_beta_hits", expected.source_beta_hits, actual.source_beta_hits);
    try sim_fixture.expectFieldEqual(case_label, "source_gamma_hits", expected.source_gamma_hits, actual.source_gamma_hits);
    try sim_fixture.expectFieldEqual(case_label, "dest_alpha_hits", expected.dest_alpha_hits, actual.dest_alpha_hits);
    try sim_fixture.expectFieldEqual(case_label, "dest_beta_hits", expected.dest_beta_hits, actual.dest_beta_hits);
    try sim_fixture.expectFieldEqual(case_label, "dest_gamma_hits", expected.dest_gamma_hits, actual.dest_gamma_hits);
}

fn fixtureOptionsFromDbSplitSummary(summary: DbSplitSimSummary) db_split_sim_fixture.Options {
    return .{
        .expected_source_doc_count = summary.source_doc_count,
        .expected_dest_doc_count = summary.dest_doc_count,
        .expected_source_alpha_hits = summary.source_alpha_hits,
        .expected_source_beta_hits = summary.source_beta_hits,
        .expected_source_gamma_hits = summary.source_gamma_hits,
        .expected_dest_alpha_hits = summary.dest_alpha_hits,
        .expected_dest_beta_hits = summary.dest_beta_hits,
        .expected_dest_gamma_hits = summary.dest_gamma_hits,
    };
}

fn dbSplitReplayArtifactPath(buf: []u8, suffix: []const u8) []const u8 {
    const base = "/tmp/antfly-db-split-replay-";
    const ts = monotonicTimeNs();
    const nonce = @atomicRmw(u64, &split_replay_artifact_nonce, .Add, 1, .monotonic);
    return std.fmt.bufPrint(buf, "{s}{d}-{d}-{s}.fixture", .{ base, ts, nonce, suffix }) catch unreachable;
}

fn ensureDbSplitSimIndexDir(alloc: Allocator, db_path: []const u8) !void {
    const path = try std.fmt.allocPrint(alloc, "{s}/indexes/{s}", .{ db_path, db_split_sim_index_name });
    defer alloc.free(path);
    try ensureDirPath(path);
}

fn writeDbSplitReplayArtifactFile(path: []const u8, contents: []const u8) !void {
    var file = try std.Io.Dir.createFileAbsolute(std.testing.io, path, .{});
    defer file.close(std.testing.io);

    var file_buf: [4096]u8 = undefined;
    var writer = file.writer(std.testing.io, &file_buf);
    try writer.interface.writeAll(contents);
    try writer.end();
}

fn writeDbSplitReplayFixtureArtifact(
    alloc: Allocator,
    case_label: []const u8,
    seed: u64,
    expectation_note: []const u8,
    summary: DbSplitSimSummary,
    actions: []const DbSplitSimAction,
) !?[]u8 {
    var path_buf: [256]u8 = undefined;
    const artifact_path = dbSplitReplayArtifactPath(&path_buf, case_label);
    const path = try alloc.dupe(u8, artifact_path);
    errdefer alloc.free(path);

    const normalized = try db_split_sim_fixture.renderReplayArtifact(
        alloc,
        fixtureOptionsFromDbSplitSummary(summary),
        case_label,
        seed,
        expectation_note,
        actions,
    );
    defer alloc.free(normalized);

    try writeDbSplitReplayArtifactFile(path, normalized);
    return path;
}

fn printDbSplitAction(action: DbSplitSimAction) !void {
    const line = try db_split_sim_fixture.renderAction(std.testing.allocator, action);
    defer std.testing.allocator.free(line);
    std.debug.print("    {s}\n", .{line});
}

fn replayDbSplitActionsAtPaths(
    alloc: Allocator,
    source_path: [*:0]const u8,
    dest_path: [*:0]const u8,
    actions: []const DbSplitSimAction,
) !DbSplitSimSummary {
    return replayDbSplitActionsAtPathsWithOptions(alloc, source_path, dest_path, .{}, actions);
}

fn replayDbSplitActionsAtPathsWithOptions(
    alloc: Allocator,
    source_path: [*:0]const u8,
    dest_path: [*:0]const u8,
    open_options: OpenOptions,
    actions: []const DbSplitSimAction,
) !DbSplitSimSummary {
    var runtime = try DbSplitSimRuntime.initWithOptions(alloc, source_path, dest_path, open_options);
    defer runtime.deinit();

    for (actions, 0..) |action, step| {
        try runtime.applyAction(action, step);
    }

    if (runtime.split_complete) {
        try runtime.reopenSource();
        try runtime.source_db.?.runUntilIdle();
        try runtime.reopenDest();
        try runtime.dest_db.?.runUntilIdle();
    } else {
        try runtime.reopenSource();
        try runtime.source_db.?.runUntilIdle();
    }
    return try runtime.summary(alloc);
}

fn summarizeDbSplitPathsWithOptions(
    alloc: Allocator,
    source_path: [*:0]const u8,
    dest_path: [*:0]const u8,
    open_options: OpenOptions,
) !DbSplitSimSummary {
    var source_db = try DB.open(alloc, std.mem.span(source_path), open_options);
    defer source_db.close();
    try source_db.runUntilIdle();
    var dest_db = try DB.open(alloc, std.mem.span(dest_path), open_options);
    defer dest_db.close();
    try dest_db.runUntilIdle();
    return try summarizeDbSplitDatabases(alloc, &source_db, &dest_db);
}

fn reportReducedDbSplitSchedule(
    alloc: Allocator,
    case_label: []const u8,
    seed: u64,
    actions: []const DbSplitSimAction,
) !void {
    const Replayer = struct {
        alloc: Allocator,
        case_label: []const u8,

        pub fn replay(self: @This(), candidate: []const DbSplitSimAction) !void {
            var source_path_tmp = try TestDirectory.init("db");
            defer source_path_tmp.cleanup();
            var dest_path_tmp = try TestDirectory.init("db");
            defer dest_path_tmp.cleanup();
            const source_path = source_path_tmp.path().ptr;
            const dest_path = dest_path_tmp.path().ptr;
            defer cleanupTempDir(source_path);
            defer cleanupTempDir(dest_path);
            const actual = try replayDbSplitActionsAtPaths(self.alloc, source_path, dest_path, candidate);
            try expectDbSplitSummaryEqual(self.case_label, try expectedDbSplitSummary(candidate), actual);
        }
    };

    const reduced = try zig_lmdb.sim.reduceFailingSequence(DbSplitSimAction, alloc, actions, Replayer{
        .alloc = alloc,
        .case_label = case_label,
    });
    defer alloc.free(reduced);

    const summary = try expectedDbSplitSummary(reduced);
    const artifact_path = writeDbSplitReplayFixtureArtifact(
        alloc,
        case_label,
        seed,
        "expected DB split replay to preserve source/destination text state across full split and reopen",
        summary,
        reduced,
    ) catch |err| blk: {
        std.debug.print("failed to write db split replay artifact for {s}: {s}\n", .{ case_label, @errorName(err) });
        break :blk null;
    };
    defer if (artifact_path) |path| alloc.free(path);

    std.debug.print("reduced failing db split schedule ({d} actions):\n", .{reduced.len});
    if (artifact_path) |path| std.debug.print("replay fixture: {s}\n", .{path});
    for (reduced) |action| try printDbSplitAction(action);
}

fn randomDbSplitWriteSpec(random: std.Random) DbSplitSimDocSpec {
    return @fromBackingInt(@intCast(random.uintLessThan(u8, 4)));
}

fn buildDbSplitReplayActions(
    alloc: Allocator,
    seed: u64,
    steps: usize,
) ![]DbSplitSimAction {
    var prng = std.Random.DefaultPrng.init(seed);
    const random = prng.random();

    var actions = std.ArrayListUnmanaged(DbSplitSimAction).empty;
    errdefer actions.deinit(alloc);

    var split_complete = false;
    var saw_write = false;
    for (0..steps) |_| {
        if (!split_complete and saw_write and random.uintLessThan(u8, 6) == 0) {
            try actions.append(alloc, .split_full);
            split_complete = true;
            continue;
        }
        if (split_complete and random.uintLessThan(u8, 4) == 0) {
            try actions.append(alloc, if (random.boolean()) .reopen_source else .reopen_dest);
            continue;
        }
        if (!split_complete and random.uintLessThan(u8, 4) == 0) {
            try actions.append(alloc, .reopen_source);
            continue;
        }
        try actions.append(alloc, .{ .add_doc = randomDbSplitWriteSpec(random) });
        saw_write = true;
    }

    if (!split_complete) try actions.append(alloc, .split_full);
    return try actions.toOwnedSlice(alloc);
}

fn dbSplitModeledOpenOptions(modeled_device: *storage_sim.ModeledDevice) OpenOptions {
    return .{
        .primary_backend = .{ .lsm = .{ .flush_threshold = 1 } },
        .storage = modeled_device.storage(),
        .index_backends = .{
            .text_main_backend = .lsm,
            .text_lsm_storage = modeled_device.storage(),
            .dense_storage_backend = .lsm,
            .dense_lsm_storage = modeled_device.storage(),
            .graph_reverse_backend = .lsm,
            .graph_lsm_storage = modeled_device.storage(),
        },
    };
}

fn prepareModeledDbSplitRoot(modeled_device: *storage_sim.ModeledDevice, path: []const u8) !void {
    try ensureDirPath(path);
    // The fixture's parent already exists outside the simulated database
    // lifecycle. Represent all of its ancestors as durable before DB.open,
    // just as the model previously did implicitly for the top-level /tmp.
    const storage = modeled_device.storage();
    var parent = std.fs.path.dirname(path) orelse return;
    try storage.createDirPath(parent);
    while (std.fs.path.dirname(parent)) |ancestor| {
        try storage.syncParentAbsolute(parent);
        if (std.mem.eql(u8, parent, ancestor)) break;
        parent = ancestor;
    }
}

pub fn runDbSplitReplayCase(
    alloc: Allocator,
    case_label: []const u8,
    seed: u64,
    steps: usize,
) !void {
    const actions = try buildDbSplitReplayActions(alloc, seed, steps);
    defer alloc.free(actions);

    var source_path_tmp = try TestDirectory.init("db");
    defer source_path_tmp.cleanup();
    var dest_path_tmp = try TestDirectory.init("db");
    defer dest_path_tmp.cleanup();
    const source_path = source_path_tmp.path().ptr;
    const dest_path = dest_path_tmp.path().ptr;
    defer cleanupTempDir(source_path);
    defer cleanupTempDir(dest_path);

    const actual = replayDbSplitActionsAtPaths(alloc, source_path, dest_path, actions) catch |err| {
        reportReducedDbSplitSchedule(alloc, case_label, seed, actions) catch {};
        return err;
    };
    expectDbSplitSummaryEqual(case_label, try expectedDbSplitSummary(actions), actual) catch |err| {
        reportReducedDbSplitSchedule(alloc, case_label, seed, actions) catch {};
        return err;
    };
}

pub fn runModeledDbSplitReplayCase(
    alloc: Allocator,
    case_label: []const u8,
    seed: u64,
    steps: usize,
) !void {
    const actions = try buildDbSplitReplayActions(alloc, seed, steps);
    defer alloc.free(actions);

    var modeled_device = storage_sim.ModeledDevice.init(alloc);
    defer modeled_device.deinit();
    const open_options = dbSplitModeledOpenOptions(&modeled_device);

    var source_path_tmp = try TestDirectory.init("db");
    defer source_path_tmp.cleanup();
    var dest_path_tmp = try TestDirectory.init("db");
    defer dest_path_tmp.cleanup();
    const source_path = source_path_tmp.path().ptr;
    const dest_path = dest_path_tmp.path().ptr;
    defer cleanupTempDir(source_path);
    defer cleanupTempDir(dest_path);
    try prepareModeledDbSplitRoot(&modeled_device, std.mem.span(source_path));
    try prepareModeledDbSplitRoot(&modeled_device, std.mem.span(dest_path));

    const actual = try replayDbSplitActionsAtPathsWithOptions(
        alloc,
        source_path,
        dest_path,
        open_options,
        actions,
    );
    expectDbSplitSummaryEqual(case_label, try expectedDbSplitSummary(actions), actual) catch |err| {
        reportReducedDbSplitSchedule(alloc, case_label, seed, actions) catch {};
        return err;
    };

    try modeled_device.device().crash();
    const reopened = try summarizeDbSplitPathsWithOptions(
        alloc,
        source_path,
        dest_path,
        open_options,
    );
    try expectDbSplitSummaryEqual(case_label, actual, reopened);
}

