fn expectDbSplitFixtureExpectation(
    fixture_name: []const u8,
    opts: db_split_sim_fixture.Options,
    actual: DbSplitSimSummary,
) !void {
    if (opts.expected_source_doc_count) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_source_doc_count", expected, actual.source_doc_count);
    if (opts.expected_dest_doc_count) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_dest_doc_count", expected, actual.dest_doc_count);
    if (opts.expected_source_alpha_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_source_alpha_hits", expected, actual.source_alpha_hits);
    if (opts.expected_source_beta_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_source_beta_hits", expected, actual.source_beta_hits);
    if (opts.expected_source_gamma_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_source_gamma_hits", expected, actual.source_gamma_hits);
    if (opts.expected_dest_alpha_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_dest_alpha_hits", expected, actual.dest_alpha_hits);
    if (opts.expected_dest_beta_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_dest_beta_hits", expected, actual.dest_beta_hits);
    if (opts.expected_dest_gamma_hits) |expected| try sim_fixture.expectFieldEqual(fixture_name, "expected_dest_gamma_hits", expected, actual.dest_gamma_hits);
}

test "db match_all consumes resolved ordinal filter" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"title\":\"alpha\"}" },
            .{ .key = "doc:b", .value = "{\"title\":\"beta\"}" },
            .{ .key = "doc:c", .value = "{\"title\":\"gamma\"}" },
        },
    });

    var include = try db.resolveDocSetForIdsAlloc(alloc, &.{"doc:b"});
    errdefer include.deinit(alloc);
    switch (include) {
        .ordinals => |ordinals| {
            try std.testing.expectEqual(@as(usize, 1), ordinals.len);
            try std.testing.expectEqual(@as(doc_set.DocOrdinal, 2), ordinals[0]);
        },
        else => return error.ExpectedOrdinalDocSet,
    }

    var filter = doc_set.ResolvedDocFilter{
        .include = include,
        .exclude = .none,
    };
    include = .all;
    defer filter.deinit(alloc);

    var result = try db.search(alloc, .{
        .query = .{ .match_all = {} },
        .resolved_doc_filter = &filter,
        .limit = 10,
        .include_stored = false,
    });
    defer result.deinit();

    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), result.hits.len);
    try std.testing.expectEqualStrings("doc:b", result.hits[0].id);
}

test "db native document filters preserve paged totals across representations" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{ .name = "ft_v1", .kind = .full_text, .config_json = "{}" });
    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
    });
    try db.addIndex(.{ .name = "sp_v1", .kind = .sparse_vector, .config_json = "{\"field\":\"sparse\"}" });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha\",\"embedding\":[0,0],\"sparse\":{\"indices\":[1],\"values\":[5]}}" },
            .{ .key = "doc:b", .value = "{\"body\":\"alpha alpha\",\"embedding\":[1,0],\"sparse\":{\"indices\":[1],\"values\":[4]}}" },
            .{ .key = "doc:c", .value = "{\"body\":\"alpha alpha alpha\",\"embedding\":[2,0],\"sparse\":{\"indices\":[1],\"values\":[3]}}" },
            .{ .key = "doc:d", .value = "{\"body\":\"alpha alpha alpha alpha\",\"embedding\":[3,0],\"sparse\":{\"indices\":[1],\"values\":[2]}}" },
            .{ .key = "doc:e", .value = "{\"body\":\"alpha\",\"embedding\":[4,0],\"sparse\":{\"indices\":[1],\"values\":[1]}}" },
        },
        .sync_level = .full_index,
    });
    const ids: []const []const u8 = &.{ "doc:a", "doc:b", "doc:c", "doc:d" };
    var filter = doc_set.ResolvedDocFilter{
        .include = try db.resolveDocSetForIdsAlloc(alloc, ids),
        .exclude = .none,
    };
    defer filter.deinit(alloc);
    filter.exclude = try db.resolveDocSetForIdsAlloc(alloc, &.{"doc:d"});

    const Shape = enum { match_all, full_text, dense, sparse, primary_store };
    for (std.enums.values(Shape)) |shape| {
        if (shape == .primary_store) try std.testing.expect(try db.deleteIndex("ft_v1"));
        for ([_]types.SearchRequest{
            .{ .limit = 1 },
            .{ .limit = 1, .offset = 1 },
            .{ .limit = 10 },
            .{ .limit = 1, .offset = 10 },
            .{ .limit = 1, .count_only = true },
        }) |page| {
            // Count-only text collectors omit hit materialization. The primary
            // store and vector paths leave count-only response shaping to the API.
            if (page.count_only and shape != .match_all and shape != .full_text) continue;
            errdefer std.debug.print("shape={s} limit={d} offset={d} count_only={}\n", .{ @tagName(shape), page.limit, page.offset, page.count_only });
            var req = page;
            req.include_stored = false;
            req.query = .{ .match_all = {} };
            switch (shape) {
                .match_all, .primary_store => {},
                .full_text => req.full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
                .dense => {
                    req.index_name = "dv_v1";
                    req.dense = .{ .vector = &.{ 0, 0 }, .k = 10 };
                },
                .sparse => {
                    req.index_name = "sp_v1";
                    req.query = .{ .sparse_knn = .{ .indices = &.{1}, .values = &.{1}, .k = 10 } };
                },
            }
            req.filter_doc_ids = ids;
            req.filter_doc_ids_positive = true;
            req.exclude_doc_ids = &.{"doc:d"};
            var public = try db.search(alloc, req);
            defer public.deinit();
            req.filter_doc_ids = &.{};
            req.filter_doc_ids_positive = false;
            req.exclude_doc_ids = &.{};
            req.resolved_doc_filter = &filter;
            var ordinal = try db.search(alloc, req);
            defer ordinal.deinit();

            // Native postings alone cannot prove that uncollected matches
            // still have stored rows. Partial text windows report their
            // verified visible prefix; exhausted windows and primary/native
            // collectors retain exact totals. Filter representation must not
            // change either the count proof or the returned page.
            const partial_text_window = (shape == .match_all or shape == .full_text) and !page.count_only and
                page.offset +| page.limit < 3;
            try std.testing.expectEqual(if (partial_text_window) page.offset +| page.limit else @as(u32, 3), public.total_hits);
            try std.testing.expectEqual(if (partial_text_window) types.TotalHitsRelation.gte else .exact, public.total_hits_relation);
            try std.testing.expectEqual(public.total_hits, ordinal.total_hits);
            try std.testing.expectEqual(public.total_hits_relation, ordinal.total_hits_relation);
            const expected_page_len: usize = if (page.count_only) 0 else @min(page.limit, 3 -| page.offset);
            try std.testing.expectEqual(expected_page_len, public.hits.len);
            try std.testing.expectEqual(public.hits.len, ordinal.hits.len);
            for (public.hits, ordinal.hits) |expected, actual| {
                try std.testing.expectEqualStrings(expected.id, actual.id);
                try std.testing.expectEqual(expected.doc_ordinal, actual.doc_ordinal);
                try std.testing.expect(!std.mem.eql(u8, actual.id, "doc:d"));
                try std.testing.expect(!std.mem.eql(u8, actual.id, "doc:e"));
            }
        }
    }
}

test "db stats report engine-owned algebraic adaptive observation status" {
    const alloc = std.testing.allocator;
    const algebraic_ir = ir_mod;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    const cfg =
        \\{
        \\  "version": 1,
        \\  "table": "orders",
        \\  "schema_version": 42,
        \\  "capability_fingerprint": "cap:v1",
        \\  "capability_lifecycle_status": "stale",
        \\  "capability_change_added_fields": 1,
        \\  "capability_change_removed_fields": 2,
        \\  "capability_change_changed_type_fields": 3,
        \\  "skipped_dynamic_fields": 4,
        \\  "skipped_complex_fields": 5,
        \\  "skipped_unbounded_fields": 6,
        \\  "group_fields": [{"name":"customer","path":"customer","type":"string"},{"name":"tenant","path":"tenant","type":"string"}],
        \\  "measure_fields": [{"name":"amount","path":"amount","type":"number"}],
        \\  "adaptive": {"observe": true, "lazy_materialization": true, "min_observations": 1, "min_estimated_scan_rows_saved": 1},
        \\  "materializations": []
        \\}
    ;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
        defer db.close();

        try db.addIndex(.{
            .name = "alg",
            .kind = .algebraic,
            .config_json = cfg,
        });

        const entry = db.core.index_manager.algebraicIndex("alg").?;
        const constraints = [_]algebraic_ir.Constraint{.{ .field = "tenant", .value = "t1" }};
        entry.index.recordObservedQueryShapeWithStore(db.core.store, .{
            .kind = .terms,
            .aggregation_name = "amount_by_customer",
            .bucket_field = "customer",
            .constraints = constraints[0..],
            .metric = .{ .name = "amount", .op = .sum, .field = "amount" },
        }, "no_materialization");

        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(usize, 1), stats.indexes.len);
        try std.testing.expectEqual(@as(u64, 1), stats.indexes[0].algebraic_observed_query_shape_count);
        try std.testing.expectEqual(@as(u64, 1), stats.indexes[0].algebraic_recommendation_count);
        try std.testing.expect(stats.indexes[0].algebraic_last_observed_query_shape != null);
        try std.testing.expect(stats.indexes[0].algebraic_last_recommended_materialization != null);
        try std.testing.expect(std.mem.indexOf(u8, stats.indexes[0].algebraic_last_recommended_materialization.?, "recommendation:v1") != null);

        const materialization_states = try db.listAlgebraicMaterializationStates(alloc, "alg");
        defer types.freeAlgebraicMaterializationStates(alloc, materialization_states);
        try std.testing.expectEqual(@as(usize, 1), materialization_states.len);
        try std.testing.expectEqualStrings("alg", materialization_states[0].index_name);
        try std.testing.expectEqualStrings("recommended", materialization_states[0].lifecycle);
        try std.testing.expectEqual(@as(u64, 1), materialization_states[0].observation_count);
        try std.testing.expect(std.mem.indexOf(u8, materialization_states[0].recommendation, "recommendation:v1") != null);

        const observations = try db.listAlgebraicQueryObservations(alloc, "alg");
        defer types.freeAlgebraicQueryObservations(alloc, observations);
        try std.testing.expectEqual(@as(usize, 1), observations.len);
        try std.testing.expectEqualStrings("alg", observations[0].index_name);
        try std.testing.expectEqual(@as(u64, 1), observations[0].count);
        try std.testing.expectEqualStrings("no_materialization", observations[0].reason);
        try std.testing.expectEqualStrings("recommended", observations[0].lifecycle);
        try std.testing.expect(observations[0].recommendation != null);
