pub fn drainTestRelationalMaintenance(db: *DB) !void {
    var passes: usize = 0;
    while (try db.rebuildRelationalColumns()) {
        passes += 1;
        try std.testing.expect(passes < 200);
    }
}

pub fn seedColumnScanPlanTest(db: *DB, alloc: Allocator) !void {
    return seedColumnScanPlanRows(db, alloc, 768);
}

fn seedColumnScanPlanRows(db: *DB, alloc: Allocator, row_count: usize) !void {
    std.debug.assert(row_count >= 8 and row_count <= 768);
    try db.setSchemaJson(alloc,
        \\{"version":1,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"n":{"type":"integer"},"user-name":{"type":"string"},"payload":{"type":"json"},"embedding":{"type":"embedding"},"wide":{"type":"string"}},"additionalProperties":false}}}}
    );
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const wide = try scratch.alloc(u8, 8192);
    @memset(wide, 'x');
    const writes = try scratch.alloc(types.BatchWrite, row_count);
    for (writes, 768 - row_count..) |*write, i| write.* = .{
        .key = try std.fmt.allocPrint(scratch, "k{d:0>4}", .{i}),
        .value = try std.fmt.allocPrint(scratch, "{{\"n\":{d},\"user-name\":\"Ada\",\"payload\":{{\"items\":[{{\"id\":{d}}},{{\"id\":2}}],\"nil\":null}},\"embedding\":[1,2,3],\"wide\":\"{s}\"}}", .{ i, i, wide }),
    };
    try db.batch(.{ .writes = writes });
    try drainTestRelationalMaintenance(db);
}

pub fn testColumnarSelection(comptime physical_plan: bool) !void {
    const row_count = if (physical_plan) 768 else 32;
    var profile = @import("../test_work_profile.zig").Profile(enum { setup, columnar, primary, assertions, dense }).init();
    defer profile.report("relational-selection");
    // Keep 768 rows for physical plans: 512 changes block layout and selects
    // sequential reads instead of late materialization. The semantic matrix
    // retains boundary keys on a smaller fixture without asserting that plan.
    var allocator_state: std.heap.SafeAllocator = .init(std.heap.page_allocator, .{ .stack_trace_frames = 0 });
    defer std.debug.assert(allocator_state.deinit() == 0);
    const alloc = if (platform.env.getenvBool("ANTFLY_TEST_ALLOCATOR_TRACES")) std.testing.allocator else allocator_state.allocator();
    relational_columns.test_disable_deadline = true;
    defer relational_columns.test_disable_deadline = false;
    for ([_]PrimaryBackend{.{ .lsm = .{ .flush_threshold = 1 } }}) |backend| {
        var path_tmp = try TestDirectory.initFast("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false, .primary_backend = backend });
        defer db.close();
        try seedColumnScanPlanRows(&db, alloc, row_count);
        if (physical_plan) try std.testing.expect(db.relational_column_maintenance.blocks_written.load(.monotonic) >= 2);
        profile.mark(.setup);
        const selections = [_][]const []const u8{
            &.{},                     &.{"user-name"}, &.{ "payload.items.id", "payload.nil", "missing.name" },
            &.{"payload.items.1.id"}, &.{"-wide"},     &.{"user-*"},
            &.{ "n", "_embeddings" },
        };
        const filters = [_][]const u8{
            "{\"numeric_range\":{\"field\":\"n\",\"min\":760}}",
            "{\"term\":{\"payload.items.id\":761}}",
            "{\"term\":{\"/payload/items/0/id\":761}}",
            "{\"conjuncts\":[{\"term\":{\"embedding.1\":2}},{\"term\":{\"n\":761}}]}",
            "{\"conjuncts\":[{\"exists\":{\"field\":\"payload.nil\"}},{\"term\":{\"n\":761}}]}",
        };
        for (0..2) |dirty| {
            if (dirty != 0) try db.batch(.{ .writes = &.{
                .{ .key = "k0761", .value = "{\"n\":761,\"user-name\":\"Grace\",\"payload\":{\"items\":[{\"id\":761}],\"nil\":null},\"embedding\":[1,2,3]}" },
                .{ .key = "k0761a", .value = "{\"n\":761,\"payload\":{\"items\":[{\"id\":761}]}}" },
            }, .deletes = &.{"k0762"} });
            for (if (physical_plan) selections[0..1] else &selections) |fields| for (if (physical_plan) filters[0..1] else &filters) |filter| for ([_]u32{ 0, 2 }) |limit| {
                var stats: types.ColumnarScanStats = .{};
                var opts = types.ScanOptions{ .include_documents = true, .fields = fields, .filter_query_json = filter, .limit = limit, .columnar_stats = &stats, .include_content_hashes = true };
                var actual = try db.scan(alloc, "k0000", "k0767", opts);
                defer actual.deinit(alloc);
                profile.mark(.columnar);
                try std.testing.expect(stats.used);
                try std.testing.expectEqual(@as(u64, 1), stats.scan_plans_built);
                if (physical_plan) try std.testing.expect(stats.scan_plan_hits > 0);
                if (dirty == 0 and RelationalProjectionPlan.supports(fields, true)) try std.testing.expectEqual(@as(u64, 0), stats.primary_rows_read);
                if (physical_plan and dirty == 0 and fields.len == 0) try std.testing.expectEqual(@as(u64, actual.documents.len), stats.late_materialized_rows);
                opts.disable_columnar_scan = true;
                opts.columnar_stats = null;
                profile.mark(.assertions);
                var expected = try db.scan(alloc, "k0000", "k0767", opts);
                defer expected.deinit(alloc);
                profile.mark(.primary);
                try std.testing.expectEqualDeep(expected.documents, actual.documents);
                try std.testing.expectEqualDeep(expected.hashes, actual.hashes);
                profile.mark(.assertions);
            };
        }
        // Dense full output must choose sequential primary access, not turn
        // every selected owner into an independent random read.
        var stats: types.ColumnarScanStats = .{};
        var dense = try db.scan(alloc, "", "", .{ .include_documents = true, .columnar_stats = &stats });
        defer dense.deinit(alloc);
        try std.testing.expectEqual(@as(usize, row_count), dense.documents.len);
        if (physical_plan) try std.testing.expect(stats.dense_delta_scans > 0);
        try std.testing.expectEqual(@as(u64, 0), stats.late_materialized_rows);
        profile.mark(.dense);
    }
}

pub fn testRelationalBoundScan(benchmark: bool) !void {
    var allocator_state: std.heap.SafeAllocator = .init(std.heap.page_allocator, .{ .stack_trace_frames = 0 });
    defer std.debug.assert(allocator_state.deinit() == 0);
    const alloc = if (platform.env.getenvBool("ANTFLY_TEST_ALLOCATOR_TRACES")) std.testing.allocator else allocator_state.allocator();
    const row_count: usize = if (benchmark) 768 else 2 * @import("column_read_cache.zig").max_rows;
    relational_columns.test_disable_deadline = true;
    defer relational_columns.test_disable_deadline = false;
    for ([_]PrimaryBackend{.{ .lsm = .{ .flush_threshold = 1 } }}) |backend| {
        var path_tmp = try TestDirectory.init("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false, .primary_backend = backend });
        defer db.close();
        try seedColumnScanPlanRows(&db, alloc, row_count);
        const Scenario = struct { fields: []const []const u8, filter: []const u8 = "{\"numeric_range\":{\"field\":\"n\",\"min\":760}}", rows: usize = 8 };
        for ([_]Scenario{
            .{ .fields = &.{} },                                  .{ .fields = &.{"payload.items.0.id"} },                                  .{ .fields = &.{"user-name"} },
            .{ .fields = &.{}, .filter = "", .rows = row_count }, .{ .fields = &.{"payload.items.0.id"}, .filter = "", .rows = row_count },
        }) |scenario| {
            const fields = scenario.fields;
            var elapsed: [2][7]u64 = undefined;
            var allocated: [2]usize = @splat(0);
            var counters: types.ColumnarScanStats = .{};
            for (0..@as(usize, if (benchmark) 8 else 1)) |round| for (0..2) |step| {
                const mode = (round + step) % 2;
                var measured = std.testing.FailingAllocator.init(alloc, .{});
                var stats: types.ColumnarScanStats = .{};
                const start = platform_time.monotonicNs();
                var result = try db.scan(measured.allocator(), "", "", .{
                    .include_documents = true,
                    .fields = fields,
                    .filter_query_json = scenario.filter,
                    .disable_columnar_scan = mode == 0,
                    .columnar_stats = &stats,
                });
                try std.testing.expectEqual(scenario.rows, result.documents.len);
                result.deinit(measured.allocator());
                const ns = platform_time.monotonicNs() - start;
                try std.testing.expectEqual(measured.allocated_bytes, measured.freed_bytes);
                if (round > 0) elapsed[mode][round - 1] = ns;
                allocated[mode] = measured.allocated_bytes;
                if (mode == 1) {
                    counters = stats;
                    try std.testing.expectEqual(@as(u64, 1), stats.scan_plans_built);
                    try std.testing.expectEqual(@as(u64, if (fields.len == 0) scenario.rows else 0), stats.primary_rows_read);
                }
            };
            if (!benchmark) continue;
            for (&elapsed) |*samples| std.mem.sort(u64, samples, {}, std.sort.asc(u64));
            std.debug.print("\nbound scan: backend={s}, projection={s}, rows={d}, primary/column median ns={d}/{d}, allocated bytes={d}/{d}, plans={d}, hits={d}, primary rows={d}, payload bytes={d}\n", .{
                @tagName(backend), if (fields.len == 0) "full" else fields[0], scenario.rows, elapsed[0][3], elapsed[1][3], allocated[0], allocated[1], counters.scan_plans_built, counters.scan_plan_hits, counters.primary_rows_read, counters.payload_bytes_read,
            });
        }
    }
}

pub fn productionLsmPhysicalChurnBenchmark(gc_min_percent: u8) !void {
    // Keep leak checks and failure injection; allocation backtraces are opt-in.
    var allocator_state: std.heap.SafeAllocator = .init(std.heap.page_allocator, .{ .stack_trace_frames = 0 });
    defer std.debug.assert(allocator_state.deinit() == 0);
    const alloc = if (platform.env.getenvBool("ANTFLY_TEST_ALLOCATOR_TRACES")) std.testing.allocator else allocator_state.allocator();
    relational_columns.test_disable_deadline = true;
    defer relational_columns.test_disable_deadline = false;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var options = db_config.primary_lsm_options_default;
    options.tombstone_gc_min_percent = gc_min_percent;
    // Exercise real persisted files; make only the obsolete-file grace period
    // deterministic. Pinned readers must still prevent premature reclamation.
    options.obsolete_retention_ns = 0;
    var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false, .primary_backend = .{ .lsm = options } });
    defer db.close();
    const columns = [_]schema_mod.RelationalColumn{
        .{ .name = "n", .path = "n", .column_type = .integer },
        .{ .name = "payload", .path = "payload", .column_type = .string },
    };
    try db.setSchema(.{ .version = 1, .storage_mode = .relational, .relational_columns = &columns });
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    var random = std.Random.DefaultPrng.init(417);
    var payload: [4096]u8 = undefined;
    var writes: [256]types.BatchWrite = undefined;
    for (&writes, 0..) |*write, i| {
        for (&payload) |*byte| byte.* = 'a' + random.random().uintLessThan(u8, 26);
        write.* = .{ .key = try std.fmt.allocPrint(scratch, "k{d:0>4}", .{i}), .value = try std.fmt.allocPrint(scratch, "{{\"n\":{d},\"payload\":\"{s}\"}}", .{ i, payload }) };
    }
    try db.batch(.{ .writes = &writes });
    try drainTestRelationalMaintenance(&db);
    const backend = db.core.primary_store_owner.lsmBackend().?;
    try backend.sync(true);
    var pinned = try db.core.store.beginReadTxn();
    var pinned_live = true;
    defer if (pinned_live) pinned.abort();
    const owner_key = try internal_keys.relationalRowKeyAlloc(scratch, writes[0].key);
    const original = try scratch.dupe(u8, try pinned.get(owner_key));
    const before = backend.snapshotWriteStats();
    var mutation_ns: [16]u64 = undefined;
    var peak_physical: u64 = 0;
    for (&mutation_ns, 0..) |*ns, round| {
        var turn = std.heap.ArenaAllocator.init(alloc);
        defer turn.deinit();
        var updates: [64]types.BatchWrite = undefined;
        for (&updates, 0..) |*write, i| {
            for (&payload) |*byte| byte.* = 'a' + random.random().uintLessThan(u8, 26);
            const row = (round % 4) * 64 + i;
            write.* = .{ .key = writes[row].key, .value = try std.fmt.allocPrint(turn.allocator(), "{{\"n\":{d},\"payload\":\"{s}\"}}", .{ row, payload }) };
        }
        const started = platform_time.monotonicNs();
        try db.batch(.{ .writes = &updates });
        ns.* = platform_time.monotonicNs() - started;
        try drainTestRelationalMaintenance(&db);
        // Checkpoint at measurement boundaries, not once per individual write.
        try backend.sync(true);
        peak_physical = @max(peak_physical, try (try backend.measurePhysicalUsage()).totalBytes());
    }
    try std.testing.expectEqualSlices(u8, original, try pinned.get(owner_key));
    pinned.abort();
    pinned_live = false;
    var deletes: [128][]const u8 = undefined;
    for (&deletes, 0..) |*key, i| key.* = writes[i * 2].key;
    try db.batch(.{ .deletes = &deletes });
    try drainTestRelationalMaintenance(&db);
    try backend.sync(true);
    try relational_columns.validatePayloadOwnershipForTest(&db, alloc);
    var stats: types.ColumnarScanStats = .{};
    var result = try db.scan(alloc, "", "", .{ .include_documents = true, .include_all_fields = false, .fields = &.{"n"}, .columnar_stats = &stats });
    defer result.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 128), result.documents.len);
    try std.testing.expectEqual(@as(u64, 0), stats.primary_rows_read);
    std.mem.sort(u64, &mutation_ns, {}, std.sort.asc(u64));
    const after = backend.snapshotWriteStats();
    std.debug.print("\nproduction LSM physical churn: GC minimum={d}%, SST/WAL written={d}/{d}, peak/settled tracked file bytes={d}/{d}, batch median/max ns={d}/{d}, live column payload={d}, projected payload bytes={d}\n", .{
        gc_min_percent,
        after.table_file_bytes - before.table_file_bytes,
        after.wal_append_bytes - before.wal_append_bytes,
        peak_physical,
        try (try backend.measurePhysicalUsage()).totalBytes(),
        mutation_ns[8],
        mutation_ns[15],
        try relational_columns.payloadStorageBytesForTest(&db, alloc),
        stats.payload_bytes_read,
    });
}

pub fn testRelationalDecodedReuse(comptime benchmark: bool) !void {
    var allocator_state: test_allocator_mod.TestAllocator = .{};
    defer allocator_state.deinit();
    const alloc = allocator_state.allocator();
    relational_columns.test_disable_deadline = true;
    defer relational_columns.test_disable_deadline = false;
    for ([_]PrimaryBackend{.{ .lsm = .{ .flush_threshold = 1 } }}) |backend| {
        for ([_]bool{ true, false }) |shared| {
            var path_tmp = try TestDirectory.initFast("db");
            defer path_tmp.cleanup();
            const path = path_tmp.path().ptr;
            var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false, .primary_backend = backend });
            defer db.close();
            const columns = [_]schema_mod.RelationalColumn{.{ .name = "payload", .path = "payload", .column_type = .string }};
            try db.setSchema(.{ .version = 1, .storage_mode = .relational, .relational_columns = &columns });
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const scratch = arena.allocator();
            var random = std.Random.DefaultPrng.init(73);
            const bytes = try scratch.alloc(u8, 64 * 1024);
            for (bytes) |*byte| byte.* = 'a' + random.random().uintLessThan(u8, 26);
            const writes = try scratch.alloc(types.BatchWrite, 128);
            for (writes, 0..) |*write, i| {
                if (!shared) _ = try std.fmt.bufPrint(bytes[0..8], "{d:0>8}", .{i});
                write.* = .{ .key = try std.fmt.allocPrint(scratch, "k{d:0>4}", .{i}), .value = try std.fmt.allocPrint(scratch, "{{\"payload\":\"{s}\"}}", .{bytes}) };
            }
            try db.batch(.{ .writes = writes });
            try drainTestRelationalMaintenance(&db);
            var elapsed: [2][9]u64 = undefined;
            var allocated: [2]usize = @splat(0);
            var counters: [2]types.ColumnarScanStats = @splat(.{});
            // Alternate cache-off/on order; warm both paths before timing.
            for (0..if (benchmark) @as(usize, 10) else 1) |round| for (0..2) |step| {
                const mode = (round + step) % 2;
                var measured = std.testing.FailingAllocator.init(alloc, .{});
                var stats: types.ColumnarScanStats = .{};
                const started = platform_time.monotonicNs();
                var result = try db.scan(measured.allocator(), "", "", .{
                    .filter_query_json = "{\"term\":{\"payload\":\"not present\"}}",
                    .columnar_decoded_cache_bytes = if (mode == 0) 0 else 512 * 1024,
                    .columnar_stats = &stats,
                });
                result.deinit(measured.allocator());
                const ns = platform_time.monotonicNs() - started;
                try std.testing.expectEqual(measured.allocated_bytes, measured.freed_bytes);
                try std.testing.expect(stats.used);
                try std.testing.expect(stats.blocks_read >= 8);
                try std.testing.expectEqual(@as(u64, 0), stats.rows_selected);
                try std.testing.expectEqual(@as(u64, 0), stats.primary_rows_read);
                try std.testing.expect(stats.decoded_cache_peak_bytes <= 512 * 1024);
                if (mode == 0) {
                    try std.testing.expectEqual(@as(u64, 0), stats.decoded_cache_hits);
                    try std.testing.expectEqual(@as(u64, 0), stats.decoded_cache_peak_bytes);
                } else if (shared) {
                    try std.testing.expectEqual(@as(u64, 1), stats.payload_pages_read);
                    try std.testing.expectEqual(stats.blocks_read - 1, stats.decoded_cache_hits);
                } else try std.testing.expectEqual(@as(u64, 0), stats.decoded_cache_hits);
                if (round > 0) elapsed[mode][round - 1] = ns;
                allocated[mode] = measured.allocated_bytes;
                counters[mode] = stats;
            };
            if (benchmark) {
                for (&elapsed) |*samples| std.mem.sort(u64, samples, {}, std.sort.asc(u64));
                std.debug.print("\ncolumnar decoded reuse: backend={s}, shared={}, median ns off/on={d}/{d}, allocated bytes={d}/{d}, decodes={d}/{d}, hits={d}, peak={d}\n", .{
                    @tagName(backend), shared, elapsed[0][4], elapsed[1][4], allocated[0], allocated[1], counters[0].payload_pages_read, counters[1].payload_pages_read, counters[1].decoded_cache_hits, counters[1].decoded_cache_peak_bytes,
                });
            }
        }
    }
}

pub fn testRelationalCleanupBackend(backend: PrimaryBackend) !void {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
