        try db.addEnrichment(.{
            .name = "primary_relations_v1",
            .kind = .asset,
            .field = "primary_relations",
            .content_type = "application/json",
        });
        try db.addEnrichment(.{
            .name = "fallback_relations_v1",
            .kind = .asset,
            .field = "fallback_relations",
            .content_type = "application/json",
        });
        try db.addIndex(.{
            .name = "relations_graph",
