            try std.testing.expectEqual(@as(usize, 1), edges.len);
            try std.testing.expectEqual(@as(f64, 2), edges[0].weight);
            try std.testing.expect(std.mem.indexOf(u8, edges[0].metadata, "\"winner\":\"primary\"") != null);
        }
        const generation = (db.core.index_manager.graphIndex("relations_graph") orelse return error.TestUnexpectedResult).config.coverage_generation;
        const contender_count_key = try internal_keys.graphEdgeContenderCountKeyAlloc(alloc, "doc:a", "relations_graph");
        defer alloc.free(contender_count_key);
        {
            const raw_count = try db.core.store.get(alloc, contender_count_key);
            defer alloc.free(raw_count);
            try std.testing.expectEqual(@as(?usize, 1), try graph_edge_contender.decodeVisibleCount(raw_count, generation));
        }
        const logical_edge_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "doc:a", "relations_graph", "mentions", "doc:b");
        defer alloc.free(logical_edge_key);
        const contender_prefix = try internal_keys.graphEdgeContenderEdgePrefixAlloc(alloc, "doc:a", "relations_graph", logical_edge_key);
        defer alloc.free(contender_prefix);
        {
            const contenders = try db.core.store.scanPrefix(alloc, contender_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, contenders);
            try std.testing.expectEqual(@as(usize, 2), contenders.len);
        }

        // Removing the higher-precedence artifact must reveal the retained
        // lower-precedence payload instead of deleting the logical edge.
        try db.batch(.{
            .writes = &.{.{
                .key = "doc:a",
                .value =
                \\{"fallback_relations":{"type":"mentions","target":{"document_id":"doc:b"},"weight":1,"winner":"fallback"}}
                ,
            }},
            .sync_level = .enrichments,
        });
        try db.runUntilIdle();

        const edges = try db.getEdges(alloc, "relations_graph", "doc:a", "mentions", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try std.testing.expectEqual(@as(usize, 1), edges.len);
        try std.testing.expectEqual(@as(f64, 1), edges[0].weight);
        try std.testing.expect(std.mem.indexOf(u8, edges[0].metadata, "\"winner\":\"fallback\"") != null);
        {
            const contenders = try db.core.store.scanPrefix(alloc, contender_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, contenders);
            try std.testing.expectEqual(@as(usize, 1), contenders.len);
        }
        try db.sync(true);
    }

    var reopened = try DB.open(alloc, std.mem.span(path), .{});
    defer reopened.close();
    const reopened_edges = try reopened.getEdges(alloc, "relations_graph", "doc:a", "mentions", .out);
    defer graph_mod.GraphIndex.freeEdges(alloc, reopened_edges);
    try std.testing.expectEqual(@as(usize, 1), reopened_edges.len);
    try std.testing.expectEqual(@as(f64, 1), reopened_edges[0].weight);
    try std.testing.expect(std.mem.indexOf(u8, reopened_edges[0].metadata, "\"winner\":\"fallback\"") != null);
}

// Regression for PR #957's review of "fix(storage): stop a surviving asset
// contender from resurrecting an explicitly deleted graph edge": removing an
// ordinary (non-winning, non-direct) contender must still leave the winning
// contender's edge in place. The sibling precedence test above exercises the
// opposite edge of this same reconcileGlobalGraphEdgeWinner path (removing
// the winner reveals the fallback); this one removes the fallback while the
// winner survives untouched, which the unconditional winner-removal this
// fixes used to wipe out alongside it.
test "db multi-source graph precedence keeps the primary edge after removing the fallback" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.addEnrichment(.{
            .name = "primary_relations_v1",
            .kind = .asset,
            .field = "primary_relations",
            .content_type = "application/json",
        });
        try db.addEnrichment(.{
            .name = "fallback_relations_v1",
            .kind = .asset,
            .field = "fallback_relations",
            .content_type = "application/json",
        });
        try db.addIndex(.{
            .name = "relations_graph",
            .kind = .graph,
            .config_json =
            \\{"sources":[{"artifact":"primary_relations_v1"},{"artifact":"fallback_relations_v1"}]}
            ,
        });

        try db.batch(.{
            .writes = &.{.{
                .key = "doc:a",
                .value =
                \\{"primary_relations":{"type":"mentions","target":{"document_id":"doc:b"},"weight":2,"winner":"primary"},"fallback_relations":{"type":"mentions","target":{"document_id":"doc:b"},"weight":1,"winner":"fallback"}}
                ,
            }},
            .sync_level = .enrichments,
        });
        try db.runUntilIdle();

        {
            const edges = try db.getEdges(alloc, "relations_graph", "doc:a", "mentions", .out);
            defer graph_mod.GraphIndex.freeEdges(alloc, edges);
            try std.testing.expectEqual(@as(usize, 1), edges.len);
            try std.testing.expectEqual(@as(f64, 2), edges[0].weight);
            try std.testing.expect(std.mem.indexOf(u8, edges[0].metadata, "\"winner\":\"primary\"") != null);
        }
        const logical_edge_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "doc:a", "relations_graph", "mentions", "doc:b");
        defer alloc.free(logical_edge_key);
        const contender_prefix = try internal_keys.graphEdgeContenderEdgePrefixAlloc(alloc, "doc:a", "relations_graph", logical_edge_key);
        defer alloc.free(contender_prefix);
        {
            const contenders = try db.core.store.scanPrefix(alloc, contender_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, contenders);
            try std.testing.expectEqual(@as(usize, 2), contenders.len);
        }

        // Removing the lower-precedence (non-winning) artifact must leave
        // the still-winning primary edge exactly as it was, not delete it.
        try db.batch(.{
            .writes = &.{.{
                .key = "doc:a",
                .value =
                \\{"primary_relations":{"type":"mentions","target":{"document_id":"doc:b"},"weight":2,"winner":"primary"}}
                ,
            }},
            .sync_level = .enrichments,
        });
        try db.runUntilIdle();

        const edges = try db.getEdges(alloc, "relations_graph", "doc:a", "mentions", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try std.testing.expectEqual(@as(usize, 1), edges.len);
        try std.testing.expectEqual(@as(f64, 2), edges[0].weight);
        try std.testing.expect(std.mem.indexOf(u8, edges[0].metadata, "\"winner\":\"primary\"") != null);
        {
            const contenders = try db.core.store.scanPrefix(alloc, contender_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, contenders);
            try std.testing.expectEqual(@as(usize, 1), contenders.len);
        }
        try db.sync(true);
    }

    var reopened = try DB.open(alloc, std.mem.span(path), .{});
    defer reopened.close();
    const reopened_edges = try reopened.getEdges(alloc, "relations_graph", "doc:a", "mentions", .out);
    defer graph_mod.GraphIndex.freeEdges(alloc, reopened_edges);
    try std.testing.expectEqual(@as(usize, 1), reopened_edges.len);
    try std.testing.expectEqual(@as(f64, 2), reopened_edges[0].weight);
    try std.testing.expect(std.mem.indexOf(u8, reopened_edges[0].metadata, "\"winner\":\"primary\"") != null);
}

test "db vector status revalidates stale repair admission without a query" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{
        .name = "dense_status",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\"}",
    });
    try db.addIndex(.{
        .name = "sparse_status",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse\"}",
    });
    try db.addIndex(.{
        .name = "repair_sibling",
        .kind = .full_text,
        .config_json = "{}",
    });

    // Keep unrelated nonblocking durable debt so stats exercises one preloaded
    // repair snapshot rather than rereading it for each stale vector gate.
    const sibling_cfg = db.core.index_manager.get("repair_sibling") orelse return error.TestUnexpectedResult;
    _ = try db.createGenerationRepairIntent(
        alloc,
        sibling_cfg.*,
        .operator_generation_rebuild,
        0,
        0,
        null,
    );

    // Model a process that observed durable repair debt immediately before
    // another owner either made the intent serviceable or removed it. Status
    // is itself an admission observer: it must heal the stale resident gates
    // rather than wait for a user query to make index wait truthful.
    try db.core.index_manager.markUnscopedRepairUnavailable("dense_status");
    try db.core.index_manager.markUnscopedRepairUnavailable("sparse_status");
    try std.testing.expect(db.core.index_manager.repairUnavailable("dense_status"));
    try std.testing.expect(db.core.index_manager.repairUnavailable("sparse_status"));

    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    var observed_dense = false;
    var observed_sparse = false;
    for (stats.indexes) |index_stats| {
        if (std.mem.eql(u8, index_stats.name, "dense_status")) {
            observed_dense = true;
            try std.testing.expect(index_stats.serving_snapshot_ready);
            try std.testing.expectEqual(db.backend_owner_id, index_stats.serving_snapshot_owner_id);
            try std.testing.expectEqual(db.status_owner_epoch, index_stats.serving_publication.?.owner_epoch);
        } else if (std.mem.eql(u8, index_stats.name, "sparse_status")) {
            observed_sparse = true;
            try std.testing.expect(index_stats.serving_snapshot_ready);
            try std.testing.expectEqual(db.status_owner_epoch, index_stats.serving_publication.?.owner_epoch);
        }
    }
    try std.testing.expect(observed_dense);
    try std.testing.expect(observed_sparse);
    try std.testing.expect(!db.core.index_manager.repairUnavailable("dense_status"));
    try std.testing.expect(!db.core.index_manager.repairUnavailable("sparse_status"));
    var refreshed = try db.runtimeStatusStatsConsistent(alloc);
    defer types.freeDBStats(alloc, refreshed);
    try std.testing.expect(refreshed.indexes[0].serving_publication.?.revision > stats.indexes[0].serving_publication.?.revision);
    try std.testing.expect(db.overlayRuntimeStatusBestEffort(alloc, &refreshed));
    for (refreshed.indexes) |item| {
        try std.testing.expectEqual(@as(?publication_mod.Stamp, null), item.serving_publication);
        try std.testing.expectEqual(@as(?publication_mod.Stamp, null), item.coverage_publication);
    }
}

test "db resolver catalog persists across reopen" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();
        try db.addResolver(.{
            .name = "knowledge_graph",
            .table = "entities",
            .source_artifact = "relations_v1",
            .resolution_artifact = "resolution_v1",
            .key_template = "{{ lower _entity.label }}/{{ slug _entity.canonical_text }}",
            .config_generation = 3,
        });
        try std.testing.expectError(error.ResolverAlreadyExists, db.addResolver(.{
            .name = "knowledge_graph",
            .table = "entities",
            .source_artifact = "relations_v1",
            .resolution_artifact = "resolution_v1",
            .key_template = "x",
        }));
        try std.testing.expectError(error.ResolverArtifactAlreadyExists, db.addResolver(.{
            .name = "duplicate_output",
            .table = "entities",
            .source_artifact = "other_v1",
            .resolution_artifact = "resolution_v1",
            .key_template = "x",
        }));
        try std.testing.expectError(error.ResolverSourceArtifactImmutable, db.upsertResolver(.{
            .name = "knowledge_graph",
            .table = "entities",
            .source_artifact = "other_v1",
            .resolution_artifact = "resolution_v1",
            .key_template = "x",
        }));
        try std.testing.expectError(error.ResolverArtifactImmutable, db.upsertResolver(.{
            .name = "knowledge_graph",
            .table = "entities",
            .source_artifact = "relations_v1",
            .resolution_artifact = "other_resolution_v1",
            .key_template = "x",
        }));
    }

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const resolvers = try db.listResolvers(alloc);
    defer {
        for (resolvers) |*r| r.deinit(alloc);
        alloc.free(resolvers);
    }
    try std.testing.expectEqual(@as(usize, 1), resolvers.len);
    try std.testing.expectEqualStrings("knowledge_graph", resolvers[0].name);
    try std.testing.expectEqualStrings("entities", resolvers[0].table);
    try std.testing.expectEqual(@as(u64, 3), resolvers[0].config_generation);

    try std.testing.expect(try db.removeResolver("knowledge_graph"));
    const after = try db.listResolvers(alloc);
    defer alloc.free(after);
    try std.testing.expectEqual(@as(usize, 0), after.len);
}

test "producer readiness cached graph relations survive metadata overwrite and reopen" {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("db");
    defer directory.cleanup();
    var fake = TestAssetProducer{ .extractor_output =
        \\{"entities":[{"text":"Alice"},{"text":"doc:b"}],"relations":[{"type":"mentions","source":{"entity_index":0},"target":{"entity_index":1},"score":1.0}]}
    };
    const config: types.IndexConfig = .{
        .name = "relations_graph",
        .kind = .graph,
        .config_json =
        \\{"sources":[{"artifact":"relations_v1","path":"$.relations[*]","format":"extraction_relation","nodes":{"model":"document","target":"{{ _item.target.text }}"},"edge":{"weight":"{{ _item.score }}"}}],"artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"target_doc"},"content_type":"application/json","producer_json":{"type":"extractor","config":{"provider":"mock"}}}}
        ,
    };
    {
        var db = try DB.open(alloc, std.mem.span(directory.path().ptr), .{ .enrichment = .{ .asset_producer = fake.producer() } });
        defer db.close();
        try db.addIndex(config);
        for ([_][]const u8{
            "{\"title\":\"before\",\"target_doc\":\"doc:b\"}",
            "{\"title\":\"after\",\"target_doc\":\"doc:b\"}",
        }) |value| {
            try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = value }}, .sync_level = .full_index });
            try db.runUntilIdle();
            const edges = try db.getEdges(alloc, config.name, "doc:a", "mentions", .out);
            defer graph_mod.GraphIndex.freeEdges(alloc, edges);
            try std.testing.expectEqual(@as(usize, 1), edges.len);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), fake.extractor_calls);
