test "index repair advance lease covers cancellation and deletion" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_background_test_open);
    defer db.close();
    try db.addIndex(.{ .name = "graph_v1", .kind = .graph, .config_json = "{}" });

    var queued = try db.repairArtifactIssuesWithRequestOptions(alloc, .{
        .target = .index,
        .index_name = "graph_v1",
        .limit = 1,
        .force = true,
    }, .{ .defer_durable_index_repair_execution = true });
    defer queued.deinit(alloc);
    const repair_id = (try db.indexRepairIdForIndex(alloc, "graph_v1")) orelse
        return error.TestUnexpectedResult;

    const Race = struct {
        db: *DB,
        repair_id: u128,
        entered: std.atomic.Value(bool) = .init(false),
        release: std.atomic.Value(bool) = .init(false),
        result: ?DB.IndexRepairAdvanceResult = null,
        err: ?anyerror = null,

        fn afterAcquire(raw: *anyopaque, _: *DB, observed_repair_id: u128) !void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(self.repair_id, observed_repair_id);
            self.entered.store(true, .release);
            while (!self.release.load(.acquire)) std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
        }

        fn run(self: *@This()) void {
            self.result = self.db.advanceIndexRepairIntent(self.db.alloc, self.repair_id, .{}) catch |err| {
                self.err = err;
                return;
            };
        }
    };
    var race = Race{ .db = &db, .repair_id = repair_id };
    DB.test_index_repair_advance_lease_hook = .{
        .ptr = &race,
        .after_acquire = Race.afterAcquire,
    };
    defer DB.test_index_repair_advance_lease_hook = null;

    var advance_thread = try std.testing.io.concurrent(Race.run, .{&race});
    var joined = false;
    defer if (!joined) {
        race.release.store(true, .release);
        advance_thread.await(std.testing.io);
    };
    var entered = false;
    for (0..100_000) |_| {
        if (race.entered.load(.acquire)) {
            entered = true;
            break;
        }
        std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
    }
    if (!entered) return error.TestTimeout;

    // Both controls observe the same full-quantum owner. Cancellation is
    // accepted, while deletion must retry instead of crossing an unowned
    // preflight/reconciliation interval.
    try std.testing.expect(try db.cancelCurrentIndexRepairAttempt(alloc, "graph_v1", repair_id));
    try std.testing.expectError(
        error.IndexRepairInProgress,
        db.prepareIndexRepairForDeletion(alloc, "graph_v1"),
    );

    race.release.store(true, .release);
    advance_thread.await(std.testing.io);
    joined = true;
    DB.test_index_repair_advance_lease_hook = null;
    try std.testing.expect(race.err == null);
    try std.testing.expect(race.result != null);
    try std.testing.expect(race.result.?.deferred);
    try std.testing.expect(!race.result.?.attempted);
    try std.testing.expect(!db.activeIndexRepairCancellationRequested("graph_v1"));

    // Cancellation is attempt-scoped. Once the owner releases its lease, the
    // next quantum can finish the still-enabled durable repair normally. A
    // non-activation phase must not even enter restart reconciliation's global
    // structural/apply fence; the ordinary activation path takes its own
    // bounded publication fence only after the candidate is ready.
    const ReconcileProbe = struct {
        calls: usize = 0,

        fn beforeFence(raw: *anyopaque, _: *DB, _: u128) !void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.calls += 1;
        }
    };
    var reconcile_probe = ReconcileProbe{};
    DB.test_index_repair_reconcile_fence_hook = .{
        .ptr = &reconcile_probe,
        .before_fence = ReconcileProbe.beforeFence,
    };
    defer DB.test_index_repair_reconcile_fence_hook = null;
    const completed = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    DB.test_index_repair_reconcile_fence_hook = null;
    try std.testing.expectEqual(@as(usize, 0), reconcile_probe.calls);
    try std.testing.expect(completed.attempted);
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
}

test "db text totals require presence proof beyond the requested page" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{ .name = "ft_rows", .kind = .full_text, .config_json = "{}" });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" },
            .{ .key = "doc:b", .value = "{\"body\":\"alpha\"}" },
        },
        .sync_level = .full_index,
    });

    // The same prefix is returned before and after the unseen row goes
    // missing. Neither query can prove an exact total from that prefix.
    for ([_]bool{ false, true }) |orphaned| {
        if (orphaned) {
            const key = try internal_keys.documentKeyAlloc(alloc, "doc:b");
            defer alloc.free(key);
            try db.core.store.delete(key);
        }
        const expected_total: u32 = if (orphaned) 1 else 2;
        for ([_]bool{ false, true }) |include_stored| {
            for ([_]types.TextQuery{
                .{ .match_all = {} },
                .{ .match = .{ .field = "body", .text = "alpha" } },
            }) |query| {
                var req = types.SearchRequest{ .index_name = "ft_rows", .full_text = query, .include_stored = include_stored, .limit = 1 };
                var page = try db.search(alloc, req);
                defer page.deinit();
                try std.testing.expectEqual(@as(usize, 1), page.hits.len);
                try std.testing.expectEqualStrings("doc:a", page.hits[0].id);
                try std.testing.expectEqual(@as(u32, 1), page.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.gte, page.total_hits_relation);

                req.count_only = true;
                var count = try db.search(alloc, req);
                defer count.deinit();
                try std.testing.expectEqual(expected_total, count.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, count.total_hits_relation);

                req.count_only = false;
                req.limit = 2;
                var complete = try db.search(alloc, req);
                defer complete.deinit();
                try std.testing.expectEqual(expected_total, complete.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, complete.total_hits_relation);
                try std.testing.expectEqual(@as(usize, expected_total), complete.hits.len);

                req.limit = 1;
                req.offset = 1;
                var tail = try db.search(alloc, req);
                defer tail.deinit();
                try std.testing.expectEqual(expected_total, tail.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, tail.total_hits_relation);
                try std.testing.expectEqual(@as(usize, if (orphaned) 0 else 1), tail.hits.len);

                // Native field-sort collectors check every counted row, so
                // their limited pages still have an exact presence proof.
                req.offset = 0;
                req.order_by = &.{.{ .field = "_id" }};
                var sorted = try db.search(alloc, req);
                defer sorted.deinit();
                try std.testing.expectEqual(expected_total, sorted.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, sorted.total_hits_relation);
                try std.testing.expectEqual(@as(usize, 1), sorted.hits.len);
            }
        }
    }
}

test "db materialized dense enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.dense);
}

test "db materialized derived dense enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.derived_dense);
}

test "db materialized sparse enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.sparse);
}

fn testMaterializedEmbeddingWriteGrowth(comptime mode: enum { dense, derived_dense, sparse }) !void {
    const alloc = std.testing.allocator;
    const is_sparse = mode == .sparse;
    const embedding_name = if (is_sparse) "document_sparse" else "document_dense";

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var deterministic_dense = embedder_mod.DeterministicDenseEmbedder{};
    var deterministic_sparse = embedder_mod.DeterministicSparseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic_dense.interface(),
            .sparse_embedder = deterministic_sparse.interface(),
        },
    });
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .field = "url",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });
    try db.addEnrichment(.{
        .name = "document_chunks_v1",
        .kind = .chunk,
        .field = "text",
        .source_artifact_name = "document_units_v1",
        .chunk_size = 256,
    });
    try db.addEnrichment(.{
        .name = embedding_name,
        .kind = .embedding,
        .field = "text",
        .source_artifact_name = "document_chunks_v1",
        .expected_dims = if (is_sparse) 0 else 3,
    });
    try db.addIndex(.{
        .name = embedding_name,
        .kind = if (is_sparse) .sparse_vector else .dense_vector,
        .config_json = if (is_sparse)
            "{\"field\":\"sparse_embedding\"}"
        else
            "{\"field\":\"embedding\",\"dims\":3,\"embedding_name\":\"document_dense\"}",
    });

    // Leave a chunk after the first flush and no spare capacity for its output.
    // Follow the configured item limit so batch tuning cannot bypass the regression.
    const chunk_count = generatedEmbedBatchItems() + 1;
    var artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer {
        for (artifact_writes.items) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        artifact_writes.deinit(alloc);
    }
    try artifact_writes.ensureTotalCapacityPrecise(alloc, chunk_count);
    for (0..chunk_count) |chunk_id| {
        const key = try internal_keys.documentUnitChunkArtifactKeyAlloc(
            alloc,
            "doc:a",
            "document_chunks_v1",
            "document:000001",
            @intCast(chunk_id),
        );
        errdefer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"text\":\"chunk {d}\"}}", .{chunk_id});
        errdefer alloc.free(value);
        artifact_writes.appendAssumeCapacity(.{ .key = key, .value = value });
    }
    const original_write_pointer = artifact_writes.items.ptr;

    const Embedding = switch (mode) {
        .dense => types.EnrichmentDenseEmbeddingWrite,
        .derived_dense => derived_types.DerivedDenseEmbeddingWrite,
        .sparse => derived_types.DerivedSparseEmbeddingWrite,
    };
    var embeddings = std.ArrayListUnmanaged(Embedding).empty;
    defer {
        for (embeddings.items) |*embedding| {
            switch (mode) {
                .dense => embedding.deinit(alloc),
                .derived_dense => derived_types.deinitDerivedDenseEmbedding(alloc, embedding.*),
                .sparse => derived_types.deinitDerivedSparseEmbedding(alloc, embedding.*),
            }
        }
        embeddings.deinit(alloc);
    }
    var chunk_cache = std.ArrayListUnmanaged(ChunkCacheEntry).empty;
    defer {
        for (chunk_cache.items) |entry| {
            alloc.free(entry.key);
            chunker_mod.freeChunks(alloc, entry.chunks);
        }
        chunk_cache.deinit(alloc);
    }

    var consumer_name = embedding_name.*;
    var consumer_indexes = [_][]u8{consumer_name[0..]};
    const request = enrichment_types.GeneratedEnrichmentRequest{
        .kind = if (is_sparse) .sparse_embedding else .dense_embedding,
        .index_name = embedding_name,
        .artifact_name = "document_chunks_v1",
        .embedding_name = embedding_name,
        .input_kind = .materialized_chunks,
        .consumer_indexes = &consumer_indexes,
        .doc_key = "doc:a",
        .source_field = "text",
        .expected_dims = if (is_sparse) 0 else 3,
        .producer_json = "{}",
    };
    const compute = switch (mode) {
        .dense => computeDenseRequest,
        .derived_dense => computeDenseRequestDerived,
        .sparse => computeSparseRequestDerived,
    };
    if (mode == .dense) {
        try compute(alloc, &db, "{}", request, &artifact_writes, &embeddings, &chunk_cache);
    } else {
        const no_deletes = std.StringHashMapUnmanaged(void).empty;
        try compute(alloc, &db, "{}", request, &artifact_writes, &no_deletes, &embeddings, &chunk_cache, null, null, true);
    }

    // Guard the test's relocation precondition, not just the successful no-growth path.
    try std.testing.expect(original_write_pointer != artifact_writes.items.ptr);
    try std.testing.expectEqual(chunk_count * 2, artifact_writes.items.len);
    try std.testing.expectEqual(chunk_count, embeddings.items.len);
    var outputs = try PendingArtifactWriteIndex.init(alloc, artifact_writes.items);
    defer outputs.deinit(alloc);
    for (0..chunk_count) |chunk_id| {
        const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(
            alloc,
            "doc:a",
            "document_chunks_v1",
            "document:000001",
            @intCast(chunk_id),
        );
        defer alloc.free(chunk_key);
        const embedding_key = try internal_keys.derivedEmbeddingArtifactKeyAlloc(alloc, chunk_key, embedding_name);
        defer alloc.free(embedding_key);
        const payload = outputs.get(embedding_key) orelse return error.TestUnexpectedResult;
        const text = try std.fmt.allocPrint(alloc, "chunk {d}", .{chunk_id});
        defer alloc.free(text);
        if (is_sparse) {
            var expected = try deterministic_sparse.interface().embedSparse(alloc, embedding_name, text);
            defer expected.deinit(alloc);
            var actual = try enrichment_artifact_codec.decodeSparseEmbeddingAlloc(alloc, payload);
            defer actual.deinit(alloc);
            try std.testing.expectEqualSlices(u32, expected.indices, actual.indices);
            try std.testing.expectEqualSlices(f32, expected.values, actual.values);
        } else {
            const expected = try deterministic_dense.interface().embedDense(alloc, embedding_name, text, 3);
            defer alloc.free(expected);
            const actual = try enrichment_artifact_codec.decodeDenseEmbeddingAlloc(alloc, payload);
            defer alloc.free(actual);
            try std.testing.expectEqualSlices(f32, expected, actual);
        }
    }
}

test "db sync_level enrichments precompute for document-mode writes does not hold the apply lock" {
    if (builtin.single_threaded or builtin.os.tag == .freestanding) return error.SkipZigTest;
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var slow_asset = SlowGatedAssetProducer{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .asset_producer = slow_asset.interface(),
            .inline_retry_max_attempts = 1,
        },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    defer slow_asset.allow();

    try db.addEnrichment(.{
        .name = "summary_v1",
        .kind = .asset,
        .field = "body",
        .content_type = "text/plain",
        .producer_json = "{\"type\":\"generator\",\"config\":{\"provider\":\"antfly\",\"model\":\"test-generator\"}}",
    });

    const Writer = struct {
        db: *DB,
        err: ?anyerror = null,

        fn run(self: *@This()) void {
            self.db.batch(.{
                .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha summary source\"}" }},
                .sync_level = .enrichments,
            }) catch |err| {
                self.err = err;
            };
        }
    };
    var writer = Writer{ .db = &db };
    const writer_thread = try std.Thread.spawn(.{}, Writer.run, .{&writer});
    var joined = false;
    defer if (!joined) {
        slow_asset.allow();
        writer_thread.join();
    };

    // Wait until the asset producer is actually invoked: this batch's
    // generated-enrichment precompute is in flight, ahead of the apply lock.
    var attempts: usize = 0;
    while (attempts < slow_test_wait_attempts) : (attempts += 1) {
        if (slow_asset.started.load(.acquire)) break;
        sleepPollInterval();
    }
    try std.testing.expect(slow_asset.started.load(.acquire));
    try std.testing.expect(!slow_asset.finished.load(.acquire));

    // A concurrent reader must not queue behind the in-flight precompute.
    // Before this fix, sync_level: .enrichments precompute for document-mode
    // writes ran entirely under the exclusive apply lock, so this probe
    // (which only takes the shared apply lock) would have blocked for as
    // long as the asset producer stayed parked.
    const probe_start_ns = monotonicTimeNs();
    _ = db.lsmMaintenanceScore();
    const probe_elapsed_ns = monotonicTimeNs() - probe_start_ns;
    try std.testing.expect(!slow_asset.finished.load(.acquire));
    try std.testing.expect(probe_elapsed_ns < 500 * std.time.ns_per_ms);

    slow_asset.allow();
    writer_thread.join();
    joined = true;
    try std.testing.expectEqual(@as(?anyerror, null), writer.err);

    const artifact_key = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "asset", "summary_v1");
    defer alloc.free(artifact_key);
    const artifact_value = try db.core.store.get(alloc, artifact_key);
    defer alloc.free(artifact_value);
    try std.testing.expectEqualStrings("asset:alpha summary source", artifact_value);
}

test "db sync_level enrichments returns without waiting on an unrelated enrichment backlog" {
    if (builtin.single_threaded or builtin.os.tag == .freestanding) return error.SkipZigTest;
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var slow_asset = SlowGatedAssetProducer{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .asset_producer = slow_asset.interface(),
            .inline_retry_max_attempts = 1,
        },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    defer slow_asset.allow();

    try db.addEnrichment(.{
        .name = "summary_v1",
        .kind = .asset,
        .field = "body",
        .content_type = "text/plain",
        .producer_json = "{\"type\":\"generator\",\"config\":{\"provider\":\"antfly\",\"model\":\"test-generator\"}}",
    });

    // sync_level: .write defers this document's asset enrichment to the
    // background runtime, which picks it up and parks in the producer.
    try db.batch(.{
        .writes = &.{.{ .key = "doc:backlog", .value = "{\"body\":\"alpha summary source\"}" }},
        .sync_level = .write,
    });

    var attempts: usize = 0;
    while (attempts < slow_test_wait_attempts) : (attempts += 1) {
        if (slow_asset.started.load(.acquire)) break;
        sleepPollInterval();
    }
    try std.testing.expect(slow_asset.started.load(.acquire));
    try std.testing.expect(!slow_asset.finished.load(.acquire));

    // This row has no value in the enrichment's source field, so its own
    // sync_level: .enrichments precompute needs nothing from the producer
    // (generated_enrichment_refs stays empty) and must not wait for
    // db.enrichment_runtime's applied_sequence to catch up to -- let alone
    // past -- the backlogged "doc:backlog" commit still parked ahead of it.
    const wait_start_ns = monotonicTimeNs();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:tiny", .value = "{\"other\":\"no body field\"}" }},
        .sync_level = .enrichments,
    });
    const wait_elapsed_ns = monotonicTimeNs() - wait_start_ns;
    try std.testing.expect(!slow_asset.finished.load(.acquire));
    try std.testing.expect(wait_elapsed_ns < 5 * std.time.ns_per_s);

    slow_asset.allow();
}

pub fn testLargeHtmlDataUrlAlloc(alloc: Allocator, version: []const u8, unique_token: []const u8, paragraph_count: usize) ![]u8 {
    var html = std.ArrayListUnmanaged(u8).empty;
    defer html.deinit(alloc);
    try html.appendSlice(alloc, "<html><body><h1>Synthetic Report ");
    try html.appendSlice(alloc, version);
    try html.appendSlice(alloc, "</h1>");
    for (0..paragraph_count) |i| {
        const paragraph = try std.fmt.allocPrint(
            alloc,
            "<p>{s} harbor terminal cargo fiscal quarterly report section {d} renewal authority volume meridian refrigerated shipping expansion contract.</p>\n",
            .{ unique_token, i },
        );
        defer alloc.free(paragraph);
        try html.appendSlice(alloc, paragraph);
    }
    try html.appendSlice(alloc, "</body></html>");

    const encoded_len = std.base64.standard.Encoder.calcSize(html.items.len);
    const encoded = try alloc.alloc(u8, encoded_len);
    defer alloc.free(encoded);
    _ = std.base64.standard.Encoder.encode(encoded, html.items);
    return try std.fmt.allocPrint(alloc, "data:text/html;base64,{s}", .{encoded});
}

pub fn testSourceDocumentJsonAlloc(alloc: Allocator, url: []const u8, sha256: []const u8) ![]u8 {
