test "source vector table rejects delayed enrichment after source update deletion or recreation" {
    const alloc = std.testing.allocator;
    const Mutation = enum { update, delete, recreate };
    const Provider = struct {
        db: ?*DB = null,
        mutation: Mutation,
        changed: bool = false,
        calls: usize = 0,
        fn embed(ptr: *anyopaque, allocator: Allocator, _: []const u8, text: []const u8, dims: u32) ![]f32 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            if (!self.changed) {
                self.changed = true;
                // Deterministically interleave the primary mutation between
                // provider input capture and completion, without timing sleeps.
                if (self.mutation != .update) {
                    try self.db.?.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .write });
                    if (self.mutation == .recreate) {
                        try self.db.?.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"old source\"}" }}, .sync_level = .write });
                    }
                } else {
                    try self.db.?.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"new source\"}" }}, .sync_level = .write });
                }
            }
            const vector = try allocator.alloc(f32, dims);
            @memset(vector, if (std.mem.eql(u8, text, "new source") or (self.mutation == .recreate and self.calls > 1)) 2 else 1);
            return vector;
        }
    };
    for ([_]bool{ false, true }) |chunked| {
        for ([_]table_storage_mod.Settings{ .{}, .{ .dense_embeddings = .vector_store } }) |settings| {
            for ([_]Mutation{ .update, .delete, .recreate }) |mutation| {
                var path_tmp = try TestDirectory.init("db");
                defer path_tmp.cleanup();
                const path = path_tmp.path().ptr;
                var provider = Provider{ .mutation = mutation };
                var db = try DB.open(alloc, std.mem.span(path), .{
                    .table_storage = settings,
                    .start_index_workers = false,
                    .enrichment = .{ .owner_id = "fenced-provider", .dense_embedder = .{ .ptr = &provider, .dense_embed_fn = Provider.embed } },
                });
                defer db.close();
                provider.db = &db;
                try db.addIndex(.{
                    .name = "dv_v1",
                    .kind = .dense_vector,
                    .config_json = if (chunked) "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":64,\"chunk_overlap\":0,\"embedding_name\":\"body_dense_v1\"}}" else "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
                });
                try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"old source\"}" }}, .sync_level = .write });
                try db.runUntilIdle();
                try std.testing.expect(provider.changed);
                if (db.core.index_manager.densePostingWalAuthoritativeByName("dv_v1")) {
                    const covered = db.core.index_manager.denseIndex("dv_v1").?.index.experimentalPostingDurableAppliedSequence().?;
                    try std.testing.expect(covered > 1);
                    // A lagging replay cursor must not delete the newer vector
                    // authority or append a mutation below its durable base.
                    try applyDerivedBatchToIndex(&db, .{
                        .sequence = 1,
                        .deleted_keys = &.{"doc:a"},
                    }, .{ .name = "dv_v1", .kind = .dense_vector });
                    try std.testing.expectEqual(@as(?u64, covered), db.core.index_manager.denseIndex("dv_v1").?.index.experimentalPostingDurableAppliedSequence());
                    // The worker path borrows the capture owned by this exact
                    // catch-up session; skipping a stale window must also let
                    // that session finish without regressing native coverage.
                    const index_ref: index_manager_mod.ManagedIndexRef = .{ .name = "dv_v1", .kind = .dense_vector };
                    const token = try beginDerivedCatchUpSessionAsync(db.async_context, index_ref);
                    var session_active = true;
                    defer if (session_active) {
                        _ = finishDerivedCatchUpSessionAsync(db.async_context, index_ref, token, 1, false) catch {};
                    };
                    _ = try applyDerivedBatchToIndexAsync(db.async_context, .{
                        .sequence = 1,
                        .deleted_keys = &.{"doc:a"},
                    }, index_ref, token);
                    _ = try finishDerivedCatchUpSessionAsync(db.async_context, index_ref, token, 1, true);
                    session_active = false;
                    try std.testing.expectEqual(@as(?u64, covered), db.core.index_manager.denseIndex("dv_v1").?.index.experimentalPostingDurableAppliedSequence());
                }
                const chunk_key = try internal_keys.chunkArtifactKeyAlloc(alloc, "doc:a", "body_chunks_v1", 0);
                defer alloc.free(chunk_key);
                const key = if (chunked) try internal_keys.derivedEmbeddingArtifactKeyAlloc(alloc, chunk_key, "body_dense_v1") else try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:a", "body_dense_v1");
                defer alloc.free(key);
                if (mutation == .delete) {
                    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, key));
                    try std.testing.expectEqual(@as(u64, 0), db.core.index_manager.denseIndex("dv_v1").?.index.metadata.active_count);
                } else {
                    const value = try db.core.store.get(alloc, key);
                    defer alloc.free(value);
                    try expectDenseEmbeddingArtifactValue(alloc, value, enrichment_artifact_codec.hashSource(if (mutation == .recreate) "old source" else "new source"), 3);
                    const vector = try enrichment_artifact_codec.decodeDenseEmbeddingAlloc(alloc, value);
                    defer alloc.free(vector);
                    try std.testing.expectEqualSlices(f32, &.{ 2, 2, 2 }, vector);
                    try std.testing.expectEqual(@as(u64, 1), db.core.index_manager.denseIndex("dv_v1").?.index.metadata.active_count);
                }
            }
        }
    }
}

pub fn testDenseSourceHashReuse(settings: table_storage_mod.Settings) !void {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .table_storage = settings,
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = counting.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
    });

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"same source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 1), counting.calls);
    if (db.local_execution.source_vectors.load(.acquire)) |source| {
        const key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:a", "body_dense_v1");
        defer alloc.free(key);
        const before = source.stats.resolved_payloads;
        try std.testing.expectEqual(
            @as(?u64, enrichment_artifact_codec.hashSource("same source")),
            try storedOrPendingEmbeddingSourceHash(&db, null, key),
        );
        try std.testing.expectEqual(before, source.stats.resolved_payloads);
    }

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"same source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 1), counting.calls);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"new source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 2), counting.calls);

    const artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:a", "body_dense_v1");
    defer alloc.free(artifact_key);
    const artifacts = try db.core.store.scanPrefix(alloc, artifact_key);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);
    try std.testing.expectEqual(@as(usize, 1), artifacts.len);
    try expectDenseEmbeddingArtifactValue(alloc, artifacts[0].value, enrichment_artifact_codec.hashSource("new source"), 3);

    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expectEqual(@as(u64, 1), stats.enrichment.skip_by_hash_count);
    try std.testing.expectEqual(@as(u64, 0), stats.enrichment.codec_decode_failures);
    try std.testing.expect(stats.enrichment.dense_artifact_bytes_written >= @as(u64, @intCast(artifacts[0].value.len * 2)));
    try std.testing.expectEqual(stats.enrichment.dense_artifact_bytes_written, stats.enrichment.artifact_bytes_written);
}

