    try noteTargetAdvanceDebtLogged(db.async_context, "dv_v1", monotonicTimeNs());
    try std.testing.expect(try db.deleteIndex("dv_v1"));
    db.backend_runtime.durable_jobs.drainOwner(db.repair_cleanup_owner_id);
