test "db cached chunk cleanup survives another failed shared batch request" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var gated = GateDenseEmbedder{
        .allowed_successes = .init(3),
        .blocked_error = error.UnsupportedEmbeddingProvider,
    };
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
        },
    });
    defer db.close();
    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":8,\"chunk_overlap\":2,\"embedding_name\":\"chunk_dense_v1\"}}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "doc:b", .value = "{\"body\":\"abcdefghijklmno\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 3), gated.snapshot().successful_requests);

    // A's new chunk stays in the shared batch. B's retained first chunk is
    // cached, but its two obsolete chunks still need deletion when A fails.
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"qrstuvwx\"}" },
            .{ .key = "doc:b", .value = "{\"body\":\"abcdefgh\"}" },
        },
        .sync_level = .write,
    });
    try std.testing.expectError(error.EnrichmentWorkerFailed, db.runUntilIdle());
    try std.testing.expect(gated.snapshot().blocked_requests > 0);

    const prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:b", "chunk", "body_chunks_v1");
    defer alloc.free(prefix);
    const artifacts = try db.core.store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);
    var embeddings: usize = 0;
    for (artifacts) |entry| {
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) embeddings += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), embeddings);
}

test "db sparse enrichment skips unchanged source hash" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var counting = CountingSparseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .enrichment = .{
            .owner_id = "worker-a",
            .sparse_embedder = counting.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "sp_v1",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse_embedding\",\"generator\":{\"kind\":\"sparse_embedding\",\"source_field\":\"body\"}}",
    });

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"same source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 1), counting.calls);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"same source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 1), counting.calls);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"new source\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(usize, 2), counting.calls);

    const artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:a", "sp_v1");
    defer alloc.free(artifact_key);
    const artifacts = try db.core.store.scanPrefix(alloc, artifact_key);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);
    try std.testing.expectEqual(@as(usize, 1), artifacts.len);
    try expectSparseEmbeddingArtifactValue(alloc, artifacts[0].value, enrichment_artifact_codec.hashSource("new source"), 2);

    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expectEqual(@as(u64, 1), stats.enrichment.skip_by_hash_count);
    try std.testing.expectEqual(@as(u64, 0), stats.enrichment.codec_decode_failures);
    try std.testing.expect(stats.enrichment.sparse_artifact_bytes_written >= @as(u64, @intCast(artifacts[0].value.len * 2)));
    try std.testing.expectEqual(stats.enrichment.sparse_artifact_bytes_written, stats.enrichment.artifact_bytes_written);
}

test "db runUntilIdle drains enrichment and derived indexing" {
