test "db write sync trailing dense no-op batches drain stale delete replay at idle" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "embedded-worker",
            .dense_embedder = deterministic.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"semantic_content\",\"embedding_name\":\"semantic_idx\"}}",
    });

    for (1..4) |i| {
        var key_buf: [32]u8 = undefined;
        var value_buf: [128]u8 = undefined;
        const key = try std.fmt.bufPrint(&key_buf, "text-{d}", .{i});
        const value = try std.fmt.bufPrint(
            &value_buf,
            "{{\"content\":\"t{d}\",\"semantic_content\":\"unique payload {d}\"}}",
            .{ i, i },
        );
        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .write,
        });
    }

    for (1..4) |i| {
        var key_buf: [32]u8 = undefined;
        var value_buf: [128]u8 = undefined;
        const key = try std.fmt.bufPrint(&key_buf, "plain-{d}", .{i});
        const value = try std.fmt.bufPrint(&value_buf, "{{\"content\":\"plain {d}\"}}", .{i});
        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .write,
        });
    }

    var drained = false;
    var attempts: usize = 0;
    while (attempts < slow_test_wait_attempts) : (attempts += 1) {
        const stats = try db.runtimeStatusStatsConsistent(alloc);
        defer types.freeDBStats(alloc, stats);
        if (stats.indexes.len != 1) {
            sleepPollInterval();
            continue;
        }
        const index = stats.indexes[0];
        if (index.doc_count == 3 and
            index.replay_applied_sequence >= index.replay_target_sequence and
            !index.replay_catch_up_required and
            index.catch_up_phase == .idle)
        {
            drained = true;
            break;
        }
        sleepPollInterval();
    }
    try std.testing.expect(drained);

    const query_vec = try deterministic.interface().embedDense(alloc, "semantic_idx", "unique payload 1", 3);
    defer alloc.free(query_vec);
    {
        var result = try waitForDenseSearchResultWithAttempts(alloc, &db, .{
            .index_name = "semantic_idx",
            .dense = .{ .vector = query_vec, .k = 3 },
            .limit = 3,
        }, 1, slow_test_wait_attempts);
        defer result.deinit();
        try std.testing.expectEqualStrings("text-1", result.hits[0].id);
    }

    try db.batch(.{
        .deletes = &.{"text-1"},
        .sync_level = .write,
    });

    var delete_drained = false;
    attempts = 0;
    while (attempts < slow_test_wait_attempts) : (attempts += 1) {
        const stats = try db.runtimeStatusStatsConsistent(alloc);
        defer types.freeDBStats(alloc, stats);
        if (stats.indexes.len != 1) {
            sleepPollInterval();
            continue;
        }
        const index = stats.indexes[0];
        if (index.doc_count == 2 and
            index.replay_applied_sequence >= index.replay_target_sequence and
            !index.replay_catch_up_required and
            index.catch_up_phase == .idle)
        {
            delete_drained = true;
            break;
        }
        sleepPollInterval();
    }
    try std.testing.expect(delete_drained);

    var after_delete = try db.search(alloc, .{
        .index_name = "semantic_idx",
        .dense = .{ .vector = query_vec, .k = 3 },
        .limit = 3,
    });
    defer after_delete.deinit();
    try std.testing.expectEqual(@as(u32, 2), after_delete.total_hits);
    for (after_delete.hits) |hit| {
        try std.testing.expect(!std.mem.eql(u8, hit.id, "text-1"));
    }
}

test "db runUntilIdle drains lazy dense posting maintenance" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"use_quantization\":false,\"lazy_posting_maintenance\":true,\"auto_posting_maintenance_max_postings\":0}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"embedding\":[1.0,0.0]}" },
            .{ .key = "doc:b", .value = "{\"embedding\":[3.0,0.0]}" },
        },
        .sync_level = .full_index,
    });

    {
        const entry = db.core.denseIndex("dv_v1") orelse return error.IndexNotFound;
        try entry.index.markNodePostingDirtyForTest(entry.index.metadata.root_node);
    }

    {
        const stats = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 1), stats.indexes[0].hbc_posting.dirty_postings);
    }

    try db.runUntilIdle();

    {
        const stats = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 0), stats.indexes[0].hbc_posting.dirty_postings);
        try std.testing.expect(stats.indexes[0].hbc_posting.maintenance_repaired_postings > 0);
    }
}

test "db posting refresh status follows verification and invalidates cached observations" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    var db = try DB.open(alloc, path_tmp.path(), .{});
    defer db.close();
    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"use_quantization\":false}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "a", .value = "{\"embedding\":[1.0,0.0]}" }},
        .sync_level = .full_index,
    });
    const entry = db.core.denseIndex("dv_v1").?;
    const manager = entry.index.resource_manager;
    entry.index.resource_manager = null;
    defer entry.index.resource_manager = manager;
    try entry.index.markNodePostingDirtyForTest(entry.index.metadata.root_node);
    {
        const status = try db.runtimeStatusStatsConsistent(alloc);
        defer types.freeDBStats(alloc, status);
        try std.testing.expect(status.indexes[0].hbc_posting.refresh_pending);
    }
    for (0..16) |_| {
        if (!(try entry.index.refreshPostingPayloadPage(1, 1)).pending) break;
    }
    try std.testing.expect(!entry.index.postingRefreshPending());
    var cached = try db.runtimeStatusStatsConsistent(alloc);
    defer types.freeDBStats(alloc, cached);
    try std.testing.expect(!cached.indexes[0].hbc_posting.refresh_pending);
    {
        const diagnostic = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, diagnostic);
        try std.testing.expect(!diagnostic.indexes[0].hbc_posting.refresh_pending);
    }
    try entry.index.markNodePostingDirtyForTest(entry.index.metadata.root_node);
    try db.overlayRuntimeStatusConsistent(alloc, &cached);
    try std.testing.expect(cached.indexes[0].hbc_posting.refresh_pending);
}

