/// Drive only the bounded source-discovery phase owned by managed admission,
/// then let the ordinary enrichment runtime publish those durable requests.
/// Tests use this boundary instead of `runUntilIdle()` alone: admission is
/// intentionally O(1), so maintenance—not DDL—owns the existing-corpus scan.
pub fn drainManagedAdmissionSourceReplayForTest(db: *DB, alloc: Allocator, repair_id: u128) !void {
    for (0..1024) |_| {
        var entry = try db.loadIndexRepairEntryById(alloc, repair_id);
        const state = entry.intent.source_replay_state;
        entry.deinit(alloc);
        if (state != .pending) {
            try db.runUntilIdle();
            // Managed dense admission begins with an explicit rebuilding
            // checkpoint. Mirror the production maintenance round which
            // publishes the exact stable-tip certificate after enrichment
            // has committed its terminal outcome tuple.
            _ = try db.finalizeDenseProjectionLifecycleForIdle();
            return;
        }
        const advanced = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
        try std.testing.expect(advanced.attempted);
        try std.testing.expect(advanced.deferred);
        try std.testing.expect(!advanced.repaired);
        try std.testing.expect(!advanced.terminal);
    }
    return error.TestExpectedEqual;
}

/// Source replay completion can start a background full checkpoint. Tests
/// which freeze or inspect its publication certificate must await that
/// distinct boundary before changing the corpus or removing the worker.
fn awaitManagedAdmissionPublicationForTest(db: *DB, alloc: Allocator, repair_id: u128) !void {
    var entry = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer entry.deinit(alloc);
    const deadline = monotonicTimeNs() +| 10 * std.time.ns_per_s;
    while (true) {
        _ = try db.finalizeDenseProjectionLifecycleForIdle();
        const checkpoint = try db.core.loadProjectionCheckpoint(alloc, entry.intent.index_name);
        if (checkpoint.published_count != null and
            try db.managedAdmissionGenerationIsServiceable(alloc, entry.intent)) return;
        if (monotonicTimeNs() >= deadline) return error.TestUnexpectedResult;
        sleepNs(std.time.ns_per_ms);
    }
}

test "index repair inspection window is bounded and rotates fairly" {
    const candidate_count = 257;
    var seen = @as([candidate_count]bool, @splat(false));
    var cursor: u64 = 0;
    var pass: usize = 0;
    while (pass < 33) : (pass += 1) {
        const window = DB.indexRepairInspectionWindow(candidate_count, 1, cursor);
        try std.testing.expectEqual(@as(usize, 8), window.budget);
        var offset: usize = 0;
        while (offset < window.budget) : (offset += 1) {
            seen[(window.start + offset) % candidate_count] = true;
        }
        cursor = @intCast((window.start + window.budget) % candidate_count);
    }
    for (seen) |inspected| try std.testing.expect(inspected);
}

test "resident index repair scheduler skips deferred prefixes with bounded fair quanta" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
    defer db.close();
    _ = try db.indexRepairIntentSummary(alloc);

    {
        lockAtomic(&db.async_context.index_repair_scheduler_mutex);
        defer db.async_context.index_repair_scheduler_mutex.unlock();
        for (0..18) |i| {
            const index_name = try std.fmt.allocPrint(alloc, "repair-{d}", .{i});
            var intent = index_repair_state.IndexRepairIntent{
                .repair_id = i + 1,
                .db_identity = 1,
                .group_id = 1,
                .replica_id = 1,
                .root_generation = 1,
                .index_name = index_name,
                .kind = .full_text,
                .config_hash = 1,
                .detected_sequence = 1,
                .target_sequence = 1,
                .started_at_ms = 1,
                .updated_at_ms = 1,
                .owner_epoch = 0,
                .automation = if (i < 17) .paused else .enabled,
            };
            try db.async_context.index_repair_scheduler.upsert(db.async_context.alloc, intent, 1);
            intent.deinit(alloc);
        }
    }

    // Exact migration repair bypasses unrelated paused prefixes without
    // consuming the ordinary scheduler's fairness cursor.
    const cursor_before = db.async_context.index_repair_scheduler.cursor;
    var targeted = try db.selectIndexRepairSchedulerQuantumForIndex(alloc, 1, "repair-17");
    defer targeted.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), targeted.inspected);
    try std.testing.expectEqual(@as(usize, 1), targeted.repairs.items.len);
    try std.testing.expectEqual(@as(usize, 1), targeted.remaining);
    try std.testing.expectEqual(@as(usize, 0), targeted.deferred);
    try std.testing.expectEqual(@as(u128, 18), targeted.repairs.items[0].repair_id);
    try std.testing.expectEqual(cursor_before, db.async_context.index_repair_scheduler.cursor);
    var paused_target = try db.selectIndexRepairSchedulerQuantumForIndex(alloc, 1, "repair-0");
    defer paused_target.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), paused_target.repairs.items.len);
    try std.testing.expectEqual(@as(usize, 1), paused_target.deferred);
    var absent_target = try db.selectIndexRepairSchedulerQuantumForIndex(alloc, 1, "absent");
    defer absent_target.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), absent_target.inspected);
    try std.testing.expectEqual(@as(usize, 0), absent_target.remaining);
    const target_summary = try db.indexRepairIntentSummaryForIndex(alloc, "repair-17");
    try std.testing.expectEqual(@as(usize, 1), target_summary.runnable);
    try std.testing.expectEqual(@as(usize, 0), target_summary.paused);
    try std.testing.expectEqual(@as(usize, 1), (try db.indexRepairIntentSummaryForIndex(alloc, "repair-0")).paused);
    try std.testing.expectEqual(@as(usize, 0), (try db.indexRepairIntentSummaryForIndex(alloc, "absent")).runnable);

    var first = try db.selectIndexRepairSchedulerQuantum(alloc, 1);
    defer first.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 8), first.inspected);
    try std.testing.expectEqual(@as(usize, 0), first.repairs.items.len);

    var second = try db.selectIndexRepairSchedulerQuantum(alloc, 1);
    defer second.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 8), second.inspected);
    try std.testing.expectEqual(@as(usize, 0), second.repairs.items.len);

    var third = try db.selectIndexRepairSchedulerQuantum(alloc, 1);
    defer third.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 8), third.inspected);
    try std.testing.expectEqual(@as(usize, 1), third.repairs.items.len);
    try std.testing.expectEqual(@as(u128, 18), third.repairs.items[0].repair_id);
    try std.testing.expect(!third.repairs.items[0].audit_due);
}

test "index repair intent string replacement is allocation failure safe" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
    defer db.close();
    try db.addIndex(.{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"external\":true}",
    });
    const cfg = db.core.index_manager.get("dense_idx") orelse return error.TestUnexpectedResult;
    const repair_id = try db.createGenerationRepairIntent(
        alloc,
        cfg.*,
        .operator_generation_validation,
        0,
        0,
        "old-error",
    );
    try db.updateIndexRepairIntent(alloc, repair_id, .{
        .candidate_relative_path = ".repair-shadow-old/indexes/dense_idx",
        .replace_candidate_path = true,
        .previous_pointer_captured = true,
        .previous_active_relative_path = ".repair-shadow-old-active/indexes/dense_idx",
        .replace_previous_active_path = true,
        .build_resume_key = "old-resume",
        .replace_build_resume_key = true,
        .last_error = "old-error-2",
        .replace_last_error = true,
    });

    try platform.allocator.checkAllAllocationFailures(
        alloc,
        struct {
            fn run(failing_alloc: Allocator, target_db: *DB, target_repair_id: u128) !void {
                try target_db.updateIndexRepairIntent(failing_alloc, target_repair_id, .{
                    .candidate_relative_path = ".repair-shadow-new/indexes/dense_idx",
                    .replace_candidate_path = true,
                    .previous_active_relative_path = ".repair-shadow-new-active/indexes/dense_idx",
                    .replace_previous_active_path = true,
                    .build_resume_key = "new-resume",
                    .replace_build_resume_key = true,
                    .last_error = "new-error",
                    .replace_last_error = true,
                });
            }
        }.run,
        .{ &db, repair_id },
    );
    try platform.allocator.checkAllAllocationFailures(
        alloc,
        struct {
            fn run(failing_alloc: Allocator, target_db: *DB, target_repair_id: u128) !void {
                try target_db.recordIndexRepairAttemptFailure(
                    failing_alloc,
                    target_repair_id,
                    "next-failure",
                    false,
                );
            }
        }.run,
        .{ &db, repair_id },
    );

    var updated = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer updated.deinit(alloc);
    try std.testing.expectEqualStrings(".repair-shadow-new/indexes/dense_idx", updated.intent.candidate_relative_path.?);
    try std.testing.expectEqualStrings(".repair-shadow-new-active/indexes/dense_idx", updated.intent.previous_active_relative_path.?);
    try std.testing.expectEqualStrings("new-resume", updated.intent.build_resume_key.?);
    try std.testing.expectEqualStrings("next-failure", updated.intent.last_error.?);
    try std.testing.expectEqual(@as(u32, 1), updated.intent.failure_streak);
}

test "repair admission revisions stay fail closed and reject delayed publishers" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
    defer db.close();
    try std.testing.expect(db.async_context.index_repair_scheduler.initialized);

    const name = "revisioned-repair";
    var older = try db.core.index_manager.beginRepairAdmissionFence(name);
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    const version = index_manager_mod.IndexManager.RepairAdmissionVersion{
        .repair_id = 7,
        .control_revision = 3,
        .revision = 3,
        .config_hash = 11,
        .root_generation = 13,
    };
    // A later non-fenced durable mutation may publish before an earlier
    // blocking fence's callback. Durable control order, not callback/fence
    // order, decides which committed state survives.
    db.core.index_manager.publishRepairAdmission(name, version, false, false);
    // The older transition is still between precommit fencing and publication.
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    var older_version = version;
    older_version.control_revision = 2;
    older_version.revision = 2;
    db.core.index_manager.finishRepairAdmissionFence(&older, name, older_version, true, false);
    // Its delayed revision cannot overwrite the newer serviceable decision.
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));

    var committed = try db.core.index_manager.beginRepairAdmissionFence(name);
    var committed_version = version;
    committed_version.control_revision = 4;
    committed_version.revision = 4;
    db.core.index_manager.finishRepairAdmissionFence(&committed, name, committed_version, true, false);
    db.core.index_manager.clearUnscopedRepairUnavailable(name);
    // Clearing an unrelated structural/legacy marker cannot open a durable
    // repair fence.
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    db.core.index_manager.publishRepairServiceabilityProof(name, committed_version);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));
    // Durable debt remains resident for exact revision checks, but aggregate
    // availability reports the effective service gate, not map occupancy.
    try std.testing.expect(!db.core.index_manager.hasRepairUnavailableIndexes());
    var progress_version = version;
    progress_version.control_revision = 5;
    progress_version.revision = 5;
    db.core.index_manager.publishRepairAdmission(name, progress_version, true, true);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));
    var unsafe_transition = try db.core.index_manager.beginRepairAdmissionFence(name);
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    db.core.index_manager.cancelRepairAdmissionFence(&unsafe_transition, name);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));
    var replacement_fence = try db.core.index_manager.beginRepairAdmissionFence(name);
    const replacement_version = index_manager_mod.IndexManager.RepairAdmissionVersion{
        .repair_id = 8,
        .control_revision = 6,
        .revision = 1,
        .config_hash = 12,
        .root_generation = 13,
    };
    db.core.index_manager.finishRepairAdmissionFence(
        &replacement_fence,
        name,
        replacement_version,
        true,
        false,
    );
    db.core.index_manager.publishRepairServiceabilityProof(name, committed_version);
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    var cleared_version = replacement_version;
    cleared_version.control_revision = 7;
    cleared_version.revision = 2;
    db.core.index_manager.publishRepairAdmission(name, cleared_version, false, false);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));

    var rebound_version = replacement_version;
    rebound_version.repair_id = 9;
    rebound_version.root_generation = 14;
    rebound_version.control_revision = 1;
    try db.core.index_manager.prepareRepairAdmissionRebind(name, rebound_version);
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    // A delayed old-root completion cannot claim the preallocated new-root
    // gate or make the replacement incarnation serviceable.
    var old_root_fence = try db.core.index_manager.beginRepairAdmissionFence(name);
    db.core.index_manager.finishRepairAdmissionFence(
        &old_root_fence,
        name,
        cleared_version,
        false,
        false,
    );
    db.core.index_manager.publishRepairAdmission(name, cleared_version, false, false);
    try std.testing.expect(db.core.index_manager.repairUnavailable(name));
    db.core.index_manager.publishRepairAdmission(name, rebound_version, false, false);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));

    var cancelled = try db.core.index_manager.beginRepairAdmissionFence(name);
    db.core.index_manager.cancelRepairAdmissionFence(&cancelled, name);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(name));
}

test "db progressive managed admission serves a checkpointed partial generation" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    // Keep exactly one published vector available while the rest of the
    // producer queue is retryable. That makes the partial-generation proof
    // deterministic without disabling the canonical index worker whose
    // applied sequence is part of the publication certificate.
    var gated = GateDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = gated.interface() },
    });
    defer db.close();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
        .sync_level = .write,
    });

    const admission_fence = db.core.nextDerivedSequence();
    const cfg = types.IndexConfig{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"body","dims":3,"metric":"cosine","embedding_name":"semantic_idx","publication_policy":"progressive","execution":{"embedding":{"batch_items":1}},"generator":{"kind":"dense_embedding","source_field":"body","embedding_name":"semantic_idx"}}
        ,
        .coverage_generation = 45,
    };
    const repair_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    const admission_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try std.testing.expectEqual(apply_state.ProjectionStatus.rebuilding, admission_checkpoint.status);
    try std.testing.expect(db.executor.appliedSequence(cfg.name) != null);
    try std.testing.expectEqual(admission_fence, try db.core.loadAppliedSequence(alloc, cfg.name));
    try std.testing.expectError(error.IndexRebuilding, db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 3 } },
        .limit = 3,
    }));

    // Publish the first admission seed, then grow the source corpus without a
    // full-index wait. The active generation remains a safe one-document
    // checkpoint while coverage becomes 1/3.
    try drainManagedAdmissionSourceReplayForTest(&db, alloc, repair_id);
    try awaitManagedAdmissionPublicationForTest(&db, alloc, repair_id);
    // The canonical worker was required to mint the real publication
    // certificate above. Pause it after that boundary so this unit test can
    // advance the artifact target and corrupt/restore the certificate one
    // transition at a time; process-level worker concurrency is covered by the
    // standalone restart regression.
    db.executor.removeWorker(cfg.name);
    db.start_index_workers = false;
    // Freeze provider progress only after the admission seed is completely
    // certified. New writes can now advance durable producer debt, but cannot
    // race the exact one-vector snapshot asserted below.
    gated.allowed_successes.store(gated.snapshot().successful_requests, .release);
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:b", .value = "{\"body\":\"beta\"}" },
            .{ .key = "doc:c", .value = "{\"body\":\"gamma\"}" },
        },
        .sync_level = .write,
    });
    var repair = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer repair.deinit(alloc);
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    const partial_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, partial_stats);
    var saw_partial_repair_degraded = false;
    for (partial_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        try std.testing.expect(index_stats.index_repair_active_generation_serviceable);
        saw_partial_repair_degraded = index_stats.repair_degraded;
    }
    try std.testing.expect(!saw_partial_repair_degraded);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(cfg.name));
    try db.failIfIndexQuarantined(cfg.name);

    // The next producer batch can publish its artifact target before the HBC
    // reaches the matching visibility boundary. Reproduce that short window:
    // the durable publication certificate must keep the last exact HBC
    // snapshot queryable while the live target advances.
    const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, cfg.name);
    defer alloc.free(counter_key);
    const target_before = (try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, cfg.name)).?;
    const certified_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try std.testing.expectEqual(@as(?u64, target_before), certified_checkpoint.published_count);
    var advanced_target: [8]u8 = undefined;
    std.mem.writeInt(u64, &advanced_target, target_before + 1, .little);
    try db.core.store.put(counter_key, &advanced_target);
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    const in_flight_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, in_flight_stats);
    for (in_flight_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        try std.testing.expect(index_stats.index_repair_active_generation_serviceable);
    }
    try db.failIfIndexQuarantined(cfg.name);

    // Model a newer live count before its next checkpoint. Native generations
    // reject direct HBC writes, so change only the published stats observation.
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        entry.index.published_active_count.store(target_before + 1, .release);
        defer entry.index.published_active_count.store(target_before, .release);
        try std.testing.expectEqual(target_before + 1, entry.index.stats().active_count);
        try std.testing.expectEqual(target_before, entry.index.servingActiveCountForCheckpoint().?);
        var ahead_checkpoint = certified_checkpoint;
        ahead_checkpoint.published_count = target_before + 1;
        try std.testing.expect(!entry.validateServingCertificate(ahead_checkpoint));
        var unspecified_checkpoint = certified_checkpoint;
        unspecified_checkpoint.published_count = null;
        try db.core.saveProjectionCheckpoint(cfg.name, unspecified_checkpoint);
        const written_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
        try std.testing.expectEqual(@as(?u64, target_before), written_checkpoint.published_count);
        const ahead_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, ahead_stats);
        for (ahead_stats.indexes) |index_stats| {
            if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
            try std.testing.expect(index_stats.serving_snapshot_ready);
            try std.testing.expectEqual(target_before, index_stats.doc_count);
        }
    }

    // The certificate is not a blanket cardinality bypass: if the loaded
    // physical snapshot no longer matches the exact published count, fail
    // closed even though source coverage and the live target look healthy.
    try db.core.saveProjectionCheckpoint(cfg.name, .{
        .applied_sequence = certified_checkpoint.applied_sequence,
        .status = certified_checkpoint.status,
        .generation = certified_checkpoint.generation,
        .config_hash = certified_checkpoint.config_hash,
        .published_count = target_before + 1,
    });
    try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    const mismatched_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, mismatched_stats);
    for (mismatched_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        try std.testing.expect(!index_stats.serving_snapshot_ready);
    }
    // Reopen may recover an older immutable native WAL prefix while a
    // sidecar names a later unfinished source window. Only that explicit
    // open-boundary proof may keep the older prefix queryable; the live
    // mismatched certificate above remains closed.
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        var advanced_checkpoint = certified_checkpoint;
        advanced_checkpoint.published_count = target_before + 1;
        try std.testing.expect(entry.validateRecoveredNativeServingCertificate(advanced_checkpoint));
        const recovered_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, recovered_stats);
        for (recovered_stats.indexes) |index_stats| {
            if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
            try std.testing.expect(index_stats.serving_snapshot_ready);
            try std.testing.expectEqual(target_before, index_stats.doc_count);
        }
        entry.recovered_native_serving_certificate = null;
        var older_checkpoint = certified_checkpoint;
        older_checkpoint.published_count = target_before - 1;
        try std.testing.expect(!entry.validateRecoveredNativeServingCertificate(older_checkpoint));

        // Native posting authority also outlives an optional sidecar whose
        // count was never written for the newest source boundary.
        var missing_checkpoint = advanced_checkpoint;
        missing_checkpoint.published_count = null;
        try apply_state.saveProjectionCheckpointWithSidecar(
            alloc,
            db.core.index_manager.checkpointIo(),
            db.core.store,
            db.core.applied_sequence_checkpoint_path,
            cfg.name,
            missing_checkpoint,
        );
        try std.testing.expect(entry.validateRecoveredNativeServingCertificate(missing_checkpoint));
        const missing_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, missing_stats);
        for (missing_stats.indexes) |index_stats| {
            if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
            try std.testing.expect(index_stats.serving_snapshot_ready);
            try std.testing.expectEqual(target_before, index_stats.doc_count);
        }
        entry.recovered_native_serving_certificate = null;
        try apply_state.saveProjectionCheckpointWithSidecar(
            alloc,
            db.core.index_manager.checkpointIo(),
            db.core.store,
            db.core.applied_sequence_checkpoint_path,
            cfg.name,
            advanced_checkpoint,
        );
    }
    // A later live write can happen to reach the invalid certificate's
    // cardinality. Status may observe it, but only a publication boundary may
    // establish a new durable proof for this checkpoint identity.
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        entry.index.published_active_count.store(target_before + 1, .release);
        defer entry.index.published_active_count.store(target_before, .release);
        const coincidental_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, coincidental_stats);
        for (coincidental_stats.indexes) |index_stats| {
            if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
            try std.testing.expect(!index_stats.serving_snapshot_ready);
        }
    }
    var legacy_checkpoint = certified_checkpoint;
    legacy_checkpoint.published_count = null;
    try db.core.saveProjectionCheckpoint(cfg.name, legacy_checkpoint);
    const legacy_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, legacy_stats);
    for (legacy_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        try std.testing.expect(index_stats.serving_snapshot_ready);
    }
    try db.core.saveProjectionCheckpoint(cfg.name, certified_checkpoint);
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    var restored_target: [8]u8 = undefined;
    std.mem.writeInt(u64, &restored_target, target_before, .little);
    try db.core.store.put(counter_key, &restored_target);

    var partial = try db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 3 } },
        .limit = 3,
    });
    defer partial.deinit();
    try std.testing.expectEqual(@as(u32, 1), partial.total_hits);
    try std.testing.expect(try db.hasPendingIndexRepairIntents(alloc));

    // A selected repair owner must recheck partial publication immediately
    // before committing preflight, just as it rechecks complete publication.
    // The provider remains held: a shadow cannot complete this source debt.
    const late_partial = blk: {
        try std.testing.expect(try db.beginIndexRepairLease(cfg.name));
        defer db.endIndexRepairLease(cfg.name);
        break :blk try db.repairIndexIssuesWithRequest(alloc, .{
            .target = .index,
            .index_name = cfg.name,
            .force = true,
        }, .{}, .already_held);
    };
    try std.testing.expectEqual(@as(u64, 0), late_partial.indexes_rebuilt);
    try std.testing.expect(late_partial.debt_remaining);
    {
        var retained_admission = try db.loadIndexRepairEntryById(alloc, repair_id);
        defer retained_admission.deinit(alloc);
        try std.testing.expectEqual(index_repair_state.Phase.detected, retained_admission.intent.phase);
        try std.testing.expectEqual(@as(?[]u8, null), retained_admission.intent.candidate_relative_path);
        try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, retained_admission.intent));
    }

    // Lazy centroid/payload refresh is performance maintenance, not index
    // reconstruction. Persist a dirty posting before the restart proof: the
    // certified generation must stay queryable and the startup planner must
    // not turn this debt into a repair admission gate.
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        try entry.index.markNodePostingDirtyForTest(entry.index.metadata.root_node);
        try std.testing.expect((try entry.index.postingBacklogStats()).hasMaintenanceDebt());
    }

    // A queryable progressive intent remains durable while its worker
    // converges, but it must not consume the bounded scheduler's only repair
    // slot and starve a later damaged index. Keep this intent oldest, then
    // prove a one-slot pass advances the second intent.
    while (currentTimeNs() / std.time.ns_per_ms <= repair.intent.started_at_ms) {
        std.atomic.spinLoopHint();
    }
    try db.addIndex(.{
        .name = "damaged_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"cosine\",\"external\":true}",
    });
    const damaged_cfg = db.core.index_manager.get("damaged_idx") orelse return error.TestUnexpectedResult;
    const damaged_repair_id = try db.createOperatorGenerationRepairIntent(alloc, damaged_cfg.*, 0, 0);
    const scheduler_pass = try db.repairRecoverableStartupIndexFailures(alloc, 1, repair_completion_test_options);
    try std.testing.expectEqual(@as(usize, 1), scheduler_pass.attempted);
    try std.testing.expectEqual(@as(usize, 2), scheduler_pass.inspected);
    try std.testing.expect((try db.indexRepairIdForIndex(alloc, cfg.name)) != null);
    {
        lockAtomic(&db.async_context.index_repair_scheduler_mutex);
        defer db.async_context.index_repair_scheduler_mutex.unlock();
        const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
            return error.TestUnexpectedResult;
        const partial_record = db.async_context.index_repair_scheduler.records.items[partial_record_index];
        // The durable admission fence is already published. The live derived
        // target continues moving as normal embeddings arrive, but that must
        // not arm a next-sequence repair wake for each batch.
        try std.testing.expectEqual(@as(?u64, null), partial_record.progress_wait_until_sequence);
        try std.testing.expect(partial_record.audit_wait_armed);
        try std.testing.expect(partial_record.next_retry_at_ms > currentTimeNs() / std.time.ns_per_ms);
    }
    {
        // Model the bounded audit deadline expiring. Selection must carry
        // that authority and the exact durable revision into one scheduled
        // execution; otherwise the queryable shortcut either rearms another
        // deadline forever or applies stale authority to a newer intent.
        {
            lockAtomic(&db.async_context.index_repair_scheduler_mutex);
            defer db.async_context.index_repair_scheduler_mutex.unlock();
            const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
                return error.TestUnexpectedResult;
            const partial_record = &db.async_context.index_repair_scheduler.records.items[partial_record_index];
            partial_record.next_retry_at_ms = 0;
            db.async_context.index_repair_scheduler.rescheduleRunnable(repair_id);
        }

        var audit_selection = try db.selectIndexRepairSchedulerQuantum(alloc, 2);
        defer audit_selection.deinit(alloc);
        var selected_due_audit: ?DB.IndexRepairSchedulerSelection.Repair = null;
        for (audit_selection.repairs.items) |scheduled| {
            if (scheduled.repair_id == repair_id) selected_due_audit = scheduled;
        }
        const stale_audit = selected_due_audit orelse return error.TestUnexpectedResult;
        try std.testing.expect(stale_audit.audit_due);

        const RevisionRace = struct {
            selected_revision: u64,
            revised_revision: u64 = 0,

            fn afterAcquire(raw: *anyopaque, target_db: *DB, observed_repair_id: u128) !void {
                const self: *@This() = @ptrCast(@alignCast(raw));
                var before = try target_db.loadIndexRepairEntryById(std.testing.allocator, observed_repair_id);
                defer before.deinit(std.testing.allocator);
                try std.testing.expectEqual(self.selected_revision, before.intent.revision);
                try target_db.updateIndexRepairIntent(std.testing.allocator, observed_repair_id, .{
                    .next_retry_at_ms = 0,
                });
                var after = try target_db.loadIndexRepairEntryById(std.testing.allocator, observed_repair_id);
                defer after.deinit(std.testing.allocator);
                self.revised_revision = after.intent.revision;
            }
        };
        var revision_race = RevisionRace{ .selected_revision = stale_audit.revision };
        DB.test_index_repair_advance_lease_hook = .{
            .ptr = &revision_race,
            .after_acquire = RevisionRace.afterAcquire,
        };
        defer DB.test_index_repair_advance_lease_hook = null;
        const stale_attempt = try db.advanceScheduledIndexRepairIntent(
            alloc,
            stale_audit.repair_id,
            repair_completion_test_options,
            stale_audit.revision,
            stale_audit.audit_due,
        );
        DB.test_index_repair_advance_lease_hook = null;
        try std.testing.expect(revision_race.revised_revision > stale_audit.revision);
        try std.testing.expect(stale_attempt.deferred);
        try std.testing.expect(!stale_attempt.attempted);
        {
            lockAtomic(&db.async_context.index_repair_scheduler_mutex);
            defer db.async_context.index_repair_scheduler_mutex.unlock();
            const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
                return error.TestUnexpectedResult;
            const partial_record = db.async_context.index_repair_scheduler.records.items[partial_record_index];
            try std.testing.expectEqual(revision_race.revised_revision, partial_record.revision);
            try std.testing.expect(partial_record.audit_wait_armed);
            try std.testing.expect(partial_record.next_retry_at_ms > currentTimeNs() / std.time.ns_per_ms);
        }

        // A transition can also win after the repair owner has reloaded its
        // entry. Audit authority is consumed later, at the queryable shortcut,
        // so that boundary must revalidate the durable revision rather than
        // trusting the owned turn's earlier snapshot.
        {
            lockAtomic(&db.async_context.index_repair_scheduler_mutex);
            defer db.async_context.index_repair_scheduler_mutex.unlock();
            const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
                return error.TestUnexpectedResult;
            const partial_record = &db.async_context.index_repair_scheduler.records.items[partial_record_index];
            partial_record.next_retry_at_ms = 0;
            db.async_context.index_repair_scheduler.rescheduleRunnable(repair_id);
        }
        var after_reload_selection = try db.selectIndexRepairSchedulerQuantum(alloc, 2);
        defer after_reload_selection.deinit(alloc);
        var selected_after_reload: ?DB.IndexRepairSchedulerSelection.Repair = null;
        for (after_reload_selection.repairs.items) |scheduled| {
            if (scheduled.repair_id == repair_id) selected_after_reload = scheduled;
        }
        const after_reload_audit = selected_after_reload orelse return error.TestUnexpectedResult;
        try std.testing.expect(after_reload_audit.audit_due);
        var after_reload_race = RevisionRace{ .selected_revision = after_reload_audit.revision };
        DB.test_index_repair_advance_lease_hook = .{
            .ptr = &after_reload_race,
            .after_reload = RevisionRace.afterAcquire,
        };
        const superseded_attempt = try db.advanceScheduledIndexRepairIntent(
            alloc,
            after_reload_audit.repair_id,
            repair_completion_test_options,
            after_reload_audit.revision,
            after_reload_audit.audit_due,
        );
        DB.test_index_repair_advance_lease_hook = null;
        try std.testing.expect(after_reload_race.revised_revision > after_reload_audit.revision);
        try std.testing.expect(superseded_attempt.busy);
        try std.testing.expect(!superseded_attempt.attempted);
        const rearm_after_reload_race = try db.advanceIndexRepairIntent(
            alloc,
            repair_id,
            repair_completion_test_options,
        );
        try std.testing.expect(rearm_after_reload_race.deferred);
        try std.testing.expect(!rearm_after_reload_race.attempted);
    }
    if (try db.indexRepairIdForIndex(alloc, "damaged_idx")) |remaining_repair_id| {
        try std.testing.expectEqual(damaged_repair_id, remaining_repair_id);
        var damaged_repair = try db.loadIndexRepairEntryById(alloc, damaged_repair_id);
        defer damaged_repair.deinit(alloc);
        try std.testing.expect(damaged_repair.intent.attempt_count != 0);
    }

    // Corpus convergence, physical projection health, and safe publication are
    // separate state machines. A crash can leave a replay cursor after the
    // physical checkpoint was already committed clean. That cursor is not
    // authority to replay the same artifacts over a serviceable publication.
    const rebuild_state_path = try db.denseIndexRebuildStatePathAlloc(alloc, cfg.name);
    defer alloc.free(rebuild_state_path);
    const rebuild_state = backfill_state_mod.RebuildState.init(rebuild_state_path);
    try rebuild_state.update("stale-completed-cursor");
    const partial_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try std.testing.expectEqual(apply_state.ProjectionStatus.clean, partial_checkpoint.status);
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    var clean_restart_plan = try db.collectDenseArtifactRebuildPlan(alloc);
    defer clean_restart_plan.deinit(alloc);
    for (clean_restart_plan.targets) |target| {
        const planned = db.core.index_manager.dense_indexes.items[target.dense_index_idx].config.name;
        try std.testing.expect(!std.mem.eql(u8, planned, cfg.name));
    }
    try std.testing.expect(!(try db.denseArtifactRebuildMaintenanceNeeded(alloc)));

    // Preserve the incomplete lifecycle marker too: a rebuilding checkpoint
    // can describe ongoing convergence without revoking the exact published
    // generation proved above.
    try db.core.saveProjectionCheckpoint(cfg.name, .{
        .applied_sequence = partial_checkpoint.applied_sequence,
        .status = .rebuilding,
        .generation = partial_checkpoint.generation,
        .config_hash = partial_checkpoint.config_hash,
        .published_count = partial_checkpoint.published_count,
    });
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    var restart_plan = try db.collectDenseArtifactRebuildPlan(alloc);
    defer restart_plan.deinit(alloc);
    for (restart_plan.targets) |target| {
        const planned = db.core.index_manager.dense_indexes.items[target.dense_index_idx].config.name;
        try std.testing.expect(!std.mem.eql(u8, planned, cfg.name));
    }

    // A managed owner can claim a newer Raft/root epoch during the same turn
    // that received an audit grant. The ownership write must invalidate the
    // prior revision's grant and preserve the progressive publication.
    const ownership_audit_rearm = try db.advanceIndexRepairIntent(
        alloc,
        repair_id,
        repair_completion_test_options,
    );
    try std.testing.expect(ownership_audit_rearm.deferred);
    try std.testing.expect(!ownership_audit_rearm.attempted);
    {
        lockAtomic(&db.async_context.index_repair_scheduler_mutex);
        defer db.async_context.index_repair_scheduler_mutex.unlock();
        const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
            return error.TestUnexpectedResult;
        const partial_record = &db.async_context.index_repair_scheduler.records.items[partial_record_index];
        partial_record.next_retry_at_ms = 0;
        db.async_context.index_repair_scheduler.rescheduleRunnable(repair_id);
    }
    var ownership_selection = try db.selectIndexRepairSchedulerQuantum(alloc, 2);
    defer ownership_selection.deinit(alloc);
    var selected_ownership_audit: ?DB.IndexRepairSchedulerSelection.Repair = null;
    for (ownership_selection.repairs.items) |scheduled| {
        if (scheduled.repair_id == repair_id) selected_ownership_audit = scheduled;
    }
    const ownership_audit = selected_ownership_audit orelse return error.TestUnexpectedResult;
    const AlwaysCurrentOwner = struct {
        fn current(_: *anyopaque) anyerror!bool {
            return true;
        }
    };
    var owner_context: u8 = 0;
    var owned_audit_options = repair_completion_test_options;
    owned_audit_options.owner_epoch = 17;
    owned_audit_options.activation_check = .{
        .ptr = &owner_context,
        .is_current_owner = AlwaysCurrentOwner.current,
    };
    const ownership_handoff = blk: {
        // A producer runtime normally supplies another deferral edge after a
        // valid audit. Remove it for this one synchronous turn so stale audit
        // authority would observably fall through into shadow construction.
        const saved_enrichment_runtime = db.enrichment_runtime;
        db.enrichment_runtime = null;
        defer db.enrichment_runtime = saved_enrichment_runtime;
        break :blk try db.advanceScheduledIndexRepairIntent(
            alloc,
            ownership_audit.repair_id,
            owned_audit_options,
            ownership_audit.revision,
            ownership_audit.audit_due,
        );
    };
    try std.testing.expect(ownership_handoff.deferred);
    try std.testing.expect(!ownership_handoff.attempted);
    {
        var owned_entry = try db.loadIndexRepairEntryById(alloc, repair_id);
        defer owned_entry.deinit(alloc);
        try std.testing.expectEqual(@as(u64, 17), owned_entry.intent.owner_epoch);
        try std.testing.expect(owned_entry.intent.revision > ownership_audit.revision);
    }
    // Keep a producer fence outstanding while the index cursor is already
    // at that replay boundary. An exact audit consumes its token and rearms
    // convergence without replacing the certified partial generation.
    const pending_enrichment = (db.enrichment_runtime orelse return error.TestUnexpectedResult).stats();
    try std.testing.expect(pending_enrichment.applied_sequence < pending_enrichment.target_sequence);
    const producer_fence = pending_enrichment.target_sequence;
    var producer_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    producer_checkpoint.applied_sequence = @max(producer_checkpoint.applied_sequence, producer_fence);
    try db.core.saveProjectionCheckpoint(cfg.name, producer_checkpoint);
    // Lifecycle metadata cannot advance native WAL coverage. Model the
    // mutation-free replay boundary through its durable sequence authority.
    try db.core.saveAppliedSequence(cfg.name, producer_fence);
    try std.testing.expectEqual(producer_fence, try db.managedIndexAppliedSequence(alloc, cfg.name));
    try db.updateIndexRepairIntent(alloc, repair_id, .{ .target_sequence = producer_fence });
    const rearmed = try db.advanceIndexRepairIntent(alloc, repair_id, repair_completion_test_options);
    try std.testing.expect(rearmed.deferred);
    try std.testing.expect(!rearmed.attempted);
    var exact_audit_revision: u64 = 0;
    {
        lockAtomic(&db.async_context.index_repair_scheduler_mutex);
        defer db.async_context.index_repair_scheduler_mutex.unlock();
        const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
            return error.TestUnexpectedResult;
        const partial_record = &db.async_context.index_repair_scheduler.records.items[partial_record_index];
        try std.testing.expect(partial_record.audit_wait_armed);
        exact_audit_revision = partial_record.revision;
        partial_record.next_retry_at_ms = 0;
        db.async_context.index_repair_scheduler.rescheduleRunnable(repair_id);
    }
    var exact_selection = try db.selectIndexRepairSchedulerQuantum(alloc, 2);
    defer exact_selection.deinit(alloc);
    var selected_exact_audit: ?DB.IndexRepairSchedulerSelection.Repair = null;
    for (exact_selection.repairs.items) |scheduled| {
        if (scheduled.repair_id == repair_id) selected_exact_audit = scheduled;
    }
    const exact_audit = selected_exact_audit orelse return error.TestUnexpectedResult;
    try std.testing.expect(exact_audit.audit_due);
    try std.testing.expectEqual(exact_audit_revision, exact_audit.revision);
    const exact_attempt = blk: {
        // An expired audit must retain a certified partial generation even
        // without the shared producer runtime supplying a second wait fence.
        const saved_enrichment_runtime = db.enrichment_runtime;
        db.enrichment_runtime = null;
        defer db.enrichment_runtime = saved_enrichment_runtime;
        break :blk try db.advanceScheduledIndexRepairIntent(
            alloc,
            exact_audit.repair_id,
            repair_completion_test_options,
            exact_audit.revision,
            exact_audit.audit_due,
        );
    };
    try std.testing.expect(exact_attempt.deferred);
    try std.testing.expect(!exact_attempt.attempted);
    {
        lockAtomic(&db.async_context.index_repair_scheduler_mutex);
        defer db.async_context.index_repair_scheduler_mutex.unlock();
        const partial_record_index = db.async_context.index_repair_scheduler.by_id.get(repair_id) orelse
            return error.TestUnexpectedResult;
        const partial_record = db.async_context.index_repair_scheduler.records.items[partial_record_index];
        try std.testing.expectEqual(exact_audit_revision +| 1, partial_record.revision);
        try std.testing.expect(partial_record.audit_wait_armed);
        try std.testing.expect(partial_record.next_retry_at_ms > currentTimeNs() / std.time.ns_per_ms);
    }

    // Force a sidecar from the unfinished window across the real reopen.
    // The immutable WAL prefix must remain queryable until the next complete
    // publication supplies a matching count.
    const restart_checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    var mismatched_restart_checkpoint = restart_checkpoint;
    mismatched_restart_checkpoint.published_count = target_before + 1;
    try apply_state.saveProjectionCheckpointWithSidecar(
        alloc,
        db.core.index_manager.checkpointIo(),
        db.core.store,
        db.core.applied_sequence_checkpoint_path,
        cfg.name,
        mismatched_restart_checkpoint,
    );
    db.close();
    db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = gated.interface() },
    });
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    const reopened_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, reopened_stats);
    for (reopened_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        try std.testing.expect(index_stats.serving_snapshot_ready);
        try std.testing.expectEqual(target_before, index_stats.doc_count);
    }
    try db.core.saveProjectionCheckpoint(cfg.name, restart_checkpoint);
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        try std.testing.expect((try entry.index.postingBacklogStats()).hasMaintenanceDebt());
    }
    var restarted_partial = try db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 3 } },
        .limit = 3,
    });
    defer restarted_partial.deinit();
    try std.testing.expectEqual(@as(u32, 1), restarted_partial.total_hits);
    try std.testing.expect(try db.hasPendingIndexRepairIntents(alloc));

    gated.allowAll();
    try db.runUntilIdle();
    {
        const entry = db.core.denseIndex(cfg.name) orelse return error.IndexNotFound;
        try std.testing.expect(!(try entry.index.postingBacklogStats()).hasMaintenanceDebt());
    }
    try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    const shared_enrichment = db.enrichment_runtime orelse return error.TestUnexpectedResult;
    const enrichment_before_unrelated_work = shared_enrichment.stats();
    shared_enrichment.notifySequence(enrichment_before_unrelated_work.applied_sequence + 1);
    const enrichment_with_unrelated_work = shared_enrichment.stats();
    try std.testing.expect(enrichment_with_unrelated_work.applied_sequence < enrichment_with_unrelated_work.target_sequence);
    const completed = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));

    // Once empty-table admission has retired its repair intent, ordinary
    // writes can make source coverage incomplete again while the last
    // progressive publication remains safe. Restart preservation must use the
    // publication proof itself, not depend on the temporary admission record.
    try db.batch(.{
        .writes = &.{.{ .key = "doc:d", .value = "{\"body\":\"delta\"}" }},
        .sync_level = .write,
    });
    try std.testing.expect(try db.progressiveManagedGenerationIsQueryable(alloc, cfg.name));
    var post_admission_restart_plan = try db.collectDenseArtifactRebuildPlan(alloc);
    defer post_admission_restart_plan.deinit(alloc);
    for (post_admission_restart_plan.targets) |target| {
        const planned = db.core.index_manager.dense_indexes.items[target.dense_index_idx].config.name;
        try std.testing.expect(!std.mem.eql(u8, planned, cfg.name));
    }
}

test "db progressive managed sparse admission serves a checkpointed partial generation" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var deterministic = embedder_mod.DeterministicSparseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .sparse_embedder = deterministic.interface() },
    });
    defer db.close();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha concept\"}" }},
        .sync_level = .write,
    });

    const admission_fence = db.core.nextDerivedSequence();
    const cfg = types.IndexConfig{
        .name = "semantic_sparse",
        .kind = .sparse_vector,
        .config_json =
        \\{"field":"sparse_embedding","embedding_name":"semantic_sparse","publication_policy":"progressive","execution":{"embedding":{"batch_items":1}},"generator":{"kind":"sparse_embedding","source_field":"body","embedding_name":"semantic_sparse"}}
        ,
        .coverage_generation = 46,
    };
    const repair_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(admission_fence, try db.core.loadAppliedSequence(alloc, cfg.name));

    var query = try deterministic.interface().embedSparse(alloc, cfg.name, "alpha concept");
    defer query.deinit(alloc);
    try std.testing.expectError(error.IndexRebuilding, db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .sparse_knn = .{ .indices = query.indices, .values = query.values, .k = 3 } },
        .limit = 3,
    }));

    try drainManagedAdmissionSourceReplayForTest(&db, alloc, repair_id);
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:b", .value = "{\"body\":\"beta concept\"}" },
            .{ .key = "doc:c", .value = "{\"body\":\"gamma concept\"}" },
        },
        .sync_level = .write,
    });
    var repair = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer repair.deinit(alloc);
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    try db.failIfIndexQuarantined(cfg.name);

    var partial = try db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .sparse_knn = .{ .indices = query.indices, .values = query.values, .k = 3 } },
        .limit = 3,
    });
    defer partial.deinit();
    try std.testing.expectEqual(@as(u32, 1), partial.total_hits);
    try std.testing.expect(try db.hasPendingIndexRepairIntents(alloc));

    db.close();
    db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .sparse_embedder = deterministic.interface() },
    });
    try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, repair.intent));
    var restarted_partial = try db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .sparse_knn = .{ .indices = query.indices, .values = query.values, .k = 3 } },
        .limit = 3,
    });
    defer restarted_partial.deinit();
    try std.testing.expectEqual(@as(u32, 1), restarted_partial.total_hits);

    try db.runUntilIdle();
    try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    const completed = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
}

test "db status cannot reopen a quarantined generation from an older publication certificate" {
    try testManagedGenerationRepairAdmission(.quarantine);
}

test "db status retains certified canonical admission during shadow build handoff" {
    try testManagedGenerationRepairAdmission(.shadow_handoff);
}

test "db initial replay repair retains certified canonical admission during shadow reconstruction" {
    try testManagedGenerationRepairAdmission(.replay_handoff);
}

test "db coverage recovery admits a published generation after its admission marker retires" {
    try testManagedGenerationRepairAdmission(.coverage_recovery);
}

pub fn testManagedGenerationRepairAdmission(mode: enum { quarantine, shadow_handoff, replay_handoff, late_completion, coverage_recovery, coverage_lag }) !void {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = deterministic.interface() },
    });
    defer db.close();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
        .sync_level = .write,
    });
    const cfg = types.IndexConfig{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"body","dims":3,"metric":"cosine","embedding_name":"semantic_idx","publication_policy":"progressive","generator":{"kind":"dense_embedding","source_field":"body","embedding_name":"semantic_idx"}}
        ,
        .coverage_generation = 42,
    };
    const admission_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    try drainManagedAdmissionSourceReplayForTest(&db, alloc, admission_id);
    try awaitManagedAdmissionPublicationForTest(&db, alloc, admission_id);
    try std.testing.expect(try db.progressiveManagedGenerationIsQueryable(alloc, cfg.name));

    if (mode == .coverage_lag) {
        // Old binaries permanently quarantined catalog admission when a
        // concurrent source change made its shadow coverage incomplete.
        // The canonical checkpoint remains certified and must recover from
        // this durable state without resetting provider retry outcomes.
        try db.recordIndexRepairAttemptFailure(alloc, admission_id, "RepairSourceCoverageIncomplete", true);
        const resumed = try db.advanceIndexRepairIntent(alloc, admission_id, .{});
        try std.testing.expect(!resumed.terminal);
        try std.testing.expect(resumed.repaired);
        try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
        try db.failIfIndexQuarantined(cfg.name);
        var result = try db.search(alloc, .{
            .index_name = cfg.name,
            .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 1 } },
            .limit = 1,
        });
        defer result.deinit();
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        return;
    }

    if (mode == .coverage_recovery) {
        try db.removeIndexRepairIntentAndPin(alloc, admission_id);
        const recovery_id = try db.createGenerationRepairIntentAtTarget(
            alloc,
            cfg,
            .replay_artifact_unavailable,
            0,
            0,
            "generated_source_coverage_incomplete_after_replay",
            null,
            .pending,
            .initial_build,
        );
        var recovery = try db.loadIndexRepairEntryById(alloc, recovery_id);
        defer recovery.deinit(alloc);
        try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, recovery.intent));
        // A safe published snapshot can serve while discovery is pending,
        // but repair may only retire after source discovery has completed.
        try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, recovery.intent));
        try db.updateIndexRepairIntent(alloc, recovery_id, .{ .source_replay_state = .complete });
        var completed = try db.loadIndexRepairEntryById(alloc, recovery_id);
        defer completed.deinit(alloc);
        try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, completed.intent));
    }

    if (mode == .late_completion or mode == .coverage_recovery) {
        // Enter the selected owner's reconstruction path after the canonical
        // worker has finished, bypassing only the earlier scheduler probe.
        var ready_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, ready_stats);
        try db.failIfIndexQuarantined(cfg.name);
        try std.testing.expect(try db.beginIndexRepairLease(cfg.name));
        defer db.endIndexRepairLease(cfg.name);
        const repair = try db.repairIndexIssuesWithRequest(alloc, .{
            .target = .index,
            .index_name = cfg.name,
            .force = true,
        }, .{}, .already_held);
        try std.testing.expectEqual(@as(u64, 0), repair.indexes_rebuilt);
        try std.testing.expectEqual(@as(u64, 1), repair.repaired);
        try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
        try db.failIfIndexQuarantined(cfg.name);
        try std.testing.expect(db.overlayRuntimeStatusBestEffort(alloc, &ready_stats));
        for (ready_stats.indexes) |item| {
            if (!std.mem.eql(u8, item.name, cfg.name)) continue;
            try std.testing.expectEqual(@as(?u128, null), item.index_repair_id);
            try std.testing.expectEqual(types.IndexLifecycleWorkClass.none, item.index_lifecycle_work_class);
            try std.testing.expect(item.serving_snapshot_ready);
        }
        return;
    }

    var retained = try db.runtimeStatusStatsConsistent(alloc);
    defer types.freeDBStats(alloc, retained);

    if (mode == .shadow_handoff or mode == .replay_handoff) {
        // Selecting shadow work must not revoke a certified, still-resident
        // canonical snapshot. Serving it does not transfer repair ownership
        // or certify the replacement generation.
        try db.updateIndexRepairIntent(alloc, admission_id, .{
            .phase = .preflight,
            .trigger = if (mode == .replay_handoff) .replay_artifact_unavailable else null,
        });
        try db.refreshIndexRepairAvailabilityForIndex(alloc, cfg.name);
        try std.testing.expect(!db.core.index_manager.repairUnavailable(cfg.name));
        try std.testing.expect(db.overlayRuntimeStatusBestEffort(alloc, &retained));
        for (retained.indexes) |item| {
            if (!std.mem.eql(u8, item.name, cfg.name)) continue;
            try std.testing.expect(item.serving_snapshot_ready);
        }
        var result = try db.search(alloc, .{
            .index_name = cfg.name,
            .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 1 } },
            .limit = 1,
        });
        defer result.deinit();
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        try std.testing.expect(try db.hasPendingIndexRepairIntents(alloc));
        return;
    } else {
        const completed = try db.advanceIndexRepairIntent(alloc, admission_id, .{});
        try std.testing.expect(completed.repaired);
        // Damage discovery revokes the earlier publication certificate even
        // when its cursor and cardinality still match.
        _ = try db.createGenerationRepairIntent(alloc, cfg, .projection_generation_invalid, 0, 0, null);
    }
    // Only repair validation can reopen either gate. Sampling status must
    // retain the same admission decision as a query.
    try std.testing.expect(db.core.index_manager.repairUnavailable(cfg.name));
    try db.refreshIndexRepairAvailabilityForIndex(alloc, cfg.name);
    try std.testing.expect(db.core.index_manager.repairUnavailable(cfg.name));

    try std.testing.expect(db.overlayRuntimeStatusBestEffort(alloc, &retained));
    for (retained.indexes) |item| {
        if (!std.mem.eql(u8, item.name, cfg.name)) continue;
        try std.testing.expect(!item.serving_snapshot_ready);
    }
    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    for (stats.indexes) |item| {
        if (!std.mem.eql(u8, item.name, cfg.name)) continue;
        try std.testing.expect(!item.index_repair_active_generation_serviceable);
        try std.testing.expect(!item.serving_snapshot_ready);
    }
    try std.testing.expectError(error.IndexRebuilding, db.search(alloc, .{
        .index_name = cfg.name,
        .query = .{ .dense_knn = .{ .vector = &.{ 1.0, 0.0, 0.0 }, .k = 1 } },
        .limit = 1,
    }));
}

test "source recovery scheduler rotates source jobs within one table" {
    const a = std.testing.allocator;
    var directory = try TestDirectory.init("db");
    defer directory.cleanup();
    var db = try DB.open(a, std.mem.span(directory.path().ptr), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    const left = types.IndexConfig{ .name = "left", .kind = .full_text, .config_json = "{\"field\":\"body\"}" };
    const right = types.IndexConfig{ .name = "right", .kind = .full_text, .config_json = "{\"field\":\"body\"}" };
    try db.addIndex(left);
    try db.addIndex(right);
    const first = try db.createGenerationRepairIntentAtTarget(a, left, .replay_artifact_unavailable, 0, 0, null, null, .pending, .initial_build);
    const second = try db.createGenerationRepairIntentAtTarget(a, right, .replay_artifact_unavailable, 0, 0, null, null, .pending, .initial_build);
    var one = try db.selectIndexRepairSchedulerQuantumScoped(a, 1, null, true);
    defer one.deinit(a);
    var two = try db.selectIndexRepairSchedulerQuantumScoped(a, 1, null, true);
    defer two.deinit(a);
    try std.testing.expect(one.repairs.items[0].repair_id != two.repairs.items[0].repair_id);
    try std.testing.expect(one.repairs.items[0].repair_id == first or one.repairs.items[0].repair_id == second);
    try std.testing.expect(two.repairs.items[0].repair_id == first or two.repairs.items[0].repair_id == second);
    try std.testing.expect(one.inspected <= DB.index_repair_inspections_per_execution_slot);
    try std.testing.expect(two.inspected <= DB.index_repair_inspections_per_execution_slot);
}

test "producer readiness local receipt migration retires only after source and checkpoint proof" {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("db");
    defer directory.cleanup();
    var db = try DB.open(alloc, std.mem.span(directory.path().ptr), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .enable_without_producers = true },
    });
    defer db.close();
    try db.addEnrichment(.{ .name = "copied", .kind = .asset, .field = "body", .content_type = "text/plain", .producer_json = "{\"type\":\"copy\"}" });
    const cfg = types.IndexConfig{
        .name = "text",
        .kind = .full_text,
        .config_json =
        \\{"sources":[{"artifact":"copied"}]}
        ,
    };
    try db.addIndex(cfg);
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"silver submarine\"}" }}, .sync_level = .full_index });
    const id = try db.createGenerationRepairIntentAtTarget(alloc, cfg, .replay_artifact_unavailable, 0, 0, null, null, .complete, .initial_build);
    var entry = try db.loadIndexRepairEntryById(alloc, id);
    defer entry.deinit(alloc);
    try std.testing.expect(try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    // Synchronous publication precedes its replay invalidation turn. The
    // current revision's receipt must survive that turn after an overwrite.
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"gold submarine\"}" }}, .sync_level = .full_index });
    try std.testing.expect(try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    // An asynchronous overwrite keeps the identity's creation generation but
    // advances its primary revision. Its previous receipt must reopen debt.
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"bronze submarine\"}" }}, .sync_level = .write });
    try local_mutation.deleteDerivedCoverageForDocKeys(alloc, db.core.store, db.core.index_manager, cfg.name, &.{"doc"});
    {
        var proof = try db.core.index_manager.acquireWritePlanSnapshot();
        defer proof.release();
        const pending_scope = try artifact_producer_readiness.localScopeAlloc(alloc, cfg.name, "copied", proof.plan());
        defer alloc.free(pending_scope);
        const marker = try internal_keys.derivedCoverageOutcomeKeyAlloc(alloc, pending_scope, db.core.index_manager.coverageGenerationForIndex(cfg.name).?, "doc");
        defer alloc.free(marker);
        try std.testing.expectError(error.NotFound, db.core.store.get(alloc, marker));
    }
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"gold submarine\"}" }}, .sync_level = .full_index });
    try std.testing.expect(try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    // A repeated row must keep its producer revision even after another
    // document has advanced the table's replay sequence.
    var before_read = try db.core.store.beginReadTxn();
    const primary_before = try artifact_producer_readiness.localPrimaryRevision(alloc, &before_read, "doc");
    before_read.abort();
    try db.batch(.{ .writes = &.{.{ .key = "other", .value = "{\"body\":\"other submarine\"}" }}, .sync_level = .full_index });
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"gold submarine\"}" }}, .sync_level = .write });
    var after_read = try db.core.store.beginReadTxn();
    const primary_after = try artifact_producer_readiness.localPrimaryRevision(alloc, &after_read, "doc");
    after_read.abort();
    try std.testing.expectEqual(primary_before, primary_after);
    try local_mutation.deleteDerivedCoverageForDocKeys(alloc, db.core.store, db.core.index_manager, cfg.name, &.{ "doc", "doc" });
    try std.testing.expect(try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    const checkpoint = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try db.core.saveProjectionCheckpoint(cfg.name, .{
        .applied_sequence = checkpoint.applied_sequence,
        .generation = checkpoint.generation,
        .config_hash = checkpoint.config_hash,
        .status = .rebuilding,
    });
    try std.testing.expect(!try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    try db.core.saveProjectionCheckpoint(cfg.name, checkpoint);
    var plan = try db.core.index_manager.acquireWritePlanSnapshot();
    defer plan.release();
    const scope = try artifact_producer_readiness.localScopeAlloc(alloc, cfg.name, "copied", plan.plan());
    defer alloc.free(scope);
    const generation = db.core.index_manager.coverageGenerationForIndex(cfg.name).?;
    const key = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, scope, generation, "produced");
    defer alloc.free(key);
    try db.core.store.delete(key);
    try std.testing.expect(!try db.localArtifactSourceRecoveryIsServiceable(alloc, entry.intent));
    const held = try db.repairRecoverableStartupIndexFailures(alloc, 1, .{ .source_replay_only = true });
    try std.testing.expect(held.repaired == 0 and held.attempted == 0);
    var pending = try db.loadIndexRepairEntryById(alloc, id);
    defer pending.deinit(alloc);
    try std.testing.expect(pending.intent.candidate_relative_path == null);
    // Restoring the exact receipt proof permits retirement without rebuilding
    // or invoking any provider from this connection-owned control turn.
    try db.core.store.put(key, &std.mem.toBytes(std.mem.nativeToLittle(u64, 2)));
    _ = try DB.independentMaintenanceRun(&db, .repair);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
}

test "db empty managed index does not invent generated coverage recovery debt" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = deterministic.interface() },
    });
    defer db.close();
    try std.testing.expectEqual(@as(?u64, null), try range_cardinality.load(alloc, db.core.store));
    _ = try db.admitManagedIndex(.{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"body","dims":3,"metric":"cosine","embedding_name":"semantic_idx","publication_policy":"progressive","generator":{"kind":"dense_embedding","source_field":"body","embedding_name":"semantic_idx"}}
        ,
        .coverage_generation = 42,
    });
    // No primary mutation has created the range counter. The empty user-key
    // namespace nevertheless proves there are no missing source outcomes;
    // repeated idle audits must not create replacement work.
    try std.testing.expect(!try db.generatedCoverageReplayNeeded(alloc));
    try std.testing.expectEqual(@as(usize, 0), try db.ensureGeneratedCoverageRecoveryIntents(alloc));
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));

    // A legacy primary record can lack both local cardinality and identity
    // metadata. It must remain unknown even when identity counters look empty.
    const primary_key = try internal_keys.documentKeyAlloc(alloc, "doc:a");
    defer alloc.free(primary_key);
    try db.core.store.put(primary_key, "{\"body\":\"alpha\"}");
    try std.testing.expect(try db.generatedCoverageReplayNeeded(alloc));
}

test "db completed partial managed admission serves and retires redundant repair" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = deterministic.interface() },
    });
    defer db.close();
    try db.addEnrichment(.{
        .name = "thumbnail",
        .kind = .embedding,
        .field = "body",
        .expected_dims = 3,
    });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:covered", .value = "{\"body\":\"alpha\"}" },
            .{ .key = "doc:skipped", .value = "{\"title\":\"no embedding source\"}" },
        },
        .sync_level = .write,
    });

    const cfg = types.IndexConfig{
        .name = "thumbnail",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"body","dims":3,"metric":"cosine","embedding_name":"thumbnail","coverage_policy":"partial","generator":{"kind":"dense_embedding","source_field":"body","embedding_name":"thumbnail"}}
        ,
        .coverage_generation = 42,
    };
    const repair_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    try drainManagedAdmissionSourceReplayForTest(&db, alloc, repair_id);

    const active = db.core.index_manager.denseIndex(cfg.name) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 1), active.index.stats().active_count);
    var repair = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer repair.deinit(alloc);
    // Native checkpoint construction may finish asynchronously after the idle
    // finalizer returns. Await its durable proof, not merely task admission.
    const publication_deadline = monotonicTimeNs() +| 10 * std.time.ns_per_s;
    while (!try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent)) {
        if (monotonicTimeNs() >= publication_deadline) return error.TestUnexpectedResult;
        _ = try db.finalizeDenseProjectionLifecycleForIdle();
        platform.time.yieldNow();
    }
    try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));
    const runtime_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, runtime_stats);
    var saw_serviceable_generation = false;
    var saw_redundant_repair_degraded = true;
    for (runtime_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, cfg.name)) continue;
        saw_serviceable_generation = index_stats.index_repair_active_generation_serviceable;
        saw_redundant_repair_degraded = index_stats.repair_degraded;
    }
    try std.testing.expect(saw_serviceable_generation);
    try std.testing.expect(!saw_redundant_repair_degraded);

    // Query admission may prove the pinned active generation independently of
    // the background scheduler, while the next scheduler quantum durably
    // removes the obsolete intent and admission marker without a shadow build.
    try db.failIfIndexQuarantined(cfg.name);
    try std.testing.expect(!db.core.index_manager.repairUnavailable(cfg.name));
    const completed = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    try std.testing.expect(completed.attempted);
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
}

test "db completed generated recovery retires an inactive candidate without an admission marker" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = deterministic.interface() },
    });
    defer db.close();
    try db.addEnrichment(.{ .name = "thumbnail", .kind = .embedding, .field = "body", .expected_dims = 3 });
    try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }}, .sync_level = .write });
    const cfg: types.IndexConfig = .{
        .name = "thumbnail",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"body","dims":3,"metric":"cosine","embedding_name":"thumbnail","coverage_policy":"partial","generator":{"kind":"dense_embedding","source_field":"body","embedding_name":"thumbnail"}}
        ,
        .coverage_generation = 42,
    };
    const admission = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    try drainManagedAdmissionSourceReplayForTest(&db, alloc, admission);
    var admitted = try db.loadIndexRepairEntryById(alloc, admission);
    defer admitted.deinit(alloc);
    const deadline = monotonicTimeNs() +| 10 * std.time.ns_per_s;
    while (!try db.managedAdmissionGenerationIsServiceable(alloc, admitted.intent)) {
        if (monotonicTimeNs() >= deadline) return error.TestUnexpectedResult;
        _ = try db.finalizeDenseProjectionLifecycleForIdle();
        platform.time.yieldNow();
    }
    _ = try db.advanceIndexRepairIntent(alloc, admission, .{});
    const marker_key = try internal_keys.managedIndexAdmissionKeyAlloc(alloc, cfg.name);
    defer alloc.free(marker_key);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, marker_key));

    // Startup coverage discovery creates this different initial-build class,
    // without a catalog-admission marker. Foreground enrichment can complete
    // the canonical generation while its inactive shadow is still pending.
    const recovery = try db.createGenerationRepairIntentAtTarget(
        alloc,
        cfg,
        .replay_artifact_unavailable,
        0,
        0,
        "generated_source_coverage_incomplete_after_replay",
        null,
        .complete,
        .initial_build,
    );
    try db.updateIndexRepairIntent(alloc, recovery, .{ .phase = .preflight });
    try db.updateIndexRepairIntent(alloc, recovery, .{
        .phase = .building,
        .candidate_relative_path = ".repair-shadow-redundant/indexes/thumbnail",
        .replace_candidate_path = true,
    });
    var entry = try db.loadIndexRepairEntryById(alloc, recovery);
    defer entry.deinit(alloc);
    try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, entry.intent));
    var invalid = entry.intent;
    invalid.work_class = .repair;
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
    invalid = entry.intent;
    invalid.root_generation +%= 1;
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
    invalid = entry.intent;
    invalid.config_hash ^= 1;
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
    invalid = entry.intent;
    invalid.phase = .activating;
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
    invalid = entry.intent;
    invalid.source_replay_state = .pending;
    try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
    invalid = entry.intent;
    invalid.group_id +%= 1;
    try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
    invalid = entry.intent;
    invalid.source_replay_state = .not_required;
    try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
    const previous = try db.core.index_manager.captureActiveIndexRootPointer(cfg.name);
    defer if (previous) |value| alloc.free(value);
    for ([_]index_repair_state.Phase{ .activating, .validating }) |phase| {
        invalid = entry.intent;
        invalid.phase = phase;
        try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
        invalid.previous_pointer_captured = true;
        invalid.previous_active_relative_path = previous;
        try std.testing.expect(try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
        try std.testing.expect(!try db.managedAdmissionGenerationIsServiceable(alloc, invalid));
        invalid.previous_active_relative_path = invalid.candidate_relative_path;
        try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
        invalid.previous_active_relative_path = previous;
        invalid.phase = .rolling_back;
        try std.testing.expect(!try db.managedAdmissionGenerationIsQueryable(alloc, invalid));
    }
    const completed = try db.advanceIndexRepairIntent(alloc, recovery, .{});
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));
    try db.failIfIndexQuarantined(cfg.name);
}

test "db completed chunked managed admission uses physical artifact count" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{ .dense_embedder = counting.interface() },
    });
    defer db.close();
    const doc_count = 50;
    const writes = try alloc.alloc(types.BatchWrite, doc_count);
    defer {
        for (writes) |write| alloc.free(@constCast(write.key));
        alloc.free(writes);
    }
    for (writes, 0..) |*write, i| {
        write.* = .{
            .key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i}),
            .value = "{\"title\":\"same\",\"body\":\"alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu\"}",
        };
    }
    for (0..5) |batch_index| {
        const offset = batch_index * 10;
        try db.batch(.{ .writes = writes[offset .. offset + 10], .sync_level = .write });
    }

    const cfg = types.IndexConfig{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"embedding","dims":3,"generator":{"kind":"dense_embedding","source_field":"body","chunk_name":"semantic_idx_chunks","chunk_size":4,"chunk_overlap":1}}
        ,
        .coverage_generation = 43,
    };
    const repair_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
    try drainManagedAdmissionSourceReplayForTest(&db, alloc, repair_id);
    try awaitManagedAdmissionPublicationForTest(&db, alloc, repair_id);

    const active = db.core.index_manager.denseIndex(cfg.name) orelse return error.TestUnexpectedResult;
    const physical_count = active.index.stats().active_count;
    try std.testing.expect(physical_count > doc_count);
    const artifact_count = (try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, cfg.name)) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(artifact_count, physical_count);
    const publication_stats = try db.runtimeStatusStatsConsistent(alloc);
    defer types.freeDBStats(alloc, publication_stats);
    const publication_index = blk: {
        for (publication_stats.indexes) |index_stats| {
            if (std.mem.eql(u8, index_stats.name, cfg.name)) break :blk index_stats;
        }
        return error.TestUnexpectedResult;
    };
    try std.testing.expect(publication_index.publication_target_ready);
    try std.testing.expectEqual(physical_count, publication_index.publication_target_count);
    const calls_before_replay = counting.calls;
    try std.testing.expect(calls_before_replay > 0);
    const dense_replay_before = try db.core.store.latestReplaySequenceForHint(.dense_vector, 0);
    const enrichment_replay_before = try db.core.store.latestReplaySequenceForHint(.enrichment, 0);

    var repair = try db.loadIndexRepairEntryById(alloc, repair_id);
    defer repair.deinit(alloc);
    try std.testing.expect(try db.managedAdmissionGenerationIsServiceable(alloc, repair.intent));

    const completed = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    try std.testing.expect(completed.attempted);
    try std.testing.expect(completed.repaired);
    try std.testing.expect(!try db.hasPendingIndexRepairIntents(alloc));

    // Replaying structurally identical source documents must not enqueue new
    // embedding work, even when an API serializer changes object key order.
    const reordered_writes = try alloc.alloc(types.BatchWrite, doc_count);
    defer alloc.free(reordered_writes);
    for (reordered_writes, 0..) |*write, i| {
        write.* = .{
            .key = writes[i].key,
            .value = "{\"body\":\"alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu\",\"title\":\"same\"}",
        };
    }
    for (0..5) |batch_index| {
        const offset = batch_index * 10;
        try db.batch(.{ .writes = reordered_writes[offset .. offset + 10], .sync_level = .write });
    }
    try db.runUntilIdle();
    try std.testing.expectEqual(physical_count, active.index.stats().active_count);
    try std.testing.expectEqual(calls_before_replay, counting.calls);
    try std.testing.expectEqual(dense_replay_before, try db.core.store.latestReplaySequenceForHint(.dense_vector, 0));
    try std.testing.expectEqual(enrichment_replay_before, try db.core.store.latestReplaySequenceForHint(.enrichment, 0));
}

// Functional repair tests verify durable construction, activation, and reopen,
// not the production reader-pause SLA. A contended CI worker can exhaust the
// 250 ms production window. These construction tests reserve a larger pause;
// the activation-budget regression separately verifies cooperative yielding.
pub const repair_completion_test_options = types.ArtifactRepairRunOptions{
    .max_activation_pause_ms = 5_000,
};

test "db algebraic generation build yields and resumes from its durable source cursor" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    const cfg = types.IndexConfig{
        .name = "analytics_idx",
        .kind = .algebraic,
        .config_json =
        \\{"version":1,"table":"docs","group_fields":[{"name":"category","path":"category","type":"string"}],"materializations":[]}
        ,
    };
    test_algebraic_repair_rebuild_batch_size = 1;
    defer test_algebraic_repair_rebuild_batch_size = null;
    const Yield = struct {
        fn requested(_: *anyopaque) bool {
            return true;
        }
    };
    var yield_token: u8 = 0;
    var repair_id: u128 = 0;
    {
        var db = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
        defer db.close();
        try db.batch(.{
            .writes = &.{
                .{ .key = "doc:a", .value = "{\"category\":\"tools\"}" },
                .{ .key = "doc:b", .value = "{\"category\":\"books\"}" },
            },
            .sync_level = .write,
        });
        repair_id = (try db.admitManagedIndex(cfg)) orelse return error.TestUnexpectedResult;
        var yield_options = repair_completion_test_options;
        yield_options.yield_check = .{ .ptr = &yield_token, .is_requested = Yield.requested };
        const first = try db.advanceIndexRepairIntent(alloc, repair_id, yield_options);
        try std.testing.expect(first.attempted);
        try std.testing.expect(first.busy);
        try std.testing.expect(!first.repaired);
        try std.testing.expectEqual(@as(u64, 1), first.documents_reprocessed);

        var state = try db.loadIndexRepairState(alloc);
        defer state.deinit(alloc);
        const intent = state.entries.items[0].intent;
        try std.testing.expectEqual(index_repair_state.Phase.building, intent.phase);
        try std.testing.expect(intent.build_resume_key != null);
        try std.testing.expectEqual(@as(u64, 1), intent.build_reprocessed);
        const candidate = intent.candidate_relative_path orelse return error.TestUnexpectedResult;
        const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.TestUnexpectedResult;
        const storage_namespace = try std.fmt.allocPrint(
            alloc,
            "{s}/{s}",
            .{ candidate[0..separator], cfg.name },
        );
        defer alloc.free(storage_namespace);
        try std.testing.expect((try db.core.index_manager.algebraicStorageNamespaceBytes(storage_namespace)) > 0);
    }

    var reopened = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
    defer reopened.close();
    try std.testing.expectEqual(repair_id, (try reopened.indexRepairIdForIndex(alloc, cfg.name)).?);
    var repaired = false;
    for (0..16) |_| {
        const step = try reopened.advanceIndexRepairIntent(alloc, repair_id, repair_completion_test_options);
        if (step.repaired) {
            repaired = true;
            break;
        }
        try std.testing.expect(!step.terminal);
        try std.testing.expectEqual(@as(u64, 0), step.next_retry_at_ms);
    }
    try std.testing.expect(repaired);
    const active = reopened.core.index_manager.algebraicIndex(cfg.name) orelse return error.TestUnexpectedResult;
    var tools = (try active.index.resolvedDocFilterForFilterJsonAlloc(
        reopened.core.store,
        "{\"term\":{\"category\":\"tools\"}}",
    )) orelse return error.TestUnexpectedResult;
    defer tools.deinit(alloc);
    var books = (try active.index.resolvedDocFilterForFilterJsonAlloc(
        reopened.core.store,
        "{\"term\":{\"category\":\"books\"}}",
    )) orelse return error.TestUnexpectedResult;
    defer books.deinit(alloc);
    switch (tools.include) {
        .ordinals => |ordinals| try std.testing.expectEqual(@as(usize, 1), ordinals.len),
        else => return error.ExpectedOrdinalDocSet,
    }
    switch (books.include) {
        .ordinals => |ordinals| try std.testing.expectEqual(@as(usize, 1), ordinals.len),
        else => return error.ExpectedOrdinalDocSet,
    }
}

