    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);
}

test "db missing activation certification exposes predecessor action required" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_background_test_open);
    defer db.close();
    try db.addIndex(.{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"external\":true}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"_embeddings\":{\"dense_idx\":[1,0]}}" }},
        .sync_level = .full_index,
    });

    var interrupted = try interruptDenseRepairAfterActivation(alloc, &db);
    defer interrupted.deinit(alloc);
    const manifest_path = try std.fmt.allocPrint(
        alloc,
        "{s}/{s}/.antfly-index-generation",
        .{ std.mem.span(path), interrupted.candidate_relative_path },
    );
    defer alloc.free(manifest_path);
    try std.Io.Dir.cwd().deleteFile(std.testing.io, manifest_path);

    const CrashAfterRollback = struct {
        fn beforeRetry(_: *anyopaque, _: *DB, _: u128) !void {
            return error.TestCrashAfterUncertifiedRollback;
        }
    };
    var rollback_hook_ctx: u8 = 0;
    DB.test_index_repair_rollback_retry_hook = .{
        .ptr = &rollback_hook_ctx,
        .before_retry = CrashAfterRollback.beforeRetry,
    };
    defer DB.test_index_repair_rollback_retry_hook = null;
    try std.testing.expectError(
        error.TestCrashAfterUncertifiedRollback,
        db.advanceIndexRepairIntent(alloc, interrupted.repair_id, .{}),
    );
    DB.test_index_repair_rollback_retry_hook = null;
    var rolling_back = try db.loadIndexRepairEntryById(alloc, interrupted.repair_id);
    defer rolling_back.deinit(alloc);
    try std.testing.expectEqual(index_repair_state.Phase.rolling_back, rolling_back.intent.phase);
    try std.testing.expectEqualStrings("activation_manifest_missing", rolling_back.intent.last_error.?);
    try std.testing.expect(!try db.core.index_manager.isRepairCandidateActive(
        "dense_idx",
        interrupted.candidate_relative_path,
    ));
    try std.testing.expectEqual(
        interrupted.repair_id,
        db.core.index_manager.failedIndexLoadSnapshot("dense_idx").?.claim_owner_repair_id.?,
    );

    index_manager_mod.test_inject_index_open_error = error.InvalidIndexConfig;
    defer index_manager_mod.test_inject_index_open_error = null;
    const resumed = try db.advanceIndexRepairIntent(alloc, interrupted.repair_id, .{});
    index_manager_mod.test_inject_index_open_error = null;
    try std.testing.expect(resumed.attempted);
    try std.testing.expect(resumed.terminal);

    var terminal = try db.loadIndexRepairEntryById(alloc, interrupted.repair_id);
    defer terminal.deinit(alloc);
    try std.testing.expectEqual(index_repair_state.Phase.terminal, terminal.intent.phase);
    try std.testing.expectEqualStrings("activation_manifest_missing", terminal.intent.last_error.?);
    try std.testing.expect(terminal.intent.candidate_relative_path == null);
    try std.testing.expect(DB.indexRepairActionRequired(terminal.intent));

    const failure = db.core.index_manager.failedIndexLoadSnapshot("dense_idx") orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("InvalidIndexConfig", failure.err_name);
    try std.testing.expectEqual(
        index_manager_mod.IndexManager.IndexLoadRecoveryAction.manual_intervention,
        failure.token.action,
    );
    try std.testing.expect(failure.claim_owner_repair_id == null);
    const terminal_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, terminal_stats);
    var observed_terminal_status = false;
    for (terminal_stats.indexes) |item| {
        if (!std.mem.eql(u8, item.name, "dense_idx")) continue;
        observed_terminal_status = true;
        try std.testing.expectEqual(types.IndexRepairStatus.failed, item.index_repair_status.?);
        try std.testing.expect(item.index_repair_action_required);
        try std.testing.expectEqualStrings("activation_manifest_missing", item.index_repair_last_error.?);
        try std.testing.expectEqualStrings("InvalidIndexConfig", item.load_error.?);
    }
    try std.testing.expect(observed_terminal_status);
    try std.testing.expectError(error.IndexUnavailable, db.search(alloc, .{
        .index_name = "dense_idx",
        .query = .{ .dense_knn = .{ .vector = &.{ 1, 0 }, .k = 1 } },
        .limit = 1,
    }));
}

test "db failed activated dense generation rolls back to retained predecessor" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var repair_id: u128 = 0;
    var candidate_relative_path: ?[]u8 = null;
    defer if (candidate_relative_path) |value| alloc.free(value);
    {
        var db = try DB.open(alloc, std.mem.span(path), no_background_test_open);
        defer db.close();
        try db.addIndex(.{
            .name = "dense_idx",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"external\":true}",
        });
        try db.batch(.{
            .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"_embeddings\":{\"dense_idx\":[1,0]}}" }},
            .sync_level = .full_index,
        });

        // Activate one healthy shadow first so the fault below proves that a
        // later failed generation can roll back to a non-canonical predecessor
        // pointer, not only to the original canonical root.
        // Use the functional test budget for every activation so scheduling
        // delays do not prevent the intended crash checkpoint from being hit.
        var first_generation = try db.repairArtifactIssuesWithRequestOptions(alloc, .{
            .target = .index,
            .artifact_kind = .embedding,
            .index_name = "dense_idx",
            .limit = 1,
            .force = true,
        }, repair_completion_test_options);
        defer first_generation.deinit(alloc);
        try std.testing.expectEqual(@as(u64, 1), first_generation.indexes_rebuilt);
        try std.testing.expect(!first_generation.debt_remaining);
        const first_generation_pointer = (try db.core.index_manager.captureActiveIndexRootPointer("dense_idx")) orelse
            return error.TestUnexpectedResult;
        defer alloc.free(first_generation_pointer);

        const CrashHook = struct {
            fn afterSnapshot(_: *anyopaque, _: *DB, _: []const u8, _: u64) !void {}
            fn afterActivation(_: *anyopaque, _: *DB, _: []const u8) !void {
                return error.TestCrashBeforeReplacementValidation;
            }
        };
        var hook_ctx: u8 = 0;
        db.shadow_index_repair_hook = .{
            .ptr = &hook_ctx,
            .after_snapshot_build = CrashHook.afterSnapshot,
            .after_pointer_activation = CrashHook.afterActivation,
        };
        try std.testing.expectError(error.TestCrashBeforeReplacementValidation, db.repairArtifactIssuesWithRequestOptions(alloc, .{
            .target = .index,
            .artifact_kind = .embedding,
            .index_name = "dense_idx",
            .limit = 1,
            .force = true,
        }, repair_completion_test_options));
        db.shadow_index_repair_hook = null;
        repair_id = (try db.indexRepairIdForIndex(alloc, "dense_idx")) orelse return error.TestUnexpectedResult;
        var interrupted = try db.loadIndexRepairEntryById(alloc, repair_id);
        defer interrupted.deinit(alloc);
        try std.testing.expectEqual(index_repair_state.Phase.activating, interrupted.intent.phase);
        try std.testing.expect(interrupted.intent.previous_pointer_captured);
        try std.testing.expectEqualStrings(first_generation_pointer, interrupted.intent.previous_active_relative_path.?);
        candidate_relative_path = try alloc.dupe(u8, interrupted.intent.candidate_relative_path.?);
    }

    // Poison only the newly active candidate. The retained predecessor remains
    // valid, while this exact failure is eligible for automatic discovery and
    // can therefore exercise the rollback/retry ownership handoff.
    const candidate_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ std.mem.span(path), candidate_relative_path.? });
    defer alloc.free(candidate_path);
    const candidate_path_z = try alloc.dupeSentinel(u8, candidate_path, 0);
    defer alloc.free(candidate_path_z);
    {
        var hbc = try hbc_mod.HBCIndex.openWithLsmOptions(alloc, candidate_path_z, .{
            .dims = 2,
            .storage_backend = .lsm,
        }, .{});
        // Corrupt the selected generation through the format-agnostic fault
        // boundary. Native v2 has no generic namespace batch in which to
        // persist the legacy incomplete-bulk marker; dropping CURRENT models
        // the equivalent unpublished generation without weakening that rule.
        try hbc.markPublishedGenerationIncompleteForTest();
        hbc.close();
    }

    var reopened = try DB.open(alloc, std.mem.span(path), no_replay_no_background_test_open);
    defer reopened.close();
    try std.testing.expectEqualStrings(
        "MissingPostingCheckpoint",
        reopened.core.index_manager.loadFailure("dense_idx") orelse return error.TestUnexpectedResult,
    );

    const RollbackCheckpointCrash = struct {
        fn afterSnapshot(_: *anyopaque, _: *DB, _: []const u8, _: u64) !void {}

        fn afterPhase(_: *anyopaque, _: *DB, _: u128, phase: index_repair_state.Phase) !void {
            if (phase == .rolling_back) return error.TestCrashBeforeRollbackPointerRestore;
        }
    };
    var rollback_checkpoint_ctx: u8 = 0;
    reopened.shadow_index_repair_hook = .{
        .ptr = &rollback_checkpoint_ctx,
        .after_snapshot_build = RollbackCheckpointCrash.afterSnapshot,
        .after_phase_persisted = RollbackCheckpointCrash.afterPhase,
    };
    try std.testing.expectError(
        error.TestCrashBeforeRollbackPointerRestore,
        reopened.rollbackUnavailableActivatedIndexRepair(alloc, repair_id, null),
    );
    reopened.shadow_index_repair_hook = null;
    {
        var checkpointed = try reopened.loadIndexRepairEntryById(alloc, repair_id);
        defer checkpointed.deinit(alloc);
        try std.testing.expectEqual(index_repair_state.Phase.rolling_back, checkpointed.intent.phase);
        try std.testing.expect(try reopened.core.index_manager.isRepairCandidateActive(
            "dense_idx",
            checkpointed.intent.candidate_relative_path.?,
        ));
    }

    const RollbackDiscovery = struct {
        repair_id: u128,
        observed: bool = false,

        fn beforeRetry(raw: *anyopaque, db: *DB, observed_repair_id: u128) !void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(self.repair_id, observed_repair_id);
            var rolling_back = try db.loadIndexRepairEntryById(db.alloc, observed_repair_id);
            defer rolling_back.deinit(db.alloc);
            try std.testing.expectEqual(index_repair_state.Phase.rolling_back, rolling_back.intent.phase);
            const generic_retry = try db.retryQuarantinedIndexLoad("dense_idx", true);
            try std.testing.expectEqual(
                index_manager_mod.IndexManager.QuarantineRetryTargetOutcome.repair_claimed,
                generic_retry.target_outcome,
            );
            const discovery = try db.discoverRecoverableStartupIndexFailures(db.alloc, 1);
            try std.testing.expectEqual(@as(usize, 0), discovery.discovered);
            try std.testing.expectEqual(@as(usize, 1), discovery.already_pending);
            try std.testing.expectEqual(
                self.repair_id,
                db.core.index_manager.failedIndexLoadSnapshot("dense_idx").?.claim_owner_repair_id.?,
            );
            self.observed = true;
            return error.TestCrashAfterRollbackPointerRestore;
        }
    };
    var rollback_discovery = RollbackDiscovery{ .repair_id = repair_id };
    DB.test_index_repair_rollback_retry_hook = .{
        .ptr = &rollback_discovery,
        .before_retry = RollbackDiscovery.beforeRetry,
    };
    defer DB.test_index_repair_rollback_retry_hook = null;
    try std.testing.expectError(
        error.TestCrashAfterRollbackPointerRestore,
        reopened.rollbackUnavailableActivatedIndexRepair(alloc, repair_id, null),
    );
    try std.testing.expect(rollback_discovery.observed);
    {
        var interrupted_rollback = try reopened.loadIndexRepairEntryById(alloc, repair_id);
        defer interrupted_rollback.deinit(alloc);
        try std.testing.expectEqual(index_repair_state.Phase.rolling_back, interrupted_rollback.intent.phase);
        try std.testing.expect(!try reopened.core.index_manager.isRepairCandidateActive(
            "dense_idx",
            interrupted_rollback.intent.candidate_relative_path.?,
        ));
    }
    DB.test_index_repair_rollback_retry_hook = null;
    try std.testing.expectEqual(
        DB.ActivatedIndexRepairRollback.prior_generation_restored,
        try reopened.rollbackUnavailableActivatedIndexRepair(alloc, repair_id, null),
    );
    try std.testing.expect(reopened.core.index_manager.loadFailure("dense_idx") == null);

    // The previous generation is immediately serviceable after rollback,
    // before another corpus rebuild is attempted.
    var previous = try reopened.search(alloc, .{
        .index_name = "dense_idx",
        .query = .{ .dense_knn = .{ .vector = &.{ 1, 0 }, .k = 1 } },
        .limit = 1,
    });
    defer previous.deinit();
    try std.testing.expectEqual(@as(u32, 1), previous.total_hits);
    try std.testing.expectEqualStrings("doc:a", previous.hits[0].id);

    const rebuilt = try reopened.advanceIndexRepairIntent(alloc, repair_id, repair_completion_test_options);
    try std.testing.expect(rebuilt.attempted);
    try std.testing.expect(rebuilt.repaired);
    try std.testing.expect(!try reopened.hasPendingIndexRepairIntents(alloc));
}

test "db last dense catch-up lease finalizes every covered rebuilding generation" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    const configs = [_]types.IndexConfig{
        .{
            .name = "dense_a",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
        },
        .{
            .name = "dense_b",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
        },
    };
    for (configs) |config| try db.addIndex(config);
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"_embeddings\":{\"dense_a\":[1,0,0],\"dense_b\":[0,1,0]}}",
        }},
        .sync_level = .full_index,
    });

    for (configs) |config| {
        const entry = db.core.index_manager.denseIndex(config.name) orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(u64, 1), entry.index.stats().active_count);
        try std.testing.expectEqual(
            @as(?u64, 1),
            try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, config.name),
        );
    }

    // Stable-tip publication owns one posting generation even though its
    // exact-vector file is shared by the table. Preserve the independently
    // certified sibling instead of projecting the owner's short fence onto
    // every dense index.
    // This fixture disables index workers. Finish acceleration staging at
    // its idle boundary before testing certification: an online pass only
    // schedules checkpoint builders and may return while either is pending.
    _ = try db.publishVectorBlockBasesAtStableTip();
    for (configs) |config| {
        try std.testing.expect(db.core.index_manager.vectorBlockReadyForDenseIndexAtSequence(
            config.name,
            try db.core.loadAppliedSequence(alloc, config.name),
            1,
        ));
    }
    {
        const owner = db.core.index_manager.denseIndex(configs[0].name) orelse
            return error.TestUnexpectedResult;
        db.core.index_manager.vector_block_stable_tip_index.store(@intFromPtr(owner), .release);
        db.core.index_manager.vector_block_stable_tip_sequence.store(
            try db.core.loadAppliedSequence(alloc, configs[0].name),
            .release,
        );
        db.core.index_manager.vector_block_stable_tip_finalizing.store(true, .release);
        defer {
            db.core.index_manager.vector_block_stable_tip_sequence.store(0, .release);
            db.core.index_manager.vector_block_stable_tip_index.store(0, .release);
            db.core.index_manager.vector_block_stable_tip_finalizing.store(false, .release);
        }

        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        const owner_stats = for (stats.indexes) |item| {
            if (std.mem.eql(u8, item.name, configs[0].name)) break item;
        } else return error.TestUnexpectedResult;
        const sibling_stats = for (stats.indexes) |item| {
            if (std.mem.eql(u8, item.name, configs[1].name)) break item;
        } else return error.TestUnexpectedResult;
        try std.testing.expect(owner_stats.dense_vector_projection_pending);
        try std.testing.expect(!sibling_stats.dense_vector_projection_pending);
    }

    for (configs) |config| {
        const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, config.name);
        defer alloc.free(counter_key);
        var counter_value: [8]u8 = undefined;
        std.mem.writeInt(u64, &counter_value, 1, .little);
        try db.core.store.put(counter_key, &counter_value);

        const applied = try db.core.loadAppliedSequence(alloc, config.name);
        try db.core.saveProjectionCheckpoint(config.name, .{
            .applied_sequence = applied,
            .status = .rebuilding,
            .generation = 7,
            .config_hash = types.indexConfigHash(config),
        });
        try beginDenseCatchUpSessionTracked(db.async_context, config.name);
    }

    finishDenseCatchUpSessionTracked(db.async_context, configs[0].name);
    try std.testing.expect(!try finalizeCoveredDenseProjectionCheckpointsIfIdle(db.async_context));
    try std.testing.expect(try finishDenseCatchUpSessionTrackedAndFinalize(db.async_context, configs[1].name));

    for (configs) |config| {
        const checkpoint = try db.core.loadProjectionCheckpoint(alloc, config.name);
        try std.testing.expectEqual(apply_state.ProjectionStatus.clean, checkpoint.status);
        try std.testing.expectEqual(@as(u64, 8), checkpoint.generation);
    }
}

test "db multi-source dense target uses physical artifact cardinality" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    for ([_]types.EnrichmentConfig{
        .{ .name = "title_dense", .kind = .embedding, .field = "title", .expected_dims = 3, .vector_space = "test:multi-source" },
        .{ .name = "summary_dense", .kind = .embedding, .field = "summary", .expected_dims = 3, .vector_space = "test:multi-source" },
    }) |enrichment| try db.addEnrichment(enrichment);
    const config: types.IndexConfig = .{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\",\"sources\":[{\"artifact\":\"title_dense\"},{\"artifact\":\"summary_dense\"}]}",
        .coverage_generation = 42,
    };
    try db.addIndex(config);

    // A single source document may contribute one vector from each stream.
    // Its generation-scoped outcome count is one, while publication must wait
    // for both physical vectors.
    const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, config.name);
    defer alloc.free(counter_key);
    var counter_value: [8]u8 = undefined;
    std.mem.writeInt(u64, &counter_value, 2, .little);
    try db.core.store.put(counter_key, &counter_value);

    // Seed the complete per-source tuple too: without it the old implementation
    // takes its missing-outcomes artifact-counter fallback and passes this test.
    for ([_][]const u8{ "produced", "skipped", "terminal_failed" }, [_]u64{ 1, 0, 0 }) |outcome, count| {
        const key = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, config.name, 42, outcome);
        defer alloc.free(key);
        var value: [8]u8 = undefined;
        try db.core.store.put(key, internal_keys.encodeDerivedCoverageOutcomeCount(&value, count));
    }

    try std.testing.expectEqual(
        @as(?u64, 2),
        try denseTargetCountForIndexContext(db.async_context, config.name),
    );
}

test "db last external dense bulk lease finalizes covered rebuilding generations" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), no_background_test_open);
    defer db.close();

    const config: types.IndexConfig = .{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
    };
    try db.addIndex(config);
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"_embeddings\":{\"dense_idx\":[1,0,0]}}",
        }},
        .sync_level = .full_index,
    });

    // Establish the physical publication boundary before introducing the
    // rebuilding checkpoint. Online publication may leave an asynchronous
    // checkpoint builder pending; this fixture exercises bulk-lease release
    // against a generation whose coverage is already complete.
    _ = try db.publishVectorBlockBasesAtStableTip();

    const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, config.name);
    defer alloc.free(counter_key);
    var counter_value: [8]u8 = undefined;
    std.mem.writeInt(u64, &counter_value, 1, .little);
    try db.core.store.put(counter_key, &counter_value);
    const applied = try db.core.loadAppliedSequence(alloc, config.name);
    try db.core.saveProjectionCheckpoint(config.name, .{
        .applied_sequence = applied,
        .status = .rebuilding,
        .generation = 11,
        .config_hash = types.indexConfigHash(config),
    });

    try beginExternalDenseBulkSessionTracked(db.async_context);
    try std.testing.expect(try finishExternalDenseBulkSessionTrackedAndFinalize(db.async_context));

    const checkpoint = try db.core.loadProjectionCheckpoint(alloc, config.name);
    try std.testing.expectEqual(apply_state.ProjectionStatus.clean, checkpoint.status);
    try std.testing.expectEqual(@as(u64, 12), checkpoint.generation);

    // The worker claim is table-wide observability, not an index-local
    // readiness fence. Another dense index may begin projection work after
    // this generation becomes complete; the immutable generation token above
    // must remain independently serviceable.
    db.async_context.dense_admission.finalizing.store(true, .release);
    defer db.async_context.dense_admission.finalizing.store(false, .release);
    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    const dense_stats = for (stats.indexes) |item| {
        if (std.mem.eql(u8, item.name, config.name)) break item;
    } else return error.TestUnexpectedResult;
    try std.testing.expect(stats.async_indexing.dense_projection_finalizing);
    try std.testing.expect(!dense_stats.dense_vector_projection_pending);
}

test "db online vector publication leaves foreground and posting mutation admission open" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var vector_storage = lsm_backend_mod.MemoryStorage.init(alloc);
    defer vector_storage.deinit();
    var raced_vector_storage = lsm_backend_mod.MemoryStorage.init(alloc);
    defer raced_vector_storage.deinit();
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.addIndex(.{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"_embeddings\":{\"dense_idx\":[1,0,0]}}" }},
        .sync_level = .full_index,
    });
    const manager = db.core.index_manager;
    try db.runUntilIdle();
    // Model missing acceleration after a complete posting repair. Use a new
    // storage namespace instead of deleting files leased by the old reader.
    manager.clearVectorBlockGenerationForTest();
    manager.setVectorBlockStorage(vector_storage.storage());
    const dense = manager.denseIndex("dense_idx").?;
    try dense.index.markNodePostingDirtyForTest(dense.index.metadata.root_node);
    const before = try dense.index.postingBacklogStats();
    try std.testing.expect(before.hasMaintenanceDebt());
    const Probe = struct {
        db: *DB,
        calls: usize = 0,
        advance_source: bool = false,
        fn run(raw: *anyopaque) !void {
            const probe: *@This() = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(@as(u32, 1), probe.db.publishedDenseSearchCount());
            try std.testing.expect(probe.db.core.apply_mutex.tryLockExclusive());
            probe.db.core.apply_mutex.unlockExclusive();
            const entry = probe.db.core.index_manager.denseIndex("dense_idx").?;
            try std.testing.expect(entry.apply_mutex.tryLock());
            entry.apply_mutex.unlock();
            probe.calls += 1;
            if (probe.advance_source) {
                probe.advance_source = false;
                try probe.db.batch(.{
                    .writes = &.{.{ .key = "doc:b", .value = "{\"_embeddings\":{\"dense_idx\":[0,1,0]}}" }},
                    .sync_level = .write,
                });
            }
        }
    };
    var probe = Probe{ .db = &db };
    const previous_hook = index_manager_mod.test_before_vector_block_primary_snapshot_build;
    index_manager_mod.test_before_vector_block_primary_snapshot_build = .{ .ctx = &probe, .call = Probe.run };
    defer index_manager_mod.test_before_vector_block_primary_snapshot_build = previous_hook;
    try std.testing.expectEqual(@as(usize, 1), try db.publishVectorBlockBasesOnline(.{}));
    try std.testing.expectEqual(@as(usize, 1), probe.calls);
    try std.testing.expectEqualDeep(before, try dense.index.postingBacklogStats());
    try std.testing.expect(!db.nativeVectorProjectionMaintenanceNeeded());
    // A posting checkpoint queued before this pass may finish asynchronously.
    // The aggregate progress count includes that legitimate handoff; it cannot
    // prove whether the exact-vector plane was rebuilt. Compare its durable
    // generation and storage sync count, retaining the no-primary-scan check.
    // This fixture disables background vector-publication owners.
    const vector_generation = manager.vector_block_generation.?.opened.store.manifest.?.latest_generation;
    const vector_syncs = vector_storage.sync_contents_calls;
    _ = try db.publishVectorBlockBasesOnline(.{});
    try std.testing.expectEqual(vector_generation, manager.vector_block_generation.?.opened.store.manifest.?.latest_generation);
    try std.testing.expectEqual(vector_syncs, vector_storage.sync_contents_calls);
    try std.testing.expectEqual(@as(usize, 1), probe.calls);

    manager.clearVectorBlockGenerationForTest();
    manager.setVectorBlockStorage(raced_vector_storage.storage());
    probe.advance_source = true;
    // An actual source write may commit while the pinned snapshot is being
    // encoded. Without a native WAL suffix this attempt must decline rather
    // than publish a stale base as ready, and a later ordinary pass must retry.
    try std.testing.expectEqual(@as(usize, 0), try db.publishVectorBlockBasesOnline(.{}));
    try std.testing.expectEqual(@as(usize, 2), probe.calls);
    try std.testing.expect(db.nativeVectorProjectionMaintenanceNeeded());
    index_manager_mod.test_before_vector_block_primary_snapshot_build = null;
    try db.runUntilIdle();
    try std.testing.expect(!db.nativeVectorProjectionMaintenanceNeeded());
    try std.testing.expectEqual(@as(u32, 0), db.publishedDenseSearchCount());
    try std.testing.expect(db.beginIndexCatalogBarrierUntil(monotonicTimeNs() + std.time.ns_per_s));
    defer db.endIndexCatalogBarrier();
    // Structural retirement owns the catalog now. Optional publication must
    // yield before touching an index, rather than waiting under another fence.
    try std.testing.expectEqual(@as(usize, 0), try db.publishVectorBlockBasesOnline(.{}));
}

