test "db reverse graph probe rejects a deleted or replaced index incarnation" {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("graph-incarnation");
    defer directory.cleanup();
    const path = directory.path().ptr;
    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();
    const cfg = types.IndexConfig{ .name = "graph_idx", .kind = .graph, .config_json = "{}" };
    try db.addIndex(cfg);
    const previous = db.core.index_manager.coverageIdentityForIndex("graph_idx").?;
    try std.testing.expect(try db.deleteIndex("graph_idx"));
    // Even an empty probe must not certify a missing or replacement index.
    try std.testing.expectError(error.IndexGenerationMismatch, db.graphHasIncomingEdgesForInternalRead(alloc, "graph_idx", &.{}, previous, null));
    // Same-name admission waits for the retired incarnation's asynchronous
    // artifact cleanup. Join its owner instead of racing it or sleeping.
    db.backend_runtime.durable_jobs.drainOwner(db.repair_cleanup_owner_id);
    try db.addIndex(cfg);
    const current = db.core.index_manager.coverageIdentityForIndex("graph_idx").?;
    try std.testing.expect(previous.generation != current.generation);
    try std.testing.expectEqual(previous.config_fingerprint, current.config_fingerprint);
    try std.testing.expectError(error.IndexGenerationMismatch, db.graphHasIncomingEdgesForInternalRead(alloc, "graph_idx", &.{"absent"}, previous, null));
    const incoming = try db.graphHasIncomingEdgesForInternalRead(alloc, "graph_idx", &.{"absent"}, current, null);
    defer alloc.free(incoming);
    try std.testing.expectEqualSlices(bool, &.{false}, incoming);
}

test "db named graph input sets carry resolved doc sets" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "gr_v1",
        .kind = .graph,
        .config_json = "{}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "n:a", .value = "{\"title\":\"A\",\"_edges\":{\"gr_v1\":{\"links\":[{\"target\":\"n:b\"}]}}}" },
            .{ .key = "n:b", .value = "{\"title\":\"B\"}" },
        },
        .sync_level = .full_index,
    });

    const graph_queries = [_]types.NamedGraphQuery{.{
        .name = "neighbors",
        .query = .{
            .query_type = .neighbors,
            .index_name = "gr_v1",
            .start_nodes = .{ .result_ref = .{ .ref = "seed", .limit = 0 } },
            .params = .{ .direction = .out, .edge_types = &.{"links"} },
        },
    }};
    const input_sets = [_]types.NamedGraphInputSet{.{
        .name = "seed",
        .hit_ids = &.{"n:a"},
    }};

    try std.testing.expectError(error.UnsupportedQueryRequest, db.executeNamedGraphQueries(alloc, .{}, &graph_queries, &input_sets));

    const current_generation = db.core.nextDerivedSequence();
    const seed_hits = try db.graphInputSetHitsAlloc(alloc, &.{"n:a"}, current_generation);
    defer {
        for (seed_hits) |*hit| hit.deinit(alloc);
        if (seed_hits.len > 0) alloc.free(seed_hits);
    }
    const seed_ordinal = seed_hits[0].doc_ordinal orelse return error.TestUnexpectedResult;
    var identity_txn = try db.core.store.beginProbeTxn();
    defer identity_txn.abort();
    try std.testing.expectEqual(@as(?doc_set.DocOrdinal, seed_ordinal), try doc_identity.lookupOrdinalTxn(alloc, &identity_txn, "n:a"));

    const results = try db.executeNamedGraphQueries(alloc, .{
        .identity_read_generation = current_generation,
    }, &graph_queries, &input_sets);
    defer {
        for (results) |*result| result.deinit(alloc);
        if (results.len > 0) alloc.free(results);
    }

    try std.testing.expectEqual(@as(usize, 1), results.len);
    try std.testing.expectEqual(@as(u32, 1), results[0].total_hits);
    try std.testing.expectEqualStrings("n:b", results[0].hits[0].id);
    try std.testing.expectEqual(try doc_identity.lookupOrdinalTxn(alloc, &identity_txn, "n:b"), results[0].hits[0].doc_ordinal);
    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expect(stats.doc_set_planning.ordinal_list_count >= 1);
    try std.testing.expect(stats.doc_set_planning.ordinal_list_docs >= 1);

    const paged_input_sets = [_]types.NamedGraphInputSet{.{
        .name = "seed",
        .hit_ids = &.{"n:a"},
        .total_hits = 2,
    }};
    try std.testing.expectError(error.UnsupportedQueryRequest, db.executeNamedGraphQueries(alloc, .{
        .identity_read_generation = current_generation,
    }, &graph_queries, &paged_input_sets));

    try std.testing.expectError(error.IdentityReadGenerationChanged, db.executeNamedGraphQueries(alloc, .{
        .identity_read_generation = current_generation -| 1,
    }, &graph_queries, &input_sets));
}

test "db general profiled search retains direct and lowered dense telemetry" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db-direct-dense-profile");
    defer path_tmp.cleanup();
    var db = try DB.open(alloc, std.mem.span(path_tmp.path().ptr), .{});
    defer db.close();
    try db.addIndex(.{ .name = "vec", .kind = .dense_vector, .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\"}" });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"_embeddings\":{\"vec\":[1,0,0]}}" },
            .{ .key = "doc:b", .value = "{\"title\":\"beta\",\"_embeddings\":{\"vec\":[0,1,0]}}" },
        },
        .sync_level = .full_index,
    });
    const dense: types.DenseKnnQuery = .{ .vector = &.{ 1, 0, 0 }, .k = 2 };
    for ([_]types.SearchRequest{
        .{ .index_name = "vec", .dense = dense, .limit = 2, .profile = true },
        .{ .index_name = "vec", .query = .{ .dense_knn = dense }, .limit = 2, .profile = true },
        .{ .dense_queries = &.{.{ .name = "vec", .index_name = "vec", .query = dense }}, .limit = 2, .profile = true },
    }) |req| {
        var ordinary = try db.searchWithCapturedRequest(alloc, req);
        defer ordinary.result.deinit();
        var profiled = try db.searchWithDenseProfile(alloc, req);
        defer profiled.result.deinit();
        const profile = profiled.dense_profile orelse return error.MissingDenseProfile;
        try std.testing.expect(profile.search_route.len > 0);
        try std.testing.expectEqual(@as(u64, 2), profile.returned_hit_count);
        try std.testing.expectEqual(ordinary.request.identity_read_generation, profiled.request.identity_read_generation);
        try std.testing.expectEqual(ordinary.result.hits.len, profiled.result.hits.len);
        for (ordinary.result.hits, profiled.result.hits) |expected, actual| {
            try std.testing.expectEqualStrings(expected.id, actual.id);
            try std.testing.expectEqual(expected.score, actual.score);
        }
    }
}

