test "db text kernel search matches projected search without stored bodies" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{\"type\":\"full_text\",\"analysis_config\":{\"field_analyzers\":{\"text\":\"simple\"}}}",
    });
    try db.batch(.{
        .writes = &.{
            .{ .key = "benchmark:0", .value = "{\"text\":\"alpha beta\"}" },
            .{ .key = "benchmark:1", .value = "{\"text\":\"alpha gamma\"}" },
            .{ .key = "benchmark:2", .value = "{\"text\":\"beta gamma\"}" },
            .{ .key = "benchmark:3", .value = "{\"text\":\"alpha beta gamma\"}" },
        },
        .sync_level = .full_text,
    });
    try db.forceCompactTextIndexes();

    const should = [_]types.TextQuery{
        .{ .term = .{ .field = "text", .term = "alpha" } },
        .{ .term = .{ .field = "text", .term = "beta" } },
    };
    const query = types.TextQuery{ .bool_query = .{ .should = &should, .min_should = 1 } };

    var projected = try db.search(alloc, .{
        .index_name = "ft_v1",
        .full_text = query,
        .limit = 3,
        .include_stored = false,
        .include_all_fields = false,
    });
    defer projected.deinit();
    var kernel = try db.searchTextKernel(alloc, "ft_v1", query, .{ .limit = 3 });
    defer kernel.deinit(alloc);
    var custom_bm25 = try db.searchTextKernel(alloc, "ft_v1", query, .{
        .limit = 3,
        .bm25 = .{ .k1 = 2.0, .b = 0.0 },
    });
    defer custom_bm25.deinit(alloc);
    var profiled = try db.searchTextKernel(alloc, "ft_v1", query, .{
        .limit = 3,
        .collect_diagnostics = true,
    });
    defer profiled.deinit(alloc);

    try std.testing.expectEqual(projected.hits.len, kernel.hits.len);
    for (projected.hits, kernel.hits) |projected_hit, kernel_hit| {
        try std.testing.expectEqual(projected_hit.doc_ordinal.?, kernel_hit.doc_ordinal);
        try std.testing.expectApproxEqRel(projected_hit.score.?, kernel_hit.score, 0.00001);
    }
    try std.testing.expectEqual(kernel.hits.len, custom_bm25.hits.len);
    try std.testing.expectEqual(kernel.hits[0].doc_ordinal, custom_bm25.hits[0].doc_ordinal);
    try std.testing.expect(@abs(kernel.hits[0].score - custom_bm25.hits[0].score) > 0.0001);
    try std.testing.expect(profiled.diagnostics.segments_considered > 0);
    try std.testing.expect(profiled.diagnostics.postings_iterators_opened > 0);
    try std.testing.expectEqual(@as(u32, 4), try db.countTextKernel(alloc, "ft_v1", query));

    var layout = try db.textIndexLayoutStats(alloc, "ft_v1");
    defer layout.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), layout.segments.len);
    try std.testing.expectEqual(@as(u32, 4), layout.global_doc_count);
    try std.testing.expectEqual(@as(u32, 4), layout.segments[0].live_doc_count);
    try std.testing.expect(layout.total_bytes > 0);
    try std.testing.expectEqual(@as(u32, 10), layout.merge_policy.max_segments_per_tier);
    try std.testing.expect(layout.merge_policy.max_segment_size > layout.merge_policy.floor_segment_size);
}

test "db text compaction preserves index sort acceleration" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
    });
    defer db.close();

    const schema_json =
        \\{"version":1,"default_type":"doc","enforce_types":false,"index_sort":[{"field":"price","order":"asc"},{"field":"_id","order":"asc"}],"document_schemas":{"doc":{"schema":{"type":"object","additionalProperties":true,"properties":{"body":{"type":"string","x-antfly-field":{"type":"text"}},"price":{"type":"number","x-antfly-field":{"type":"number","sortable":true}}}}}}}
    ;
    try db.setSchemaJson(alloc, schema_json);

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    for (0..12) |i| {
        const key = try std.fmt.allocPrint(alloc, "doc:{d:0>3}", .{i});
        defer alloc.free(key);
        const price = 100 - i;
        const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\",\"price\":{d}}}", .{ i, price });
        defer alloc.free(value);

        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .full_index,
        });
    }

    try db.forceCompactTextIndexes();

    const text_index = db.core.index_manager.textIndex("ft_v1").?;
    const snapshot = text_index.snapshot();
    try std.testing.expect(snapshot.segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);
    for (snapshot.segments) |segment| {
        const fields = (try segment.reader.indexSortFieldsAlloc(alloc)) orelse return error.TestUnexpectedResult;
        defer segment_mod.freeIndexSortFields(alloc, fields);
        try std.testing.expectEqual(@as(usize, 2), fields.len);
        try std.testing.expectEqualStrings("price", fields[0].field);
        try std.testing.expectEqualStrings("_id", fields[1].field);

        var bounds = (try segment.reader.indexSortBoundsAlloc(alloc)) orelse return error.TestUnexpectedResult;
        defer bounds.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 2), bounds.first.len);
        try std.testing.expectEqual(@as(usize, 2), bounds.last.len);
    }

    const order_by = [_]types.SortField{
        .{ .field = "price" },
        .{ .field = "_id" },
    };
    var result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match_all = {} },
        .order_by = &order_by,
        .include_stored = false,
        .profile = true,
        .limit = 3,
    });
    defer result.deinit();

    try std.testing.expectEqual(@as(usize, 3), result.hits.len);
    try std.testing.expectEqualStrings("doc:011", result.hits[0].id);
    try std.testing.expectEqualStrings("doc:010", result.hits[1].id);
    try std.testing.expectEqualStrings("doc:009", result.hits[2].id);
    {
        var txn = try db.core.store.beginProbeTxn();
        defer txn.abort();
        for (result.hits) |hit| {
            const ordinal = try doc_identity.lookupOrdinalTxn(alloc, &txn, hit.id);
            try std.testing.expectEqual(ordinal, hit.doc_ordinal);
        }
    }
    const sort_profile = result.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("sorted_segment_seek", sort_profile.plan);
    try std.testing.expectEqualStrings("sorted_segment_scan", sort_profile.source);
    try std.testing.expectEqualStrings("index_sort_sorted_segment_seek", sort_profile.selection_reason);
    try std.testing.expectEqualStrings("source_free", sort_profile.source_load);
    try std.testing.expect(sort_profile.index_sort_match);
    try std.testing.expect(sort_profile.sorted_segment_executor_available);
    try std.testing.expect(sort_profile.sorted_segment_bounds_available);
    try std.testing.expectEqual(@as(u64, 0), sort_profile.stored_json_load_count);

    var after_page = try db.search(alloc, .{
        .index_name = "ft_v1",
