test "db index sort schema change requires a new text index generation" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
    });
    defer db.close();

    const sortable_schema_json =
        \\{"version":1,"default_type":"doc","enforce_types":false,"document_schemas":{"doc":{"schema":{"type":"object","additionalProperties":true,"properties":{"body":{"type":"string","x-antfly-field":{"type":"text"}},"price":{"type":"number","x-antfly-field":{"type":"number","sortable":true}}}}}}}
    ;
    try db.setSchemaJson(alloc, sortable_schema_json);

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:b", .value = "{\"body\":\"common old\",\"price\":2}" },
            .{ .key = "doc:d", .value = "{\"body\":\"common old\",\"price\":4}" },
        },
        .sync_level = .full_index,
    });

    const index_sort_schema_json =
        \\{"version":2,"default_type":"doc","enforce_types":false,"index_sort":[{"field":"price","order":"asc"},{"field":"_id","order":"asc"}],"document_schemas":{"doc":{"schema":{"type":"object","additionalProperties":true,"properties":{"body":{"type":"string","x-antfly-field":{"type":"text"}},"price":{"type":"number","x-antfly-field":{"type":"number","sortable":true}}}}}}}
    ;
    try db.setSchemaJson(alloc, index_sort_schema_json);

    try db.addIndex(.{
        .name = "ft_v2",
        .kind = .full_text,
        .config_json = "{}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"common new\",\"price\":1}" },
            .{ .key = "doc:c", .value = "{\"body\":\"common new\",\"price\":3}" },
        },
        .sync_level = .full_index,
    });

    const order_by = [_]types.SortField{
        .{ .field = "price" },
        .{ .field = "_id" },
    };
    var original_generation = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match_all = {} },
        .order_by = &order_by,
        .include_stored = false,
        .profile = true,
        .limit = 4,
    });
    defer original_generation.deinit();

    try std.testing.expectEqual(@as(usize, 4), original_generation.hits.len);
    try std.testing.expectEqualStrings("doc:a", original_generation.hits[0].id);
    try std.testing.expectEqualStrings("doc:b", original_generation.hits[1].id);
    try std.testing.expectEqualStrings("doc:c", original_generation.hits[2].id);
    try std.testing.expectEqualStrings("doc:d", original_generation.hits[3].id);
    const original_profile = original_generation.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("native_doc_values_top_n", original_profile.plan);
    try std.testing.expectEqualStrings("doc_values_collector", original_profile.source);
    try std.testing.expectEqualStrings("doc_values_collector", original_profile.selection_reason);
    try std.testing.expect(!original_profile.index_sort_match);
    try std.testing.expect(!original_profile.sorted_segment_executor_available);
    try std.testing.expectEqualStrings("request_mismatch", original_profile.index_sort_coverage);
    try std.testing.expectEqual(@as(u64, 0), original_profile.stored_json_load_count);

    var next_generation = try db.search(alloc, .{
        .index_name = "ft_v2",
        .query = .{ .match_all = {} },
        .order_by = &order_by,
        .include_stored = false,
        .profile = true,
        .limit = 4,
    });
    defer next_generation.deinit();

    try std.testing.expectEqual(@as(usize, 4), next_generation.hits.len);
    try std.testing.expectEqualStrings("doc:a", next_generation.hits[0].id);
    try std.testing.expectEqualStrings("doc:b", next_generation.hits[1].id);
    try std.testing.expectEqualStrings("doc:c", next_generation.hits[2].id);
    try std.testing.expectEqualStrings("doc:d", next_generation.hits[3].id);
    {
        var txn = try db.core.store.beginProbeTxn();
        defer txn.abort();
        for (next_generation.hits) |hit| {
            const ordinal = try doc_identity.lookupOrdinalTxn(alloc, &txn, hit.id);
            try std.testing.expectEqual(ordinal, hit.doc_ordinal);
        }
    }
    const next_profile = next_generation.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("sorted_segment_seek", next_profile.plan);
    try std.testing.expectEqualStrings("sorted_segment_scan", next_profile.source);
    try std.testing.expectEqualStrings("index_sort_sorted_segment_seek", next_profile.selection_reason);
    try std.testing.expectEqualStrings("covered_with_bounds", next_profile.index_sort_coverage);
    try std.testing.expect(next_profile.index_sort_match);
    try std.testing.expect(next_profile.sorted_segment_executor_available);
    try std.testing.expect(next_profile.sorted_segment_bounds_available);
    try std.testing.expectEqual(@as(u64, 0), next_profile.stored_json_load_count);
}

test "db text compaction preserves ordinal filters across reopen" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    const expected_ordinal: doc_set.DocOrdinal = 9;
    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
        });
        defer db.close();

        try db.addIndex(.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        });

        for (0..12) |i| {
            const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
            defer alloc.free(key);
            const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
            defer alloc.free(value);

            try db.batch(.{
                .writes = &.{.{ .key = key, .value = value }},
                .sync_level = .full_index,
            });
        }

        var include = try db.resolveDocSetForIdsAlloc(alloc, &.{"doc:8"});
        errdefer include.deinit(alloc);
        const resolved_ordinal = switch (include) {
            .ordinals => |ordinals| blk: {
                try std.testing.expectEqual(@as(usize, 1), ordinals.len);
                break :blk ordinals[0];
            },
            else => return error.ExpectedOrdinalDocSet,
        };
        try std.testing.expectEqual(expected_ordinal, resolved_ordinal);

        var filter = doc_set.ResolvedDocFilter{
            .include = include,
            .exclude = .none,
        };
        include = .all;
        defer filter.deinit(alloc);

        try db.forceCompactTextIndexes();

        const text_index = db.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);

        var result = try db.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match = .{ .field = "body", .text = "common" } },
            .limit = 20,
            .resolved_doc_filter = &filter,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 1), result.total_hits);
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        try std.testing.expectEqualStrings("doc:8", result.hits[0].id);
        try std.testing.expectEqual(@as(?doc_set.DocOrdinal, expected_ordinal), result.hits[0].doc_ordinal);
    }

    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
        });
        defer reopened.close();

        var include = try reopened.resolveDocSetForIdsAlloc(alloc, &.{"doc:8"});
        errdefer include.deinit(alloc);
        const resolved_ordinal = switch (include) {
            .ordinals => |ordinals| blk: {
                try std.testing.expectEqual(@as(usize, 1), ordinals.len);
                break :blk ordinals[0];
            },
            else => return error.ExpectedOrdinalDocSet,
        };
        try std.testing.expectEqual(expected_ordinal, resolved_ordinal);

        var filter = doc_set.ResolvedDocFilter{
            .include = include,
            .exclude = .none,
        };
        include = .all;
        defer filter.deinit(alloc);

        const text_index = reopened.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);

        var result = try reopened.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match = .{ .field = "body", .text = "common" } },
            .limit = 20,
            .resolved_doc_filter = &filter,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 1), result.total_hits);
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        try std.testing.expectEqualStrings("doc:8", result.hits[0].id);
        try std.testing.expectEqual(@as(?doc_set.DocOrdinal, expected_ordinal), result.hits[0].doc_ordinal);
    }
}

test "db v02 provisioning binds released epoch with missing local public metadata" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db-schema-format-retry");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    const schema_json = @embedFile("../testdata/v02-server/schema.json");
    var parsed = try public_table_schema.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const runtime_schema = try public_table_schema.deriveRuntimeTableSchema(alloc, parsed);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    const original = @embedFile("../testdata/v02-server/schema.asch");
    const versioned_key = try schema_mod.schemaVersionKeyAlloc(alloc, 0);
    defer alloc.free(versioned_key);
    const active_key = "\x00\x00__metadata__:schema";
    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false });
        defer db.close();
        try db.setSchemaJson(alloc, schema_json);
        try db.core.store.put(active_key, original);
        try db.core.store.put(versioned_key, original);
        try db.core.store.delete(public_schema_json_key);
        const public_version_key = try public_table_schema.versionedSchemaKeyAlloc(alloc, 0);
        defer alloc.free(public_version_key);
        try db.core.store.delete(public_version_key);
    }
    for (0..3) |_| {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_optional_runtimes = false,
            .schema_before_index_load = .{ .runtime_schema = runtime_schema, .public_schema_json = schema_json },
        });
        defer db.close();
        try std.testing.expect(try schema_mod.schemasEqual(alloc, runtime_schema, db.core.schema.?));
        var view = db.core.acquireSchemaView().?;
        defer view.release();
        try std.testing.expect(view.validator() != null);
        for ([_][]const u8{ active_key, versioned_key }) |key| {
            const actual = try db.core.store.get(alloc, key);
            defer alloc.free(actual);
            try std.testing.expectEqualSlices(u8, original, actual);
        }
        try db.batch(.{ .writes = &.{.{ .key = "doc:1", .value = "{\"_type\":\"doc\",\"body\":\"still writable\",\"count\":7}" }} });
    }
}

test "db owner open does not downgrade a newer durable schema for Raft catch-up" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db-owner-schema-catch-up");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    const older_json = "{\"version\":0}";
    const newer_json = "{\"version\":1}";
    var parsed = try public_table_schema.parseValidatedTableSchema(alloc, older_json);
    defer parsed.deinit(alloc);
    const older_schema = try public_table_schema.deriveRuntimeTableSchema(alloc, parsed);
    defer schema_mod.freeSchema(alloc, older_schema);
    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_optional_runtimes = false });
        defer db.close();
        try db.setSchemaJson(alloc, newer_json);
    }
    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtimes = false,
        .schema_before_index_load = .{ .runtime_schema = older_schema, .public_schema_json = older_json },
    });
    defer reopened.close();
    try std.testing.expectEqual(@as(u32, 1), reopened.core.schema.?.version);
    const public_json = try reopened.core.store.get(alloc, public_schema_json_key);
    defer alloc.free(public_json);
    try std.testing.expectEqualStrings(newer_json, public_json);
}

