fn testChildGenerationInstall(native: bool) !void {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db-child-generation-owner-reopen");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    const namespace: doc_identity.Namespace = .{ .table_id = 17, .shard_id = 19, .range_id = 19 };
    const old_json =
        \\{"version":0,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const next_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"fk","child_columns":["id"],"parent_table":"parent","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    var parsed_next = try public_table_schema.parseValidatedTableSchema(alloc, next_json);
    defer parsed_next.deinit(alloc);
    const next_schema = try public_table_schema.deriveRuntimeTableSchema(alloc, parsed_next);
    defer schema_mod.freeSchema(alloc, next_schema);
    var fence: relational_integrity_topology.Fence = undefined;
    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .identity_namespace = namespace, .online_source_authority = if (native) .native else .raft, .start_optional_runtimes = false });
        defer db.close();
        try db.setSchemaJson(alloc, old_json);
        const catalog = try db.core.store.get(alloc, relational_integrity_catalog.key);
        defer alloc.free(catalog);
        var catalog_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(catalog, &catalog_digest, .{});
        fence = .{
            .transition_id = 1,
            .attempt = 1,
            .peer_group_id = 19,
            .owner_group_id = 19,
            .role = .child_generation_source,
            .namespace = namespace,
            .catalog_digest = catalog_digest,
        };
        if (native) {
            try db.batchNativeFkGenerationApply(.{ .relational_topology = .{ .action = .begin, .fence = fence } });
            try std.testing.expectError(error.InvalidBatchRequest, db.batchNativeFkGenerationApply(.{ .writes = &.{.{ .key = "no", .value = "{}" }}, .relational_topology = .{ .action = .begin, .fence = fence } }));
        } else try db.batch(.{ .relational_topology = .{ .action = .begin, .fence = fence } });
        try std.testing.expect(try db.childGenerationSourcePinsSchemaJson(next_json));
        try std.testing.expect(try db.childGenerationSourceDefersOwnerCatalog());
    }
    var after_catalog_digest: [32]u8 = undefined;
    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{
            .identity_namespace = namespace,
            .online_source_authority = if (native) .native else .raft,
            .start_optional_runtimes = false,
            .schema_before_index_load = .{ .runtime_schema = next_schema, .public_schema_json = next_json },
        });
        defer reopened.close();
        try std.testing.expectEqual(@as(u32, 0), reopened.core.schema.?.version);
        try std.testing.expect(try reopened.childGenerationSourcePinsSchemaJson(next_json));
        const public_json = try reopened.core.store.get(alloc, public_schema_json_key);
        defer alloc.free(public_json);
        try std.testing.expectEqualStrings(old_json, public_json);
        const old_catalog = try reopened.core.store.get(alloc, relational_integrity_catalog.key);
        defer alloc.free(old_catalog);
        var before_catalog_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(old_catalog, &before_catalog_digest, .{});
        var prepared = try reopened.core.prepareSchemaMetadataPublishedChild(next_schema, &.{.{ .key = public_schema_json_key, .value = next_json }});
        defer prepared.deinit();
        std.crypto.hash.Blake3.hash(prepared.integrity_catalog.?.value, &after_catalog_digest, .{});
        var old_json_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(old_json, &old_json_digest, .{});
        var next_json_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(next_json, &next_json_digest, .{});
        const install: DB.PublishedChildSchema = .{
            .fence = fence,
            .before_schema_json_digest = old_json_digest,
            .schema_json_digest = next_json_digest,
            .before_catalog_digest = before_catalog_digest,
            .after_catalog_digest = after_catalog_digest,
            .ordered_receipt = .{ .term = 1, .index = if (native) 5 else 1 },
            .native = native,
        };
        for (0..2) |_| {
            if (native) try reopened.batchNativeFkGenerationApply(.{ .relational_topology = .{ .action = .install_child_schema, .fence = fence, .child_schema_install = .{ .schema_json = next_json, .before_schema_json_digest = old_json_digest, .schema_json_digest = next_json_digest, .before_catalog_digest = before_catalog_digest, .after_catalog_digest = after_catalog_digest } } }) else try reopened.installPublishedChildSchema(alloc, next_json, install);
        }
        try std.testing.expectEqual(@as(u32, 1), reopened.core.schema.?.version);
        try std.testing.expect((try reopened.relationalTopologyStatus()).fence == null);
        try std.testing.expect(!(try reopened.childGenerationSourceDefersOwnerCatalog()));
    }
    var installed = try DB.open(alloc, std.mem.span(path), .{
        .identity_namespace = namespace,
        .online_source_authority = if (native) .native else .raft,
        .start_optional_runtimes = false,
        .schema_before_index_load = .{ .runtime_schema = next_schema, .public_schema_json = next_json },
    });
    defer installed.close();
    try std.testing.expectEqual(@as(u32, 1), installed.core.schema.?.version);
    try std.testing.expect(!(try installed.childGenerationSourcePinsSchemaJson(next_json)));
    const installed_public = try installed.core.store.get(alloc, public_schema_json_key);
    defer alloc.free(installed_public);
    try std.testing.expectEqualStrings(next_json, installed_public);
    const installed_catalog = try installed.core.store.get(alloc, relational_integrity_catalog.key);
    defer alloc.free(installed_catalog);
    var installed_digest: [32]u8 = undefined;
    std.crypto.hash.Blake3.hash(installed_catalog, &installed_digest, .{});
    try std.testing.expectEqual(after_catalog_digest, installed_digest);
    const receipt_bytes = try installed.core.store.get(alloc, relational_integrity_generation_admission.source_install_receipt_key);
    defer alloc.free(receipt_bytes);
    const receipt = try relational_integrity_generation_admission.AppliedReceipt.decode(receipt_bytes);
    try std.testing.expectEqual(@as(u64, 1), receipt.term);
    try std.testing.expectEqual(@as(u64, if (native) 5 else 1), receipt.index);
    if (native) try std.testing.expect((try readOrderedApplyReceipt(alloc, installed.core.store)) == null);
    // A later DROP publication fences the already-installed v1 layout. The
    // schema pin is intentionally false for an equal version, but cold owner
    // index reconciliation must still wait for this dual-role fence.
    const dual_fence: relational_integrity_topology.Fence = .{
        .admission_epoch = 2,
        .transition_id = 2,
        .attempt = 1,
        .peer_group_id = 19,
        .owner_group_id = 19,
        .role = .child_generation_dual,
        .namespace = namespace,
        .catalog_digest = installed_digest,
    };
    try installed.batch(.{ .relational_topology = .{ .action = .begin, .fence = dual_fence } });
    try std.testing.expect(!(try installed.childGenerationSourcePinsSchemaJson(next_json)));
    try std.testing.expect(try installed.childGenerationSourceDefersOwnerCatalog());
}

test "db provisioning schema is persisted before configured full text indexes open" {
    const alloc = std.testing.allocator;
    const table_schema_api = public_table_schema;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    // Persist the target-generation catalog entry while the shard still has
    // no target schema. This is the state an interrupted migration presents
    // to the next provisioning open.
    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
        defer db.close();
        try db.addIndex(.{
            .name = "full_text_index_v1",
            .kind = .full_text,
            .config_json = "{}",
        });
    }

    const schema_json =
        \\{
        \\  "version": 1,
        \\  "default_type": "doc",
        \\  "enforce_types": true,
        \\  "document_schemas": {
        \\    "doc": {
        \\      "schema": {
        \\        "type": "object",
        \\        "additionalProperties": false,
        \\        "properties": {
        \\          "body": {
        \\            "type": "string",
        \\            "x-antfly-types": ["text"],
        \\            "x-antfly-include-in-all": false
        \\          }
        \\        },
        \\        "required": ["body"]
        \\      }
        \\    }
        \\  }
        \\}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);

    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .schema_before_index_load = .{
            .runtime_schema = runtime_schema,
            .public_schema_json = schema_json,
        },
    });
    defer reopened.close();

    const entry = reopened.core.index_manager.textIndexEntry("full_text_index_v1") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 1), entry.runtime_schema.?.version);
    try reopened.batch(.{
        .writes = &.{.{ .key = "doc:1", .value = "{\"body\":\"alpha beta\"}" }},
        .sync_level = .full_text,
    });

    const snapshot = entry.persistent.snapshot();
    try std.testing.expectEqual(@as(u32, 1), try snapshot.termDocFreq(alloc, "body", "alpha"));
    try std.testing.expectEqual(@as(u32, 0), try snapshot.termDocFreq(alloc, "body.keyword", "alpha beta"));
    try std.testing.expectEqual(@as(u32, 0), try snapshot.termDocFreq(alloc, "_all", "alpha"));
}

test "db best effort force compact leaves text merge debt under pressure" {
    const alloc = std.testing.allocator;
    const table_schema_api = public_table_schema;

    var budgets = resource_manager_mod.Options.defaultBudgets();
    budgets[@backingInt(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_limit_bytes = 1,
        .hard_limit_bytes = 1024 * 1024,
    };
    var policies = resource_manager_mod.Options.defaultPolicies();
    policies[@backingInt(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_action = .defer_background_work,
        .hard_action = .defer_background_work,
    };
    var resource_manager = resource_manager_mod.ResourceManager.init(.{
        .budgets = budgets,
        .policies = policies,
    });
    var tracked_usage: u64 = 0;
    resource_manager.observeUsage(.text_merge_buffers, &tracked_usage, 2);
    defer resource_manager.observeUsage(.text_merge_buffers, &tracked_usage, 0);

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .resource_manager = &resource_manager,
        .text_merge = .{ .enabled = false },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    const schema_json =
        \\{
        \\  "default_type": "doc",
        \\  "document_schemas": {
        \\    "doc": {
        \\      "schema": {
        \\        "type": "object",
        \\        "properties": {
        \\          "body": {
        \\            "type": "string",
        \\            "x-antfly-types": ["text"]
        \\          }
        \\        }
        \\      }
        \\    }
        \\  }
        \\}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    for (0..12) |i| {
        const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
        defer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
        defer alloc.free(value);

        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .full_text,
        });
    }

    const text_index_before = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index_before.snapshot().segments.len > 1);

    try db.bestEffortForceCompactTextIndexes();

    const text_index_after = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index_after.snapshot().segments.len > 1);

    var result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match = .{ .field = "body", .text = "common" } },
        .limit = 20,
    });
    defer result.deinit();

    try std.testing.expectEqual(@as(u32, 12), result.total_hits);
}

test "db runUntilIdle defers full text merge pressure without failing" {
    const alloc = std.testing.allocator;

    var budgets = resource_manager_mod.Options.defaultBudgets();
    budgets[@backingInt(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_limit_bytes = 1,
        .hard_limit_bytes = 1,
    };
    var policies = resource_manager_mod.Options.defaultPolicies();
    policies[@backingInt(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_action = .defer_background_work,
        .hard_action = .reject_work,
    };
    var resource_manager = resource_manager_mod.ResourceManager.init(.{
        .budgets = budgets,
        .policies = policies,
    });

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .resource_manager = &resource_manager,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    for (0..12) |i| {
        const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
        defer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
        defer alloc.free(value);

        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .full_text,
        });
    }

    const before = db.pendingWorkStats().text_merge;
    try std.testing.expect(before.pending_segments > 0);

    try db.runUntilIdle();

    const after = db.pendingWorkStats().text_merge;
    try std.testing.expect(after.pending_segments > 0);
    try std.testing.expect(after.deferred_for_pressure >= before.deferred_for_pressure);

    const text_index = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index.snapshot().segments.len > 1);
}

test "db phrase query survives text compaction deletes and reopen" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.addIndex(.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        });

        for (0..6) |i| {
            const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
            defer alloc.free(key);

            const body = switch (i) {
                0 => "alpha beta",
                1 => "alpha beta gamma",
                2 => "alpha only",
                3 => "beta only",
                4 => "alpha beta delta",
                else => "gamma delta",
            };
            const value = try std.fmt.allocPrint(
                alloc,
                "{{\"title\":\"both\",\"body\":\"{s}\"}}",
                .{body},
            );
            defer alloc.free(value);

            try db.batch(.{
                .writes = &.{.{
                    .key = key,
                    .value = value,
                }},
                .sync_level = .full_index,
            });
        }

        try db.batch(.{
            .deletes = &.{"doc:1"},
            .sync_level = .full_index,
        });

        const text_index = db.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len < 6);

        var result = try db.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match_phrase = .{ .field = "body", .text = "alpha beta" } },
            .limit = 10,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 2), result.total_hits);
        try std.testing.expect(
            (std.mem.eql(u8, result.hits[0].id, "doc:0") and std.mem.eql(u8, result.hits[1].id, "doc:4")) or
                (std.mem.eql(u8, result.hits[0].id, "doc:4") and std.mem.eql(u8, result.hits[1].id, "doc:0")),
        );
    }

    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{});
        defer reopened.close();

        var result = try reopened.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match_phrase = .{ .field = "body", .text = "alpha beta" } },
            .limit = 10,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 2), result.total_hits);
        try std.testing.expect(
            (std.mem.eql(u8, result.hits[0].id, "doc:0") and std.mem.eql(u8, result.hits[1].id, "doc:4")) or
                (std.mem.eql(u8, result.hits[0].id, "doc:4") and std.mem.eql(u8, result.hits[1].id, "doc:0")),
        );
    }
}

