        \\            "additionalProperties": {
        \\              "type": "object",
        \\              "properties": {
        \\                "body": {
        \\                  "type": "string",
        \\                  "x-antfly-types": ["text"]
        \\                }
        \\              }
        \\            }
        \\          },
        \\          "dyn": {
        \\            "type": "object",
        \\            "additionalProperties": true
        \\          },
        \\          "open": {
        \\            "type": "object",
        \\            "additionalProperties": true
