        const stats = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 1), stats.doc_identity.state_rows);
        try std.testing.expectEqual(@as(u64, 0), stats.doc_identity.live_ordinals);
        try std.testing.expectEqual(@as(u64, 1), stats.doc_identity.tombstone_ordinals);
        try std.testing.expectEqual(@as(u64, 0), stats.doc_identity.primary_docs_missing_ordinals);
        try std.testing.expectEqual(@as(u64, 0), stats.doc_identity.primary_docs_missing_identity_state);
        try std.testing.expect(!stats.doc_identity.rebuild_required);
    }

    try db.setSchema(.{
        .version = 2,
        .default_type = "_default",
        .ttl_duration_ns = 0,
    });

    var text = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match = .{ .field = "body", .text = "common" } },
        .limit = 10,
    });
    defer text.deinit();
    try std.testing.expectEqual(@as(u32, 0), text.total_hits);
}

test "db ttl delete callback atomically removes dense artifacts and updates repair counters" {
    const alloc = std.testing.allocator;
    const ttl_duration_ns: u64 = std.time.ns_per_s;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.setSchema(.{
        .version = 1,
        .default_type = "_default",
        .ttl_duration_ns = ttl_duration_ns,
    });
    try db.addIndex(.{
        .name = "external_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"external\":true}",
    });

    const timestamp_ns = currentTimeNs() - 2 * ttl_duration_ns;
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:expired",
            .value = "{\"title\":\"gone\",\"_embeddings\":{\"external_v1\":[1,0]}}",
        }},
        .timestamp_ns = timestamp_ns,
        .sync_level = .full_index,
    });
    try std.testing.expectEqual(
        @as(?u64, 1),
        try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, "external_v1"),
    );

    var ttl_ctx = TtlCleanupContext{
        .batch = db.batchContext(),
        .grace_period_ns = 0,
    };
    const candidate_key = try alloc.dupe(u8, "doc:expired");
    defer alloc.free(candidate_key);
    const candidates = [_]ttl_runtime_mod.DeleteCandidate{.{
        .key = candidate_key,
        .timestamp_ns = timestamp_ns,
    }};
    try std.testing.expectEqual(
        @as(u32, 1),
        try deleteExpiredDocumentsFromCandidates(&ttl_ctx, &candidates),
    );

    const artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:expired", "external_v1");
    defer alloc.free(artifact_key);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, artifact_key));
    try std.testing.expectEqual(
        @as(?u64, 0),
        try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, "external_v1"),
    );
    const stats = try db.runtimeStatusStatsConsistent(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expectEqual(@as(u64, 0), stats.source_doc_count);
    try std.testing.expectEqual(@as(u64, 0), stats.doc_identity.live_ordinals);
}

