    {
        var deterministic_receiver = embedder_mod.DeterministicDenseEmbedder{};
        var receiver = try DB.open(alloc, std.mem.span(receiver_path), .{
            .primary_backend = primary_backend,
            .enrichment = .{
                .owner_id = "merge-receiver",
                .dense_embedder = deterministic_receiver.interface(),
            },
        });
        defer receiver.close();
        try receiver.updateRange(.{ .start = "doc:a", .end = "doc:m" });

        var deterministic_donor = embedder_mod.DeterministicDenseEmbedder{};
        var donor = try DB.open(alloc, std.mem.span(donor_path), .{
            .primary_backend = primary_backend,
            .enrichment = .{
                .owner_id = "merge-donor",
                .dense_embedder = deterministic_donor.interface(),
            },
        });
        defer donor.close();
        try donor.updateRange(.{ .start = "doc:m", .end = "" });

        try receiver.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
        });
        try donor.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
        });

        try donor.batch(.{
            .writes = &.{.{ .key = "doc:y", .value = "{\"body\":\"donor pre-cutover\"}" }},
            .sync_level = .write,
        });
        try donor.enrichment_runtime.?.waitForApplied(1);
        try donor.executor.waitForAll(2);

        try receiver.updateRange(.{ .start = "doc:a", .end = "" });
        try donor.updateRange(.{ .start = "doc:m", .end = "doc:m" });

        try receiver.batch(.{
            .writes = &.{.{ .key = "doc:z", .value = "{\"body\":\"receiver pre-reopen\"}" }},
            .sync_level = .write,
        });
        try receiver.enrichment_runtime.?.waitForApplied(1);
        try receiver.executor.waitForAll(2);
        try receiver.sync(true);
        try donor.sync(true);
    }

    var deterministic_receiver = embedder_mod.DeterministicDenseEmbedder{};
    var reopened_receiver = try DB.open(alloc, std.mem.span(receiver_path), .{
        .primary_backend = primary_backend,
        .enrichment = .{
            .owner_id = "merge-receiver",
            .dense_embedder = deterministic_receiver.interface(),
        },
    });
    defer reopened_receiver.close();

    var deterministic_donor = embedder_mod.DeterministicDenseEmbedder{};
    var reopened_donor = try DB.open(alloc, std.mem.span(donor_path), .{
        .primary_backend = primary_backend,
        .enrichment = .{
            .owner_id = "merge-donor",
            .dense_embedder = deterministic_donor.interface(),
        },
    });
    defer reopened_donor.close();

    try std.testing.expectError(error.KeyOutOfRange, reopened_donor.batch(.{
        .writes = &.{.{ .key = "doc:x", .value = "{\"body\":\"donor still fenced\"}" }},
        .sync_level = .write,
    }));

    const receiver_before = try reopened_receiver.stats(alloc);
    defer types.freeDBStats(alloc, receiver_before);
    const receiver_dense_before = try reopened_receiver.core.loadAppliedSequence(alloc, "dv_v1");

    try reopened_receiver.batch(.{
        .writes = &.{.{ .key = "doc:w", .value = "{\"body\":\"receiver post-reopen\"}" }},
        .sync_level = .write,
    });
    try reopened_receiver.runUntilIdle();
    const receiver_dense_after = try waitForAppliedSequenceAdvance(alloc, &reopened_receiver, "dv_v1", receiver_dense_before);
    try std.testing.expect(receiver_dense_after > receiver_dense_before);

    const pre_reopen_vec = try deterministic_receiver.interface().embedDense(alloc, "", "receiver pre-reopen", 3);
    defer alloc.free(pre_reopen_vec);

    var pre_reopen_result = try waitForSearchResult(alloc, &reopened_receiver, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = pre_reopen_vec,
            .k = 3,
        },
    }, 1);
    defer pre_reopen_result.deinit();
    var found_pre_reopen = false;
    for (pre_reopen_result.hits) |hit| {
        if (std.mem.eql(u8, hit.id, "doc:z")) found_pre_reopen = true;
    }
    try std.testing.expect(found_pre_reopen);

    const receiver_vec = try deterministic_receiver.interface().embedDense(alloc, "", "receiver post-reopen", 3);
    defer alloc.free(receiver_vec);

    var receiver_result = try waitForSearchResult(alloc, &reopened_receiver, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = receiver_vec,
            .k = 3,
        },
    }, 1);
    defer receiver_result.deinit();
    var found = false;
    for (receiver_result.hits) |hit| {
        if (std.mem.eql(u8, hit.id, "doc:w")) found = true;
    }
    try std.testing.expect(found);
}

test "db merge-style cutover preserves text sparse and graph indexes across reopen with durable lsm primary backend" {
    const alloc = std.testing.allocator;

    var receiver_tmp = try TestDirectory.init("db");
    defer receiver_tmp.cleanup();
    const receiver_path = receiver_tmp.path().ptr;

    var donor_tmp = try TestDirectory.init("db");
    defer donor_tmp.cleanup();
    const donor_path = donor_tmp.path().ptr;

    const primary_backend: PrimaryBackend = .{ .lsm = db_config.primary_lsm_options_default };

    {
        var receiver = try DB.open(alloc, std.mem.span(receiver_path), .{
            .primary_backend = primary_backend,
        });
        defer receiver.close();
        try receiver.updateRange(.{ .start = "doc:a", .end = "doc:m" });

        var donor = try DB.open(alloc, std.mem.span(donor_path), .{
            .primary_backend = primary_backend,
        });
        defer donor.close();
        try donor.updateRange(.{ .start = "doc:m", .end = "" });

        const index_cfgs = [_]types.IndexConfig{
            .{
                .name = "ft_v1",
                .kind = .full_text,
                .config_json = "{\"field\":\"title\"}",
            },
            .{
                .name = "sp_v1",
                .kind = .sparse_vector,
                .config_json = "{\"field\":\"sparse\"}",
            },
            .{
                .name = "graph_v1",
                .kind = .graph,
                .config_json = "{}",
            },
        };
        for (index_cfgs) |cfg| {
            try receiver.addIndex(cfg);
            try donor.addIndex(cfg);
        }

        try receiver.updateRange(.{ .start = "doc:a", .end = "" });
        try donor.updateRange(.{ .start = "doc:m", .end = "doc:m" });

        try receiver.batch(.{
            .writes = &.{
                .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"sparse\":{\"indices\":[1],\"values\":[1.0]}}" },
                .{ .key = "doc:z", .value = "{\"title\":\"zeta\",\"sparse\":{\"indices\":[2],\"values\":[1.0]}}" },
            },
            .graph_writes = &.{
                .{ .index_name = "graph_v1", .source = "doc:z", .target = "doc:y", .edge_type = "cites", .weight = 1.0 },
            },
        });
        try receiver.sync(true);
        try donor.sync(true);
    }

    var reopened_receiver = try DB.open(alloc, std.mem.span(receiver_path), .{
        .primary_backend = primary_backend,
    });
    defer reopened_receiver.close();

    var reopened_donor = try DB.open(alloc, std.mem.span(donor_path), .{
        .primary_backend = primary_backend,
    });
    defer reopened_donor.close();

    try std.testing.expectError(error.KeyOutOfRange, reopened_donor.batch(.{
        .writes = &.{.{ .key = "doc:x", .value = "{\"title\":\"blocked\"}" }},
    }));

    var receiver_text = try reopened_receiver.search(alloc, .{
        .index_name = "ft_v1",
        .full_text = .{ .match = .{ .field = "title", .text = "zeta" } },
    });
    defer receiver_text.deinit();
    try std.testing.expectEqual(@as(u32, 1), receiver_text.total_hits);
    try std.testing.expectEqualStrings("doc:z", receiver_text.hits[0].id);

    var receiver_sparse = try reopened_receiver.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = &.{2},
            .values = &.{1.0},
            .k = 2,
        } },
        .limit = 2,
    });
    defer receiver_sparse.deinit();
    try std.testing.expectEqual(@as(u32, 1), receiver_sparse.total_hits);
    try std.testing.expectEqualStrings("doc:z", receiver_sparse.hits[0].id);

    const receiver_incoming = try reopened_receiver.getEdges(alloc, "graph_v1", "doc:y", "cites", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, receiver_incoming);
    try std.testing.expectEqual(@as(usize, 1), receiver_incoming.len);
    try std.testing.expectEqualStrings("doc:z", receiver_incoming[0].source);

    var donor_text = try reopened_donor.search(alloc, .{
        .index_name = "ft_v1",
        .full_text = .{ .match = .{ .field = "title", .text = "zeta" } },
    });
    defer donor_text.deinit();
    try std.testing.expectEqual(@as(u32, 0), donor_text.total_hits);

    var donor_sparse = try reopened_donor.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = &.{2},
            .values = &.{1.0},
            .k = 2,
        } },
        .limit = 2,
    });
    defer donor_sparse.deinit();
    try std.testing.expectEqual(@as(u32, 0), donor_sparse.total_hits);

    const donor_incoming = try reopened_donor.getEdges(alloc, "graph_v1", "doc:y", "cites", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, donor_incoming);
    try std.testing.expectEqual(@as(usize, 0), donor_incoming.len);
}

pub fn cacheBlockHitsForBench(stats: anytype) u64 {
    var hits: u64 = 0;
    if (@hasField(@TypeOf(stats), "run_table_block")) {
        hits += stats.run_table_block.hits;
    }
    if (@hasField(@TypeOf(stats), "run_table_physical_block")) {
        hits += stats.run_table_physical_block.hits;
    }
    return hits;
}

pub fn normalizedBenchSearchEffort(effort: ?f32) f32 {
    const value = effort orelse return 0.5;
    if (std.math.isNan(value)) return 0.5;
    if (value < 0) return 0;
    if (value > 1) return 1;
    return value;
}

fn estimateBenchDenseLeafCount(stats: hbc_mod.IndexStats) u32 {
    if (stats.active_count == 0) return 0;
    const leaf_size = @max(stats.leaf_size, 1);
    const estimated = (stats.active_count + leaf_size - 1) / leaf_size;
    return @intCast(@min(estimated, @as(u64, std.math.maxInt(u32))));
}

pub fn resolveBenchSearchWidth(k: u32, effort: f32, stats: hbc_mod.IndexStats) u32 {
    const min_width = @max(k, @as(u32, 64));
    const legacy_max_width = @max(min_width * 20, @as(u32, 4096));
    const legacy_balanced_width = min_width + @as(u32, @intFromFloat(@as(f32, @floatFromInt(legacy_max_width - min_width)) * 0.5));
    const estimated_leaf_count = estimateBenchDenseLeafCount(stats);
    const max_width = if (estimated_leaf_count > 0)
        @max(min_width, @max(estimated_leaf_count, if (stats.node_count > 0 and stats.node_count <= std.math.maxInt(u32)) @as(u32, @intCast(stats.node_count)) else estimated_leaf_count))
    else if (stats.node_count > legacy_max_width and stats.node_count <= std.math.maxInt(u32))
        @as(u32, @intCast(stats.node_count))
    else
        legacy_max_width;
    const balanced_cap = if (estimated_leaf_count > 0) @max(min_width, estimated_leaf_count) else max_width;
    const leaf_balanced_width = min_width + @as(u32, @intFromFloat(@as(f32, @floatFromInt(balanced_cap - min_width)) * 0.5));
    const balanced_width = @min(legacy_balanced_width, leaf_balanced_width);

    if (effort <= 0.5) {
        if (balanced_width <= min_width) return min_width;
        const ratio = effort / 0.5;
        return min_width + @as(u32, @intFromFloat(@as(f32, @floatFromInt(balanced_width - min_width)) * ratio));
    }

    if (max_width <= balanced_width) return max_width;
    const ratio = (effort - 0.5) / 0.5;
    const width = balanced_width + @as(u32, @intFromFloat(@as(f32, @floatFromInt(max_width - balanced_width)) * ratio));
    return @min(width, max_width);
}

pub fn resolveBenchSearchEpsilon(effort: f32) f32 {
    if (effort < 0.5) {
        return 1.0 + (effort * 12.0);
    }
    return 7.0 + ((effort - 0.5) * 186.0);
}

test "db hbc posting lazy versus eager profile benchmark" {
    if (!profileBenchTestsEnabled()) return error.SkipZigTest;
    const alloc = std.testing.allocator;

    const dims: usize = @max(@as(usize, 1), readEnvUsize("ANTFLY_HBC_POSTING_BENCH_DIMS", 16));
    const doc_count: usize = @max(@as(usize, 1), readEnvUsize("ANTFLY_HBC_POSTING_BENCH_DOCS", 1024));
    const Mode = struct {
        name: []const u8,
        lazy: bool,
    };
    const modes = [_]Mode{
        .{
            .name = "eager",
            .lazy = false,
        },
        .{
            .name = "lazy",
            .lazy = true,
        },
    };

    const BenchWrites = struct {
        fn fill(
            allocator: Allocator,
            writes: []types.BatchWrite,
            vector_buf: []f32,
            salt: usize,
        ) !void {
            for (writes, 0..) |*write, doc_id| {
                var norm_sq: f32 = 0;
                for (vector_buf, 0..) |*slot, dim| {
                    const raw: u32 = @intCast(((doc_id + salt) * 1103515245 + dim * 2654435761 + 19) % 1000);
                    const centered = (@as(f32, @floatFromInt(raw)) / 500.0) - 1.0;
                    slot.* = centered;
                    norm_sq += centered * centered;
                }
                const inv_norm: f32 = 1.0 / @sqrt(norm_sq);
                for (vector_buf) |*slot| slot.* *= inv_norm;

                const key = try std.fmt.allocPrint(allocator, "doc:{d}", .{doc_id});
                errdefer allocator.free(key);
                const value = try std.fmt.allocPrint(
                    allocator,
                    "{{\"embedding\":{f}}}",
                    .{std.json.fmt(vector_buf, .{})},
                );
                write.* = .{
                    .key = key,
                    .value = value,
                };
            }
        }

        fn free(allocator: Allocator, writes: []types.BatchWrite) void {
            for (writes) |*write| {
                allocator.free(write.key);
                allocator.free(write.value);
                write.* = .{ .key = &.{}, .value = &.{} };
            }
        }
    };

    for (modes) |mode| {
        var path_tmp = try TestDirectory.init("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;

        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        const config_json = try std.fmt.allocPrint(
            alloc,
            "{{\"field\":\"embedding\",\"dims\":{d},\"metric\":\"cosine\",\"use_quantization\":true,\"lazy_posting_maintenance\":{s},\"auto_posting_maintenance_max_postings\":0}}",
            .{ dims, if (mode.lazy) "true" else "false" },
        );
        defer alloc.free(config_json);

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = config_json,
        });

        const writes = try alloc.alloc(types.BatchWrite, doc_count);
        @memset(writes, .{ .key = &.{}, .value = &.{} });
        defer {
            BenchWrites.free(alloc, writes);
            alloc.free(writes);
        }

        const vector_buf = try alloc.alloc(f32, dims);
        defer alloc.free(vector_buf);

        try BenchWrites.fill(alloc, writes, vector_buf, 0);
        const seed_start = monotonicTimeNs();
        try db.batch(.{
            .writes = writes,
            .sync_level = .full_index,
        });
        const seed_ns = monotonicTimeNs() - seed_start;

        const seed_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, seed_stats);

        BenchWrites.free(alloc, writes);
        try BenchWrites.fill(alloc, writes, vector_buf, 17);

        var batch_profile = BatchProfile{};
        const write_start = monotonicTimeNs();
        try db.batchProfiled(.{
            .writes = writes,
            .sync_level = .full_index,
        }, &batch_profile);
        const write_ns = monotonicTimeNs() - write_start;

        const before_idle_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, before_idle_stats);

        const idle_start = monotonicTimeNs();
        const idle_steps = try db.runDensePostingMaintenanceForIdle();
        const idle_ns = monotonicTimeNs() - idle_start;

        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);

        std.debug.print(
            "hbc_posting_lazy_vs_eager mode={s} docs={d} seed_ms={d} update_ms={d} idle_ms={d} idle_steps={d} dirty_before_idle={d} dirty_after_idle={d} update_lazy_centroid_deferrals={d} update_repaired_postings={d} total_lazy_centroid_deferrals={d} total_repaired_postings={d} split_postings={d} merged_postings={d} boundary_reassigned={d}\n",
            .{
                mode.name,
                doc_count,
                @divTrunc(seed_ns, std.time.ns_per_ms),
                @divTrunc(write_ns, std.time.ns_per_ms),
                @divTrunc(idle_ns, std.time.ns_per_ms),
                idle_steps,
                before_idle_stats.indexes[0].hbc_posting.dirty_postings,
                stats.indexes[0].hbc_posting.dirty_postings,
                profileDelta(stats.indexes[0].hbc_posting.lazy_centroid_deferrals, seed_stats.indexes[0].hbc_posting.lazy_centroid_deferrals),
                profileDelta(stats.indexes[0].hbc_posting.maintenance_repaired_postings, seed_stats.indexes[0].hbc_posting.maintenance_repaired_postings),
                stats.indexes[0].hbc_posting.lazy_centroid_deferrals,
                stats.indexes[0].hbc_posting.maintenance_repaired_postings,
                stats.indexes[0].hbc_posting.maintenance_split_postings,
                stats.indexes[0].hbc_posting.maintenance_merged_postings,
                stats.indexes[0].hbc_posting.maintenance_boundary_reassigned_vectors,
            },
        );
    }
}

test "native restore deletes projections only for explicit physical corruption" {
    try std.testing.expect(DB.nativeBackupProjectionLoadFailureIsRepairable("Corrupted"));
    try std.testing.expect(DB.nativeBackupProjectionLoadFailureIsRepairable("FileNotFound"));
    try std.testing.expect(DB.nativeBackupProjectionLoadFailureIsRepairable("UnsupportedVersion"));
    try std.testing.expect(!DB.nativeBackupProjectionLoadFailureIsRepairable("OutOfMemory"));
    try std.testing.expect(!DB.nativeBackupProjectionLoadFailureIsRepairable("InputOutput"));
    try std.testing.expect(!DB.nativeBackupProjectionLoadFailureIsRepairable("TableReadChurn"));
    try std.testing.expect(!DB.nativeBackupProjectionLoadFailureIsRepairable("UnknownBackendFailure"));
}

test "native restore backend configuration is resolved exactly once" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = std.mem.span(path_tmp.path().ptr);
    defer cleanupTempDir(path);
    var candidate_path_tmp = try TestDirectory.init("db");
    defer candidate_path_tmp.cleanup();
    const candidate_path = std.mem.span(candidate_path_tmp.path().ptr);
    defer cleanupTempDir(candidate_path);

    const ConfiguratorContext = struct {
        expected_path: []const u8,
        calls: usize = 0,

        fn configure(ptr: *anyopaque, configured_path: []const u8, opaque_options: *anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const opts: *OpenOptions = @ptrCast(@alignCast(opaque_options));
            if (!std.mem.eql(u8, configured_path, self.expected_path)) return error.UnexpectedConfiguredPath;
            self.calls += 1;
            opts.start_index_workers = false;
            opts.start_optional_runtimes = false;
            opts.ttl_cleanup = .{ .enabled = false };
        }
    };
    var context = ConfiguratorContext{ .expected_path = path };
    var runtime = try background_runtime_mod.BackendRuntimeHandle.init(alloc, .{ .backend = .io_threaded });
    defer runtime.deinit();
    runtime.ptr().db_open_configurator = .{
        .ptr = &context,
        .configure_fn = ConfiguratorContext.configure,
    };

    const resolved = try DB.resolveNativeRestoreOpenPlan(path, .{ .backend_runtime = runtime.ptr() });
    try std.testing.expectEqual(@as(usize, 1), context.calls);

    var transition = try generation_lifecycle.beginProcessExclusiveWithRuntime(path, runtime.ptr());
    var staged = try transition.beginStaging();
    const staged_path = try alloc.dupe(u8, staged.path());
    defer alloc.free(staged_path);
    const staged_options = try resolved.optionsForStagedGeneration(&staged);
    try std.testing.expectEqual(&staged, staged_options.staged_generation.?);
    var candidate = try DB.open(alloc, staged.path(), staged_options);
    candidate.close();
    try std.testing.expectEqual(@as(usize, 1), context.calls);
    staged.deinit();
    transition.deinit();
    try std.testing.expectError(
        error.InvalidGenerationTransition,
        DB.open(alloc, staged_path, staged_options),
    );

    const target_options = try resolved.optionsForTarget(path);
    try std.testing.expectEqual(@as(?*const generation_lifecycle.StagedGeneration, null), target_options.staged_generation);
    var db = try DB.open(alloc, path, target_options);
    defer db.close();
    try std.testing.expectEqual(@as(usize, 1), context.calls);
    try std.testing.expectError(
        error.NativeRestoreTargetPathMismatch,
        resolved.optionsForTarget(candidate_path),
    );

    var unrelated_transition = try generation_lifecycle.beginProcessExclusiveWithRuntime(candidate_path, runtime.ptr());
    defer unrelated_transition.deinit();
    var unrelated_staged = try unrelated_transition.beginStaging();
    defer unrelated_staged.deinit();
    try std.testing.expectError(
        error.NativeRestoreTargetPathMismatch,
        resolved.optionsForStagedGeneration(&unrelated_staged),
    );
}

