test "source vector migration progress pages sync the WAL without flushing tiny runs" {
    const alloc = std.testing.allocator;
    var tmp = try TestDirectory.init("vector-migration-page-wal");
    defer tmp.cleanup();
    var db = try DB.open(alloc, std.mem.span(tmp.path().ptr), .{
        .table_storage = .{ .dense_embeddings = .primary_lsm },
        .start_index_workers = false,
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    // Verification and cleanup often change only a small progress record.
    // A byte-bounded scan must not turn those records into one SST per page.
    for (0..64) |i| {
        const key = try std.fmt.allocPrint(alloc, "ordinary-{d:0>4}", .{i});
        defer alloc.free(key);
        try db.core.store.put(key, "value");
    }
    const request: vector_migration.contract.Request = .{
        .job_id = "page-wal",
        .mode = .online,
        .budget = .{ .batch_rows = 1, .disk_reserve_bytes = 0 },
    };
    try db.startVectorMigration(request);
    const backend = db.core.primary_store_owner.lsmBackend().?;
    const before = backend.snapshotWriteStats();
    for (0..32) |_| try db.advanceVectorMigration(request.job_id);
    const after = backend.snapshotWriteStats();
    var job = (try vector_migration.load(alloc, db.core.store)).?;
    defer job.deinit();
    try std.testing.expectEqual(@as(u64, 32), job.value.scanned_rows);
    try std.testing.expectEqual(before.flushes, after.flushes);
    try std.testing.expectEqual(before.flush_output_runs, after.flush_output_runs);
}

test "source vector migration drains late oversized embeddings and skips unrelated payloads" {
    const alloc = std.testing.allocator;
    var tmp = try TestDirectory.init("migration-large-rows");
    defer tmp.cleanup();
    const path = std.mem.span(tmp.path().ptr);
    const options: OpenOptions = .{ .table_storage = .{ .dense_embeddings = .primary_lsm }, .start_index_workers = false, .start_optional_runtimes = false };
    const key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "late", "model");
    defer alloc.free(key);
    const values: [2048]f32 = @splat(0.5);
    const artifact = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 2, &values);
    defer alloc.free(artifact);
    const large: [6000]u8 = @splat('x');
    const request: vector_migration.contract.Request = .{ .job_id = "large", .mode = .online, .budget = .{ .batch_rows = 2, .batch_bytes = 4096, .disk_reserve_bytes = 0 } };
    {
        var db = try DB.open(alloc, path, options);
        defer db.close();
        try db.core.store.put("unrelated-before", &large);
        try db.startVectorMigration(request);
        for (0..128) |_| {
            var job = (try vector_migration.load(alloc, db.core.store)).?;
            defer job.deinit();
            if (job.value.phase == .ready) break;
            try db.advanceVectorMigration(request.job_id);
        } else return error.VectorMigrationDidNotFinish;
        // Capture is still active after verification: this valid vector is
        // larger than a page but already has a durable candidate reference.
        try db.core.store.put(key, artifact);
        try db.core.store.put("unrelated-after", &large);
        try db.publishVectorMigration(request.job_id);
        try db.advanceVectorMigration(request.job_id);
    }
    var db = try DB.open(alloc, path, options);
    defer db.close();
    try completeVectorMigrationForTest(&db, request.job_id);
    const actual = try db.core.store.get(alloc, key);
    defer alloc.free(actual);
    try std.testing.expectEqualSlices(u8, artifact, actual);
    inline for (.{ "unrelated-before", "unrelated-after" }) |name| {
        const document = try db.core.store.get(alloc, name);
        defer alloc.free(document);
        try std.testing.expectEqualSlices(u8, &large, document);
    }
}

test "source vector migration recovers each preparation commit and publication boundary" {
    const alloc = std.testing.allocator;
    const Hook = struct {
        var selected: vector_migration.Boundary = .before_prepare;
        fn fail(point: vector_migration.Boundary) !void {
            if (point == selected) return error.TestVectorMigrationCrash;
        }
    };
    inline for (std.meta.tags(vector_migration.Boundary)) |point| {
        var tmp = try TestDirectory.init("vector-migration-crash");
        defer tmp.cleanup();
        const path = std.mem.span(tmp.path().ptr);
        const options: OpenOptions = .{
            .table_storage = .{ .dense_embeddings = .primary_lsm },
            .start_index_workers = false,
            .start_optional_runtimes = false,
            .ttl_cleanup = .{ .enabled = false },
        };
        const key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model");
        defer alloc.free(key);
        const value = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 123, &.{ 1, -2, 3 });
        defer alloc.free(value);
        const request: vector_migration.contract.Request = .{ .job_id = "crash", .mode = .online };
        {
            var db = try DB.open(alloc, path, options);
            defer db.close();
            try db.core.store.put(key, value);
            try db.startVectorMigration(request);
            Hook.selected = point;
            vector_migration.test_boundary = Hook.fail;
            defer vector_migration.test_boundary = null;
            if (point == .reclamation_request or point == .reclamation_receipt) {
                var crashed = false;
                for (0..512) |_| {
                    var state = (try vector_migration.load(alloc, db.core.store)).?;
                    defer state.deinit();
                    if (state.value.phase == .ready) {
                        try db.publishVectorMigration(request.job_id);
                    } else db.advanceVectorMigration(request.job_id) catch |err| {
                        try std.testing.expectEqual(error.TestVectorMigrationCrash, err);
                        crashed = true;
                        break;
                    };
                }
                try std.testing.expect(crashed);
            } else if (point == .publication_commit or point == .publication_sync) {
                for (0..256) |_| {
                    var state = (try vector_migration.load(alloc, db.core.store)).?;
                    defer state.deinit();
                    if (state.value.phase == .ready) break;
                    try db.advanceVectorMigration(request.job_id);
                } else return error.VectorMigrationDidNotFinish;
                try std.testing.expectError(error.TestVectorMigrationCrash, db.publishVectorMigration(request.job_id));
            } else {
                try std.testing.expectError(error.TestVectorMigrationCrash, db.advanceVectorMigration(request.job_id));
            }
            try std.testing.expectError(error.VectorMigrationRecoveryRequired, db.advanceVectorMigration(request.job_id));
            try std.testing.expectError(error.VectorMigrationRecoveryRequired, db.core.store.put(key, value));
        }
        // Multiple reopens must agree on both the decision and exact payload.
        for (0..3) |_| {
            var db = try DB.open(alloc, path, options);
            defer db.close();
            try completeVectorMigrationForTest(&db, request.job_id);
            const restored = try db.core.store.get(alloc, key);
            defer alloc.free(restored);
            try std.testing.expectEqualSlices(u8, value, restored);
            try std.testing.expectError(error.VectorMigrationAlreadyPublished, db.cancelVectorMigration(request.job_id));
        }
    }
}

test "source vector migration preserves concurrent models deletes and old snapshots through restart" {
    const alloc = std.testing.allocator;
    const payload = artifact_payload_mod;
    var tmp = try TestDirectory.init("vector-migration");
    defer tmp.cleanup();
    const path = std.mem.span(tmp.path().ptr);
    const options: OpenOptions = .{
        .table_storage = .{ .dense_embeddings = .primary_lsm },
        .start_index_workers = false,
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    };
    const key_a = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model-a");
    defer alloc.free(key_a);
    const key_b = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model-b");
    defer alloc.free(key_b);
    const key_c = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "earlier", "model-c");
    defer alloc.free(key_c);
    const old = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 11, &.{ 1, 2, 3 });
    defer alloc.free(old);
    const new = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 12, &.{ 4, 5, 6 });
    defer alloc.free(new);
    const request: vector_migration.contract.Request = .{
        .job_id = "online-test",
        .mode = .online,
        .budget = .{ .batch_rows = 2 },
    };
    {
        var db = try DB.open(alloc, path, options);
        defer db.close();
        try db.core.store.putBatch(&.{ .{ .key = key_a, .value = old }, .{ .key = key_b, .value = old } }, &.{});
        var old_reader = try db.core.store.beginReadTxn();
        defer old_reader.abort();
        try db.startVectorMigration(request);
        try db.startVectorMigration(request);
        try db.advanceVectorMigration(request.job_id);
        try db.core.store.putBatch(&.{ .{ .key = key_a, .value = new }, .{ .key = key_c, .value = old } }, &.{key_b});
        var raw = try db.core.store.runtime_store.beginRead();
        defer raw.abort();
        try std.testing.expectEqualSlices(u8, new, try raw.get(key_a));
        const candidate_key = try vector_migration.contract.candidateKeyAlloc(alloc, key_a);
        defer alloc.free(candidate_key);
        try std.testing.expectEqualSlices(u8, &(try payload.Reference.forArtifact(key_a, new)).encode(), try raw.get(candidate_key));
        try std.testing.expectEqualSlices(u8, old, try old_reader.get(key_a));
        try std.testing.expect(!try db.collectSourceVectorGarbage());
    }
    {
        var db = try DB.open(alloc, path, options);
        defer db.close();
        var before_publication = try db.core.store.beginReadTxn();
        defer before_publication.abort();
        for (0..256) |_| {
            var state = (try vector_migration.load(alloc, db.core.store)).?;
            defer state.deinit();
            if (state.value.phase == .ready) break;
            try db.advanceVectorMigration(request.job_id);
        } else return error.VectorMigrationDidNotFinish;
        try db.publishVectorMigration(request.job_id);
        try db.publishVectorMigration(request.job_id);
        try db.core.store.put(key_c, new);
        for (0..256) |_| {
            var state = (try vector_migration.load(alloc, db.core.store)).?;
            defer state.deinit();
            if (state.value.phase == .complete) break;
            try db.advanceVectorMigration(request.job_id);
        } else return error.VectorMigrationDidNotFinish;
        try std.testing.expectEqualSlices(u8, old, try before_publication.get(key_c));
        var raw = try db.core.store.runtime_store.beginRead();
        defer raw.abort();
        try std.testing.expect(payload.isReference(try raw.get(key_a)));
        try std.testing.expect(payload.isReference(try raw.get(key_c)));
        try std.testing.expectError(error.NotFound, raw.get(key_b));
    }
    // The durable publication bridges a catalog response lost after DB sync.
    var reopened = try DB.open(alloc, path, options);
    defer reopened.close();
    try std.testing.expectEqual(.vector_store, reopened.local_execution.table_storage.dense_embeddings);
    const restored = try reopened.core.store.get(alloc, key_a);
    defer alloc.free(restored);
    try std.testing.expectEqualSlices(u8, new, restored);
}

test "source vector table persists references without an ANN index and reopens" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    const key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model-a");
    defer alloc.free(key);
    const other_key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model-b");
    defer alloc.free(other_key);
    const first = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 11, &.{ 1, 2, 3 });
    defer alloc.free(first);
    const second = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 12, &.{ 4, 5 });
    defer alloc.free(second);
    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .table_storage = .{ .dense_embeddings = .vector_store },
            .start_index_workers = false,
            .start_optional_runtimes = false,
            .ttl_cleanup = .{ .enabled = false },
        });
        defer db.close();
        try db.core.store.putBatch(&.{ .{ .key = key, .value = first }, .{ .key = other_key, .value = second } }, &.{});
        var raw = try db.core.store.runtime_store.beginRead();
        defer raw.abort();
        try std.testing.expect(artifact_payload_mod.isReference(try raw.get(key)));
        try std.testing.expectError(error.ImmutableTableStorageSettings, db.configureTableStorage(.{}));
        try db.sync(true);
    }
    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer reopened.close();
    try std.testing.expectEqual(table_storage_mod.DenseEmbeddings.vector_store, reopened.local_execution.table_storage.dense_embeddings);
    const value = try reopened.core.store.get(alloc, key);
    defer alloc.free(value);
    try std.testing.expectEqualSlices(u8, first, value);
    const other = try reopened.core.store.get(alloc, other_key);
    defer alloc.free(other);
    try std.testing.expectEqualSlices(u8, second, other);
    // Open schedules artifact cleanup even with index workers disabled. Its
    // metadata scans retain payload sessions, so join this owner's startup
    // jobs before driving the bounded collector to completion.
    reopened.backend_runtime.durable_jobs.drainOwner(reopened.repair_cleanup_owner_id);
    var collection_turns: usize = 0;
    while (!try reopened.collectSourceVectorGarbage()) : (collection_turns += 1) {
        if (collection_turns == 1024) return error.CollectionDidNotFinish;
        platform_time.yieldBriefly();
    }
    try std.testing.expectEqual(@as(u64, 2), (try reopened.sourceVectorStats()).?.live_payloads_at_collection);
}

test "source vector table collection defers until an old read transaction releases its payload session" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var db = try DB.open(alloc, std.mem.span(path), .{
        .table_storage = .{ .dense_embeddings = .vector_store },
        .start_index_workers = false,
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    db.backend_runtime.durable_jobs.drainOwner(db.repair_cleanup_owner_id);

    const key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc", "model");
    defer alloc.free(key);
    const first = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 11, &.{ 1, 2, 3 });
    defer alloc.free(first);
    const replacement = try enrichment_artifact_codec.encodeDenseEmbeddingAlloc(alloc, 12, &.{ 4, 5, 6 });
    defer alloc.free(replacement);
    try db.core.store.put(key, first);
    try db.sync(true);
    // Full sync may start a bounded mark before the reader is admitted. Drain
    // that cut first: the assertion below tests admission of a NEW collection
    // while an old snapshot is active, not completion of its already-safe cut.
    var initial_gc_turns: usize = 0;
    while (!try db.collectSourceVectorGarbage()) : (initial_gc_turns += 1) {
        if (initial_gc_turns == 1024) return error.CollectionDidNotFinish;
        platform_time.yieldBriefly();
    }

    {
        var reader = try db.core.store.beginReadTxn();
        defer reader.abort();
        try db.core.store.put(key, replacement);
        try std.testing.expectEqual(@as(u64, 2), (try db.sourceVectorStats()).?.retained_payloads);
        const before = (try db.sourceVectorStats()).?;
        try std.testing.expect(!try db.collectSourceVectorGarbage());
        const deferred = (try db.sourceVectorStats()).?;
        try std.testing.expectEqual(before.collections, deferred.collections);
        try std.testing.expectEqual(before.collection_deferrals + 1, deferred.collection_deferrals);
        try std.testing.expectEqual(@as(u64, 2), deferred.retained_payloads);
        // Resolve only after the attempted collection: the old transaction's
        // primary reference must still have a live source payload to read.
        try std.testing.expectEqualSlices(u8, first, try reader.get(key));
    }

    var collection_turns: usize = 0;
    while (!try db.collectSourceVectorGarbage()) : (collection_turns += 1) {
        if (collection_turns == 1024) return error.CollectionDidNotFinish;
        platform_time.yieldBriefly();
    }
    try std.testing.expectEqual(@as(u64, 1), (try db.sourceVectorStats()).?.live_payloads_at_collection);
    try std.testing.expectEqual(@as(u64, 1), (try db.sourceVectorStats()).?.retained_payloads);
    const current = try db.core.store.get(alloc, key);
    defer alloc.free(current);
    try std.testing.expectEqualSlices(u8, replacement, current);
}

test "source vector table retains artifacts after dropping last consumer and rebuilds" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    var db = try DB.open(alloc, std.mem.span(path), .{
        .table_storage = .{ .dense_embeddings = .vector_store },
        .start_index_workers = false,
        .start_optional_runtimes = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    const config = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true,\"embedding_name\":\"shared_source\"}";
    try db.addIndex(.{ .name = "first", .kind = .dense_vector, .config_json = config });
    const key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc", "shared_source");
    defer alloc.free(key);
    const doc_key = try internal_keys.documentKeyAlloc(alloc, "doc");
    defer alloc.free(doc_key);
    try db.core.store.put(doc_key, "{\"title\":\"test\"}");
    try putDenseEmbeddingArtifactWithCounterForTest(&db, alloc, key, null, &.{ 1, 0, 0 });
    _ = try db.rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeeded(alloc);
    try std.testing.expect(try db.deleteIndex("first"));
    var pages: usize = 0;
    while (try db.advanceGeneratedArtifactCleanupPage(null) != .idle) : (pages += 1) {
        if (pages > 10000) return error.CleanupDidNotDrain;
        try db.core.index_manager.checkpointIo().sleep(std.Io.Duration.fromMilliseconds(1), .awake);
    }
    const retained = try db.core.store.get(alloc, key);
    defer alloc.free(retained);
    try std.testing.expectEqual(@as(usize, 3), try enrichment_artifact_codec.decodeDenseEmbeddingDims(retained));
    try db.addIndex(.{ .name = "replacement", .kind = .dense_vector, .config_json = config });
    _ = try db.rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeeded(alloc);
    const repair_id = (try db.indexRepairIdForIndex(alloc, "replacement")) orelse return error.TestUnexpectedResult;
    _ = try db.advanceIndexRepairIntent(alloc, repair_id, .{});
    try db.runUntilIdle();
    try std.testing.expectEqual(@as(u64, 1), db.core.index_manager.denseIndex("replacement").?.index.metadata.active_count);
    // Native repair candidates must retain the table's source ownership. A
    // missing binding used to silently build a second full-payload ANN base.
    const relative = (try db.core.index_manager.captureActiveIndexRootPointer("replacement")) orelse return error.TestUnexpectedResult;
    defer alloc.free(relative);
    const candidate_root = std.fs.path.dirname(std.fs.path.dirname(relative).?).?;
    const map_root = try std.fmt.allocPrint(alloc, "{s}/{s}/vector-blocks", .{ std.mem.span(path), candidate_root });
    defer alloc.free(map_root);
    var map = try @import("../vector_block_store.zig").Store.openReadOnlyWithBlocks(alloc, db.core.index_manager.vector_block_storage.?, map_root);
    defer map.deinit();
    try std.testing.expectEqual(.artifact_reference, map.baseEncoding());
}

test "db capacity deferred dense repairs exclusively own both model generations across restart" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    const configs = [_]types.IndexConfig{
        .{ .name = "model_a", .kind = .dense_vector, .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}" },
        .{ .name = "model_b", .kind = .dense_vector, .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"external\":true}" },
    };
    const options: OpenOptions = .{
        .open_mode = .writer_no_replay,
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    };
    var repair_ids: [2]u128 = undefined;
    {
        var db = try DB.open(alloc, std.mem.span(path), options);
        defer db.close();
        for (configs) |cfg| try db.addIndex(cfg);
        try db.batch(.{
            .writes = &.{.{ .key = "doc:a", .value = "{\"_embeddings\":{\"model_a\":[1,0,0],\"model_b\":[0,1]}}" }},
            .sync_level = .write,
        });
        for (configs, 0..) |cfg, i| {
            // Reproduce a publication cursor ahead of an empty canonical ANN
            // generation. Durable shadow repair owns the missing artifacts.
            try db.core.saveAppliedSequence(cfg.name, 1);
            try db.core.saveProjectionCheckpoint(cfg.name, .{
                .applied_sequence = 1,
                .status = .rebuilding,
                .generation = 1,
                .config_hash = types.indexConfigHash(cfg),
            });
            repair_ids[i] = try db.createOperatorGenerationRepairIntent(alloc, cfg, 0, 0);
            const step = try db.advanceIndexRepairIntent(alloc, repair_ids[i], .{
                .capacity_domain_id = 77,
                .capacity_observation = .{ .available_bytes = 1, .capacity_bytes = 1 },
            });
            try std.testing.expect(step.disk_wait);
            try std.testing.expect(step.deferred);
            try std.testing.expectEqual(@as(u64, 0), db.core.index_manager.denseIndex(cfg.name).?.index.stats().active_count);
        }
        var plan = try db.collectDenseArtifactRebuildPlan(alloc);
        defer plan.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 0), plan.targets.len);
        try std.testing.expectEqual(@as(usize, 0), plan.generation_repairs.len);
    }
    var db = try DB.open(alloc, std.mem.span(path), options);
    defer db.close();
    {
        var plan = try db.collectDenseArtifactRebuildPlan(alloc);
        defer plan.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 0), plan.targets.len);
        try std.testing.expectEqual(@as(usize, 0), plan.generation_repairs.len);
    }
    for (configs, repair_ids) |cfg, repair_id| {
        try db.updateIndexRepairIntent(alloc, repair_id, .{ .next_retry_at_ms = 0 });
        var repaired = false;
        for (0..16) |_| {
            const step = try db.advanceIndexRepairIntent(alloc, repair_id, repair_completion_test_options);
            try std.testing.expect(!step.terminal);
            if (step.repaired) {
                repaired = true;
                break;
            }
        }
        try std.testing.expect(repaired);
        try std.testing.expectEqual(@as(u64, 1), db.core.index_manager.denseIndex(cfg.name).?.index.stats().active_count);
    }
}

test "db algebraic path conversion preserves provenance under allocation failures" {
    const edge = graph_query_mod.PathEdgeInfo{
        .source = "a",
        .target = "b",
        .edge_type = "R",
        .edge_id = "one",
        .owner_document = "fact:one",
        .weight = 2,
        .metadata = "{\"fact\":1}",
        .traversal_direction = .in,
    };
    const Case = struct {
        fn convert(alloc: Allocator, item: graph_query_mod.PathEdgeInfo) !void {
            const path = (try DB.graphResultNodePathAlloc(alloc, .{ .key = "b", .depth = 1, .distance = 1, .path = &.{ "a", "b" }, .path_edges = &.{item} })).?;
            defer paths_mod.freePath(alloc, path);
            try std.testing.expectEqualStrings(item.metadata, path.edges[0].metadata);
            try std.testing.expectEqualStrings(item.edge_id, path.edges[0].edge_id);
            try std.testing.expectEqualStrings(item.owner_document, path.edges[0].owner_document);
            try std.testing.expectEqual(item.traversal_direction, path.edges[0].traversal_direction);
        }
    };
    try platform.allocator.checkAllAllocationFailures(std.testing.allocator, Case.convert, .{edge});
}

pub fn expectPhysicalSplitRetirements(options: OpenOptions) !void {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("retirement-split-review");
    defer directory.cleanup();
    var destination = try TestDirectory.init("retirement-split-review-child");
    defer destination.cleanup();
    var db = try DB.open(alloc, std.mem.span(directory.path().ptr), options);
    defer db.close();
    try db.addIndex(.{ .name = "facts", .kind = .graph, .config_json = "{}" });
    try db.batch(.{ .writes = &.{.{ .key = "z", .value = "{}" }}, .graph_writes = &.{.{ .index_name = "facts", .source = "z", .target = "a", .edge_type = "R" }}, .sync_level = .full_index });
    try db.batch(.{ .graph_deletes = &.{.{ .index_name = "facts", .source = "z", .target = "a", .edge_type = "R" }}, .sync_level = .full_index });
    try db.runUntilIdle();
    try std.testing.expect(try db.core.store.hasGraphRetirements());
    try prepareSplitDestination(&db, .{ .start = "m", .end = "" }, std.mem.span(destination.path().ptr));
    var child = try DB.open(alloc, std.mem.span(destination.path().ptr), options);
    defer child.close();
    const artifact = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "z", "facts", "R", "a");
    defer alloc.free(artifact);
    try std.testing.expect(try child.core.store.graphRelationshipRetired(artifact));
    // Replay/materialization writes must honor the primary marker even when
    // physical shard copying bypassed transactional directory maintenance.
    try child.core.store.put(artifact, "reconstructed");
    const revived = try missingAsNull(child.core.store.get(alloc, artifact));
    defer if (revived) |value| alloc.free(value);
    try std.testing.expect(revived == null);
    const split_lower = try documentRangeLowerAlloc(alloc, "m");
    defer alloc.free(split_lower);
    try finalizePrimarySplitPreservingMetadata(&db, split_lower, .{ .start = "", .end = "m" });
    try std.testing.expect(!try db.core.store.hasGraphRetirements());
    const parent_refs = try db.core.store.scanPrefix(alloc, internal_keys.graph_retirement_ref_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, parent_refs);
    try std.testing.expectEqual(@as(usize, 0), parent_refs.len);
}

